insert into public.transaction_municipal_requirements
  (municipality_code, municipality_name, county, requirement_key, requirement_state, title, requirements, fees, application_url, department_url, source_urls, source_excerpt, source_hash, last_verified_at, metadata, curated_note, curated_override)
values
  ($t$0201$t$, $t$Allendale Borough$t$, $t$BERGEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Compliance (change of tenancy, use or ownership)$t$, $j$["Issued by: Borough of Allendale Construction Code Official, with the Property Maintenance Official, Zoning Official and the Borough Fire Inspector","Contact: Anthony Hackett, Code Official · 201-818-4400 ext. 208","Apply: The Code says the inspection is made within 10 to 15 days of receiving the application and fee, and not more than 60 days before the change of ownership.","How to apply: Apply online with the Borough's Certificate of Compliance application (GovPilot), listed on the Construction and Zoning Permits & Forms page, and pay in full before the application is reviewed. Give the closing date, new owner details and who to contact for the inspection. The Construction Code Office (500 W Crescent Ave) is open Monday to Friday 9:00am to 4:30pm.","Valid for: Inspection may be made no more than 60 days before the change of ownership","Inspection of the visual parts of the house for Borough code violations, with no pending violations or orders from the Construction, Property Maintenance or Zoning Officials","Smoke alarms on each level and within 10 feet of each sleeping area (10-year sealed battery units where battery powered); carbon monoxide alarms; listed in the application","Portable fire extinguisher 2A-10B:C within 10 feet of the kitchen (form still lists it)","A low voltage smoke alarm system used as the primary system must have been inspected by a qualified technician within 12 months; proof shown to the Fire Inspector","Zoning inspection: pool fence and self-latching gates, visual exterior check, sidewalks (trip hazards must be replaced before closing), house number visible, no open building permits","List any deck, fence, garage, shed, pool or finished basement on the application","Also: Final water reading: Call Suez at (855) 367-6708 for a final water reading 72 hours before closing. Water charges are lienable and must be paid before closing.","Also: Sidewalk inspection: The zoning inspection checks sidewalks for cracks and trip hazards; failing sections must be replaced before closing.","Also: Open permits: Any open building permits are checked during the zoning inspection."]$j$::jsonb, $j$[{"label":"Certificate of compliance for change in ownership of residential premises (Zoning fee schedule, Code Section 120-23)","amount":"$100"},{"label":"Reinspection for certificate of compliance","amount":"$25"},{"label":"Certificate of occupancy for change in ownership of nonresidential or residential premises (separate line in the same schedule; which one applies to a home sale is unclear)","amount":"$200"}]$j$::jsonb, $t$https://main.govpilot.com/web/public/4544861f-4d1_Certificate-of-Compliance-Application-ALLENDALE?uid=6902&ust=NJ&pu=1&id=0$t$, $t$https://www.allendalenj.gov/building-development/construction-and-zoning/$t$, $j$[{"url":"https://ecode360.com/8920485","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/8917485","label":"Official source (ecode360.com)"},{"url":"https://main.govpilot.com/web/public/4544861f-4d1_Certificate-of-Compliance-Application-ALLENDALE?uid=6902&ust=NJ&pu=1&id=0","label":"Official source (main.govpilot.com)"},{"url":"https://www.allendalenj.gov/building-development/construction-and-zoning/","label":"Official source (allendalenj.gov)"},{"url":"https://ecode360.com/8917292","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$No residential or nonresidential property may be changed in tenancy, use or ownership unless a certificate of compliance has been issued by the Borough Construction Code Official on forms provided and the required fee paid for such inspection.$t$, $t$f04809ea0fce5ee52deeaaebbd1d36dafa92dcdc129186d86b31eba21adc10c7$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":0,"fee_bad":0,"fee_unchecked":4,"quotes":15,"q_ok":7,"q_bad":0,"q_unchecked":8},"source":"property/data/municipal-requirements/checked/0201.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0201.json$t$, true),
  ($t$0201$t$, $t$Allendale Borough$t$, $t$BERGEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Borough of Allendale (Certificate of Compliance inspection by the Construction Code Office and Borough Fire Inspector; Allendale Fire Prevention Bureau is the LEA) (town fire bureau)","Contact: Kevin M Todd, Fire Official (state fire directory) · 201-818-4400 x301 · fireofficial@allendalenj.gov","Apply: Inspection within 10 to 15 days of the application and fee (Code Section 128-15); no tiered rush fees were found.","How to apply: The smoke alarm, carbon monoxide alarm and extinguisher check is done as part of the Certificate of Compliance; apply with the same online GovPilot application. For fire code questions contact Allendale Fire Prevention.","Fire official in the NJ state directory, updated 6/4/2025: Kevin M Todd · (201) 818-4400 · fireofficial@Allendalenj.gov","Smoke alarms on each level and within ten feet of each separate sleeping area, listed to ANSI/UL 217; basement alarms near the stairway to the floor above","Ten-year sealed battery smoke alarms where battery powered; hardwired alarms from original construction may not be replaced with battery units; replace alarms older than 10 years","Carbon monoxide alarms (UL 2034) for each separate sleeping area; combination units are acceptable","Portable fire extinguisher 2A-10B:C, no more than 10 pounds, within 10 feet of the kitchen, mounted, serviced and tagged in the past 12 months or with a recent receipt (form still lists it)","Low voltage primary alarm systems need a technician inspection within 12 months","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Certificate of Compliance (smoke and CO check is part of this certificate)","amount":"$100"}]$j$::jsonb, $t$https://main.govpilot.com/web/public/4544861f-4d1_Certificate-of-Compliance-Application-ALLENDALE?uid=6902&ust=NJ&pu=1&id=0$t$, $t$https://www.allendalenj.gov/public-safety/fire-prevention-bureau/$t$, $j$[{"url":"https://www.allendalenj.gov/public-safety/fire-prevention-bureau/","label":"Official source (allendalenj.gov)"},{"url":"https://main.govpilot.com/web/public/4544861f-4d1_Certificate-of-Compliance-Application-ALLENDALE?uid=6902&ust=NJ&pu=1&id=0","label":"Official source (main.govpilot.com)"},{"url":"https://ecode360.com/8920485","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/8917463","label":"Official source (ecode360.com)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://ecode360.com/8917292","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$Allendale Fire Prevention 201-818-4400 X301 fireofficial@allendalenj.gov$t$, $t$99b1ff37c5bad4208c31b35b023ca0844fb7b6a08edba48cafa9cababc7fcdde$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":0,"fee_bad":0,"fee_unchecked":4,"quotes":15,"q_ok":7,"q_bad":0,"q_unchecked":8},"source":"property/data/municipal-requirements/checked/0201.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0201.json$t$, true),
  ($t$0202$t$, $t$Alpine Borough$t$, $t$BERGEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Continued Occupancy Resale (CCO)$t$, $j$["Issued by: Borough of Alpine Construction (Building) Department, Code Official/Building Inspector","Contact: John Scialla, Construction Code Official / Building Subcode Official (technical assistant: Catherine Booth, ext. 222) · 201-784-2900 ext. 222 · constoff@alpinenj.org","Apply: Apply at least 20 business days before the change of occupancy; the Code Official inspects within 10 business days of a complete application. The application form says the department has 10 working days to approve or deny.","How to apply: Fill out the Borough's Application for Continued Occupancy Compliance (Construction Department), have it notarized, and drop it off with the fee at the Building Department, 100 Church Street, Alpine, as soon as the contract is signed. Office hours are Monday to Friday 9:00 am to 3:30 pm. Inspections are by appointment. If the house will be demolished or violations can only be fixed after closing, ask for a certificate of noncompliance instead (seller and buyer letters, notarized, reviewed by the Borough Attorney and Engineer).","Valid for: 90 days from issuance (CCO and smoke/CO certificates, per the Borough guidelines)","General inspection of the visible parts of the house, property and other structures for Borough ordinance, Uniform Construction Code and Uniform Fire Code violations and unsafe conditions","Smoke alarms working and maintained as required at original construction; battery-only alarms must be 10-year sealed units (effective January 1, 2019)","Carbon monoxide alarm within 10 feet of each bedroom area","Portable fire extinguisher, 2A:10B:C, no larger than 10 pounds, mounted within 10 feet of the kitchen (form still lists it)","NFPA report required on all low voltage alarm systems; someone on site who knows how to reset the alarm system","Electrical covers, handrails on stairs with more than three risers, working faucets and toilets, operable bedroom windows, egress locks without keys (no double cylinder deadbolts)","Garage fire-resistive rating maintained, gas piping strapped with shut-offs (no aluminum piping), clearance to combustibles, pool barriers, house numbers at least 4 inches","All open permits must be closed; work done without permits must be permitted and inspected before the CCO is issued","Application must be signed and notarized","Also: Open permits: All open permits must be closed, and any work found done without permits must be permitted and inspected before the CCO is issued.","Also: Low voltage alarm systems: An NFPA report is required on all low voltage alarm systems at the CCO inspection.","Also: Advanced septic (pretreatment) system license transfer: Homes with an active sewage treatment system using advanced wastewater pretreatment need a Board of Health license; the Borough fee schedule lists a $50 realty transfer fee and a $50 late fee for applications more than 14 days after realty transfer. Septic matters go to the Alpine Health Department, 201-784-2900 ext. 219.","Also: Fire Official status report (optional): On request of an owner or purchaser, the Fire Official issues a certificate listing unabated fire code violations and unpaid fees, for a $25 fee."]$j$::jsonb, $j$[{"label":"CCO resale, residential, 10 or more days prior","amount":"$400.00"},{"label":"CCO resale, residential, 4 to 10 days prior","amount":"$600.00"},{"label":"CCO resale, residential, fewer than 4 days prior","amount":"$800.00"},{"label":"CCO reinspection","amount":"$90"},{"label":"Certificate of noncompliance (transfer only, occupancy prohibited until violations are corrected)","amount":"$400"}]$j$::jsonb, $t$https://www.alpinenj.gov/file/a542c1d0-c177-11f0-84b6-8526c67a8884$t$, $t$https://www.alpinenj.gov/page/building-dept$t$, $j$[{"url":"https://ecode360.com/8924167","label":"Official source (ecode360.com)"},{"url":"https://www.alpinenj.gov/file/a542c1d0-c177-11f0-84b6-8526c67a8884","label":"Official source (alpinenj.gov)"},{"url":"https://www.alpinenj.gov/page/building-dept","label":"Official source (alpinenj.gov)"}]$j$::jsonb, $t$Certificate of continued occupancy resale shall be required upon any transfer of ownership to an existing premises which is accompanied by a change in the occupancy of such premises.$t$, $t$967e4a3b81d9b9d064deb2018f6d1f2eebab0fc72db92786ab141aac15ff794d$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":0,"fee_bad":0,"fee_unchecked":5,"quotes":14,"q_ok":1,"q_bad":0,"q_unchecked":13},"source":"property/data/municipal-requirements/checked/0202.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0202.json$t$, true),
  ($t$0202$t$, $t$Alpine Borough$t$, $t$BERGEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Alpine Bureau of Fire Prevention (Alpine Fire Department), inspected with the Borough Code Enforcement / Building Department CCO (town fire bureau)","Contact: Keith Dalton, Fire Official (also Zoning Officer / Fire Subcode Official) · 201-784-2900 ext. 224 · fireofficial@alpinenj.org","Apply: The Borough recommends requesting the CCO and smoke/CO inspection as soon as the contract is signed. The certificate is valid for 90 days from issuance.","How to apply: The Borough's guidelines say the Alpine Code Enforcement Bureau enforces the smoke and carbon monoxide alarm certificate and that it is inspected with the CCO; drop off the Application for Continued Occupancy Compliance with fees at the Building Department. Call the Fire Official, Keith Dalton, at 201-784-2900 ext. 224 to confirm whether a separate smoke/CO fee applies.","Fire official in the NJ state directory, updated 7/21/2025: Keith P Dalton · (201) 784-2900 · fireofficial@alpinenj.org","Smoke alarm on each level and outside each separate sleeping area, near the bedrooms (Borough Code 119-10)","Carbon monoxide alarm within 10 feet of each bedroom area","Battery-only smoke alarms must be 10-year sealed units","Portable fire extinguisher, 2A:10B:C, no larger than 10 pounds, mounted within 10 feet of the kitchen (form still lists it)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[]$j$::jsonb, $t$https://www.alpinenj.gov/file/a542c1d0-c177-11f0-84b6-8526c67a8884$t$, $t$https://www.alpinenj.gov/page/alpine-fire-dept$t$, $j$[{"url":"https://ecode360.com/8922203","label":"Official source (ecode360.com)"},{"url":"https://www.alpinenj.gov/file/a542c1d0-c177-11f0-84b6-8526c67a8884","label":"Official source (alpinenj.gov)"},{"url":"https://www.alpinenj.gov/page/alpine-fire-dept","label":"Official source (alpinenj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Before any one- or two-family residential structure is sold, leased or otherwise made subject to a change of occupancy for residential purposes, the owner shall obtain a certificate of smoke detector and carbon monoxide alarm compliance, evidencing compliance with this chapter and with the New Jersey Fire Safety Code, N.J.A.C. 5:70-4.19.$t$, $t$47185cc34ec1fe101fa8f946bdd577ba136f1500e0dc3379f5c407009ce1827d$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":0,"fee_bad":0,"fee_unchecked":5,"quotes":14,"q_ok":1,"q_bad":0,"q_unchecked":13},"source":"property/data/municipal-requirements/checked/0202.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0202.json$t$, true),
  ($t$0203$t$, $t$Bergenfield Borough$t$, $t$BERGEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$New Tenant/Resale Certificate (Certificate of Continued Occupancy, CCO)$t$, $j$["Issued by: Borough of Bergenfield Construction Code Department / Code Enforcement (GovPilot form is headed Code Enforcement)","Contact: (201) 387-4055 ext. 4092","How to apply: Apply online with the Borough's GovPilot New Tenant/Resale Certificate form (or the notarized paper application from the Construction Code Department, 198 N. Washington Ave.). Attach the notarized forms, the water service line/backflow confirmation number and, if there is a sump pump, the Sump Pump Certification. The fee covers the certificate and the smoke/CO inspection.","Inspection of the home before the sale (exterior and interior checklist: walkways, stairs and handrails, roof, gutters, paint, house number, plumbing, sump pump discharge, heater venting, debris, hedges, unregistered vehicles, broken glass, deadbolt with thumb latch, water heater relief valve extension, removal of basement kitchens built without permits)","Smoke detectors on each level and carbon monoxide detectors within 10 feet of bedrooms (sealed units if not hardwired)","Fire extinguisher (form still lists it)","Licensed plumber's Water Service Line check (lead or galvanized) and backflow preventer certification if there is a lawn or fire sprinkler system, before an inspection is scheduled","Sump Pump Certification if the house has a sump pump, before an inspection is scheduled","Notarized application signed by owner and purchaser, attesting to the use (one family / two family) and maximum occupancy","Owner certifies the dwelling meets zoning and that no rubbish, debris or bulk garbage will be left before new occupancy","Agreement of Use Regarding Basement/Attic and Verification of Occupancy (rental registration notice) forms in the application packet","Also: Water service line and backflow certification: A licensed plumber must check the water service line for lead or galvanized material, and certify any backflow preventer if there is a lawn or fire sprinkler system, before the resale inspection is scheduled.","Also: Sump pump certification: If the house has a sump pump, a Sump Pump Certification must be submitted before the inspection can be scheduled; the pump must drain outside and cannot be connected to the sewer.","Also: Rental registration for two-family homes: Buyers who will rent a unit must register with Code Enforcement (annual registration by February 15, $50 per rental unit); two-family and non-owner-occupied homes are inspected on every change in occupancy."]$j$::jsonb, $j$[{"label":"Resale/new tenant certificate with smoke/CO inspection, single-family or condo (online fee table; reinspection $25)","amount":"$95.00"},{"label":"Resale/new tenant certificate with smoke/CO inspection, two-family (online fee table; reinspection $25)","amount":"$120.00"},{"label":"Paper application, one family: $50.00 certificate fee plus $45.00 fire fee","amount":"$50.00"},{"label":"Paper application, two family: $75.00 certificate fee plus $45.00 fire fee","amount":"$75.00"}]$j$::jsonb, $t$https://main.govpilot.com/web/public/bcb49b67-dba_Rental-Resale-Borough-of-Bergenfield$t$, $t$https://bergenfield.com/departments/code-enforcement-bureau/$t$, $j$[{"url":"https://main.govpilot.com/web/public/bcb49b67-dba_Rental-Resale-Borough-of-Bergenfield","label":"Official source (main.govpilot.com)"},{"url":"https://bergenfieldnj.gov/wp-content/uploads/2025/02/APPLICATION-FOR-RESALE-OR-RENTAL-CERTIFICATE-FOR-ONE-FAMILY-TWO-FAMILY-AND-MULTIPLE-DWELLINGS.pdf","label":"Official source (bergenfieldnj.gov)"},{"url":"https://bergenfield.com/departments/code-enforcement-bureau/","label":"Official source (bergenfield.com)"}]$j$::jsonb, $t$A New Tenant/Resale Certificate is required by the Borough of Bergenfield when a property is being sold or a new tenant is moving in.$t$, $t$7c500fe87820c818e7da9427e4eeac09da0cae3494243e1b2acc1a43a5001f8e$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":2,"fee_bad":0,"fee_unchecked":3,"quotes":14,"q_ok":9,"q_bad":0,"q_unchecked":5},"source":"property/data/municipal-requirements/checked/0203.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0203.json$t$, true),
  ($t$0203$t$, $t$Bergenfield Borough$t$, $t$BERGEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Borough of Bergenfield (smoke/CO certificate taken with the resale certificate application; Bergenfield Fire Prevention Bureau is the fire code enforcing agency) (town fire bureau)","Contact: Kevin Cook, Fire Official (Fire Inspector: Lou Turso, ext 4074; Fire Prevention Clerk: Sharon Rugel, ext 4174) · (201) 387-4055 ext 4 · fireprevention@bergenfieldnj.gov","How to apply: The smoke detector and carbon monoxide certificate is applied for together with the New Tenant/Resale Certificate (GovPilot form or paper application with the notarized one and two family CSDCMAC page). Payment must accompany the application (credit card, check or money order payable to Borough of Bergenfield).","Fire official in the NJ state directory, updated 3/2/2026: Kevin R Cook · (201) 387-4055 · fire-prevention@bergenfield.com","Smoke detectors on each level of the dwelling, including basements (excluding attic or crawl space); 10 year sealed units on the CSDCMAC form","Smoke detectors and carbon monoxide detector outside each separate sleeping area (within 10 feet of bedrooms)","All smoke and carbon monoxide detectors in working order","Fire extinguisher (form still lists it)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke/CO fire fee included in the resale application (paper form)","amount":"$45.00"}]$j$::jsonb, $t$https://main.govpilot.com/web/public/bcb49b67-dba_Rental-Resale-Borough-of-Bergenfield$t$, $t$https://bergenfield.com/departments/fire-prevention-bureau/$t$, $j$[{"url":"https://bergenfield.com/departments/fire-prevention-bureau/","label":"Official source (bergenfield.com)"},{"url":"https://bergenfieldnj.gov/wp-content/uploads/2025/02/APPLICATION-FOR-RESALE-OR-RENTAL-CERTIFICATE-FOR-ONE-FAMILY-TWO-FAMILY-AND-MULTIPLE-DWELLINGS.pdf","label":"Official source (bergenfieldnj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Fire Official: Kevin Cook$t$, $t$bd4f194fc06d9ca8188276bd8621071249cfebe6a230ddd7fc0b2fb043065aff$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":2,"fee_bad":0,"fee_unchecked":3,"quotes":14,"q_ok":9,"q_bad":0,"q_unchecked":5},"source":"property/data/municipal-requirements/checked/0203.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0203.json$t$, true),
  ($t$0204$t$, $t$Bogota Borough$t$, $t$BERGEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Continued Occupancy (CCO)$t$, $j$["Issued by: Borough of Bogota Building Department (Construction Code and Zoning Official)","Contact: Arthur Sopelsa, Construction Code and Zoning Official · 201-342-1736 x224 · bldgdept@bogotaonline.org","Apply: Fees go up when the request comes in late: base fee more than 20 business days before the change of occupant, double at 10 to 20 days, triple at under 10 days.","How to apply: Print and fill in the Borough's Certificate of Continued Occupancy (CCO) Permit Application and file it with the Building Department at Borough Hall, 375 Larch Avenue, Bogota, NJ 07603, with the fee. Apply more than 20 business days before closing to pay the base fee.","Valid for: A temporary certificate of occupancy (90 day maximum, not extendable) is available at half the fee plus a 120% bond for unfinished work.","Borough CCO application, which is also the smoke detector, carbon monoxide and fire extinguisher certification form","Access to the dwelling unit, basement, attic and common areas for the inspection","New buyer or tenant names and the number of dwelling units must be listed on the application","Fire extinguisher (form still lists it)","Also: Late-request surcharge: CCO fees double if the request comes 10 to 20 days before the change of occupant and triple if under 10 days."]$j$::jsonb, $j$[{"label":"CCO, one-family dwelling (sale or rental), request received more than 20 business days before the change of occupant","amount":"$100.00"},{"label":"CCO, two-family dwelling (sale or rental), request received more than 20 business days before the change of occupant","amount":"$150.00"},{"label":"CCO request received 10 to 20 days before the change of occupant","amount":"$200.00 one-family, $300.00 two-family (double the base fee)"},{"label":"CCO request received less than 10 days before the change of occupant","amount":"$300.00 one-family, $450.00 two-family (triple the base fee)"}]$j$::jsonb, $t$https://www.bogotanj.gov/_files/ugd/8d609e_2346f3c07d424c37807d86013e6fad2d.pdf$t$, $t$https://www.bogotanj.gov/building-department$t$, $j$[{"url":"https://www.bogotanj.gov/forms","label":"Official source (bogotanj.gov)"},{"url":"https://www.bogotanj.gov/_files/ugd/8d609e_2346f3c07d424c37807d86013e6fad2d.pdf","label":"Official source (bogotanj.gov)"},{"url":"https://ecode360.com/34713647","label":"Official source (ecode360.com)"},{"url":"https://www.bogotanj.gov/building-department","label":"Official source (bogotanj.gov)"}]$j$::jsonb, $t$(CCO) Permit Application$t$, $t$d78ce05caa84cc9c9c4387f32d07cefe6df6e348bd1f65b8deefd28172be4877$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":0,"fee_bad":0,"fee_unchecked":6,"quotes":14,"q_ok":7,"q_bad":0,"q_unchecked":7},"source":"property/data/municipal-requirements/checked/0204.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0204.json$t$, true),
  ($t$0204$t$, $t$Bogota Borough$t$, $t$BERGEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Borough of Bogota Building Department (smoke detector compliance on the CCO form); fire code enforcing agency: Bogota Bureau of Fire Prevention (town fire bureau)","Contact: Daniel Klima, Fire Marshal (Fire Official) · 201-646-0801 · fireprevention@bogotaonline.org","Apply: Same as the CCO: base fee more than 20 business days before the change of occupant, double at 10 to 20 days, triple at under 10 days.","How to apply: File the Borough's CCO / smoke detector, carbon monoxide and fire extinguisher certification application with the Building Department at 375 Larch Avenue. Questions about alarm rules can go to the Fire Prevention Bureau at 31 Fairview Avenue.","Fire official in the NJ state directory, updated 5/14/2026: Daniel Klima · (201) 342-1736 · dklima@bogotaonline.org","Smoke detectors and carbon monoxide alarms checked on the Borough's combined smoke detector / carbon monoxide / fire extinguisher certification (the CCO application)","Access to the dwelling unit, basement, attic and common areas","Fire extinguisher (form still lists it)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke/CO certification on the CCO, one-family (same fee as the CCO, not an extra charge)","amount":"$100.00"},{"label":"Smoke/CO certification on the CCO, two-family (same fee as the CCO, not an extra charge)","amount":"$150.00"}]$j$::jsonb, $t$https://www.bogotanj.gov/_files/ugd/8d609e_2346f3c07d424c37807d86013e6fad2d.pdf$t$, $t$https://www.bogotanj.gov/fire-prevention$t$, $j$[{"url":"https://www.bogotanj.gov/_files/ugd/8d609e_2346f3c07d424c37807d86013e6fad2d.pdf","label":"Official source (bogotanj.gov)"},{"url":"https://www.bogotanj.gov/fire-prevention","label":"Official source (bogotanj.gov)"},{"url":"https://ecode360.com/34716012","label":"Official source (ecode360.com)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://ecode360.com/34713647","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$SMOKE DETECTOR - CARBON MONOXIDE - FIRE EXTINGUISHER CERTIFICATION$t$, $t$b46e87a196d0ee3148c1051d409c981442f847c94a7ef8c1017274d2705de7c0$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":0,"fee_bad":0,"fee_unchecked":6,"quotes":14,"q_ok":7,"q_bad":0,"q_unchecked":7},"source":"property/data/municipal-requirements/checked/0204.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0204.json$t$, true),
  ($t$0205$t$, $t$Carlstadt Borough$t$, $t$BERGEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Zoning & Property Maintenance Compliance (Certificate of Zoning Compliance on change of ownership)$t$, $j$["Issued by: Borough of Carlstadt Zoning Department (Zoning Officer / zoning code enforcement official)","Contact: Frank Recanati, Zoning Officer · (201) 939-2304 · ZoningDept@CarlstadtNJ.us","Apply: Payment and application must be received before the inspection is scheduled. No published turnaround time.","How to apply: Fill out the Application For Residential and Commercial Certificate of Zoning & Property Maintenance Compliance (with the residential supplement) and return it with the $75 fee per unit to the Zoning Office, 500 Madison Street. Checks payable to Borough of Carlstadt. The inspection is scheduled after payment and application are received.","On-site inspection by a Zoning Inspector under Borough Ordinance 95-3 (zoning and property maintenance)","Required on the change of ownership of any residential property, whether one-, two- or multi-family","Complete and submit the Supplemental Information for Residential Certificate of Zoning Compliance with the application","Separate smoke detector / carbon monoxide alarm inspection by the Carlstadt Bureau of Fire Safety (separate fee)","For dwellings built before 1978, the residential supplement asks for a lead dust wipe test report from a licensed lead evaluation contractor (the form ties this to the lead-safe rental law; confirm whether it applies to an owner-occupied sale)","Also: Lead dust wipe test (pre-1978, confirm): The residential supplement to the zoning compliance application asks for a lead dust wipe test by a licensed lead evaluation contractor for dwellings built before 1978. The section is written around the state lead-safe rental law, so confirm whether the Zoning Office requires it for an owner-occupied sale."]$j$::jsonb, $j$[{"label":"Certificate of zoning compliance, on-site inspection per residential unit","amount":"$75.00"},{"label":"Certificate of zoning compliance, reinspection per unit","amount":"$50.00"},{"label":"Certificate of zoning compliance, additional copies of certificate","amount":"$15"}]$j$::jsonb, $t$https://www.carlstadtnj.us/_Content/pdf/forms/Commercial-Residential-Zoning-Compliance.pdf$t$, $t$https://www.carlstadtnj.us/forms$t$, $j$[{"url":"https://ecode360.com/27311689","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/27116954","label":"Official source (ecode360.com)"},{"url":"https://www.carlstadtnj.us/_Content/pdf/forms/Commercial-Residential-Zoning-Compliance.pdf","label":"Official source (carlstadtnj.us)"}]$j$::jsonb, $t$Upon the change of ownership of any residential property regardless of whether the property is designated as a one- or two- or multi-family dwelling in the tax records or the assessment records of the Borough.$t$, $t$e9b95d24db448602263cc075f7309e5a24f64930ed2222ef7c77cd3421497f79$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":3,"fee_bad":0,"fee_unchecked":1,"quotes":19,"q_ok":14,"q_bad":0,"q_unchecked":5},"source":"property/data/municipal-requirements/checked/0205.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0205.json$t$, true),
  ($t$0205$t$, $t$Carlstadt Borough$t$, $t$BERGEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Carlstadt Fire Department, Bureau of Fire Safety (town fire bureau)","Contact: Anthony M. Silleto III, Fire Official · (201) 460-3942 · firesafety@carlstadtnj.us","Apply: Payment and application must be received before the inspection is scheduled. Certificates are e-mailed at the time of inspection.","How to apply: Complete the Application For Smoke Detector & Carbon Monoxide Alarm Compliance Inspection and submit it with the $75.00 fee (cash, check or money order payable to Borough of Carlstadt) to the Bureau of Fire Safety, 500 Madison Street. The inspection is scheduled after payment is received. Certificates are valid for six months and are not transferable.","Fire official in the NJ state directory, updated 5/18/2026: Anthony M Silleto III · (201) 460-3942 · firesafety@carlstadtnj.us","Smoke alarm on every level and within 10 feet of every bedroom door; hardwired alarms may not be replaced with battery-operated ones","Alarm type depends on the year the house was built or renovated (sealed battery alarms for pre-1977 homes, electric/interconnected alarms for newer homes, per the Bureau's table)","Carbon monoxide alarm within 10 feet of every bedroom door in homes with a fuel-burning device or an attached garage (listed to UL-2034)","Central station / low voltage fire alarm systems must be tested and certified by the alarm company on an NFPA form; the Bureau will not test them","Owner or authorized agent must be present at the inspection","Portable fire extinguisher (still mentioned on the Borough's zoning supplement form, although state law dropped it from the sale certificate in February 2025)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke detector and carbon monoxide alarm compliance inspection (application fee, non-refundable)","amount":"$75.00"}]$j$::jsonb, $t$https://www.carlstadtnj.us/_Content/pdf/forms/Residential-fire-safety-certificate.pdf$t$, $t$https://www.carlstadtnj.us/departments/fire-department$t$, $j$[{"url":"https://www.carlstadtnj.us/_Content/pdf/forms/Residential-fire-safety-certificate.pdf","label":"Official source (carlstadtnj.us)"},{"url":"https://ecode360.com/27116944","label":"Official source (ecode360.com)"},{"url":"https://www.carlstadtnj.us/_Content/pdf/forms/Commercial-Residential-Zoning-Compliance.pdf","label":"Official source (carlstadtnj.us)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$the owner shall obtain a Certificate of Smoke Detector & Carbon Monoxide Alarm Compliance, evidencing compliance with NJAC 5:70-4.19 from the Carlstadt Fire Department Bureau of Fire Safety.$t$, $t$75ab41906c52397a3d7b8570970f36c6dc1c1c660602aad572010c976af2b7bd$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":3,"fee_bad":0,"fee_unchecked":1,"quotes":19,"q_ok":14,"q_bad":0,"q_unchecked":5},"source":"property/data/municipal-requirements/checked/0205.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0205.json$t$, true),
  ($t$0206$t$, $t$Cliffside Park Borough$t$, $t$BERGEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Continued Occupancy (CCO) for sale$t$, $j$["Issued by: Borough of Cliffside Park Fire Prevention Bureau (handles all CCO documents; shares the 2nd floor office with the Building Department)","Contact: Pamela Petermann, Secretary, Fire Prevention Bureau (Fire Official and Code Enforcement: Gregory Yfantis, 201-313-2063… · 201-313-2062 · pleone@cliffsideparknj.gov","Apply: Inspections must be requested at least a week before the closing or move-in date. Inspections are Tuesdays and Thursdays only, 10 AM to 12 PM or 1 PM to 3 PM, with a 2 hour window.","How to apply: Fill out the one page Certificate of Continued Occupancy form (Sale) from the Building Department's Applications and Permits page and bring it, with a property survey and two checks (one to \"Borough of Cliffside Park\" for the CCO, one to \"Cliffside Park Fire Prevention\" for the inspection), to the Fire Prevention Bureau, Municipal Complex, 525 Palisade Avenue, 2nd floor. All fees must be paid before the inspection is scheduled.","Survey of the property is required for 1 or 2 family homes (not for condominiums); without it no CCO is issued","Two separate payments by check or money order (no cash, no credit cards): $50.00 CCO fee to the Borough and $75.00 inspection fee to Cliffside Park Fire Prevention","Smoke and carbon monoxide detectors on each level within 10 feet of each bedroom; battery smoke detectors must be 10 year sealed and hardwired detectors must be under 10 years old","Fire extinguisher (under 10 pounds) mounted in the kitchen for 1 and 2 family homes (form still lists it)","Basement may not be used as a dwelling unit, only as a recreation and family room","One inspector does the CCO and smoke/CO inspection together; paperwork is handed over at the end of the inspection","Also: Property survey: A survey of the property must be submitted with the sale CCO application for 1 or 2 family homes (not condominiums)."]$j$::jsonb, $j$[{"label":"Certificate of Continued Occupancy, 1 or 2 family dwelling","amount":"$50.00"},{"label":"Certificate of Continued Occupancy, condo/co-op","amount":"$50.00"},{"label":"Certificate of Continued Occupancy (Borough fee schedule, Section 11-1.4)","amount":"$50.00"},{"label":"Smoke and carbon monoxide inspection fee (sale), payable to Cliffside Park Fire Prevention","amount":"$75.00"}]$j$::jsonb, $t$https://www.cliffsideparknj.gov/Sale%20CCO%20New.pdf$t$, $t$https://www.cliffsideparknj.gov/departments/fire_prevention_bureau.php$t$, $j$[{"url":"https://www.cliffsideparknj.gov/departments/building_department/index.php","label":"Official source (cliffsideparknj.gov)"},{"url":"https://www.cliffsideparknj.gov/departments/building_department/applications_and_permits.php","label":"Official source (cliffsideparknj.gov)"},{"url":"https://www.cliffsideparknj.gov/Sale%20CCO%20New.pdf","label":"Official source (cliffsideparknj.gov)"},{"url":"https://ecode360.com/35162510","label":"Official source (ecode360.com)"},{"url":"https://www.cliffsideparknj.gov/departments/fire_prevention_bureau.php","label":"Official source (cliffsideparknj.gov)"}]$j$::jsonb, $t$Certificate of Occupancy, Required for sale of property.$t$, $t$4a7a792348dc61f0f09c915d15c23eb790fdee224b72e5d0956f99a3f6b49c75$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":0,"fee_bad":0,"fee_unchecked":5,"quotes":19,"q_ok":6,"q_bad":0,"q_unchecked":13},"source":"property/data/municipal-requirements/checked/0206.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0206.json$t$, true),
  ($t$0206$t$, $t$Cliffside Park Borough$t$, $t$BERGEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Cliffside Park Fire Prevention Bureau (town fire bureau)","Contact: Gregory Yfantis, Fire Official & Code Enforcement · 201-313-2062 · gyfantis@cliffsideparknj.gov","Apply: Request at least a week before closing. Inspections Tuesdays and Thursdays, 10 AM to 12 PM or 1 PM to 3 PM. The smoke/CO inspection is done at the same visit as the CCO inspection.","How to apply: Applied for together with the sale CCO: there is no separate Fire Prevention paperwork. Pay the $75.00 inspection fee by check or money order to \"Cliffside Park Fire Prevention\" at the Fire Prevention Bureau, 525 Palisade Avenue, 2nd floor.","Fire official in the NJ state directory, updated 2/26/2026: Gregory Yfantis · (201) 313-2063 · gyfantis@cliffsideparknj.gov","Smoke and carbon monoxide detectors on each level within 10 feet of each bedroom (common hallway)","All battery smoke detectors must be 10 year sealed; hardwired smoke detectors must be under 10 years old","Fire extinguisher (under 10 pounds) mounted in the kitchen (form still lists it)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke and carbon monoxide inspection fee (sale), payable to Cliffside Park Fire Prevention","amount":"$75.00"}]$j$::jsonb, $t$https://www.cliffsideparknj.gov/Sale%20CCO%20New.pdf$t$, $t$https://www.cliffsideparknj.gov/departments/fire_prevention_bureau.php$t$, $j$[{"url":"https://www.cliffsideparknj.gov/Sale%20CCO%20New.pdf","label":"Official source (cliffsideparknj.gov)"},{"url":"https://www.cliffsideparknj.gov/departments/fire_prevention_bureau.php","label":"Official source (cliffsideparknj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$There is NO PAPERWORK for Fire Prevention, this is the only form you need to fill out.$t$, $t$609303071ab3e0f32aa31a980c01f338ac9ad1fd05f05e82df5504a4b5fad78b$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":0,"fee_bad":0,"fee_unchecked":5,"quotes":19,"q_ok":6,"q_bad":0,"q_unchecked":13},"source":"property/data/municipal-requirements/checked/0206.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0206.json$t$, true),
  ($t$0207$t$, $t$Closter Borough$t$, $t$BERGEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Residential Certificate of Continued Occupancy (RCCO)$t$, $j$["Issued by: Borough of Closter Building Department (Code Enforcement Bureau / Construction Code Official)","Contact: 201-784-0600 ext. 441 · construction@closternj.us","Apply: The code gives the Borough up to 21 days after a complete application to issue the certificate or a written denial. Construction Official inspections are Monday to Friday, 8:30 AM to 11:30 AM.","How to apply: Submit the Residential Certificate of Continued Occupancy (RCCO) & Lead Paint Application (form BOC-3) with the fee to the Code Enforcement Bureau, 295 Closter Dock Road, Closter, NJ 07624, checking 'Change of Ownership (RESALE)'. Include the signature page of the sale contract. Then schedule the inspection with the Construction Official at (201) 784-0600 ext. 441 or construction@closternj.us. Separately schedule the smoke/CO inspection with the Fire Marshal.","Valid for: A temporary certificate of continued occupancy (with escrow held by the attorneys) may be issued for up to 90 days unless extenuating circumstances are shown.","Smoke detector certificate from the Closter Fire Prevention Bureau, and carbon monoxide detectors properly installed, before the RCCO is issued","Abate zoning and property maintenance violations","Finalize and close out open construction permits","Signature page of the purchase and sale contract showing all parties on the new deed (resales only)","Abate hazardous or unsightly conditions, including Borough sidewalks, private walkways, gutters, downspouts, windows, cladding, wiring, venting, surface water, fencing and pool barriers, and handrails on stairs with 3 or more risers","Disconnect or reroute sump pumps from the Borough sanitary sewer (construction permit required)","Remove double-key locks on the primary exterior door","Display the street address in numbers on the front of the house","Lead-safe or lead-free paint certificate only for rental units built before 1978 (not required for a sale)","Also: Sump pump disconnection: Sump pumps must be disconnected or rerouted from the Borough sanitary sewer before the RCCO is issued (construction permit required).","Also: Sidewalks and exterior conditions: The RCCO inspection requires hazardous or unsightly conditions to be fixed, including Borough sidewalks, walkways, gutters and pool barriers.","Also: Open permits and violations: Open construction permits must be closed and zoning and property maintenance violations abated before the RCCO is issued."]$j$::jsonb, $j$[{"label":"RCCO inspection, one dwelling unit","amount":"$100.00"},{"label":"RCCO inspection, each additional dwelling unit (for example a 2 family)","amount":"$40.00"}]$j$::jsonb, $t$https://core-docs.s3.us-east-1.amazonaws.com/documents/asset/uploaded_file/4528/BOC/3875048/RCCO___Lead_Paint.pdf$t$, $t$https://www.closterboro.com/page/building-department-copy$t$, $j$[{"url":"https://core-docs.s3.us-east-1.amazonaws.com/documents/asset/uploaded_file/4528/BOC/5334162/RCCO___Lead_Paint_Instructions.pdf","label":"Official source (core-docs.s3.us-east-1.amazonaws.com)"},{"url":"https://core-docs.s3.us-east-1.amazonaws.com/documents/asset/uploaded_file/4528/BOC/3875048/RCCO___Lead_Paint.pdf","label":"Official source (core-docs.s3.us-east-1.amazonaws.com)"},{"url":"https://www.closterboro.com/page/building-department-copy","label":"Official source (closterboro.com)"},{"url":"https://ecode360.com/7048411","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$A RESIDENTIAL CERTIFICATE OF CONTINUED OCCUPANCY IS REQUIRED PRIOR TO THE RENTAL OR RESALE OF 1-, 2- AND MULTIPLE-FAMILY DWELLING UNITS.$t$, $t$4728835cf4e71cd0c97a0f8dd7fdf8443eb1c6704562097f3d0fa734111bf182$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":2,"fee_bad":0,"fee_unchecked":1,"quotes":16,"q_ok":7,"q_bad":0,"q_unchecked":9},"source":"property/data/municipal-requirements/checked/0207.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0207.json$t$, true),
  ($t$0207$t$, $t$Closter Borough$t$, $t$BERGEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Closter Fire Prevention Bureau (Borough of Closter) (town fire bureau)","Contact: Kevin Whitney, Fire Marshal · 201-768-3698 · fireprev@closternj.us","Apply: Inspections are only on Saturday mornings and must be scheduled at least two weeks in advance. The bureau is part time; calls are normally returned within 24 hours.","How to apply: Call the Fire Prevention Bureau at 201-768-3698 (leave a voicemail) or email fireprev@closternj.us at least two weeks ahead to book a Saturday morning inspection. Pay $50.00 at the inspection by check or money order payable to \"Borough of Closter\".","Fire official in the NJ state directory (town), updated 2/18/2026: Kevin Whitney · (201) 768-3698 · fireprev@closterboro.com","Smoke detectors: one per floor including the basement, and one within 10 feet of all bedrooms","Carbon monoxide units: one within 10 feet of all bedrooms","Inspection must be done before the closing","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke and carbon monoxide detector inspection for a home sale","amount":"$50.00"}]$j$::jsonb, null, $t$https://www.closterboro.com/page/fire-prevention-bureau$t$, $j$[{"url":"https://www.closterboro.com/page/fire-prevention-bureau","label":"Official source (closterboro.com)"},{"url":"https://core-docs.s3.us-east-1.amazonaws.com/documents/asset/uploaded_file/4528/BOC/5334162/RCCO___Lead_Paint_Instructions.pdf","label":"Official source (core-docs.s3.us-east-1.amazonaws.com)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Inspections are conducted only on Saturday mornings. All requests must be scheduled at least two weeks in advance.$t$, $t$5eef70c4896110b0ab271dd293b91c6c3f4a096fe0087b35aca2acb244982d7b$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":2,"fee_bad":0,"fee_unchecked":1,"quotes":16,"q_ok":7,"q_bad":0,"q_unchecked":9},"source":"property/data/municipal-requirements/checked/0207.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0207.json$t$, true),
  ($t$0208$t$, $t$Cresskill Borough$t$, $t$BERGEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Residential Resale/Rental Certificate (inspection certificate for resale)$t$, $j$["Issued by: Borough of Cresskill Building Department (Construction Official)","Contact: Linda Ziccarelli, Certificate Coordinator (application form; email lziccarelli@cresskillboro.org, phone (201) 569-5400). Construction… · 201-569-7775 · bldgdept@cresskillboro.org","Apply: Code says the inspection is done within 10 days after the written request and payment, and the certificate is issued or denied within 10 working days after entry. Fees go up for requests made 10 or fewer business days before the inspection.","How to apply: Fill out the Residential Resale/Rental Certificate Application (Building Department forms page) and submit it with a check payable to Borough of Cresskill to Borough Hall, 67 Union Avenue. One check can cover both the building and fire inspections. Close any open permits first. Building inspection times are set by the office.","Written application to the Construction Official with seller, buyer, closing date and room details","All open permits must be inspected and closed before the resale inspection can be scheduled","Visual inspection for flue connections, permitted water heaters and mechanical equipment, sump pumps not tied to the sanitary sewer, stove anti-tip brackets, rigid kitchen exhaust ducts, covered outlets and panels, no lamp cords on fixed appliances","Handrails on four or more risers, guards on landings 30 inches above grade and open basement stairs, garage walls and ceilings next to the house sheetrocked","Pool gates and fencing self-closing and latching (latches 54 inches above grade); lawn and bushes neatly trimmed","Real estate sign needs a sign permit (asked on the application)","Monitored alarm: have the password or someone on site to turn it off","Separate smoke/CO certificate from the Fire Prevention Division (one check can cover both)","Also: Open permits: All open permits must be inspected and closed before the resale inspection can be scheduled.","Also: Real estate sign permit: The resale application asks whether a real estate sign is on the property; if so a sign permit or permit number is needed."]$j$::jsonb, $j$[{"label":"Resale/rental certificate, request more than 10 business days before inspection (application form; office says one check can cover building and fire inspections)","amount":"$200"},{"label":"Request 4 to 10 business days before inspection (application form)","amount":"$250"},{"label":"Request less than 4 business days before inspection (application form)","amount":"$300"},{"label":"Reinspection if the first inspection fails (application form)","amount":"$50"},{"label":"Certificate for resale/rental, request more than 10 business days before inspection (Code 207-31, amended 3-5-2025)","amount":"$100"},{"label":"Code 207-31, request 4 to 10 business days before inspection","amount":"$125"},{"label":"Code 207-31, request fewer than 4 business days before inspection","amount":"$150"}]$j$::jsonb, $t$https://www.cresskillboro.com/index.php/government/forms/construction/848-residential-resale-rental-certificate-application/file$t$, $t$https://www.cresskillboro.com/index.php/departments/construction$t$, $j$[{"url":"https://ecode360.com/41836230","label":"Official source (ecode360.com)"},{"url":"https://www.cresskillboro.com/index.php/government/forms/construction/848-residential-resale-rental-certificate-application/file","label":"Official source (cresskillboro.com)"},{"url":"https://www.cresskillboro.com/index.php/departments/construction","label":"Official source (cresskillboro.com)"},{"url":"https://www.cresskillboro.com/government/forms/construction","label":"Official source (cresskillboro.com)"}]$j$::jsonb, $t$No property owner and/or landlord shall authorize resale occupancy or rent, leave, sublet, or permit residual stay, pursuant to a tenancy or a use and occupancy, transfer title to a new owner, new co-tenants, or a new co-owner, in any new or previously constructed residential dwelling unit or structure within the Borough of Cresskill unless that person or entity shall have first obtained either a certificate of occupancy, or resale and/or rental certificate.$t$, $t$ad222ded505067f275d5bb5c4eddc3a1288f873dc60c1abfb4ee6b9d3a7c8a0f$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":12,"fee_ok":4,"fee_bad":0,"fee_unchecked":8,"quotes":17,"q_ok":10,"q_bad":0,"q_unchecked":7},"source":"property/data/municipal-requirements/checked/0208.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0208.json$t$, true),
  ($t$0208$t$, $t$Cresskill Borough$t$, $t$BERGEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Cresskill Fire Department, Division of Fire Prevention (town fire bureau)","Contact: David Haenelt, Fire Marshal (Fire Official); ext. 705 · (201) 568-0030 · DHaenelt@cresskillboro.org","Apply: Fee depends on business days between the request and the inspection (more than 10 business days for the lowest fee). Inspections Monday to Friday 9:30 to 11:30 am; certificates ready after 12:00 pm the next business day. Certificate valid 6 months.","How to apply: Fill out the Smoke Detector & Carbon Monoxide Alarm Compliance Certificate Application (page 2 of the resale/rental packet) and pay by cash, check or online payment. Someone must be present during the inspection window. If the home has a monitored alarm system as the primary system, bring an NFPA 72 inspection report dated within 30 days.","Fire official in the NJ state directory, updated 7/28/2026: David A Haenelt · (201) 569-5400 · dhaenelt@cresskillboro.org","Smoke alarm on every level including the basement (not needed in an unfinished attic); on sleeping floors within 10 feet of all bedroom doors","Alarm type depends on when the home was built or renovated (battery on all levels before 1977 up to hardwired, interconnected with battery backup in every bedroom since March 1991); electric alarms cannot be replaced with battery alarms","Any smoke alarm more than 10 years old must be replaced; alarms must be properly mounted (no Velcro or tape)","Two-family homes: smoke alarm at each landing of common halls and stairways","CO alarm within 10 feet of all bedroom doors in homes with fuel-burning appliances, fireplaces or attached garages (UL 2034, NFPA 720); stand-alone CO alarms are treated as expired after 5 to 7 years unless documentation shows a longer life","Low-voltage fire alarm systems are not tested by the Division; an NFPA 72 report from an approved contractor, no more than 30 days old, is required","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke and CO certificate, request more than 10 business days before inspection (Code 128-12, amended 3-5-2025)","amount":"$100"},{"label":"Request 4 to 10 business days before inspection","amount":"$125"},{"label":"Request fewer than 4 business days before inspection","amount":"$150"},{"label":"Reinspection, per occurrence","amount":"$50"},{"label":"Penalty for failing to get the certificate","amount":"$500"}]$j$::jsonb, $t$https://www.cresskillboro.com/index.php/government/forms/construction/848-residential-resale-rental-certificate-application/file$t$, $t$https://www.cresskillboro.com/index.php/departments/fire-prevention$t$, $j$[{"url":"https://www.cresskillboro.com/index.php/government/forms/fire-prevention/1222-cresskill-smoke-co-requirements/file","label":"Official source (cresskillboro.com)"},{"url":"https://www.cresskillboro.com/index.php/government/forms/construction/848-residential-resale-rental-certificate-application/file","label":"Official source (cresskillboro.com)"},{"url":"https://ecode360.com/6269071","label":"Official source (ecode360.com)"},{"url":"https://www.cresskillboro.com/index.php/departments/fire-prevention","label":"Official source (cresskillboro.com)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$A Certificate of Smoke Alarm and Carbon Monoxide Alarm (CSACMAC) is required before any residential unit is sold, leased or otherwise made subject to change of occupancy for residential purposes.$t$, $t$aa7325eeb94d9bf6149fcaba43524bc4f26118d6dbc5c828b3513dd6fd93e45e$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":12,"fee_ok":4,"fee_bad":0,"fee_unchecked":8,"quotes":17,"q_ok":10,"q_bad":0,"q_unchecked":7},"source":"property/data/municipal-requirements/checked/0208.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0208.json$t$, true),
  ($t$0209$t$, $t$Demarest Borough$t$, $t$BERGEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Rental/Resale Certificate (certificate of occupancy on resale, also called continued certificate of occupancy)$t$, $j$["Issued by: Borough of Demarest Building Department (Construction Official)","Contact: Dot Haight, Technical Assistant, Building Department · 201-768-3398 · dhaight@demarestnj.gov","Apply: The Borough says the process takes about 4 to 6 weeks, so allow ample time. The code says the certificate may be issued up to two weeks before the closing.","How to apply: Fill out the Borough's Application for Rental Resale Certificate (circle Resale), and pay by check payable to The Borough of Demarest ($115 total: $75.00 building and $40.00 fire). Turn it in to the Building Department at 118 Serpentine Road, Demarest, NJ 07627 (Monday to Friday, 8:00 to 3:00, closed 1 to 2 for lunch). Questions go to Dot Haight at 201-768-3398.","Complete the Rental/Resale Certificate application, pay the fees and have the home inspected before any change in occupancy","Building inspection: no visible safety problems (such as missing hand or guard rails), no illegal work done without permits, and no illegal conversions (for example one family to two family)","Fire inspection of smoke and carbon monoxide detectors is done as part of the same application (see fire certificate)","Sump pumps must discharge onto the property or the street, not into the Borough sewer","Common fail items on the Borough checklist: handrail on stairs with 4 or more risers, enclosed stair risers, working bedroom windows, house numbers 4 to 6 inches, visible hydrant, secondary power source warning label at the electric panel and meter, neat property, stove tip bracket, even walkways","The applicant must arrange removal of all household materials and garbage","The Borough advises the realtor be present for all inspections","Also: Sump pump discharge: The resale inspection checks that any sump pump empties onto the property or the street and is not tied into the Borough sewer.","Also: Secondary power source label: Homes with a generator, solar panels or battery storage need a printed warning label (for example 'CAUTION: MULTIPLE SOURCES OF POWER') within 18 inches of the main electric panel and meter.","Also: Open permits and illegal work: The certificate is issued only if there has been no illegal work performed without permits and inspections and no illegal conversions."]$j$::jsonb, $j$[{"label":"Resale/rental certificate, building inspection","amount":"$75.00"},{"label":"Total check for building and fire inspections","amount":"$115"},{"label":"Continued certificate of occupancy inspection fee (code)","amount":"$75"},{"label":"Additional fee on issuance of the certificate of occupancy (code)","amount":"$35"},{"label":"Reinspection, change of occupancy of a 1 or 2 household dwelling (application form, Ord. 1101-22)","amount":"$50"}]$j$::jsonb, $t$https://www.demarestnj.gov/government/forms/construction/1942-rental-resale-certificate-application/file$t$, $t$https://www.demarestnj.gov/departments/construction$t$, $j$[{"url":"https://www.demarestnj.gov/departments/construction","label":"Official source (demarestnj.gov)"},{"url":"https://ecode360.com/31312659","label":"Official source (ecode360.com)"},{"url":"https://www.demarestnj.gov/government/forms/construction/1942-rental-resale-certificate-application/file","label":"Official source (demarestnj.gov)"}]$j$::jsonb, $t$Please be advised that in order to rent or sell your home a Rental/Resale Certificate is required.$t$, $t$5c21f144bd94d066bd73f421fa9b18b752bd3a4fbdce83320cae2090cae1dc26$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":8,"fee_ok":4,"fee_bad":0,"fee_unchecked":4,"quotes":14,"q_ok":11,"q_bad":0,"q_unchecked":3},"source":"property/data/municipal-requirements/checked/0209.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0209.json$t$, true),
  ($t$0209$t$, $t$Demarest Borough$t$, $t$BERGEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Demarest Borough Fire Prevention (Fire Official), inspected through the Building Department resale application (town fire bureau)","Contact: Alan J Silverman, Fire Official · 201-768-3398 · firemusik@aol.com","Apply: Handled with the resale certificate, which the Borough says takes about 4 to 6 weeks. Fire subcode inspections are listed for Tuesday 1 to 3 pm and Friday 1 to 2 pm.","How to apply: Use the same Application for Rental Resale Certificate as the building inspection; the $40.00 fire fee is included in the $115 check to The Borough of Demarest. File it at the Building Department, 118 Serpentine Road, and the office schedules the fire and building inspections.","Fire official in the NJ state directory, updated 3/2/2026: Alan J Silverman · (201) 768-3398 · firemusik@aol.com","Smoke detector on each level, including walk-up attic and basement (basement detector on the ceiling at the foot of the stairs)","Smoke detector on the ceiling within 10 feet of each sleeping area, in a common area, not inside bedrooms; extra detectors if bedrooms are in a separate area","Battery-only smoke detectors must be 10-year sealed battery units listed to ANSI/UL 217; hardwired (110V) detectors may not be replaced with battery units","Carbon monoxide detector within 10 feet of any sleeping area (not inside bedrooms); battery operated is allowed","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke detector certificate application, 1 or 2 household dwelling (code)","amount":"$40"},{"label":"Smoke detector certificate reinspection (code)","amount":"$40"},{"label":"Fire inspection portion of the resale application","amount":"$40.00"}]$j$::jsonb, $t$https://www.demarestnj.gov/government/forms/construction/1942-rental-resale-certificate-application/file$t$, $t$https://www.demarestnj.gov/departments/construction$t$, $j$[{"url":"https://www.demarestnj.gov/government/forms/construction/1942-rental-resale-certificate-application/file","label":"Official source (demarestnj.gov)"},{"url":"https://www.demarestnj.gov/departments/construction","label":"Official source (demarestnj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://ecode360.com/31312659","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$No certificate shall be issued for any structure unless an approved “Automatic Fire Detection System” and Carbon Monoxide Detector is installed per NFiPA-72 or 74 and N.J.A.C. 5:70-2.3.$t$, $t$5c3652fb46b793d16dd06bd74dc40e265a66146123d9133e0316ddc4e9cc902b$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":8,"fee_ok":4,"fee_bad":0,"fee_unchecked":4,"quotes":14,"q_ok":11,"q_bad":0,"q_unchecked":3},"source":"property/data/municipal-requirements/checked/0209.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0209.json$t$, true),
  ($t$0210$t$, $t$Dumont Borough$t$, $t$BERGEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Resale and/or Rental Certificate (Certificate of Continued Occupancy, CCO)$t$, $j$["Issued by: Borough of Dumont Building Department (building and fire inspections)","Contact: Vincent Bruno, Construction Official · 201-387-5034 · vbruno@dumontboro.org","Apply: Inspections are only on Tuesdays and Thursdays between 9:00 am and 11:00 am. The base fee assumes 11 or more business days' notice; shorter notice costs more. Open permits must be closed before the resale inspection.","How to apply: Fill out the Borough's Resale and/or Rental Certificate Application completely (single or two family, closing date, buyer and seller, room counts, open permits) and submit it to the Building Department, 50 Washington Avenue, with a check payable to the Borough of Dumont. One payment covers both the building and the fire (smoke/CO) inspections. The Building Department then schedules the inspection for a Tuesday or Thursday morning. Check for open permits first (openpermitinquiry@dumontboro.org).","All open permits must be inspected and closed before the resale inspection; no unpaid fees or property maintenance violations","Furnace/boiler flue connections properly sealed at the chimney","Water heater and mechanical equipment replaced under a permit, with an inspection sticker on the unit","Sump pump must discharge outside, not into the sanitary sewer","Anti-tip brackets on kitchen stoves where the maker requires them; rigid exhaust ducts for visible hood/microwave ducts where required","Electrical outlets, switches, boxes and panels covered; no lamp cords on fixed appliances","Handrails on 4 or more risers; guards on landings 30 inches above floor or grade and on open basement stairs","Garage walls and ceilings next to the house must be sheet-rocked","Pool fences and gates compliant (gates swing out, self-close and latch, latch 54 inches above grade); hot tubs need approved latches","Lawn and bushes neatly trimmed","Bedroom and bathroom count must match the property tax record","Smoke alarm on every level, less than 10 years old, 10-year sealed battery or hardwired","Carbon monoxide alarm within 10 feet of every bedroom (battery or plug-in)","For a 1 or 2 family resale, the buyer signs a notarized basement/attic use agreement (no separate dwelling unit, no bedrooms or cooking in the basement or attic)","Someone over 18 must be home for the inspection window","Also: Open permits: All open permits must be inspected and closed before the resale inspection. Questions about older permits: openpermitinquiry@dumontboro.org.","Also: Basement/attic use agreement: For a 1 or 2 family resale the new owner signs a notarized agreement that the basement or attic will not be used as a separate dwelling unit, for bedrooms, or for cooking.","Also: Sump pump: Sump pumps must discharge outside and cannot be connected to the sanitary sewer; checked during the resale inspection."]$j$::jsonb, $j$[{"label":"Resale certificate, single family (building and fire inspections together), 11 or more business days' notice","amount":"$125"},{"label":"Resale certificate, two family or multi-family, 11 or more business days' notice","amount":"$135"},{"label":"Extra charge, inspection with 5 to 10 business days' notice","amount":"$25"},{"label":"Extra charge, inspection with 1 to 4 business days' notice","amount":"$100"},{"label":"CCO for sale, one-family (Borough code 182-2, inspection 10 or more days before closing)","amount":"$75"},{"label":"CCO for sale, two-family (Borough code 182-2, inspection 10 or more days before closing)","amount":"$85"},{"label":"Reinspection (Borough code 182-2)","amount":"$125"}]$j$::jsonb, $t$https://www.dumontnj.gov/api/v1/files/c8614330-8ae4-11f1-adad-c167157e1ec1/download$t$, $t$https://www.dumontnj.gov/building-department$t$, $j$[{"url":"https://www.dumontnj.gov/api/v1/files/c8614330-8ae4-11f1-adad-c167157e1ec1/download","label":"Official source (dumontnj.gov)"},{"url":"https://ecode360.com/9554134","label":"Official source (ecode360.com)"},{"url":"https://www.dumontnj.gov/building-department","label":"Official source (dumontnj.gov)"}]$j$::jsonb, $t$Resale and/or Rental Certificate Application$t$, $t$1f156ed8dfb87db2ed17db098b5d45900e135fda3d3fddc9fc7f6ce7daad8a36$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":12,"fee_ok":8,"fee_bad":0,"fee_unchecked":4,"quotes":13,"q_ok":7,"q_bad":0,"q_unchecked":6},"source":"property/data/municipal-requirements/checked/0210.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0210.json$t$, true),
  ($t$0210$t$, $t$Dumont Borough$t$, $t$BERGEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Borough of Dumont (municipal fire code enforcement; smoke/CO inspection done with the Building Department resale inspection) (town fire bureau)","Contact: David H Gluckman, Fire Official (NJ DCA fire directory) · 201-387-5034 · dgluckman@dumontboro.org","Apply: Inspected together with the resale certificate on Tuesday or Thursday mornings; 11 or more business days' notice for the base fee.","How to apply: Use the Borough's combined Resale and/or Rental Certificate Application; the one payment covers both the building and fire inspections.","Fire official in the NJ state directory (town), updated 2/19/2026: David H Gluckman · (201) 310-1482 · dgluckman@dumontboro.org","Smoke alarm on every level, less than 10 years old, with a 10-year sealed battery or hardwired","Carbon monoxide alarm within 10 feet of every bedroom (battery or plug-in accepted)","Is the alarm system monitored? (asked on the application)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Resale certificate, single family (building and fire inspections together), 11 or more business days' notice","amount":"$125"},{"label":"Resale certificate, two family or multi-family, 11 or more business days' notice","amount":"$135"},{"label":"Extra charge, inspection with 5 to 10 business days' notice","amount":"$25"},{"label":"Extra charge, inspection with 1 to 4 business days' notice","amount":"$100"},{"label":"Smoke detector compliance certificate (Borough code 182-2, payable to Dumont Fire Prevention Bureau)","amount":"$50"}]$j$::jsonb, $t$https://www.dumontnj.gov/api/v1/files/c8614330-8ae4-11f1-adad-c167157e1ec1/download$t$, $t$https://www.dumontnj.gov/building-department$t$, $j$[{"url":"https://www.dumontnj.gov/api/v1/files/c8614330-8ae4-11f1-adad-c167157e1ec1/download","label":"Official source (dumontnj.gov)"},{"url":"https://ecode360.com/9554134","label":"Official source (ecode360.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Payments include both Building and Fire inspections.$t$, $t$df0e9c20a7945cd347492d6d94a9121394024512453f96b450bc02ff951aff1b$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":12,"fee_ok":8,"fee_bad":0,"fee_unchecked":4,"quotes":13,"q_ok":7,"q_bad":0,"q_unchecked":6},"source":"property/data/municipal-requirements/checked/0210.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0210.json$t$, true),
  ($t$0211$t$, $t$Elmwood Park Borough$t$, $t$BERGEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Continuing Occupancy (CCO), called a Certificate of Re-Occupancy on the Building Department page$t$, $j$["Issued by: Borough of Elmwood Park Zoning Enforcement Officer (Building Department)","Contact: James DePadova, Zoning Officer (named in search results for the Building Department page; not confirmed on a fetched page) · 201-796-1457 x8802","How to apply: Apply to the Building Department (Zoning Enforcement Officer) at the Municipal Building, 182 Market Street, on the form the Enforcement Officer provides, and pay the fee. The Officer inspects the home and issues the certificate if no violations are found. The fee and inspection may be waived if the same home was inspected within the last 60 days with no physical change.","Apply on the Enforcement Officer's form and pay the fee; the Enforcement Officer then inspects for compliance with building, health, safety and fire codes and Borough ordinances","No new occupancy until any violations found are corrected","No CO or CCO is issued on a transfer of title while there are housing code violations; work done without required permits and approvals must be removed to the Construction Official's satisfaction","Smoke detector, carbon monoxide detector and fire extinguisher certificate from the Fire Prevention Bureau is a separate requirement (see fire certificate)","Also: Illegal or unpermitted work: To get a CO or CCO for a transfer of title, any work done without required permits and approvals must be removed to the Construction Official's satisfaction, and no CCO is issued while housing code violations exist."]$j$::jsonb, $j$[{"label":"Certificate of Continuing Occupancy, residential single-family dwelling","amount":"$100"},{"label":"Certificate of Continuing Occupancy, commercial multi-family or industrial","amount":"$275"}]$j$::jsonb, null, $t$https://www.elmwoodparknj.us/building-department$t$, $j$[{"url":"https://ecode360.com/35182540","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/35179182","label":"Official source (ecode360.com)"},{"url":"https://www.elmwoodparknj.us/building-department","label":"Official source (elmwoodparknj.us)"}]$j$::jsonb, $t$No person shall occupy or use any portion of a commercial, industrial or residential building after such building or portion thereof has been vacated or sold, or for which there has been a change in use or a change in occupancy, until the owner/landlord shall have applied for and secured a Certificate of Continuing Occupancy from the Zoning Enforcement Officer of the Borough of Elmwood Park.$t$, $t$248d01d8257e0b55fde5028132424c1886b18230e20a62c41d6b94b62f25e155$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":7,"fee_ok":0,"fee_bad":0,"fee_unchecked":7,"quotes":11,"q_ok":1,"q_bad":0,"q_unchecked":10},"source":"property/data/municipal-requirements/checked/0211.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0211.json$t$, true),
  ($t$0211$t$, $t$Elmwood Park Borough$t$, $t$BERGEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Elmwood Park Fire Prevention Bureau (town fire bureau)","Contact: Steven A Kochik, Fire Official · (201) 796-1795 · SKochik@elmwoodparknj.us","Apply: Fee must be prepaid with the application; the Fire Official then schedules the inspection. After a failure the owner has five days to correct (three days after a second failure). No published rush tiers.","How to apply: Apply to the Elmwood Park Fire Prevention Bureau, Municipal Building, 182 Market Street, Elmwood Park, NJ 07407, with the fee prepaid. The Bureau office hours are Monday to Friday, 8:30am to 1pm (per search results for the Bureau page).","Fire official in the NJ state directory, updated 3/2/2026: Steven A Kochik · (201) 796-1795 · SKochik@elmwoodparknj.us","Smoke detector on each level, including the basement ceiling; 10-year sealed battery single station alarms listed to ANSI/UL 217, and hardwired (A/C) alarms from original construction may not be replaced with battery alarms","Carbon monoxide alarm in the immediate vicinity of sleeping areas (battery, hard-wired or plug-in, UL 2034), unless the building has no fuel-burning device and no attached garage","Portable fire extinguisher installed and maintained per N.J.A.C. 5:70 (Borough code still lists it)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke detector, carbon monoxide detector and portable fire extinguisher certificate of inspection, single-family sale","amount":"$100"},{"label":"Same certificate, two-family sale","amount":"$125"},{"label":"Reinspection after a first failure (may be imposed)","amount":"$25"},{"label":"Reinspection after a second failure","amount":"$60"},{"label":"No-show fee (no one at the home to let the inspector in)","amount":"$25"}]$j$::jsonb, null, $t$https://elmwoodparknj.us/borough-directory/118-departments-offices/fire-prevention-bureau$t$, $j$[{"url":"https://ecode360.com/35179434","label":"Official source (ecode360.com)"},{"url":"https://elmwoodparknj.us/borough-directory/118-departments-offices/fire-prevention-bureau","label":"Official source (elmwoodparknj.us)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Upon the sale of a one- or two-family residence or the rental, lease or transfer of any dwelling unit, the seller, landlord or transferor is required to obtain from the Elmwood Park Fire Prevention Bureau, a smoke detector and carbon monoxide detector and portable fire extinguisher certificate of inspection, certifying that the smoke detectors and carbon monoxide detectors and fire extinguishers are in compliance with the provisions of the New Jersey Uniform Fire Code.$t$, $t$738107c0a844058968fd381bcebe6c44e4169a13b5f03abae215a323fa6f1628$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":7,"fee_ok":0,"fee_bad":0,"fee_unchecked":7,"quotes":11,"q_ok":1,"q_bad":0,"q_unchecked":10},"source":"property/data/municipal-requirements/checked/0211.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0211.json$t$, true),
  ($t$0213$t$, $t$Edgewater Borough$t$, $t$BERGEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Continued Occupancy (CCO) on resale$t$, $j$["Issued by: Edgewater Building Department (Construction Official as Enforcement Officer)","Contact: Art Sopelsa, Construction Official, Inspector/Building Sub-Code Official · 201-943-1700 ext. 3127 · asopelsa@edgewaternj.org","Apply: Code says the inspection is done within a reasonable time, not more than 30 days after a complete application. Residential CCO inspections are Tuesday and Thursday, 11:00 AM to 2:00 PM.","How to apply: Fill in and print the Commercial / Residential Certificate of Continued Occupancy application and bring it, with the fee and proof of paid taxes, to the Building Department, 55 River Road, Second Floor, Room 223. Someone must be at the home for the inspection (Tuesday or Thursday, 11 AM to 2 PM). Apply separately to the Fire Prevention Bureau for the sale Certificate of Compliance.","Apply before the sale; no one may occupy the home after a sale until the CCO is issued","Proof of paid taxes must be shown before the certificate is issued","Ten-year sealed battery smoke alarms within 10 feet of all sleeping areas on every level","Carbon monoxide detectors on every level, within 10 feet of sleeping areas, outside any room with a fuel-burning appliance and near an attached garage entrance","Handrails on all stairways with three or more risers","Must meet Hotel and Multiple Dwelling Law items (holes in walls, GFIs, paint)","Portable ABC fire extinguisher no larger than 10 pounds in or near the kitchen for 1 and 2 family homes (Borough code still lists it)","A separate Fire Prevention Bureau Certificate of Compliance is also required for sales","Also: Paid taxes: Proof of paid taxes must be shown before the Building Department issues the CCO, and the Fire Prevention COC needs all taxes, penalties and fees owed to the Borough paid.","Also: Open permits: The Fire Prevention Certificate of Compliance is only issued once all open building permits are closed."]$j$::jsonb, $j$[{"label":"Single family residential sale inspection, Building Department","amount":"$100"},{"label":"Two family residential sale inspection, Building Department","amount":"$125"},{"label":"Re-inspection, first failure","amount":"$50"},{"label":"Re-inspection, second failure","amount":"$75"},{"label":"Residential CCO (fee printed on the Building Department form)","amount":"$100.00"}]$j$::jsonb, $t$https://www.edgewaternj.org/DocumentCenter/View/12346/ComercialResidential-CCO$t$, $t$https://www.edgewaternj.org/152/Certificate-of-Continued-Occupancy$t$, $j$[{"url":"https://www.edgewaternj.org/149/Building-Department","label":"Official source (edgewaternj.org)"},{"url":"https://www.edgewaternj.org/152/Certificate-of-Continued-Occupancy","label":"Official source (edgewaternj.org)"},{"url":"https://ecode360.com/14392352","label":"Official source (ecode360.com)"},{"url":"https://www.edgewaternj.org/DocumentCenter/View/12205/2026-002-Repeal-Replace-Chapter-157-10-Fees-CCOpdf","label":"Official source (edgewaternj.org)"},{"url":"https://www.edgewaternj.org/DocumentCenter/View/12346/ComercialResidential-CCO","label":"Official source (edgewaternj.org)"}]$j$::jsonb, $t$Issue certificates of continued occupancy on the resale of buildings, condos and co-op units and rental of condo and co-ops$t$, $t$42796dbe69a12f3ec36a9c3b2a967a1a7f492a95d1943f7b9f3859d5cd0302a1$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":9,"fee_ok":9,"fee_bad":0,"fee_unchecked":0,"quotes":19,"q_ok":15,"q_bad":0,"q_unchecked":4},"source":"property/data/municipal-requirements/checked/0213.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0213.json$t$, true),
  ($t$0213$t$, $t$Edgewater Borough$t$, $t$BERGEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Edgewater Fire Prevention Bureau (Sale Certificate of Compliance) (town fire bureau)","Contact: Steven J. Curry, Fire Official / Fire Subcode Official · 201-943-1700 ext. 4116 or 4115 (secretaries); ext. 4117 (Fire Official) · stevenc@edgewaternj.org","Apply: Apply before the home is sold and before the new owner moves in. The inspector will not call before arriving and no exact arrival time is given.","How to apply: Fill out the 2026 Sale Smoke Certification Application (all pages) and return it with payment (cash, money order or check to the Borough of Edgewater Fire Prevention) to the Fire Prevention Bureau, 916 River Road, Floor 3. List a contact person who will meet the inspector. Applications must be accompanied with payment.","Fire official in the NJ state directory, updated 5/18/2026: Steven J Curry · (201) 943-1700 · stevenc@edgewaternj.org","Smoke alarms placed by year built: pre-1977 homes on each level and within 10 feet of sleeping areas (10-year sealed battery allowed); newer homes need 110V interconnected alarms as originally required","Any smoke alarm more than 10 years old must be replaced; battery alarms must be 10-year sealed, UL or ETL listed","Carbon monoxide detectors within 10 feet of all sleeping areas, on every level, outside any room with a fuel-burning appliance and near an attached garage entrance","CO detectors more than 5 years old must be replaced unless the maker allows longer (10 years for sealed combination units)","A COC is only issued once all open building permits are closed and all taxes, penalties and fees owed to the Borough are paid","No one may occupy the home before Fire Prevention Bureau approval","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Sale Certificate of Compliance (smoke/CO), application fee","amount":"$100"},{"label":"Re-inspection after first failure","amount":"$50.00"},{"label":"Each additional failure","amount":"$75.00"},{"label":"Two family residential sale inspection, Fire Prevention Bureau (ordinance)","amount":"$125"}]$j$::jsonb, $t$https://www.edgewaternj.org/DocumentCenter/View/12199/2026-Sale-Smoke-Certification-Application$t$, $t$https://www.edgewaternj.org/930/Applications-for-a-Certificate-of-Compli$t$, $j$[{"url":"https://www.edgewaternj.org/930/Applications-for-a-Certificate-of-Compli","label":"Official source (edgewaternj.org)"},{"url":"https://www.edgewaternj.org/DocumentCenter/View/12199/2026-Sale-Smoke-Certification-Application","label":"Official source (edgewaternj.org)"},{"url":"https://www.edgewaternj.org/DocumentCenter/View/12205/2026-002-Repeal-Replace-Chapter-157-10-Fees-CCOpdf","label":"Official source (edgewaternj.org)"},{"url":"https://www.edgewaternj.org/177/Bureau-of-Fire-Prevention","label":"Official source (edgewaternj.org)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$*** All rentals & sales must apply for a Certificate of Compliance Inspection with the Fire Prevention Bureau as well. A COC must be applied for before a property is sold or rented out and before the new owner or tenant moves in.***$t$, $t$292ba1cdc9fe5f4ba310e30d3520e2c81d67caafc6a155b2bf57b64d89226aed$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":9,"fee_ok":9,"fee_bad":0,"fee_unchecked":0,"quotes":19,"q_ok":15,"q_bad":0,"q_unchecked":4},"source":"property/data/municipal-requirements/checked/0213.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0213.json$t$, true),
  ($t$0214$t$, $t$Emerson Borough$t$, $t$BERGEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Residential Transfer of Ownership Certificate (Certificate of Continued Occupancy, CCO)$t$, $j$["Issued by: Borough of Emerson Building Department, with the Fire Prevention Bureau doing the smoke/CO part","Contact: Scott Wickersheim, Construction Official (Technical Assistant: Patty Rusch) · 201-262-6086 ext. 1214 · buildingadmin@emersonnj.gov","Apply: The Borough recommends applying 3 to 4 weeks before the closing date","How to apply: Fill out the Borough's Application for Residential Transfer of Ownership Certificate (on the Forms page), give the closing date, seller, buyer, block and lot and a contact, and pay two checks: the CCO fee to the Borough of Emerson and the smoke/CO fee to the Fire Prevention Bureau. Payments and paperwork can be left in the drop box by the Building Department window on the Municipal Place side of Borough Hall. Questions go to the Building Department at 201-262-6086 ext. 1214 or buildingadmin@emersonnj.gov.","Combined application for the transfer of ownership certificate and the smoke alarm / carbon monoxide alarm / fire extinguisher inspection (one form, two checks)","Homeowner checklist used at the CCO inspection: smoke alarms on each level and within 10 feet of bedrooms, CO alarms near bedrooms, fire extinguisher mounted in the kitchen (form still lists it)","In-ground oil tanks must have certification","Sump pump must drain to the exterior, not into the waste line","Monitored fire alarms need a certification from the monitoring company and police registration","Garage door openers on a dedicated outlet; keyless deadbolt on the inside of the front door; working GFI outlets in the kitchen; dryer vented outside","Bedroom windows must operate and be the correct size for egress; house number visible from the street; hydrant on the property kept visible","Pool barrier in good repair with self-closing, self-latching gates; property neat and clean; secure flue connections at boiler, furnace and water heater","Also: Oil tank certification: The CCO homeowner checklist says in-ground oil tanks must have certification.","Also: Sump pump discharge: The CCO checklist requires the sump pump to drain to the exterior, not into the waste (sewer) line.","Also: Monitored fire alarm certification: If the home has a monitored fire alarm, a certification from the monitoring company that it works is needed, and the system must be registered with the Police."]$j$::jsonb, $j$[{"label":"Certificate of Continued Occupancy (CCO) for a residential transfer, check to Borough of Emerson","amount":"$105"},{"label":"Certificate of continued occupancy, UCC applicant requested, general visual inspection (Code Section 132-3)","amount":"$125 per subcode"},{"label":"Reinspection after a failed inspection","amount":"$45.00"}]$j$::jsonb, $t$https://emersonnj.gov/vertical/sites/%7B3CE7C79E-1CDE-42D4-BE99-DEDBCE95F9A4%7D/uploads/Residential_Transfer_Form.pdf$t$, $t$https://emersonnj.gov/index.asp?SEC=CAE99956-793B-48C6-930F-762AC417DF10$t$, $j$[{"url":"https://emersonnj.gov/vertical/sites/%7B3CE7C79E-1CDE-42D4-BE99-DEDBCE95F9A4%7D/uploads/Residential_Transfer_Form.pdf","label":"Official source (emersonnj.gov)"},{"url":"https://ecode360.com/11485696","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/11485664","label":"Official source (ecode360.com)"},{"url":"https://emersonnj.gov/index.asp?SEC=CAE99956-793B-48C6-930F-762AC417DF10","label":"Official source (emersonnj.gov)"}]$j$::jsonb, $t$(Per Ordinance No. 1618-20)$t$, $t$cf4a0c268d6a4f6ebd23a6178a1f738736a397864286c816951a804d2c19a049$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":8,"fee_ok":3,"fee_bad":0,"fee_unchecked":5,"quotes":16,"q_ok":12,"q_bad":0,"q_unchecked":4},"source":"property/data/municipal-requirements/checked/0214.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0214.json$t$, true),
  ($t$0214$t$, $t$Emerson Borough$t$, $t$BERGEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Emerson Fire Prevention Bureau (town fire bureau)","Contact: AJ Sottile, Fire Official · 201-927-3262 · fireofficial@emersonnj.gov","Apply: Fee depends on how far ahead the inspection is scheduled from when the paperwork is submitted: 10 days or more for the lowest fee. The Borough recommends submitting 3 to 4 weeks before closing.","How to apply: Use the same Residential Transfer of Ownership Certificate form as the CCO. Mark the smoke and CO alarm types (hardwired, battery or low voltage) and pay the smoke/CO fee by check made out to the Fire Prevention Bureau. Fire Prevention Bureau office hours are Monday, Wednesday and Friday, 8:30 AM to 3:00 PM.","Fire official in the NJ state directory, updated 2/27/2026: Anthony J Sottile · (201) 262-6086 · fireofficial@emersonnj.org","Smoke alarms on every level (basement, first floor, second floor), excluding crawl spaces and unfinished attics, and outside each separate sleeping area within 10 feet of bedrooms","All battery-operated smoke alarms must be 10-year sealed battery units","Carbon monoxide alarms within 10 feet of bedroom areas in the hallway, permanently mounted or plug-in","Portable fire extinguisher, at least 2A:10B:C and no more than 10 pounds, mounted within 10 feet of the kitchen in the exit path, top no more than 5 feet above the floor, serviced and tagged by a state-certified contractor in the past 12 months or with a recent purchase receipt (form still lists it)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke and CO alarm inspection scheduled 10 days or more from paperwork submittal","amount":"$45"},{"label":"Smoke and CO alarm inspection scheduled more than 4 but less than 10 days from paperwork submittal (Code Section 150-7F)","amount":"$90"},{"label":"Smoke and CO alarm inspection scheduled 4 days or less from paperwork submittal","amount":"$161"},{"label":"Each additional inspection after a failed inspection","amount":"$45"},{"label":"Smoke/CO fee as printed on the transfer form, less than 10 days (form amount)","amount":"$95"}]$j$::jsonb, $t$https://emersonnj.gov/vertical/sites/%7B3CE7C79E-1CDE-42D4-BE99-DEDBCE95F9A4%7D/uploads/Residential_Transfer_Form.pdf$t$, $t$https://emersonnj.gov/fireprevention$t$, $j$[{"url":"https://emersonnj.gov/fireprevention","label":"Official source (emersonnj.gov)"},{"url":"https://ecode360.com/11486048","label":"Official source (ecode360.com)"},{"url":"https://emersonnj.gov/vertical/sites/%7B3CE7C79E-1CDE-42D4-BE99-DEDBCE95F9A4%7D/uploads/Residential_Transfer_Form.pdf","label":"Official source (emersonnj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Fire Official: AJ Sottile$t$, $t$f2e40a26e72d8303e069aa2a489e5c178aa2428f12f58eb436d2210bc7970cc9$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":8,"fee_ok":3,"fee_bad":0,"fee_unchecked":5,"quotes":16,"q_ok":12,"q_bad":0,"q_unchecked":4},"source":"property/data/municipal-requirements/checked/0214.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0214.json$t$, true),
  ($t$0215$t$, $t$Englewood$t$, $t$BERGEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Continued Occupancy (CCO) for a residential resale$t$, $j$["Issued by: City of Englewood Building & Code Enforcement (CCO Inspector / Chief Inspector)","Contact: Jahvia Griffin, CCO Inspector (direct line 201-871-6650) · 201-871-6642 · jgriffin@cityofenglewood.org","Apply: The City calls to schedule an inspection within 10 business days of receiving a complete application; the certificate is emailed 2 business days after a passed inspection.","How to apply: The seller, seller's agent or seller's attorney completes the Residential Resale CCO application and brings or mails it with a check or money order payable to the City of Englewood to the Building Department, 2-10 N. Van Brunt St (2nd floor), Englewood, NJ 07631. Credit cards, fax and email are not accepted. Fees are non-refundable.","Valid for: If the buyer changes 30 days after the inspection, a new application and payment are needed.","All outstanding permits must be closed before the CCO inspection can be scheduled; applications are returned if there are open permits or violations","Inspection of walls, floors, ceilings, stairs and rails; no illegal apartments, illegally rented rooms or work done without permits","Smoke alarm on each level including the basement and outside each sleeping area (10-year sealed battery units, hardwired not replaced with battery); photoelectric if a bedroom is within 10 feet of the kitchen","Carbon monoxide alarm within 10 feet of the sleeping areas when there is a fuel-burning appliance or attached garage","ABC fire extinguisher within 10 feet of the kitchen (form still lists it)","House number at least 3 inches high in contrasting colors near the front door; no keyed deadbolt inside; bedroom egress windows open easily; handrails on 4 or more steps; bathroom fan where there is no window; water heater relief pipe within 6 inches of the floor","Central-station fire alarm systems must be tested before the inspection with a test report","Resale-only (buyer not occupying): buyer's notarized letter; bank-owned: copy of contract or notarized bank letter","Also: Open permits and violations: All open permits must be closed before the CCO inspection is scheduled; applications with outstanding permits or violations are returned.","Also: Illegal units: Illegal apartments or unpermitted work must be removed or legalized and pass a second inspection before the CCO is issued."]$j$::jsonb, $j$[{"label":"CCO application, 1 and 2 family house or condo","amount":"$150"},{"label":"CCO application, 3 and 4 family house","amount":"$250"},{"label":"CCO processing/inspection, one- or two-family home (City web page)","amount":"$150"}]$j$::jsonb, $t$https://cityofenglewood.org/DocumentCenter/View/111/Certificate-of-Continued-Occupancy---Residential-Resale-PDF$t$, $t$https://cityofenglewood.org/1163/Certificate-of-Continued-Occupancy-Lette$t$, $j$[{"url":"https://cityofenglewood.org/1163/Certificate-of-Continued-Occupancy-Lette","label":"Official source (cityofenglewood.org)"},{"url":"https://cityofenglewood.org/DocumentCenter/View/111/Certificate-of-Continued-Occupancy---Residential-Resale-PDF","label":"Official source (cityofenglewood.org)"},{"url":"https://cityofenglewood.org/Directory.aspx?did=6","label":"Official source (cityofenglewood.org)"}]$j$::jsonb, $t$The seller must receive a Certificate of Continued Occupancy (CCO) before transferring ownership.$t$, $t$554f1b5059d12d718ad3ef0966371e19510873ff7ea46815ce77b66f54c44040$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":7,"fee_ok":7,"fee_bad":0,"fee_unchecked":0,"quotes":16,"q_ok":15,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/0215.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0215.json$t$, true),
  ($t$0215$t$, $t$Englewood$t$, $t$BERGEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: City of Englewood (Building & Code Enforcement for the smoke/CO check during the CCO; Englewood Fire Department Fire Prevention is the LEA) (town fire bureau)","Contact: Rocco Carbone, Fire Official (state fire directory) · 201-871-6642 · carbone@englewoodfire.com","Apply: Fee depends on how many business days before the inspection the request is made: more than 10 business days for the lowest fee.","How to apply: The smoke alarm, CO alarm and extinguisher check is part of the CCO inspection by the City's Building & Code Enforcement office (2-10 North Van Brunt St). Ask the office whether the smoke certificate fee is charged in addition to the CCO fee.","Fire official in the NJ state directory, updated 4/14/2025: Rocco Carbone · (201) 871-6693 · carbone@englewoodfire.com","Smoke alarms on each level including the basement and outside each sleeping area; 10-year sealed battery units, or hardwired; alarms over 10 years old replaced","Carbon monoxide alarm within 10 feet of each sleeping area when there is a fuel-burning appliance or attached garage (battery, hardwired or plug-in)","Fire extinguisher 2A:10B:C, no more than 10 pounds, within 10 feet of the kitchen, mounted, serviced and tagged within 12 months or with a recent receipt (CCO form still lists it)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Certificate of Smoke Detector and Carbon Monoxide Alarm compliance, request more than 10 business days before inspection","amount":"$150.00"},{"label":"Request 4 to 10 business days before inspection","amount":"$175.00"},{"label":"Request fewer than 4 business days before inspection","amount":"$200.00"},{"label":"Reinspection fee per occurrence (ordinance spells it 'Reinsertion')","amount":"$75.00"}]$j$::jsonb, $t$https://cityofenglewood.org/DocumentCenter/View/111/Certificate-of-Continued-Occupancy---Residential-Resale-PDF$t$, $t$https://cityofenglewood.org/1163/Certificate-of-Continued-Occupancy-Lette$t$, $j$[{"url":"https://ecode360.com/EN2705/laws/LF2556609.pdf","label":"Official source (ecode360.com)"},{"url":"https://cityofenglewood.org/1163/Certificate-of-Continued-Occupancy-Lette","label":"Official source (cityofenglewood.org)"},{"url":"https://cityofenglewood.org/DocumentCenter/View/111/Certificate-of-Continued-Occupancy---Residential-Resale-PDF","label":"Official source (cityofenglewood.org)"},{"url":"https://cityofenglewood.org/Directory.aspx?did=6","label":"Official source (cityofenglewood.org)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$B. Certificate of Smoke Detector and Carbon Monoxide Alarm compliance:$t$, $t$1fe6140d9d8f6c0bbe78ad53eac0abd50fb991951d2bed4f66499dd4d257b4c6$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":7,"fee_ok":7,"fee_bad":0,"fee_unchecked":0,"quotes":16,"q_ok":15,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/0215.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0215.json$t$, true),
  ($t$0216$t$, $t$Englewood Cliffs Borough$t$, $t$BERGEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Continued Occupancy (CCO), Residential Sale$t$, $j$["Issued by: Borough of Englewood Cliffs Building Department (Construction Official)","Contact: Gino Tessaro, Construction Official (tech assistant: Cathy Scancarella, cscancarella@englewoodcliffsnj.org) · 201-569-5252 · GTessaro@englewoodcliffsnj.org","Apply: Apply at least two weeks before closing. Requests received fewer than 4 business days before closing pay a $150.00 expedite fee.","How to apply: Download the Application for Certificate of Continued Occupancy Residential Sale from the Building page, complete all pages (room count and sump pump affidavits are notarized; smoke/CO affidavit signed by owner, tenant or licensed electrician) and submit it with a $100.00 check payable to the Borough of Englewood Cliffs at the Building Department, 482 Hudson Terrace. Permit pick-up and payment is Monday to Friday 9:00 AM to 2:00 PM. Give the name and phone of the person who will meet the inspector.","Valid for: If the home is not occupied within six months of issuance, the certificate expires and a new one is needed.","Inspection of the visible parts of the house for the Property Maintenance Code and Borough building, plumbing, electrical, health, safety and fire ordinances; violations must be corrected (14 days allowed after a notice)","Smoke detectors and carbon monoxide detectors tested and working at the inspection; signed smoke/CO affidavit (owner, tenant or NJ licensed electrician); smoke detectors over 10 years old and CO detectors over 5 years old replaced","Homes with 110V (hardwired) smoke or CO detection need a written report from a NJ licensed electrician or certified alarm company; existing low voltage alarm/smoke systems must work","Minimum size 10 type ABC fire extinguisher within 10 feet of the kitchen (form still lists it)","House number at least 3 inches (6 inches if the house is more than 50 feet from the curb), contrasting and visible from the street","Notarized owner affidavit that no sump pumps, storm drains or other devices are connected to the sewer line; notarized room count per floor","All building permits closed and all taxes, penalties and fees due to the Borough paid before closing","Unit doors opening to a corridor must be self-closing and self-latching where applicable","No one may occupy the home before approval from the Fire Inspector","Also: Sump pump / storm drain affidavit and inspection: At every CCO or ownership transfer the fire subcode official inspects for sump pumps or drains discharging into the sanitary sewer; the owner signs a notarized affidavit that none are connected. No CCO is issued until any such connection is removed.","Also: House number: No CCO is issued unless the house number meets Property Maintenance Code Section 10-7.2e (at least 3 inches, or 6 inches if more than 50 feet from the curb, contrasting and visible).","Also: Open permits, taxes and fees: No CCO is issued before closing without closing all building permits and paying all taxes, penalties and fees due to the Borough."]$j$::jsonb, $j$[{"label":"CCO, resale (Borough Code 9-17.2)","amount":"$100"},{"label":"Expedite, request fewer than 4 business days before closing","amount":"$150"},{"label":"Second or later reinspection (Code)","amount":"$50"},{"label":"Re-inspection after a failed inspection (application form)","amount":"$125.00"}]$j$::jsonb, $t$https://englewoodcliffsnj.org/Documents/Departments/Building/Application-for-Certificate-of-Continured-Occupancy-Residential-Sale.pdf$t$, $t$https://englewoodcliffsnj.org/departments/building/index.php$t$, $j$[{"url":"https://englewoodcliffsnj.org/departments/building/index.php","label":"Official source (englewoodcliffsnj.org)"},{"url":"https://ecode360.com/35700600","label":"Official source (ecode360.com)"},{"url":"https://englewoodcliffsnj.org/Documents/Departments/Building/Application-for-Certificate-of-Continured-Occupancy-Residential-Sale.pdf","label":"Official source (englewoodcliffsnj.org)"}]$j$::jsonb, $t$A Continuing Certificate of Occupancy is required on all re-sales of homes, and rental properties as well.$t$, $t$aed7ac669fc837b7a09f29bb69998d51366342d5c4c5315a8d9bd33de937236d$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":0,"fee_bad":0,"fee_unchecked":4,"quotes":10,"q_ok":3,"q_bad":0,"q_unchecked":7},"source":"property/data/municipal-requirements/checked/0216.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0216.json$t$, true),
  ($t$0216$t$, $t$Englewood Cliffs Borough$t$, $t$BERGEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Englewood Cliffs Building Department (smoke/CO checked as part of the CCO); Fire Prevention under the Englewood Cliffs Fire Department is the LEA (town fire bureau)","Contact: Joseph Cardullo, Fire Official (NJ DCA directory) · 201-569-5252 · fireofficial@englewoodcliffsnj.org","Apply: With the CCO: apply at least two weeks before closing.","How to apply: The smoke/CO affidavit and electrician or alarm company report are part of the CCO Residential Sale application filed with the Building Department; no separate smoke certificate application or fee is posted.","Fire official in the NJ state directory, updated 2/6/2025: Joseph Cardullo · (201) 569-5252 · fireofficial@englewoodcliffsnj.org","Smoke detectors by year built: pre-1977 battery units on each level and within 10 feet of sleeping areas; later homes 110V units (interconnected from 8/6/84; battery back-up and in each bedroom after 9/5/91)","Smoke detectors with a manufacture date over 10 years must be replaced; batteries changed at the time of inspection","Carbon monoxide detectors within 10 feet of all sleeping areas; CO detectors over 5 years old replaced","Hardwired (110V) systems need a written report from a NJ licensed electrician or certified alarm company; battery systems need a signed affidavit","Minimum size 10 type ABC fire extinguisher within 10 feet of the kitchen (form still lists it)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[]$j$::jsonb, $t$https://englewoodcliffsnj.org/Documents/Departments/Building/Application-for-Certificate-of-Continured-Occupancy-Residential-Sale.pdf$t$, $t$https://englewoodcliffsnj.org/departments/building/index.php$t$, $j$[{"url":"https://englewoodcliffsnj.org/Documents/Departments/Building/Application-for-Certificate-of-Continured-Occupancy-Residential-Sale.pdf","label":"Official source (englewoodcliffsnj.org)"},{"url":"https://ecode360.com/35700600","label":"Official source (ecode360.com)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Smoke Detectors and Carbon Monoxide Detectors shall be tested and in working order at the time of inspection.$t$, $t$60080aeca726233bdd6c8733ad3e5611d13282af68f06a4a0ea34e6f719006e2$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":0,"fee_bad":0,"fee_unchecked":4,"quotes":10,"q_ok":3,"q_bad":0,"q_unchecked":7},"source":"property/data/municipal-requirements/checked/0216.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0216.json$t$, true),
  ($t$0217$t$, $t$Fair Lawn Borough$t$, $t$BERGEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Continued Occupancy (CCO) - Resale$t$, $j$["Issued by: Borough of Fair Lawn Construction Code Official (Building Department resale-CCO inspectors; Zoning Dept phone on the form)","Contact: Richard Bolan, Building and Zoning Official (CCO form lists Zoning Dept 201-794-5308) · (201) 794-5307","Apply: The ordinance says the CCO is issued or denied within 10 days of filing the application. Inspections are 12 pm to 4 pm.","How to apply: Complete the Borough's Application for Certificate of Continued Occupancy-Resale (owner, buyer, both attorneys, closing date, whether the buyer will occupy) and pay the fee; the form says to call the Zoning Dept at 201-794-5308 and that a missed appointment counts as the first inspection. Have the DPW water valve letter signed and get the Fire Prevention Bureau smoke alarm certificate. If violations remain, the Construction Code Official may allow closing when the purchaser certifies in writing that violations will be corrected and a repair escrow is set up.","Valid for: One year from the date of issuance, provided there is no material change in the physical status of the premises","Applies to one- and two-family dwellings on any transfer of title (exempt: 3+ family buildings, deed corrections, spouse and parent/child or grandparent/grandchild transfers, new construction, estate distributions, receivers/trustees, quitclaims to quiet title)","Visual inspection by the Construction Code Official (who may refer to subcode officials, the Water Department and the Department of Health) covering sidewalks, electrical service, plumbing, heating and ventilation, building exterior, fences, driveways and other hazards","Resale checklist also covers walkways, debris, oil tank, railings, accessory structures, sprinklers, water valve certificate, water heater, sump pump, gas pipe, handrails, stairs, renovations, fire certificate and open permits","Water service valves before and after the meter must be working ball valves, signed off by the Department of Public Works (Ordinance 241.24)","Smoke alarm certificate from the Fire Prevention Bureau","Additions or construction done without permits must be legalized","Also: Water meter valve inspection (DPW): Under Ordinance 241.24 the water service valves before and after the meter must be working ball valves; call DPW at 201-794-5326 or 201-794-5304 for an inspection and give the signed letter to the Building Department.","Also: Open permits and unpermitted work: Additions or construction found without permits must be legalized before the CCO; the checklist records open building, plumbing, electrical and fire permits.","Also: Optional code letter: A $50 code letter at resale or refinancing is available from the Construction office (separate from the CCO)."]$j$::jsonb, $j$[{"label":"CCO for one- or two-family dwelling, initial inspection plus one follow-up","amount":"$175"},{"label":"Each subsequent CCO inspection for the same applicant","amount":"$50"},{"label":"Additional certified copy of the CCO","amount":"$5"}]$j$::jsonb, $t$https://www.fairlawn.org/uploads/dm/21203/Residential_CCO_Application$t$, $t$https://www.fairlawn.org/building-zoning$t$, $j$[{"url":"https://ecode360.com/10054087","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/10051317","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/10051123","label":"Official source (ecode360.com)"},{"url":"https://www.fairlawn.org/building-zoning","label":"Official source (fairlawn.org)"},{"url":"https://www.fairlawn.org/uploads/dm/21203/Residential_CCO_Application","label":"Official source (fairlawn.org)"}]$j$::jsonb, $t$Transfer of title to real property in the Borough of Fair Lawn containing a building or permanent structure of any kind.$t$, $t$dea5c11a098649a52cf15e04129cd651a546b6c7c9e5302c22bed9c64e101916$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":0,"fee_bad":0,"fee_unchecked":6,"quotes":20,"q_ok":4,"q_bad":0,"q_unchecked":16},"source":"property/data/municipal-requirements/checked/0217.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0217.json$t$, true),
  ($t$0217$t$, $t$Fair Lawn Borough$t$, $t$BERGEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Fair Lawn Bureau of Fire Prevention (town fire bureau)","Contact: Angelo Castronovo, Fire Official (Deputy Fire Official: Don Santangelo) · (201) 794-5408 · castronovo@fairlawn.org","Apply: Fee depends on how far in advance the inspection is scheduled. The certificate is good for six months.","How to apply: Call the Fire Prevention Bureau at 201-794-5408 to schedule. Pay by check payable to Borough of Fair Lawn; cash is not accepted at the inspection site.","Fire official in the NJ state directory, updated 1/17/2025: Angelo M Castronovo · (201) 794-5408 · castronovo@fairlawn.org","At least one 10 year sealed smoke alarm on each level including the basement, within 10 feet of each entrance to a sleeping area (or inside each sleeping area), and near the stairway on levels without a sleeping area","Hardwired smoke detectors from original construction or rehabilitation must be kept operational; wireless detectors do not meet code unless installed by permit or variance","Combination smoke/CO alarms must be 10 year sealed battery units","Carbon monoxide alarm on each level that has a bedroom (battery, hard-wired or plug-in; table-top models not acceptable)","Two-family homes: 10 year sealed smoke detector outside each doorway in common stairwells and hallways, and a smoke alarm at the foot of the stairs in each separate basement","Secondary power source caution label within 18 inches of the main electrical panel and meter if the home has a generator, solar panels or battery storage","Fire extinguisher (ordinance fee title still lists it)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke detector, CO alarm and fire extinguisher compliance certificate and inspection (ordinance)","amount":"$90"},{"label":"Reinspection, each additional visit","amount":"$50"},{"label":"Upper end of the flyer's fee range (shorter notice)","amount":"$125.00"}]$j$::jsonb, null, $t$https://www.fairlawn.org/fire-prevention$t$, $j$[{"url":"https://ecode360.com/10051317","label":"Official source (ecode360.com)"},{"url":"https://www.fairlawn.org/uploads/dm/21219/Smoke_Detection_Certification_Requirements","label":"Official source (fairlawn.org)"},{"url":"https://www.fairlawn.org/fire-prevention","label":"Official source (fairlawn.org)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Certificate of smoke detector, carbon monoxide alarms and fire extinguisher compliance and its inspection: $90$t$, $t$9c7320ab2cb4cc1ceba6df33cd2ab9275f1f62d96213532f23529d2d51080097$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":0,"fee_bad":0,"fee_unchecked":6,"quotes":20,"q_ok":4,"q_bad":0,"q_unchecked":16},"source":"property/data/municipal-requirements/checked/0217.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0217.json$t$, true),
  ($t$0218$t$, $t$Fairview Borough$t$, $t$BERGEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Continued Occupancy (CCO), residential resale$t$, $j$["Issued by: Borough of Fairview Building Department (Construction Official / Zoning Officer)","Contact: Richard Bolan, Construction Official / Zoning Officer (Technical Assistant: Nicole Bellucci) · 201-943-5485 · nbellucci@fairviewborough.com","Apply: The Borough Code says the application must be filed at least 21 calendar days before the new owner or tenant moves in. Inspections are Monday to Friday, 10 am to 12 pm, after the full paperwork and payment are in.","How to apply: Download the Residential Resale Packet from the Building Department's Applications page, complete every page (notarized originals, one-sided copies), attach the survey, and hand it in with payment at the Municipal Building, 59 Anderson Avenue, 3rd Floor. Pay by cash (exact change), check or money order to the Borough of Fairview; no credit cards. The office then schedules the inspection.","Valid for: A temporary certificate may be issued if only minor violations remain, conditioned on fixing them within 45 days.","Complete all 9 pages of the Residential Resale/Refinance CCO application, with original notarized signatures","Copy of the property survey (resales)","Smoke detectors and carbon monoxide detectors must be UL 217 approved and installed","Disclose any permits that need final inspections","Tenant affidavit: valid rental CCOs for every current tenant, or the seller must apply and pay for them","Tank affidavit: any oil tank must be properly decommissioned (permit and inspection closed) before the resale certificate is issued, or a buyer agreement or metal detector sweep provided","Buyer affidavit acknowledging the legal number of dwelling units (Ordinance 03-22, $5,000 minimum fine per added unit)","Zoning use, visible hazards and outstanding violations are checked","Also: Heating oil tank: Seller must certify there was never a tank, or that it was properly decommissioned; an improperly closed tank needs a permit and inspection closed before the resale certificate is issued (or a buyer agreement or licensed metal-detector sweep).","Also: Open permits: The application asks about permits needing final inspections; outstanding violations or Construction Official orders are checked.","Also: Rental CCOs for current tenants: Before a resale CCO is issued, valid rental CCOs must be on file for every apartment with current tenants, or the seller must apply and pay for them.","Also: Buyer affidavit on number of units: Buyer signs a notarized affidavit on the legal number of dwelling units; adding units later carries a minimum $5,000 fine per unit (Ordinance 03-22)."]$j$::jsonb, $j$[{"label":"Residential resale CCO application","amount":"$125.00"},{"label":"CCO fee, change in ownership (Borough Code §11-4)","amount":"$125 per unit"}]$j$::jsonb, $t$https://fairviewborough.com/government/forms/construction/74-residential-resale-packet/file$t$, $t$https://fairviewborough.com/departments/construction$t$, $j$[{"url":"https://fairviewborough.com/departments/construction","label":"Official source (fairviewborough.com)"},{"url":"https://fairviewborough.com/government/forms/construction/74-residential-resale-packet/file","label":"Official source (fairviewborough.com)"},{"url":"https://ecode360.com/35232884","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$Certificates of Occupancy are required for all resales, rentals and the opening of any new or existing business.$t$, $t$2a96865ff266ebdb8208427344212d6ec7eed3e5ccce6b91329543068693060f$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":2,"fee_bad":0,"fee_unchecked":1,"quotes":19,"q_ok":13,"q_bad":0,"q_unchecked":6},"source":"property/data/municipal-requirements/checked/0218.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0218.json$t$, true),
  ($t$0218$t$, $t$Fairview Borough$t$, $t$BERGEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Borough of Fairview Building Department (smoke detector compliance through the resale CCO); fire code enforcing agency: Fairview Bureau of Fire Safety (town fire bureau)","Contact: Dennis Licameli, Fire Official/Fire Chief · (201) 943-3300 Ext. 256 · dlicameli@fairviewborough.com","Apply: Same as the CCO: file at least 21 calendar days before occupancy; inspections Monday to Friday, 10 am to 12 pm.","How to apply: Part of the Residential Resale CCO packet filed with the Building Department, 59 Anderson Avenue, 3rd Floor. The Bureau of Fire Safety handles fire code questions.","Fire official in the NJ state directory (town), updated 7/28/2026: Dennis Licameli · (201) 945-3040 · dlicameli@fairviewborough.com","Smoke detectors and carbon monoxide alarms installed (checked during the CCO inspection); CO and smoke detectors must be UL 217 approved per the packet","Carbon monoxide alarms near sleeping areas in homes with a fuel-burning appliance or attached garage (Borough Code §11-4)","Existing one and two family homes may use approved battery smoke detectors under the Borough Code","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke/CO check within the resale CCO (same fee as the CCO, not an extra charge)","amount":"$125.00"}]$j$::jsonb, $t$https://fairviewborough.com/government/forms/construction/74-residential-resale-packet/file$t$, $t$https://fairviewborough.com/departments/fire-prevention$t$, $j$[{"url":"https://fairviewborough.com/departments/fire-prevention","label":"Official source (fairviewborough.com)"},{"url":"https://fairviewborough.com/government/forms/construction/74-residential-resale-packet/file","label":"Official source (fairviewborough.com)"},{"url":"https://ecode360.com/35209080","label":"Official source (ecode360.com)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Dennis Licameli$t$, $t$63104171adccbd65ee27ee610827c9df5e0889b81ed3bc5b8a4f393083df9db9$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":2,"fee_bad":0,"fee_unchecked":1,"quotes":19,"q_ok":13,"q_bad":0,"q_unchecked":6},"source":"property/data/municipal-requirements/checked/0218.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0218.json$t$, true),
  ($t$0219$t$, $t$Fort Lee Borough$t$, $t$BERGEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Compliance (COC) for sales (Certificate of Continued Occupancy)$t$, $j$["Issued by: Borough of Fort Lee Fire Prevention Bureau (enforcement officer under Borough Code Chapter 182)","Contact: Steven J. Curry, Fire Official · 201-592-3500 x1502 · S-Curry@fortleenj.org","Apply: No published lead time. The inspector will not call before arriving and exact arrival times are not given.","How to apply: Print the Application for a SALE Certificate of Compliance (COC) packet from the Fire Prevention Bureau's Applications & Forms page, fill in every page (including the smoke/CO affidavit and the rental-intent letter) and submit it with $100 by check payable to the Borough of Fort Lee or by credit card (fee applies) to the Fire Prevention Bureau, 1365 Inwood Terrace. The Bureau schedules the inspection.","Valid for: The $100 fee is waived if the same premises was inspected within 180 days (Code 182-5); no other validity period is published","Inspection for compliance with applicable building, health, safety and fire codes (Code 182-2)","Smoke detectors and carbon monoxide detectors installed per the Bureau's affidavit (smoke detectors older than 10 years must be replaced; CO detectors older than 5 years replaced unless the maker allows longer)","Signed Smoke/CO Detector affidavit completed by the owner (realtors may not fill it out)","All open building permits closed and all taxes, penalties and fees due to the Borough paid before the COC is issued","Name and phone of the person who will meet the inspector","Signed letter stating whether the new owner will rent the one- or two-family home (non-owner-occupied homes must register with the Fire Prevention Bureau)","Also: Open permits and municipal charges: The COC is only issued once all open building permits are closed and all taxes, penalties and fees due to the Borough are paid.","Also: Rental registration if the buyer will rent: If the new owner will rent a one- or two-family home, they must register with the Fire Prevention Bureau (annual $100 fee for non-owner-occupied units) and a separate rental COC is needed before a tenant moves in. Owner-occupied sales are not affected."]$j$::jsonb, $j$[{"label":"Sale Certificate of Compliance (COC), covers the smoke/CO inspection; one fee","amount":"$100"}]$j$::jsonb, $t$https://www.fortleenj.org/DocumentCenter/View/8398/COC-SALE-App-Affidavit-040125-PDF$t$, $t$https://www.fortleenj.org/248/Fire-Prevention-Bureau$t$, $j$[{"url":"https://ecode360.com/10067065","label":"Official source (ecode360.com)"},{"url":"https://www.fortleenj.org/DocumentCenter/View/8398/COC-SALE-App-Affidavit-040125-PDF","label":"Official source (fortleenj.org)"},{"url":"https://www.fortleenj.org/249/Programs-Duties","label":"Official source (fortleenj.org)"},{"url":"https://www.fortleenj.org/248/Fire-Prevention-Bureau","label":"Official source (fortleenj.org)"}]$j$::jsonb, $t$No person shall occupy or use any portion of a commercial, industrial or residential building after such building or portion thereof has been vacated or sold, or in which there has been a change in occupancy, until the owner/landlord shall have applied for and secured a certificate of compliance therefor from the enforcement officer of the Borough of Fort Lee.$t$, $t$405e5e31b5555b647a113b40e36e028e3d78d1c87c53f4ebc28d00745a22f354$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":2,"fee_ok":2,"fee_bad":0,"fee_unchecked":0,"quotes":15,"q_ok":12,"q_bad":0,"q_unchecked":3},"source":"property/data/municipal-requirements/checked/0219.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0219.json$t$, true),
  ($t$0219$t$, $t$Fort Lee Borough$t$, $t$BERGEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Fort Lee Fire Prevention Bureau (town fire bureau)","Contact: Steven J. Curry, Fire Official · 201-592-3500 x1502 · S-Curry@fortleenj.org","Apply: No published lead time; the Bureau schedules the inspection after the application and fee are received.","How to apply: Submit the SALE Certificate of Compliance (COC) packet with the smoke/CO affidavit and $100 to the Fire Prevention Bureau, 1365 Inwood Terrace, Fort Lee.","Fire official in the NJ state directory, updated 3/2/2026: Steven J Curry · (201) 592-3500 · scurry@fortleenj.org","Smoke detectors on each level and within 10 feet of sleeping areas; requirements step up by year built (110V interconnected detectors, battery backup, detectors inside bedrooms for newer homes)","Battery-only smoke detectors must be 10-year sealed battery units, UL or ETL listed; detectors older than 10 years must be replaced","Carbon monoxide detectors within 10 feet of sleeping areas, on every level, outside rooms with fuel-burning appliances and near an attached garage entrance; CO detectors older than 5 years replaced unless the manufacturer allows longer","Fire extinguisher not required for one- and two-family homes (per the Bureau's 5/20/25 packet)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Sale Certificate of Compliance (COC) including the smoke/CO inspection (same single $100 fee as the resale certificate)","amount":"$100"}]$j$::jsonb, $t$https://www.fortleenj.org/DocumentCenter/View/8398/COC-SALE-App-Affidavit-040125-PDF$t$, $t$https://www.fortleenj.org/248/Fire-Prevention-Bureau$t$, $j$[{"url":"https://www.fortleenj.org/DocumentCenter/View/8398/COC-SALE-App-Affidavit-040125-PDF","label":"Official source (fortleenj.org)"},{"url":"https://www.fortleenj.org/248/Fire-Prevention-Bureau","label":"Official source (fortleenj.org)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$One & Two-Family Homes and Attached Single Family Dwellings - Not Required$t$, $t$4383707740e6753e7d093a7d7801e3d7a31faa98778a732f7443a4313f509f6e$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":2,"fee_ok":2,"fee_bad":0,"fee_unchecked":0,"quotes":15,"q_ok":12,"q_bad":0,"q_unchecked":3},"source":"property/data/municipal-requirements/checked/0219.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0219.json$t$, true),
  ($t$0220$t$, $t$Franklin Lakes Borough$t$, $t$BERGEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Fire Certificate on sale (Certificate of Smoke Alarm and Carbon Monoxide Alarm with resale site inspection)$t$, $j$["Issued by: Franklin Lakes Fire Prevention Bureau","Contact: Brian Comitto, Fire Official (Fire Prevention Secretary: Melodie Petrosino, ext. 1219) · 201-891-4000 ext. 1218 · bcomitto@franklinlakes.org","Apply: Application must be submitted 30 days before the closing date. The certificate expires 90 days from approval.","How to apply: Download the Application for Smoke Alarm & Carbon Monoxide Alarm (Residential-Resale/Rental/Change of Occupant) from the Borough Forms page (Fire Prevention Bureau section), complete it and submit it with the fee at least 30 days before closing to the Fire Prevention Bureau, 480 DeKorte Drive. Fees and all documents must be processed before the inspection is scheduled. Office hours are by appointment; leave a voicemail or email.","Valid for: 90 days from date of approval","Smoke alarms and carbon monoxide alarms meeting state law (see fire certificate)","All open construction permits must be closed out","No pending violations, including interior doors with keyed locks and illegal basement bedrooms","House numbers at least 3 inches high in a contrasting color, permanently fixed and clearly visible near the front door","Permanent pool fence at least 4 ft with self-latching, lockable gates","Railings on interior or exterior stairs with 4 or more risers; water heater and boiler relief pipe within 6 inches of the floor; no holes in the garage ceiling; no extension cords used as permanent wiring; appliance flue pipes in good condition and sealed","Real estate taxes must be current; property owner's professional services escrow account may not be deficient","Properties on the Abandoned/Foreclosure/Nuisance Registry must be deregistered","Also: Open permits: All open construction permits must be closed out before the fire certificate is issued.","Also: Real estate taxes: The certificate is valid only if all real estate taxes are current.","Also: Abandoned/foreclosure/nuisance registry: Properties listed on the registry must be deregistered or yearly fees continue."]$j$::jsonb, $j$[{"label":"Fire certificate (smoke alarm and carbon monoxide alarm, resale), initial inspection","amount":"$150.00"},{"label":"Reinspection","amount":"$100.00"},{"label":"Fire certificate inspection, initial (Borough Code 259-7B(4))","amount":"$150"}]$j$::jsonb, $t$https://www.franklinlakes.org/vertical/sites/%7B02E9C1B5-59B4-4B82-8487-CE42C675CF8A%7D/uploads/fire_new_doc.pdf$t$, $t$https://www.franklinlakes.org/fp$t$, $j$[{"url":"https://ecode360.com/7171383","label":"Official source (ecode360.com)"},{"url":"https://www.franklinlakes.org/vertical/sites/%7B02E9C1B5-59B4-4B82-8487-CE42C675CF8A%7D/uploads/fire_new_doc.pdf","label":"Official source (franklinlakes.org)"},{"url":"https://www.franklinlakes.org/forms","label":"Official source (franklinlakes.org)"},{"url":"https://www.franklinlakes.org/fp","label":"Official source (franklinlakes.org)"}]$j$::jsonb, $t$Before any residential dwelling is sold, leased, or otherwise made subject to a change of occupancy, the owner shall obtain a fire certificate.$t$, $t$840dae2778a5dd9b5fa918ec0b1606539ed38094d4ceb974d72da8f549fd1c73$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":4,"fee_bad":0,"fee_unchecked":1,"quotes":15,"q_ok":9,"q_bad":0,"q_unchecked":6},"source":"property/data/municipal-requirements/checked/0220.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0220.json$t$, true),
  ($t$0220$t$, $t$Franklin Lakes Borough$t$, $t$BERGEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Franklin Lakes Fire Prevention Bureau (town fire bureau)","Contact: Brian Comitto, Fire Official · 201-891-4000 ext. 1218 · bcomitto@franklinlakes.org","Apply: Submit the application 30 days before closing; certificate expires 90 days from approval.","How to apply: Same application as the resale fire certificate: Application for Smoke Alarm & Carbon Monoxide Alarm on the Borough Forms page, filed with the fee at the Fire Prevention Bureau, 480 DeKorte Drive, Franklin Lakes.","Fire official in the NJ state directory, updated 2/19/2026: Brian M Comitto · (201) 891-0048 · bcomitto@franklinlakes.org","Pre-1978 homes: at least 10 year sealed battery smoke alarms on each level and within 10 feet of all sleeping areas","1978 to 1983: hardwired alarms on each level and within 10 feet of sleeping areas; 1984 to 1990: interconnected hardwired alarms with battery backup; 1991 to present: interconnected hardwired alarms with battery backup on each level and in all bedrooms","Hardwired alarms may not be replaced with battery alarms; smoke alarms older than 10 years must be replaced","Low voltage fire alarm systems need an NFPA 72 inspection report and proof of monitoring before the inspection is scheduled","Carbon monoxide alarms within 10 feet of all sleeping areas, battery, hardwired or plug-in, listed to UL 2034, within the manufacturer's life span","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Fire certificate (smoke alarm and carbon monoxide alarm, resale), initial inspection","amount":"$150.00"},{"label":"Reinspection","amount":"$100.00"}]$j$::jsonb, $t$https://www.franklinlakes.org/vertical/sites/%7B02E9C1B5-59B4-4B82-8487-CE42C675CF8A%7D/uploads/fire_new_doc.pdf$t$, $t$https://www.franklinlakes.org/fp$t$, $j$[{"url":"https://www.franklinlakes.org/vertical/sites/%7B02E9C1B5-59B4-4B82-8487-CE42C675CF8A%7D/uploads/fire_new_doc.pdf","label":"Official source (franklinlakes.org)"},{"url":"https://ecode360.com/7171383","label":"Official source (ecode360.com)"},{"url":"https://www.franklinlakes.org/fp","label":"Official source (franklinlakes.org)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Before any sale, lease, or change of occupancy for residential purposes can occur the owner shall obtain a certificate of smoke alarm and carbon monoxide alarm (CSACMA) from the Franklin Lakes Bureau of Fire Prevention.$t$, $t$2b0e3f089cb77cf42897530964d0f7970d621604c8c8d0b79a46839e503fc05d$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":4,"fee_bad":0,"fee_unchecked":1,"quotes":15,"q_ok":9,"q_bad":0,"q_unchecked":6},"source":"property/data/municipal-requirements/checked/0220.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0220.json$t$, true),
  ($t$0221$t$, $t$Garfield$t$, $t$BERGEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Continuing Occupancy (Certificate of Occupancy for Resale)$t$, $j$["Issued by: City of Garfield Building Department (Construction Official as enforcement officer), with inspection by the Garfield Fire Prevention Bureau","Contact: Elizabeth Pacyga, Named on the City's resale C.O. instructions as the person to start the process · 973-340-2000 · epacyga@garfieldnj.org","Apply: The code gives the City up to 30 days after a complete application to inspect and issue the certificate. The City says not to schedule a closing until the C.O. is obtained.","How to apply: Apply online through the City's FastTrackGov citizen portal (create an account, submit and pay), or email Elizabeth Pacyga (epacyga@garfieldnj.org) with the property address, the buyer's and seller's names, home addresses, phones and emails, and the Surrogate letter for an estate. Wait for the City's email before paying; pay the C.O. fee by check or money order to \"CITY OF GARFIELD\" and the smoke certification fee separately to \"BUREAU OF FIRE PREVENTION\".","General inspection of the visible parts of the building for imminent hazards and compliance with building, health, safety and fire codes","Approved smoke detector installed (smoke and carbon monoxide certification is done at the same time)","Seller and buyer names, current home addresses, phone numbers and emails (no business, attorney or realtor addresses)","For an estate sale, a copy of the Surrogate letter","If illegal extra units are found, separate utility services must be removed and the owner and buyer must sign a sworn statement","Also: Dwelling certificate before transfer of title: Garfield Code Chapter 128 requires a dwelling certificate (number of occupants and unit location) filed not more than 60 days before conveyance of a one- or two-unit dwelling, with a dwelling inspection before transfer of title, unless one was done within 11 months. The code fee is $60 per dwelling unit, which it says includes the smoke detector certification; a $60 return-visit fee applies if access is not given."]$j$::jsonb, $j$[{"label":"Certificate of occupancy for resale, 1 family","amount":"$50.00"},{"label":"Certificate of occupancy for resale, 2 family","amount":"$100.00"},{"label":"Certificate of continuing occupancy, one-family home or condo unit (Code Section 105-9)","amount":"$50"},{"label":"Certificate of continuing occupancy, two-family dwelling (Code Section 105-9)","amount":"$100"}]$j$::jsonb, $t$https://garfieldnj.portal.fasttrackgov.com/Common/ApplicationLinks.aspx$t$, $t$https://www.garfieldnj.org/Departments/building-department$t$, $j$[{"url":"https://www.garfieldnj.org/_Content/pdf/CERTIFICATE-OF-OCCUPANCY-FOR-A-RESALE.pdf","label":"Official source (garfieldnj.org)"},{"url":"https://www.garfieldnj.org/Departments/fire-prevention","label":"Official source (garfieldnj.org)"},{"url":"https://www.garfieldnj.org/Departments/building-department","label":"Official source (garfieldnj.org)"},{"url":"https://ecode360.com/10083600","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$HOW TO OBTAIN A CERTIFICATE OF OCCUPANCY FOR RESALE$t$, $t$698c7f87815423b71e2ad5667ff3f326a84526adb34b0782ab86f93c75684857$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":4,"fee_bad":0,"fee_unchecked":2,"quotes":15,"q_ok":12,"q_bad":0,"q_unchecked":3},"source":"property/data/municipal-requirements/checked/0221.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0221.json$t$, true),
  ($t$0221$t$, $t$Garfield$t$, $t$BERGEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Garfield Bureau of Fire Prevention (Garfield Fire Department) (town fire bureau)","Contact: James E Kovacs, Fire Official (NJ DCA fire directory); Debra Schult is the Fire Prevention contact on the City page · 973-340-2000 · dschult@garfieldnj.org","Apply: Done together with the resale certificate of occupancy; the City starts processing when the complete information is received.","How to apply: Start through the resale C.O. process (FastTrackGov portal or email epacyga@garfieldnj.org). Pay the smoke certification fee with one check or money order payable to \"BUREAU OF FIRE PREVENTION\".","Fire official in the NJ state directory, updated 4/9/2026: James E Kovacs · (973) 340-2000 · jkovacs@garfieldnj.org","Smoke alarms on each level and outside each separate sleeping area, located per NFPA 72","Battery smoke alarms must be 10-year sealed units (UL 217); hardwired alarms must stay hardwired","Carbon monoxide alarms in the immediate vicinity of sleeping areas (UL 2034), where there is a fuel-burning device or attached garage","Smoke and CO detectors within 10 feet of all bedrooms; access to the attic and basement at the inspection","Fire extinguisher (an older City smoke detector application form still lists it)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke and carbon monoxide detector certification, 1 family","amount":"$50.00"},{"label":"Smoke and carbon monoxide detector certification, 2 family","amount":"$100.00"}]$j$::jsonb, $t$https://garfieldnj.portal.fasttrackgov.com/Common/ApplicationLinks.aspx$t$, $t$https://www.garfieldnj.org/Departments/fire-prevention$t$, $j$[{"url":"https://www.garfieldnj.org/_Content/pdf/CERTIFICATE-OF-OCCUPANCY-FOR-A-RESALE.pdf","label":"Official source (garfieldnj.org)"},{"url":"https://www.garfieldnj.org/Departments/fire-prevention","label":"Official source (garfieldnj.org)"},{"url":"https://www.garfieldnj.org/_Content/pdf/Dwelling-Certificate-Instruction-Sheet.pdf","label":"Official source (garfieldnj.org)"},{"url":"https://www.garfieldnj.org/_Content/pdf/forms/Smoke-Detector-Application.pdf","label":"Official source (garfieldnj.org)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$One (1) check or money order for your smoke certification made payable to "BUREAU OF FIRE PREVENTION"$t$, $t$e04e1199d55d9adb44df7aaa9be29e90477de2a98120a0cb0d62aebe5bd8d184$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":4,"fee_bad":0,"fee_unchecked":2,"quotes":15,"q_ok":12,"q_bad":0,"q_unchecked":3},"source":"property/data/municipal-requirements/checked/0221.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0221.json$t$, true),
  ($t$0222$t$, $t$Glen Rock Borough$t$, $t$BERGEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Continued Occupancy (CCO) for residential resale$t$, $j$["Issued by: Borough of Glen Rock Building Department (Code Enforcement Bureau), with Fire Prevention sign-off","Contact: Dave Nizborski, Construction Official (dnizborski@glenrocknj.net) · 201-670-3965, option 1 · building@glenrocknj.net","Apply: Apply at least 30 days before closing or reoccupancy. The certificate is not issued until Fire Prevention gives final approval.","How to apply: Fill out the CCO application in the Residential Resale Packet and hand it in with the $100.00 fee (cash or check payable to Borough of Glen Rock) to the Building Department at least 30 days before closing. Forms can be dropped off at the Building Department, put in the drop box in front of Borough Hall, or mailed to Borough Hall, 1 Harding Plaza, Glen Rock, NJ 07452. Fill out the Fire Prevention CCO application in the same packet at least 10 days before closing.","Application and fee to the Building Department (third floor, Municipal Building, 1 Harding Plaza)","Records review: all construction permits must be properly inspected and closed","Visible inspection of the house by the Building Department for code violations affecting occupant safety","Separate Fire Prevention smoke/CO inspection; certificate not issued until Fire Prevention approves","DPW inspects the public sidewalks, as applicable","Common failures: double-cylinder deadbolts with removable interior key on a primary exit door, vinyl dryer or kitchen exhaust connectors, extension cords for sump pumps or garage door openers","Permits are required for water heaters, heating systems, water softeners, lawn irrigation, electric wiring, EV chargers, patios and decks","Also: Sidewalk inspection: DPW inspects the public sidewalks for resales and rentals; sidewalk repairs need a DPW permit. DPW: 201-670-3980, 473 Doremus Avenue.","Also: Open permits: All construction permits must be properly inspected and closed before the CCO is issued."]$j$::jsonb, $j$[{"label":"CCO for resale","amount":"$100.00"},{"label":"Certificate of continued occupancy, single-family dwelling (Ordinance 1879, Section 101-12, local certificate fees)","amount":"$100"},{"label":"Temporary certificate of continued occupancy, per dwelling unit (Ordinance 1879)","amount":"$100"}]$j$::jsonb, $t$https://glenrocknj.net/government/forms/construction/1585-residential-resale-packet/file$t$, $t$https://glenrocknj.net/departments/construction$t$, $j$[{"url":"https://glenrocknj.net/government/forms/construction/1585-residential-resale-packet/file","label":"Official source (glenrocknj.net)"},{"url":"https://glenrocknj.net/government/forms/construction/913-building-fees/file","label":"Official source (glenrocknj.net)"},{"url":"https://glenrocknj.net/departments/construction","label":"Official source (glenrocknj.net)"},{"url":"https://glenrocknj.net/government/forms/construction","label":"Official source (glenrocknj.net)"}]$j$::jsonb, $t$all Glen Rock property owners who sell or rent their dwellings are required to obtain a borough issued CCO Certificate prior to closing and/or allowing occupancy of such dwellings.$t$, $t$d8abcd4cd7081b48615fcd49ded416fcfeacc6870ef168ae6665df898ae95b41$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":7,"fee_ok":7,"fee_bad":0,"fee_unchecked":0,"quotes":14,"q_ok":13,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/0222.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0222.json$t$, true),
  ($t$0222$t$, $t$Glen Rock Borough$t$, $t$BERGEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Glen Rock Fire Prevention Bureau (town fire bureau)","Contact: Kyle Ladewig, Fire Official (kladewig@glenrocknj.net); Administrative Assistant: Barbara Shuart · 201-670-3986 · fireprevention@glenrocknj.net","Apply: Submit the Fire Prevention CCO application no less than 10 days before the closing date. Fee is based on days before closing: 10 days or more for the lowest fee.","How to apply: Fill out the Glen Rock Fire Prevention Application - Certificate of Continued Occupancy - Residential (in the Residential Resale Packet) with seller, attorney and contact details, and submit it no less than 10 days before closing. Office hours Monday to Friday 8 to 11 am. Low-voltage or central station systems must be tested and certified by the alarm company or a NJ licensed electrician on an NFPA 72 form.","Fire official in the NJ state directory, updated 2/19/2026: Kyle Ladewig · (201) 670-3986 · kladewig@glenrocknj.net","Single family: UL-listed 10-year sealed battery smoke alarms (no battery compartment) on each level including the basement, within 10 feet of each sleeping area entrance or inside each sleeping area, and in each bedroom","Two family: on each level including the basement, near sleeping areas, in the main living area, in common stairwells and hallways, outside each doorway, and at the front of the basement stairs","Hardwired (AC) smoke alarms from original construction or rehabilitation cannot be replaced with battery-only alarms; all detectors must be less than 10 years old","CO alarm within 10 feet of each sleeping area entrance or inside each sleeping area; CO detectors older than 5 years (manufacture date) must be replaced","Portable fire extinguisher 2A:10B:C under 10 pounds within 10 feet of the kitchen, with its bracket, dated within 12 months or tagged (form still lists it)","Secondary power source label (\"CAUTION: MULTIPLE SOURCES OF POWER\") within 18 inches of the main panel and the meter, if the home has a generator, solar panels or battery storage","Legible house numbers visible from the street; front-door deadbolts must be keyless on the inside","Monitored or low-voltage systems must be tested with an NFPA 72 report and monitoring kept active","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke/CO inspection for CCO, 10 days or more before closing","amount":"$100"},{"label":"10 to 4 days before closing","amount":"$125"},{"label":"3 days or less before closing","amount":"$175"},{"label":"Reinspection","amount":"$50"}]$j$::jsonb, $t$https://glenrocknj.net/government/forms/construction/1585-residential-resale-packet/file$t$, $t$https://glenrocknj.net/departments/fire-prevention$t$, $j$[{"url":"https://glenrocknj.net/government/forms/construction/1585-residential-resale-packet/file","label":"Official source (glenrocknj.net)"},{"url":"https://glenrocknj.net/departments/fire-prevention","label":"Official source (glenrocknj.net)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$FORM MUST BE SUBMITTED NO LESS THAN 10 DAYS PRIOR TO CLOSING DATE$t$, $t$c68962c9db7d23eab021feb9017b03ca779fc75917edc90835c61519e6fea0b2$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":7,"fee_ok":7,"fee_bad":0,"fee_unchecked":0,"quotes":14,"q_ok":13,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/0222.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0222.json$t$, true),
  ($t$0223$t$, $t$Hackensack$t$, $t$BERGEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Continued Occupancy (CCO), one and two family houses$t$, $j$["Issued by: City of Hackensack Department of Building, Housing and Land Use (Property Maintenance Division)","Contact: Ernest Sisco, Construction Official · 201-646-3920 · esisco@hackensack.org","How to apply: Apply online with the City's CCO Application (GovPilot) for one and two family houses, using the CCO Checklist to prepare. The office is the Department of Building, Housing and Land Use, 216 Union Street, Hackensack, NJ 07601, 201-646-3920. The smoke and carbon monoxide inspection is applied for separately with the Fire Department.","Apply online with the CCO Application (one and two family houses only) and list new occupants and any garage, deck, fence, shed, pool or finished basement","Owner certifies the home and other structures meet City zoning and that no rubbish, debris or bulk garbage will be left before the new occupancy","All permits and final inspections must be verified for any construction work, including water heater or boiler replacement","Sump pumps must discharge outside the house, not into the sanitary sewer","Handrails on interior stairs of 3 or more risers or over 24 inches high, and on exterior stairs of 4 or more risers","Smoke detector on every level including basements and walk-up attics (10-year sealed battery), and carbon monoxide detectors within 10 feet of all bedrooms","Front door deadbolt may not be keyed on both sides","No open breaker slots in the main panel; junction boxes, outlet and switch covers in place","Gas valves at all appliances, unused gas lines capped, traps on all sinks","Chimney base sealed around smoke pipes; smoke pipes screwed at all joints","Relief valves on boilers and water heaters piped to within 6 inches of the floor","House numbers at least 4 inches high, visible from the street","No sleeping in kitchens, non-habitable spaces or cellars","Separate smoke and carbon monoxide inspection from the Hackensack Fire Department","Also: Open permits: The owner must verify all permits and final inspections for any construction work, including water heater or boiler replacements, or the CCO will not be issued.","Also: Sump pump discharge: Sump pumps must discharge outside and may not be connected to the sanitary sewer.","Also: Zoning certification and debris: The owner certifies on the CCO application that all structures meet zoning and that no rubbish or bulk garbage will be left before the new occupancy."]$j$::jsonb, $j$[{"label":"Certificate of continued occupancy (resale or change in tenancy), one and two family house","amount":"$85"}]$j$::jsonb, $t$https://main.govpilot.com/web/public/03e88201-6d6_CCO-Application-hackensack?uid=6978&ust=NJ&pu=1&id=0$t$, $t$https://www.hackensack.org/building-housing-and-land-use/$t$, $j$[{"url":"https://www.hackensack.org/building-housing-and-land-use/","label":"Official source (hackensack.org)"},{"url":"https://main.govpilot.com/web/public/03e88201-6d6_CCO-Application-hackensack?uid=6978&ust=NJ&pu=1&id=0","label":"Official source (main.govpilot.com)"},{"url":"https://www.hackensack.org/fire-department/","label":"Official source (hackensack.org)"},{"url":"https://ecode360.com/10194321","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$CCO Application (One- and Two-Family Houses Only)$t$, $t$27055023c0964a063187074fe267fce668e104c0b27d6a6e5af8910d5f66b114$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":1,"fee_bad":0,"fee_unchecked":3,"quotes":14,"q_ok":10,"q_bad":0,"q_unchecked":4},"source":"property/data/municipal-requirements/checked/0223.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0223.json$t$, true),
  ($t$0223$t$, $t$Hackensack$t$, $t$BERGEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Hackensack Fire Department, Fire Prevention Bureau (town fire bureau)","Contact: Chris Annunziata, Fire Official, Deputy Chief · 201-646-7685 · fire@hackensack.org","Apply: By appointment. The certificate is issued at the time of the inspection and is valid for 6 months. A failed inspection or no-show needs a new application and fee. Office hours 9 to 4:30, Monday to Friday.","How to apply: Fill out the Smoke and Carbon Form (CSACMAPFEC) and book an inspection with the Fire Prevention Bureau, 205 State Street, 201-646-7685. Pay $70.00 by credit card or check to the Hackensack Fire Department. To pay online, email the completed form to fire@hackensack.org; an invoice number and payment instructions come back, and payment is made on the Fire Department payment portal.","Fire official in the NJ state directory, updated 3/25/2026: Chris G Annunziata · (201) 646-7685 · cannunziata@hackensack.org","Smoke detectors on every level (basement, first floor, second floor, not crawl spaces or unfinished attics) and outside each separate sleeping area; basement detector near the bottom of the basement stairs","Carbon monoxide alarms in every separate sleeping area per NFPA 720 (the CCO checklist says within 10 feet of all bedrooms)","Battery smoke detectors must be 10-year sealed battery units (per the CCO checklist)","Fire extinguisher (form still lists it under the inspector's section)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Certificate of smoke alarm, carbon monoxide alarm and portable fire extinguisher compliance (CSACMAPFEC)","amount":"$70.00"},{"label":"CSACMAPFEC application and inspection (code)","amount":"$70"},{"label":"Reinspection after a failure or no-show (code)","amount":"$70"}]$j$::jsonb, $t$https://www.hackensack.org/wp-content/uploads/2026/01/Smoke-and-Carbon-Form.pdf$t$, $t$https://www.hackensack.org/fire-department/$t$, $j$[{"url":"https://www.hackensack.org/wp-content/uploads/2026/01/Smoke-and-Carbon-Form.pdf","label":"Official source (hackensack.org)"},{"url":"https://www.hackensack.org/fire-department/","label":"Official source (hackensack.org)"},{"url":"https://ecode360.com/10191418","label":"Official source (ecode360.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$CERTIFICATES ARE VALID FOR 6 MONTHS$t$, $t$70d6a228a1ea7dd2e52eda5c128c34ab7755b6714758c96e7cb360ed91d438da$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":1,"fee_bad":0,"fee_unchecked":3,"quotes":14,"q_ok":10,"q_bad":0,"q_unchecked":4},"source":"property/data/municipal-requirements/checked/0223.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0223.json$t$, true),
  ($t$0224$t$, $t$Harrington Park Borough$t$, $t$BERGEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Rental and/or Resale Certificate (Certificate of Continued Occupancy) with Smoke Detector/Carbon Monoxide Alarm compliance$t$, $j$["Issued by: Borough of Harrington Park Building Department (Construction Department), with the Harrington Park Fire Prevention Bureau inspecting smoke and CO alarms","Contact: Jody Wasson, Technical Assistant to the Construction Official (Construction Official: Scott Wickersheim… · 201-768-2585 · building@harringtonparknj.gov","Apply: Borough code says the inspection is done within 21 days of a complete application; an extra $40 buys 5 day service.","How to apply: Fill out the Borough's Rental and/or Resale Certificate & Smoke Detector/Carbon Monoxide Alarm/Fire Extinguisher Compliance application (property, buyer, seller, realtor, closing date, email required) and pay by check to the \"Borough of Harrington Park\" at the time of application. For residential properties, contact Tom Simpson (201-321-9550, tsimp07640@gmail.com) to schedule inspections. Building Department office: 85 Harriot Avenue, 201-768-2585.","Valid for: Inspections are valid for 6 months. A temporary certificate (with escrow) may be issued for up to 90 days.","Property used as zoned or approved (one family, two family, etc.)","No sump pump or unauthorized water connection into the sanitary sewer","All open construction permits inspected, approved and closed","Sidewalks, if installed, in good condition","No interior double-key lock on the main entry/exit door","At least one handrail on stairs with 4 or more risers","No hazardous or imminent-danger conditions on a general visual inspection","Pools need an approved barrier with gates that open out, self-close and latch","Smoke detector on each level including the basement, and within 10 feet of all bedroom doors (not in attics, crawl spaces or right by the kitchen); battery or interconnected electric","At least one carbon monoxide alarm within 10 feet of all bedroom doors (battery, plug-in or combination)","Fire extinguisher (the form title still lists it, but the checklist gives no extinguisher requirement)","Also: Sump pump / sewer connection: No sump pump or other unauthorized water connection into the sanitary sewer; checked during the resale inspection.","Also: Sidewalks: Sidewalks, if installed, must be in good condition.","Also: Open permits: All open construction permits must be inspected, approved and closed."]$j$::jsonb, $j$[{"label":"Rental/resale certificate and smoke/CO inspection, one-family or condo/townhouse","amount":"$160"},{"label":"Rental/resale certificate, multi-family (per apartment)","amount":"$110"},{"label":"Expedited 5 day service (added to the fee)","amount":"$40"}]$j$::jsonb, $t$https://www.harringtonparknj.gov/government/forms/construction/non-construction-applications-forms/708-rental-resale-certificate-application-fillable/file$t$, $t$https://www.harringtonparknj.gov/departments/construction$t$, $j$[{"url":"https://www.harringtonparknj.gov/departments/construction","label":"Official source (harringtonparknj.gov)"},{"url":"https://www.harringtonparknj.gov/government/forms/construction/non-construction-applications-forms/708-rental-resale-certificate-application-fillable/file","label":"Official source (harringtonparknj.gov)"},{"url":"https://ecode360.com/13391613","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$As of May 2024 - If you are selling or renting your property, a Residential Rental/Resale Certificate Application is required.$t$, $t$2fad223415174db5c2be11b3658c4d8032de23ae2e20e9b45475ab0c3a26727c$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":5,"fee_bad":0,"fee_unchecked":0,"quotes":13,"q_ok":9,"q_bad":0,"q_unchecked":4},"source":"property/data/municipal-requirements/checked/0224.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0224.json$t$, true),
  ($t$0224$t$, $t$Harrington Park Borough$t$, $t$BERGEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Harrington Park Fire Prevention Bureau (Harrington Park Fire Department), inspected with the Borough Rental/Resale Certificate (town fire bureau)","Contact: Thomas E Simpson, Fire Official (residential contact on the application) · 201-321-9550 · tsimp07640@gmail.com","Apply: Inspections by appointment; extra $40 for 5 day service. Valid 6 months.","How to apply: Use the Borough's combined Rental and/or Resale Certificate & Smoke Detector/Carbon Monoxide Alarm/Fire Extinguisher Compliance application; contact Tom Simpson to schedule.","Fire official in the NJ state directory, updated 2/19/2026: Thomas E Simpson · (201) 321-9550 · tsimp07640@gmail.com","Smoke detector on each level, including the basement","Smoke detectors within 10 feet of all bedroom doors; not in attics, crawl spaces or the immediate kitchen area","Smoke detectors may be battery operated or an electric interconnected system","At least one carbon monoxide alarm within 10 feet of all bedroom doors (battery, plug-in or combination smoke/CO)","Fire extinguisher (named in the form title; form still lists it, no placement rules given)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Rental/resale certificate and smoke/CO inspection, one-family or condo/townhouse","amount":"$160"},{"label":"Expedited 5 day service (added to the fee)","amount":"$40"}]$j$::jsonb, $t$https://www.harringtonparknj.gov/government/forms/construction/non-construction-applications-forms/708-rental-resale-certificate-application-fillable/file$t$, $t$https://www.harringtonparknj.gov/departments/construction$t$, $j$[{"url":"https://www.harringtonparknj.gov/government/forms/construction/non-construction-applications-forms/708-rental-resale-certificate-application-fillable/file","label":"Official source (harringtonparknj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Tom Simpson: 201-321-9550$t$, $t$2bb80146845dc20bdf32cb87562bf1180acde906394f2d4133748cf88ae41d4a$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":5,"fee_bad":0,"fee_unchecked":0,"quotes":13,"q_ok":9,"q_bad":0,"q_unchecked":4},"source":"property/data/municipal-requirements/checked/0224.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0224.json$t$, true),
  ($t$0225$t$, $t$Hasbrouck Heights Borough$t$, $t$BERGEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Occupancy for sale (certificate of continued occupancy / zoning certificate of compliance)$t$, $j$["Issued by: Borough of Hasbrouck Heights Building Department (Construction and Code Enforcement); inspections by the Fire Chief","Contact: Chris Cunningham, Construction Official and Zoning Officer · 201-288-2143","Apply: Allow two weeks for processing","How to apply: Get the residential CO form at the Building Department, 320 Boulevard, Hasbrouck Heights (Monday to Friday 9:00 a.m. to 4:30 p.m.; summer hours 8:00 a.m. to 3:30 p.m.). Include buyer and seller information and the buyer's phone number, pay the fee, and allow two weeks. The Fire Chief does the inspection.","CO form from the Building Department, 320 Boulevard, with buyer and seller information including the buyer's phone number","Inspection done by the Heights Fire Chief (Rob Knobloch)","Zoning certificate of compliance on a change in ownership: the premises must conform to zoning (or a variance or lawful nonconforming use), meet Planning Board / Board of Adjustment conditions and the Property Maintenance Code","Owner-occupied single-family homes sold to an owner-occupant are reviewed only for zoning conformity","Also: Zoning certificate of compliance: Borough Code Section 275-39 requires a zoning certificate of compliance on any change in ownership; fees in Section 133-30C are $50 (single-family) and $75 (two-family).","Also: Open permit search: To get a list of open or closed permits on a property, submit an OPRA request to the Borough Clerk; the response normally takes about 7 business days."]$j$::jsonb, $j$[{"label":"Certificate of Occupancy for sale, one family","amount":"$50.00"},{"label":"Certificate of Occupancy for sale, two family","amount":"$75.00"},{"label":"Certificate of continued occupancy, single-family dwelling (Borough Code 133-12)","amount":"$50"},{"label":"Certificate of continued occupancy, two-family dwelling (Borough Code 133-12)","amount":"$75"}]$j$::jsonb, null, $t$https://hasbrouck-heightsnj.org/pages/construction-code-enforcement$t$, $j$[{"url":"https://hasbrouck-heightsnj.org/pages/construction-code-enforcement","label":"Official source (hasbrouck-heightsnj.org)"},{"url":"https://ecode360.com/10376737","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/10374053","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$Yes, we require a CO for the sale of a residential home as well as the sale of a commercial property.$t$, $t$5a7bef9de7fccece6c1be0de4019a3d65812d29e7bee2deab95a53922650eebd$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":2,"fee_bad":0,"fee_unchecked":2,"quotes":10,"q_ok":7,"q_bad":0,"q_unchecked":3},"source":"property/data/municipal-requirements/checked/0225.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0225.json$t$, true),
  ($t$0225$t$, $t$Hasbrouck Heights Borough$t$, $t$BERGEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Hasbrouck Heights Fire Prevention Bureau (Fire Department) (town fire bureau)","Contact: Robert Knobloch, Fire Official (secretary: Nancy Halloran) · 201-288-4110 · rknobloch@hasbrouck-heightsnj.org","Apply: Allow two weeks for the sale CO, which the Fire Chief inspects","How to apply: No separate smoke/CO certificate application or fee was found online. The Building Department's sale CO is inspected by the Fire Chief; call the Fire Prevention Bureau (201-288-4110) to confirm whether the smoke/CO certificate is issued with the CO or needs its own application.","Fire official in the NJ state directory, updated 9/26/2025: Robert Knobloch · (201) 288-4110 · rknobloch@hasbrouck-heightsnj.org","Smoke alarms on each level and outside each sleeping area, and carbon monoxide alarms near sleeping areas, as required by N.J.A.C. 5:70-2.3 (no Borough checklist found online)","The Borough's sale CO inspection is done by the Fire Chief / Fire Official","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[]$j$::jsonb, null, $t$https://hasbrouck-heightsnj.org/pages/fire-prevention$t$, $j$[{"url":"https://hasbrouck-heightsnj.org/pages/fire-prevention","label":"Official source (hasbrouck-heightsnj.org)"},{"url":"https://ecode360.com/10374368","label":"Official source (ecode360.com)"},{"url":"https://hasbrouck-heightsnj.org/pages/construction-code-enforcement","label":"Official source (hasbrouck-heightsnj.org)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Fire Prevention Office Hours:$t$, $t$93359585ba454107003aaa1658db63524428e0bb946f3a7640beed125624401c$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":2,"fee_bad":0,"fee_unchecked":2,"quotes":10,"q_ok":7,"q_bad":0,"q_unchecked":3},"source":"property/data/municipal-requirements/checked/0225.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0225.json$t$, true),
  ($t$0226$t$, $t$Haworth Borough$t$, $t$BERGEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Resale Certificate (Continued Certificate of Occupancy)$t$, $j$["Issued by: Borough of Haworth Building Department (Construction Official)","Contact: Robert Sherrow, Construction Official (Technical Assistant: Liana Piretra) · 201-384-8824 · building@haworthnj.org","Apply: About 2 to 3 weeks; two inspections are needed (fire and building)","How to apply: Fill out the Resale Certificate Application (Residential) with closing date, seller and buyer details and an inspection contact, and submit it with a $100 check payable to the Borough of Haworth to the Building Department, 300 Haworth Avenue (building@haworthnj.org, 201-384-8824). Both fire and building inspections are scheduled from this one application.","Smoke detectors on every level (battery units allowed in existing 1 and 2 family homes); basement detector on the basement ceiling at the foot of the stairs","Carbon monoxide detectors within 10 feet of bedrooms in the hallway (not inside bedrooms)","Hardwired systems must be interconnected","Sump pump must discharge onto the property or street, not into the Borough sewer","Pool: compliant locking gate and fencing","House number near the front door light, 4 to 6 inches high, contrasting colors","Handrails where there are 4 or more steps","Anti-tip bracket on the stove","Sidewalks, curbs and gutters in safe, even condition","No fire extinguisher needed (form notes the February 3, 2025 change)","Also: Sump pump discharge: Sump pumps must empty onto the property or the street and cannot be connected to the Borough sewer; checked during the resale inspection.","Also: Sidewalks and curbs: Sidewalks, curbs and gutters in front of the home must be kept in safe, even condition; checked during the resale inspection."]$j$::jsonb, $j$[{"label":"Resale certificate application fee (single and multi-family)","amount":"$100"},{"label":"Re-inspection after a failed inspection","amount":"$25"},{"label":"Certificate of Continued Occupancy, residential (Borough code)","amount":"$100"}]$j$::jsonb, $t$https://www.haworthnj.org/vertical/sites/%7B3226EF68-541C-456F-8644-AC724E9AC52C%7D/uploads/Re_Sale_Certificate_Residential.pdf$t$, $t$https://www.haworthnj.org/building$t$, $j$[{"url":"https://www.haworthnj.org/building","label":"Official source (haworthnj.org)"},{"url":"https://www.haworthnj.org/vertical/sites/%7B3226EF68-541C-456F-8644-AC724E9AC52C%7D/uploads/Re_Sale_Certificate_Residential.pdf","label":"Official source (haworthnj.org)"},{"url":"https://ecode360.com/35571707","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$If you are selling your home a Re Sale Certificate Residential is required.$t$, $t$40772d7e4b9aabcd262a4e96126c4282b0849484f5e7da21eaa96e3a0c964696$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":2,"fee_bad":0,"fee_unchecked":2,"quotes":15,"q_ok":11,"q_bad":0,"q_unchecked":4},"source":"property/data/municipal-requirements/checked/0226.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0226.json$t$, true),
  ($t$0226$t$, $t$Haworth Borough$t$, $t$BERGEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Haworth Bureau of Fire Prevention (Fire Official), inspected as part of the Borough Resale Certificate (town fire bureau)","Contact: Alan J. Silverman, Fire Official · 201-384-4785 · firemusik@aol.com","Apply: The whole resale process takes about 2 to 3 weeks.","How to apply: Apply through the Building Department's Resale Certificate Application; the form says two inspections are required, fire and building. The Fire Protection Subcode/Fire Official (Alan Silverman) inspects Tuesday and Friday, 12:00 to 2:00 pm.","Fire official in the NJ state directory, updated 4/2/2026: Alan J Silverman · (201) 384-4785 · firemusik@aol.com","Approved smoke detection and carbon monoxide detector installed per NFPA 72 and N.J.A.C. 5:70-2.3","Battery smoke and CO detectors are allowed in existing 1 and 2 family homes; electric systems must be interconnected","Smoke detectors on every level, within 10 feet of sleeping areas in a common area, not within 3 feet of an outside door, window or air vent","No fire extinguisher required (per the Borough's 2/25/2025 form)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Certificate of Compliance for smoke alarms (Borough code)","amount":"$35"}]$j$::jsonb, $t$https://www.haworthnj.org/vertical/sites/%7B3226EF68-541C-456F-8644-AC724E9AC52C%7D/uploads/Re_Sale_Certificate_Residential.pdf$t$, $t$https://www.haworthnj.org/building$t$, $j$[{"url":"https://www.haworthnj.org/vertical/sites/%7B3226EF68-541C-456F-8644-AC724E9AC52C%7D/uploads/Re_Sale_Certificate_Residential.pdf","label":"Official source (haworthnj.org)"},{"url":"https://ecode360.com/35571784","label":"Official source (ecode360.com)"},{"url":"https://www.haworthnj.org/fire","label":"Official source (haworthnj.org)"},{"url":"https://www.haworthnj.org/building","label":"Official source (haworthnj.org)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Resale Certificate shall not be issued for any structure unless an approved “Automatic Fire Detection System” and$t$, $t$619f8f633523e9a9a1ce35978d043efc968791ee367935b7326b4ef922bcf190$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":2,"fee_bad":0,"fee_unchecked":2,"quotes":15,"q_ok":11,"q_bad":0,"q_unchecked":4},"source":"property/data/municipal-requirements/checked/0226.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0226.json$t$, true),
  ($t$0227$t$, $t$Hillsdale Borough$t$, $t$BERGEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Continuing Certificate of Inspection (CCI) for Sale, Transfer or Lease$t$, $j$["Issued by: Borough of Hillsdale Fire Prevention Bureau / Code Enforcement Official (380 Hillsdale Avenue)","Contact: Darren Blankenbush, Fire Official · 201-722-2612 x1568 · dblankenbush@hillsdalenj.org","Apply: Must allow 10 business days for the inspection. CCI inspections are held Tuesday 4:00 to 6:00 pm.","How to apply: Fill out the Borough's Application for Continuing Certificate of Inspection (CCI) for Sale, Transfer or Lease (linked from the Building, Construction & Zoning page) and pay by check made payable to the Borough of Hillsdale. Give the anticipated closing date and an inspection contact. Allow 10 business days. A missed appointment counts as the initial inspection and is a failure. Call 201-722-2612 to make an appointment.","Valid for: 60 days from the issuance date","Smoke alarms on each level and outside each separate sleeping area; 10-year sealed battery alarms (ANSI/UL 217), and AC-powered alarms from original construction may not be replaced with battery alarms","Carbon monoxide alarms within 10 feet of the doorway or inside each separate sleeping area (battery, hard-wired or plug-in with battery back-up), unless the home has no fuel-burning device and no attached garage","Monitored or low-voltage fire alarm systems need an inspection or certification report from a NJ licensed electrician or alarm contractor showing the system works","Sump pumps must discharge directly to the exterior","Garage door openers plugged into a dedicated outlet (no adaptors or extension cords)","Front door dead bolt must be keyless (thumb-turn) on the inside","Dryer vents must vent directly to the exterior","Bedroom windows must operate and be the correct size for egress (especially attic and basement rooms)","House number visible from the street","No excessive debris or abandoned vehicles","Boiler, furnace and water heater flue connections secure at the chimney","Application asks whether there are open building permits","Portable fire extinguisher is no longer required (Fire Official memo of March 1, 2025)","Also: Open permits: The CCI application asks whether there are open building permits; call the Building Department (201-722-2612) to check before the inspection.","Also: Sump pump discharge: Sump pumps must discharge directly to the exterior (CCI checklist item)."]$j$::jsonb, $j$[{"label":"Continuing Certificate of Inspection (CCI) for sale, transfer or lease, inspection fee","amount":"$100.00"},{"label":"CCI re-inspection fee (after a failure)","amount":"$50.00"}]$j$::jsonb, $t$https://www.hillsdalenj.org/vertical/Sites/%7BFE916F8D-CA48-4788-B4B7-6A2BF8501398%7D/uploads/CCI_application_form.pdf$t$, $t$https://www.hillsdalenj.org/buildingconstructionzoning$t$, $j$[{"url":"https://www.hillsdalenj.org/buildingconstructionzoning","label":"Official source (hillsdalenj.org)"},{"url":"https://www.hillsdalenj.org/vertical/Sites/%7BFE916F8D-CA48-4788-B4B7-6A2BF8501398%7D/uploads/CCI_application_form.pdf","label":"Official source (hillsdalenj.org)"}]$j$::jsonb, $t$to view the requirements for change of occupancy, 1-2 Family dwellings & application$t$, $t$2c3a567b3e5cc9966a43ba3f3edcf3e967697cee7c36c1c8b627f2efdcd461e8$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":0,"fee_bad":0,"fee_unchecked":4,"quotes":13,"q_ok":4,"q_bad":0,"q_unchecked":9},"source":"property/data/municipal-requirements/checked/0227.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0227.json$t$, true),
  ($t$0227$t$, $t$Hillsdale Borough$t$, $t$BERGEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Hillsdale Fire Prevention Bureau (Hillsdale Fire Department), through the Continuing Certificate of Inspection (town fire bureau)","Contact: Darren Blankenbush, Fire Official · 201-722-2612 ext. 1568 · dblankenbush@hillsdalenj.org","Apply: Allow 10 business days; CCI inspections Tuesday 4:00 to 6:00 pm. Certificate valid 60 days.","How to apply: The smoke and CO alarm check is part of the CCI. Submit the CCI application to the Fire Prevention Bureau, 380 Hillsdale Ave., with a check to the Borough of Hillsdale.","Fire official in the NJ state directory, updated 5/18/2026: Darren l Blankenbush · (201) 722-2612 · dblankenbush@hillsdalenj.org","Smoke alarms on each level and outside each separate sleeping area; 10-year sealed battery type (ANSI/UL 217); hardwired alarms may not be swapped for battery alarms","Carbon monoxide alarms within 10 feet of the doorway or inside each sleeping area","Extra smoke and CO alarms if bedrooms are in separate areas of the home","Proof that any monitored or low-voltage fire alarm system works (report from a NJ licensed electrician or alarm contractor)","Portable fire extinguisher no longer required (per the Bureau's March 1, 2025 memo)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Continuing Certificate of Inspection (CCI) for sale, transfer or lease, inspection fee","amount":"$100.00"},{"label":"CCI re-inspection fee (after a failure)","amount":"$50.00"}]$j$::jsonb, $t$https://www.hillsdalenj.org/vertical/Sites/%7BFE916F8D-CA48-4788-B4B7-6A2BF8501398%7D/uploads/CCI_application_form.pdf$t$, $t$https://www.hillsdalenj.org/buildingconstructionzoning$t$, $j$[{"url":"https://www.hillsdalenj.org/vertical/Sites/%7BFE916F8D-CA48-4788-B4B7-6A2BF8501398%7D/uploads/CCI_application_form.pdf","label":"Official source (hillsdalenj.org)"},{"url":"https://ecode360.com/10261709","label":"Official source (ecode360.com)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Hillsdale Fire Prevention Bureau 380 Hillsdale Ave. Hillsdale, New Jersey 07642 Phone: 201-722-2612 Ext. 1568$t$, $t$52e2fd4aa300d1f1ed7cbf75188e5378ddb23a699e6e5fe90620d2274c02ab80$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":0,"fee_bad":0,"fee_unchecked":4,"quotes":13,"q_ok":4,"q_bad":0,"q_unchecked":9},"source":"property/data/municipal-requirements/checked/0227.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0227.json$t$, true),
  ($t$0228$t$, $t$Ho-Ho-Kus Borough$t$, $t$BERGEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Continued Occupancy (CCO)$t$, $j$["Issued by: Borough of Ho-Ho-Kus Construction Code Official (with the Property Maintenance Officer and Zoning Officer); the combined application is handled through the Bureau of Fire Prevention","Contact: Mark Berninger, Construction Code Official, Building Subcode Official · 201-652-4400 ext. 241","Apply: The code says to apply 25 business days before the change of ownership; the Borough inspects within 10 business days of a complete application, no more than 30 days before the change. The Borough's cover letter says certificates are issued within five business days unless there are open items.","How to apply: Download the CCO and Smoke Detector Compliance Application from the Borough's Forms and Applications page. Fill out both the Application for Residential Certificate of Continued Occupancy and the smoke detector / CO / fire extinguisher compliance application (seller or seller's agent signs), and pay by check made payable to the Borough of Ho-Ho-Kus (one $250 check covers both). The forms carry the Bureau of Fire Prevention address: 333 Warren Avenue, Ho-Ho-Kus, NJ 07423, 201-652-4400 x219.","Valid for: One year from the date of issue","Review of Borough files for open building or zoning permits or violations, and a check that utilities, assessor and tax files are current","General inspection of the visible parts of the building, property and equipment for violations of Borough ordinances, the NJ Construction Code and the NJ Fire Code","All open permits, violations or fees owed to the Borough must be satisfied before the CCO is issued","Smoke detector, carbon monoxide alarm and fire extinguisher compliance certificate (separate part of the same packet)","If violations cannot be fixed before closing, a temporary CCO (TCCO) may be issued with a $1,000 cash bond","Also: Open permits, violations and Borough fees: All open permits, violations or fees owed to the Borough must be satisfied before the CCO is issued; the Borough also checks that utilities, assessor and tax files are current."]$j$::jsonb, $j$[{"label":"CCO application fee (Borough cover letter)","amount":"$150"},{"label":"Certificate of continued occupancy application fee (Code Section 77-6.2A), plus $75 per resubmission","amount":"$100"},{"label":"Temporary certificate of continued occupancy (TCCO) application fee (Code Section 77-6.2B)","amount":"$200"},{"label":"Combined check for CCO and smoke detector compliance certificate","amount":"$250"}]$j$::jsonb, $t$https://www.hhkborough.com/DocumentCenter/View/881/CCO-and-Smoke-Detector-Compliance-Application$t$, $t$https://www.hhkborough.com/1208/Forms-and-Applications$t$, $j$[{"url":"https://ecode360.com/13541569","label":"Official source (ecode360.com)"},{"url":"https://www.hhkborough.com/DocumentCenter/View/881/CCO-and-Smoke-Detector-Compliance-Application","label":"Official source (hhkborough.com)"},{"url":"https://www.hhkborough.com/Directory.aspx","label":"Official source (hhkborough.com)"},{"url":"https://ecode360.com/15602479","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$No residential or nonresidential property may be changed in tenancy, use or ownership unless a certificate of continued occupancy has been issued by the Borough Construction Code Official on forms provided and the required fee paid for such inspection.$t$, $t$853077dfceaa7527eefe7d67eeb77cd85628bfcfaceff0e8164fc4679d02e2fc$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":0,"fee_bad":0,"fee_unchecked":6,"quotes":13,"q_ok":3,"q_bad":0,"q_unchecked":10},"source":"property/data/municipal-requirements/checked/0228.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0228.json$t$, true),
  ($t$0228$t$, $t$Ho-Ho-Kus Borough$t$, $t$BERGEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Ho-Ho-Kus Bureau of Fire Prevention (town fire bureau)","Contact: Daniel Mc Eldowney, Fire Official · 201-652-4400 ext. 219","Apply: The Borough letter says certificates are issued within five business days unless there are open items. The code says the inspection is done within 10 to 15 days of receiving the application and fee.","How to apply: Fill out the Application for Smoke Detector, Carbon Monoxide Detector and Fire Extinguisher Compliance in the CCO and Smoke Detector Compliance packet, check off each item, sign it, and submit it to the Bureau of Fire Prevention with a check made payable to the Borough of Ho-Ho-Kus. The Borough then inspects.","Fire official in the NJ state directory, updated 2/19/2026: Daniel F Mc Eldowney · (201) 652-4400 · d.mceldowney@yahoo.com","Ten-year sealed smoke detectors (batteries cannot be removed) on every level of the home, including the basement, not required in crawl spaces or unfinished attics","Smoke detectors within 10 feet of all sleeping areas and at the bottom of stairs, on the ceiling","Carbon monoxide detectors in the hall within 10 feet of bedroom doors, on the ceiling or wall; plug-in units only if an outlet is in the hall; all detectors permanently mounted","All smoke and carbon monoxide detectors in working order","One ABC rated 10 lb. dry chemical extinguisher within 10 feet of the kitchen (form still lists it)","Seller or seller's agent signs an affidavit that the items are installed; the Borough then inspects","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Certificate of Smoke Detector Compliance application fee (Borough cover letter)","amount":"$100.00"},{"label":"Certificate of inspection, first visit $50 and $25 per later visit (Code Section 26-9D, 1991 text)","amount":"$50"}]$j$::jsonb, $t$https://www.hhkborough.com/DocumentCenter/View/881/CCO-and-Smoke-Detector-Compliance-Application$t$, $t$https://www.hhkborough.com/Directory.aspx$t$, $j$[{"url":"https://ecode360.com/13538603","label":"Official source (ecode360.com)"},{"url":"https://www.hhkborough.com/DocumentCenter/View/881/CCO-and-Smoke-Detector-Compliance-Application","label":"Official source (hhkborough.com)"},{"url":"https://www.hhkborough.com/Directory.aspx","label":"Official source (hhkborough.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Upon the sale of a dwelling unit or the rental, lease or transfer of any dwelling unit, the seller, landlord, transferor, buyer, transferee or tenant is required to obtain from the Ho-Ho-Kus Bureau of Fire Prevention a certificate of inspection stating that the property is in compliance with the provisions of this chapter.$t$, $t$409ecabfab443a9cb815495c7f64cc6dfea82a3752f90770a492c318e9206131$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":0,"fee_bad":0,"fee_unchecked":6,"quotes":13,"q_ok":3,"q_bad":0,"q_unchecked":10},"source":"property/data/municipal-requirements/checked/0228.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0228.json$t$, true),
  ($t$0229$t$, $t$Leonia Borough$t$, $t$BERGEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Resale/Rental Occupancy (CRO, also called CCO)$t$, $j$["Issued by: Borough of Leonia Building Department (Public Officer / property maintenance inspection)","Contact: J.P. Lee, Technical Assistant, Building Department · 201-592-5780 x 253 · JPLee@leonianj.gov","Apply: Fees must be paid before the inspection to lock in the date; the fee is lower the further ahead the inspection is scheduled (15 days or more for the lowest fee).","How to apply: Apply online with the Borough's Residential CCO (CRO) application on GovPilot, linked from the 'Certificate of Resale/Rental (CRO/CCO)' page, and pay the Borough of Leonia (two separate payments: CRO and smoke/CO). To schedule, come to the Building Department, 312 Broad Ave, Leonia, NJ 07605, or call 201-592-5780 ext. 253.","Online CRO application with the new owner's details and the closing date","All open permits must have a final inspection before a CRO inspection can be scheduled (Building Department guidance)","Separate Certificate of Smoke Alarm, Carbon Monoxide Alarm and Secondary Power Supply Identification Label compliance with its own inspection and fee","Secondary power supply (generator, solar, battery) must be identified on the application; at least one option must be checked","Owner certifies the house meets zoning and that no rubbish, debris or bulk garbage will be left before the new occupancy","Resale-only certificates (buyer not occupying) need a notarized letter from the purchaser's attorney","Also: Open permits: All open permits must have a final inspection before a CRO inspection can be scheduled.","Also: Water service line: SUEZ asks owners to confirm a water meter is installed and that there is no lead service line; contact SUEZ directly if so (request, not a sale condition)."]$j$::jsonb, $j$[{"label":"CRO inspection scheduled within 7 days (current online form)","amount":"$150"},{"label":"CRO inspection scheduled within 14 days (current online form)","amount":"$125"},{"label":"CRO inspection scheduled 15 days or more ahead (current online form)","amount":"$100"},{"label":"CRO reinspection (current online form)","amount":"$50"},{"label":"Certificate of sale/rental occupancy, inspection fee three weeks before inspection date (Code Section 123-23F; lower than the current form)","amount":"$50"},{"label":"Certificate of sale/rental occupancy, two weeks before (Code)","amount":"$75"},{"label":"Certificate of sale/rental occupancy, one week before (Code)","amount":"$100"}]$j$::jsonb, $t$https://main.govpilot.com/web/public/2b087029-724_Residential-CCO-Application-leonia?uid=7020&ust=NJ&pu=1&id=0$t$, $t$https://www.leonianj.gov/borough-government/borough-departments/building-department$t$, $j$[{"url":"https://www.leonianj.gov/borough-government/borough-departments/building-department","label":"Official source (leonianj.gov)"},{"url":"https://main.govpilot.com/web/public/2b087029-724_Residential-CCO-Application-leonia?uid=7020&ust=NJ&pu=1&id=0","label":"Official source (main.govpilot.com)"},{"url":"https://ecode360.com/9252039","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/9250935","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$Certificate of Resale/Rental: If there is a change of occupancy whether by resale or rental you are required to submit a CRO application, along with the proper fee, to the Building Department.$t$, $t$6ca416325ab78e275d4f57d400a2e44eb88577894426281960a3ce1c92f9675d$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":14,"fee_ok":7,"fee_bad":0,"fee_unchecked":7,"quotes":13,"q_ok":5,"q_bad":0,"q_unchecked":8},"source":"property/data/municipal-requirements/checked/0229.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0229.json$t$, true),
  ($t$0229$t$, $t$Leonia Borough$t$, $t$BERGEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Leonia Fire Prevention Bureau (town fire bureau)","Contact: David A. Haenelt, Fire Marshal · 201-592-5780 x254 · dhaenelt@leonianj.gov","Apply: Fee depends on how far ahead the inspection is scheduled (code: more than 10 business days for the lowest fee; current form: 15 days or more).","How to apply: Requested on the same online Residential CCO (CRO) application, with a separate payment for the smoke/CO inspection. Questions to the Fire Prevention Bureau, Borough Hall, 312 Broad Avenue, 2nd floor.","Fire official in the NJ state directory (town), updated 4/9/2026: Dave Haenelt · (201) 592-5780 · dhaenelt@leonianj.gov","Smoke alarms and carbon monoxide alarms per N.J.A.C. 5:70-4.19 (see the Borough's CSACMAC requirements sheet)","Secondary power supply identification label where a generator, solar or battery system exists (listed on the Borough form)","No fire extinguisher: the Borough says the fire extinguisher requirement has been removed","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke & CO certification inspection within 7 days (current online form)","amount":"$150"},{"label":"Smoke & CO certification inspection within 14 days (current online form)","amount":"$125"},{"label":"Smoke & CO certification inspection 15 days or more ahead (current online form)","amount":"$100"},{"label":"Certificate of smoke alarm and CO alarm compliance, more than 10 business days before inspection (Code Section 136-13)","amount":"$100"},{"label":"Four to 10 business days before inspection (Code)","amount":"$125"},{"label":"Fewer than four business days before inspection (Code)","amount":"$150"},{"label":"Reinspection per occurrence (Code)","amount":"$50"}]$j$::jsonb, $t$https://main.govpilot.com/web/public/2b087029-724_Residential-CCO-Application-leonia?uid=7020&ust=NJ&pu=1&id=0$t$, $t$https://www.leonianj.gov/borough-government/borough-departments/fire-prevention-bureau$t$, $j$[{"url":"https://main.govpilot.com/web/public/2b087029-724_Residential-CCO-Application-leonia?uid=7020&ust=NJ&pu=1&id=0","label":"Official source (main.govpilot.com)"},{"url":"https://www.leonianj.gov/borough-government/borough-departments/building-department","label":"Official source (leonianj.gov)"},{"url":"https://ecode360.com/9251166","label":"Official source (ecode360.com)"},{"url":"https://www.leonianj.gov/borough-government/borough-departments/fire-prevention-bureau","label":"Official source (leonianj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Note: Two inspections are required when selling or renting one- and two-family dwellings, including co-ops, condominiums, and townhomes.$t$, $t$58c5aab3d5b0d0c366b20493bbb4e67dd74c22407c50da8ebd63ad84e058d93a$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":14,"fee_ok":7,"fee_bad":0,"fee_unchecked":7,"quotes":13,"q_ok":5,"q_bad":0,"q_unchecked":8},"source":"property/data/municipal-requirements/checked/0229.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0229.json$t$, true),
  ($t$0230$t$, $t$Little Ferry Borough$t$, $t$BERGEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Resale (Certificate of Continued Occupancy / CCO)$t$, $j$["Issued by: Borough of Little Ferry Building Department (Construction Official)","Contact: Keith Dalton, Construction Code Official (technical assistant: Bertha Sneyer, 201-641-2942, b-sneyer@littleferrynj.org) · 201-641-9234 ext. 664 · k-dalton@littleferrynj.org","How to apply: Download the Application for a Certificate of Resale from the Building Department page, fill out every page (owner affidavit, buyer's notarized Certificate in Lieu of Oath, Tax Office sign-off, Police emergency contact form) and submit it with a check for $100 per unit payable to the Borough of Little Ferry at Borough Hall, 215-217 Liberty Street (Monday to Friday 8:30am to 4:30pm). Give the name and phone of the person who will meet the inspector. Permit and inspection requests also run through the SDL Portal linked on the Building Department page.","Inspection of the unit by the Building Department; nobody may occupy the home before Building Department approval","All open building permits must be closed, and all taxes, penalties and fees due to the Borough must be paid; the Tax Office signs off that taxes are current","Buyer signs a notarized Certificate in Lieu of Oath stating the number of dwelling units (no illegal units; basement may not be used as a dwelling or sleeping area; short-term rentals prohibited)","Owner (not the realtor) signs the Smoke/CO Detectors, Fire Door and Fire Extinguisher Affidavit","Smoke detectors as required for the year built, on every level and near sleeping areas; detectors over 10 years old replaced; battery-only units must be 10-year sealed","Carbon monoxide detectors within 10 feet of sleeping areas, on every level, outside any room with a fuel-burning appliance and near an attached garage entrance; CO detectors over 5 years old replaced unless the manufacturer allows longer","ABC fire extinguisher rated at least 2A:10B:C within 10 feet of the kitchen, top no more than 5 feet above the floor (form still lists it)","Buyer fills out the Police Department emergency contact form","Construction Official certifies whether there are open permits","Also: Taxes and Borough fees current: The Tax Office must sign that taxes are current, and all taxes, penalties and fees due to the Borough must be paid before the CCO is issued.","Also: Open permits: The Construction Official certifies whether there are open permits; all must be closed before the CCO is issued.","Also: Buyer's Certificate in Lieu of Oath (unit count): The buyer signs a notarized statement of how many dwelling units the house has, agreeing not to rent part of a single-family home or convert it without telling the Construction Department.","Also: Police emergency contact form: The buyer fills out the Police Department emergency contact form included in the resale packet."]$j$::jsonb, $j$[{"label":"Certificate of Resale, per unit","amount":"$100"},{"label":"Resale certificate, per dwelling unit (Borough Code 13-1.6)","amount":"$100"}]$j$::jsonb, $t$https://www.littleferrynj.org/filestorage/121/137/Certificate_of_Resale_-_8-21-25.pdf$t$, $t$https://www.littleferrynj.org/content/121/137/default.aspx$t$, $j$[{"url":"https://www.littleferrynj.org/filestorage/121/137/Certificate_of_Resale_-_8-21-25.pdf","label":"Official source (littleferrynj.org)"},{"url":"https://www.littleferrynj.org/content/121/137/default.aspx","label":"Official source (littleferrynj.org)"},{"url":"https://ecode360.com/34742970","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$Application for a Certificate of RESALE Borough Ordinance No. 1605-19-23 Ordinance No.1272-04-09$t$, $t$f5f8456afe820df86c43e8f30b8b296be0f43192671f70df907b56c71112a412$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":2,"fee_ok":0,"fee_bad":0,"fee_unchecked":2,"quotes":9,"q_ok":2,"q_bad":0,"q_unchecked":7},"source":"property/data/municipal-requirements/checked/0230.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0230.json$t$, true),
  ($t$0230$t$, $t$Little Ferry Borough$t$, $t$BERGEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Entire borough: issued by Borough of Little Ferry Building Department (smoke/CO checked as part of the Certificate of Resale) (town fire bureau)","Entire borough contact: Keith Dalton, Construction Code Official · 201-641-9234 ext. 664 · k-dalton@littleferrynj.org","Entire borough, how to apply: The smoke, CO and extinguisher requirements and the owner affidavit are pages of the Certificate of Resale application filed with the Building Department.","Entire borough (per state directory): issued by NJ Division of Fire Safety (listed in the NJ DCA directory as the smoke detector compliance office for Little Ferry)","Entire borough (per state directory) contact: 609-633-6132","Entire borough (per state directory), how to apply: Call the number listed in the state directory, (609) 633-6132, to confirm whether a state-issued certificate is needed in addition to the Borough's resale inspection.","Fire official in the NJ state directory (town), updated 2/27/2026: William R Holley · (201) 641-9234 · wrhdpw1@gmail.com","Smoke detectors placed according to the year the house was built (battery 10-year sealed units allowed for pre-1977 homes; 110V interconnected units for newer homes), on each level and within 10 feet of sleeping rooms","Smoke detectors with a manufacture date over 10 years must be replaced","Carbon monoxide detectors within 10 feet of sleeping areas, on every level, outside rooms with fuel-burning appliances and near an attached garage entrance","ABC fire extinguisher rated at least 2A:10B:C within 10 feet of the kitchen (form still lists it)","Owner or building management (not the realtor) signs the Smoke/CO Detectors, Fire Door and Fire Extinguisher Affidavit","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[]$j$::jsonb, $t$https://www.littleferrynj.org/filestorage/121/137/Certificate_of_Resale_-_8-21-25.pdf$t$, $t$https://www.littleferrynj.org/content/121/137/default.aspx$t$, $j$[{"url":"https://www.littleferrynj.org/filestorage/121/137/Certificate_of_Resale_-_8-21-25.pdf","label":"Official source (littleferrynj.org)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Smoke/Carbon Dioxide (CO) Detectors / Fire Door / Fire Extinguisher Requirements$t$, $t$296a5d2ceeffe89e86503fd16ce58d8363b3f8c24cadf0cbe17ef688e3555496$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":2,"fee_ok":0,"fee_bad":0,"fee_unchecked":2,"quotes":9,"q_ok":2,"q_bad":0,"q_unchecked":7},"source":"property/data/municipal-requirements/checked/0230.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0230.json$t$, true),
  ($t$0232$t$, $t$Lyndhurst Township$t$, $t$BERGEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Resale Certificate (Certificate of Continued Occupancy)$t$, $j$["Issued by: Township of Lyndhurst Construction / Building Department","Contact: 201-804-2490, ex. 2550","How to apply: Download the Application for Resale Certificate (CO Application) from the Township Forms page, Construction Department section, and file it with the Building/Construction Department at Town Hall, 367 Valley Brook Avenue. The Tax Assessor completes the room breakdown before the inspection. Apply for the separate smoke/CO certificate with the Bureau of Fire Prevention.","Application for Resale Certificate listing seller, buyer, sale price and closing date","Room-by-room breakdown is filled out by the Tax Assessor before the inspection and compared with the assessor's record","Inspector checks open permits, the number of families, smoke detectors and carbon monoxide detectors","Proof that the lead water service pipe has been replaced (or that the property is excluded) before a Certificate of Occupancy, Certificate of Code Compliance and smoke/CO certificates are issued on a sale","Also: Lead water service pipe: On a sale or transfer, the owner must show the lead service pipe was replaced (or the property is excluded) to get the Certificate of Occupancy, Certificate of Code Compliance and smoke/CO certificates.","Also: Assessor room check: The Tax Assessor fills in the present and past room breakdown on the resale application before the inspection.","Also: Open permits: The resale inspector records open permits on the application."]$j$::jsonb, $j$[{"label":"Certificate of continued occupancy, one family","amount":"$100"},{"label":"Certificate of continued occupancy, two family","amount":"$150"}]$j$::jsonb, $t$https://www.lyndhurstnj.org/_Content/pdf/forms/Construction/CO-Application.pdf$t$, $t$https://www.lyndhurstnj.org/Departments/construction-department$t$, $j$[{"url":"https://www.lyndhurstnj.org/forms","label":"Official source (lyndhurstnj.org)"},{"url":"https://www.lyndhurstnj.org/_Content/pdf/forms/Construction/CO-Application.pdf","label":"Official source (lyndhurstnj.org)"},{"url":"https://ecode360.com/34769770","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/44786227","label":"Official source (ecode360.com)"},{"url":"https://www.lyndhurstnj.org/Directory","label":"Official source (lyndhurstnj.org)"}]$j$::jsonb, $t$CO Application$t$, $t$eb662c5fe75e265cdbb2ca5a844c01783b735538a0625d628440bac9feca2dba$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":3,"fee_bad":0,"fee_unchecked":2,"quotes":13,"q_ok":5,"q_bad":0,"q_unchecked":8},"source":"property/data/municipal-requirements/checked/0232.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0232.json$t$, true),
  ($t$0232$t$, $t$Lyndhurst Township$t$, $t$BERGEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Lyndhurst Bureau of Fire Prevention (town fire bureau)","Contact: Robert Ferrara, Fire Official · (201) 933-3079 · robertf@lyndhurstnj.org","Apply: Fee depends on business days between payment and the inspection date: more than 10 business days for the lowest fee.","How to apply: Fill in the Certificate of Smoke Detector & Carbon Monoxide Alarm Compliance form (property, closing date, seller and agent, and the email address the certificate should go to) and send it with a check payable to Township of Lyndhurst to the Bureau of Fire Prevention, 253 Stuyvesant Ave.","Fire official in the NJ state directory (town), updated 7/28/2026: Robert Ferrara · (201) 933-3079 · robertf@lyndhurstnj.org","Ten-year sealed battery single station smoke alarms listed to ANSI/UL 217; A/C-powered alarms from original construction may not be replaced with battery alarms","Smoke detectors on every level (basement, first floor, second floor) excluding crawl spaces and unfinished attics, and outside sleeping areas","Carbon monoxide alarm outside each sleeping area; two needed if bedrooms are on different levels or wings","Minimum alarm type depends on when the house was built or renovated (form has a year-by-year table)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke/CO certificate, inspection scheduled more than 10 business days after payment","amount":"$45.00"},{"label":"Smoke/CO certificate, inspection scheduled 4 to 10 business days after payment","amount":"$90.00"},{"label":"Smoke/CO certificate, inspection scheduled fewer than 4 business days after payment","amount":"$161.00"}]$j$::jsonb, $t$https://www.lyndhurstnj.org/_Content/pdf/forms/Certificate-of-Smoke-Detector-Carbon-Monoxide-Alarm-Compliance.pdf$t$, $t$https://www.lyndhurstnj.org/Departments/fire-prevention$t$, $j$[{"url":"https://www.lyndhurstnj.org/_Content/pdf/forms/Certificate-of-Smoke-Detector-Carbon-Monoxide-Alarm-Compliance.pdf","label":"Official source (lyndhurstnj.org)"},{"url":"https://www.lyndhurstnj.org/Directory","label":"Official source (lyndhurstnj.org)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$before any one or two-family dwelling is sold, leased, or otherwise made subject to change in occupancy for residential purposes, the owner shall obtain a certificate of compliance from the Lyndhurst Bureau of Fire Prevention.$t$, $t$5214c577cc200726a945f1c3d6ad23714f652bd7fd3dabaacf22b3c742349ae7$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":3,"fee_bad":0,"fee_unchecked":2,"quotes":13,"q_ok":5,"q_bad":0,"q_unchecked":8},"source":"property/data/municipal-requirements/checked/0232.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0232.json$t$, true),
  ($t$0233$t$, $t$Mahwah Township$t$, $t$BERGEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Continued Occupancy (CCO), residential, selling a home$t$, $j$["Issued by: Township of Mahwah Building Department (Construction Code Official)","Contact: Anthony Vero, Construction Code Official / Building Subcode · 201-529-5757 · avero@mahwahtwp.org","Apply: The code says CCOs are issued or denied within 10 days of filing the application. The code also requires the CCO before the property is listed.","How to apply: Apply on the Township's CCO form through the Building Department (Department of Inspections), 475 Corporate Drive, 201-529-5757. The CCO form itself was not found online; call the Building Department for it.","Valid for: One year from the date of issuance, provided there is no material change in the physical status of the premises","Required for one- and two-family dwellings before the property is listed, and on transfer of title (homes with 3 or more units are exempt)","Visual inspection by the Construction Code Official, who may call in subcode officials, the Water Department and the Department of Health","Inspection covers items such as pools, electric fixtures and wiring, plumbing fixtures and water heaters, heating and ventilation, the building exterior and other hazards","Any additions or construction done without permits must have permit fees paid before the CCO is issued","Separate smoke/CO certificate from Fire Prevention (not part of the CCO inspection)","Exempt transfers include deed corrections, transfers between spouses, parent and child or grandparent and grandchild, estate distributions, new construction and quitclaim deeds to quiet title","Also: Tax search notice: Tax searches and added assessment searches from the Tax Collector carry a notice that a CCO is required for a sale.","Also: Unpermitted work: If the CCO inspection finds additions or construction done without permits, the permit fees must be paid before the CCO is issued.","Also: Water Department and Health inspection: The CCO inspection may include the Water Department and the Department of Health."]$j$::jsonb, $j$[{"label":"Certificate of Continued Occupancy, residential (selling a home)","amount":"$175"}]$j$::jsonb, null, $t$https://www.mahwahtwp.org/159/Construction-Office-Department-of-Inspec$t$, $j$[{"url":"https://ecode360.com/49703411","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/34810206","label":"Official source (ecode360.com)"},{"url":"https://www.mahwahtwp.org/157/Fire-Prevention","label":"Official source (mahwahtwp.org)"},{"url":"https://www.mahwahtwp.org/159/Construction-Office-Department-of-Inspec","label":"Official source (mahwahtwp.org)"}]$j$::jsonb, $t$A certificate of continued occupancy shall be required in the following occurrences:$t$, $t$8922dd2acc0809463b542e63f484b2d39b6c9747aab0677ae723ea954a59ff53$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":2,"fee_ok":1,"fee_bad":0,"fee_unchecked":1,"quotes":18,"q_ok":9,"q_bad":0,"q_unchecked":9},"source":"property/data/municipal-requirements/checked/0233.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0233.json$t$, true),
  ($t$0233$t$, $t$Mahwah Township$t$, $t$BERGEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Township of Mahwah Fire Prevention Bureau (Department of Fire Prevention) (town fire bureau)","Contact: Michael Roe, Fire Official (Fire Inspectors Ed Garza and Nick Kovacs, ext. 290) · 201-529-5757 ext. 275 · mroe@mahwahtwp.org","Apply: Contact the office or stop in to schedule once the application and affidavit are complete. If the change of occupant does not happen within 6 months, a new application is needed.","How to apply: Download the Mahwah Fire Prevention Smoke Inspection Packet (or pick one up at the Building Department), complete the application and affidavit, and return it with $90 cash or check payable to Township of Mahwah to Fire Prevention, 475 Corporate Drive. Then call or stop in to schedule the inspection.","Fire official in the NJ state directory (town), updated 7/22/2026: Michael R Roe · (201) 529-5757 · MRoe@mahwahtwp.org","Smoke detector on each level including basements (not attics or crawl spaces), and smoke and CO alarm outside each separate sleeping area within 10 feet of bedrooms","Homes built before January 1, 1977 may use 10-year lithium sealed battery smoke detectors; homes built on or after that date need hardwired detectors as originally required","The Township asks that hardwired detectors with removable batteries and detectors older than 10 years be replaced with hardwired 10-year sealed battery backup units; CO detectors replaced with 10-year sealed battery units","Low voltage monitored fire alarm systems must stay monitored and a copy of the alarm report must be included with the affidavit","Signed affidavit (Application and Certification) returned with the fee before the inspection","Portable fire extinguisher no longer required as of February 15, 2025 (the packet's form title still lists it)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Certificate of Smoke Alarm and Carbon Monoxide Alarm Compliance","amount":"$90"}]$j$::jsonb, $t$https://www.mahwahtwp.org/DocumentCenter/View/9113$t$, $t$https://www.mahwahtwp.org/157/Fire-Prevention$t$, $j$[{"url":"https://www.mahwahtwp.org/157/Fire-Prevention","label":"Official source (mahwahtwp.org)"},{"url":"https://www.mahwahtwp.org/DocumentCenter/View/9113","label":"Official source (mahwahtwp.org)"},{"url":"https://ecode360.com/34810979","label":"Official source (ecode360.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Another task performed by Fire Prevention is the certification of the operation of smoke detectors required by the State of New Jersey when a home is sold or there is a change of tenant.$t$, $t$9bda3ebcc7a5030deae99e5f066bf5afa40a39f5d1be929356186d5ba9125835$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":2,"fee_ok":1,"fee_bad":0,"fee_unchecked":1,"quotes":18,"q_ok":9,"q_bad":0,"q_unchecked":9},"source":"property/data/municipal-requirements/checked/0233.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0233.json$t$, true),
  ($t$0234$t$, $t$Maywood Borough$t$, $t$BERGEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Continued Occupancy (CCO), Resale / Rental Certificate$t$, $j$["Issued by: Borough of Maywood Construction Official (Building Department / Department of Code Enforcement)","Contact: Gary Goodman, Construction Official & Building Inspector (Zoning Official/Inspector: Dina Lynch, dlynch@maywoodboro.org) · 201-845-2900 · ggoodman@maywoodboro.org","Apply: Under the Borough Code, the owner allows the inspection within 5 days of paying the fee and applying, and the certificate (or a 14-day temporary certificate, or a denial) is issued within 5 days of the inspection.","How to apply: Get the original Resale / Rental Certificate application at Borough Hall, 15 Park Avenue (only a sample is posted online), and file it with the Building Department with the fee. A separate application and fee for the smoke/CO certificate go to the Fire Prevention Bureau (Borough Hall, 3rd floor). Building inspections are requested by email; building inspection hours are Tuesday and Thursday 3 to 6 pm.","Valid for: Expires if the home is not occupied within six months of issuance","Separate smoke/CO certificate of compliance from the Fire Prevention Bureau (the Borough calls it the \"Smoke Certificate for CCO\")","Handrails secured on any stair with 3 or more risers or over 24 inches high, including attic, basement and exterior stairs; no temporary wood railings","Front door deadbolt may not be keyed on both sides","No open slots in the main electric panel; GFI outlets required","Traps on all sinks, toilets, baths and showers; gas valves on all appliances and unused gas lines capped","Chimney base sealed around smoke pipes; boiler and water heater smoke pipes screwed at all joints","Permits and final inspections closed for any construction work, water heater or boiler replacement","Sump pumps must discharge outside, not into the house sewer","Shrubs within 10 feet of a roadway (25 feet of an intersection) no taller than 3 1/2 feet","House number at least 3 inches high, visible from the street","Sidewalks may not be lifted, broken or cracked; soil movement will be inspected; Borough property maintenance code applies inside and out","Also: Open permits: Permits and final inspections must be completed for any construction work, water heater or boiler replacement before the CCO is issued.","Also: Sidewalks: The CCO checklist says sidewalks cannot be lifted, broken or cracked."]$j$::jsonb, $j$[{"label":"Certificate of continued occupancy, one-family structure","amount":"$50"},{"label":"Certificate of continued occupancy, multiple dwellings","amount":"$50 per unit"}]$j$::jsonb, $t$https://maywoodnj.govoffice3.com/vertical/Sites/%7B3F816141-7A2D-4412-8A8D-6C5C2C1C1341%7D/uploads/Sample_Resale_and_Rental_Certificate_Application_and_Checklist.pdf$t$, $t$https://www.maywoodnj.com/index.asp?SEC=82CCEA50-FBAF-464D-9347-1E7D1052EA69$t$, $j$[{"url":"https://ecode360.com/10328648","label":"Official source (ecode360.com)"},{"url":"https://www.maywoodnj.com/index.asp?SEC=82CCEA50-FBAF-464D-9347-1E7D1052EA69","label":"Official source (maywoodnj.com)"},{"url":"https://maywoodnj.govoffice3.com/vertical/Sites/%7B3F816141-7A2D-4412-8A8D-6C5C2C1C1341%7D/uploads/Sample_Resale_and_Rental_Certificate_Application_and_Checklist.pdf","label":"Official source (maywoodnj.govoffice3.com)"},{"url":"https://ecode360.com/10328934","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$No owner shall sell, rent or lease any dwelling unit to any person intending to use the dwelling unit for residential purposes, or allow any person to inhabit any dwelling unit, or sell, rent, lease or allow the occupancy of a nonresidential unit, unless the owner has obtained from the Construction Official a certificate of continued occupancy.$t$, $t$598e3f2a3fd3e2cd2871d892a2278b80c756b19c2f56ce3140be31916b4c5846$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":0,"fee_bad":0,"fee_unchecked":5,"quotes":15,"q_ok":6,"q_bad":0,"q_unchecked":9},"source":"property/data/municipal-requirements/checked/0234.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0234.json$t$, true),
  ($t$0234$t$, $t$Maywood Borough$t$, $t$BERGEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Maywood Fire Prevention Bureau (town fire bureau)","Contact: Thomas Tuttle, Fire Official (per NJ DCA fire directory); Fire Inspector on the Borough page: Rich Minervini · 201-845-2900 ext. 213 · fireinspector@maywoodboro.org","Apply: Fee tier counts business days between the application and the inspection date, starting the next business day after the application and fee are received. Fire inspection hours: Monday and Wednesday 5 to 7 pm.","How to apply: Apply in person at Maywood Borough Hall, 3rd floor, 15 Park Avenue, with exact cash or a check payable to \"Maywood Fire Prevention Bureau\" (a fee is required for each inspection). Only a sample form is posted online; the original is obtained at Borough Hall.","Fire official in the NJ state directory, updated 3/2/2026: Thomas Tuttle · (201) 845-2900 · ttuttle@maywoodboro.org","Smoke alarms on each level including the basement and habitable attic, outside each sleeping area within 10 feet, and in any room with a fuel-fired fireplace","Smoke alarms must be less than 10 years old and UL listed; battery alarms must be sealed 10-year units; 110-volt interconnected systems may not be converted to battery alarms","Carbon monoxide alarms on all levels with sleeping areas, within 10 feet of all sleeping areas; CO alarms must be less than seven (7) years old","Portable fire extinguisher, at least 2A-10:BC, no more than 10 pounds, mounted in or within 10 feet of the kitchen near an exit path (form still lists it)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Certificate of compliance (smoke, CO, extinguisher), more than 10 business days between application and inspection","amount":"$50.00"},{"label":"Between 4 and 10 business days between application and inspection","amount":"$85.00"},{"label":"Three business days or less between application and inspection","amount":"$140.00"}]$j$::jsonb, $t$https://www.maywoodnj.com/vertical/Sites/%7B3F816141-7A2D-4412-8A8D-6C5C2C1C1341%7D/uploads/Sample_Smoke_Certificate_for_CCO.pdf$t$, $t$https://www.maywoodnj.com/index.asp?SEC=6CF5C39F-F882-401B-A80D-15309871E3A8$t$, $j$[{"url":"https://www.maywoodnj.com/vertical/Sites/%7B3F816141-7A2D-4412-8A8D-6C5C2C1C1341%7D/uploads/Sample_Smoke_Certificate_for_CCO.pdf","label":"Official source (maywoodnj.com)"},{"url":"https://www.maywoodnj.com/index.asp?SEC=6CF5C39F-F882-401B-A80D-15309871E3A8","label":"Official source (maywoodnj.com)"},{"url":"https://ecode360.com/10329101","label":"Official source (ecode360.com)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Application for inspection is made at the Maywood Borough Hall, 3rd Floor.$t$, $t$6bbb86c8314447e1707908203b51d585f44fa2c5a125b566de4275f5ee6414a0$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":0,"fee_bad":0,"fee_unchecked":5,"quotes":15,"q_ok":6,"q_bad":0,"q_unchecked":9},"source":"property/data/municipal-requirements/checked/0234.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0234.json$t$, true),
  ($t$0235$t$, $t$Midland Park Borough$t$, $t$BERGEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Resale Certificate (Certificate of Continued Occupancy, Residential)$t$, $j$["Issued by: Borough of Midland Park Building Department (Construction/Zoning Official)","Contact: 201-445-5720 · lkrantz@midlandparknj.gov","Apply: The application must be submitted at least 20 days before the closing date. The Construction/Zoning Official calls the seller to schedule the inspection.","How to apply: Fill out the Application for a Resale Certificate and the Smoke Detector Certificate of Compliance application (on the Selling Your House page or at the Borough Hall front desk) and submit both at least 20 days before closing. Payments can be combined in one check to the Borough of Midland Park. Mail the forms and payment or drop them in the \"Tax Payments\" mailbox at 280 Godwin Avenue marked \"Attn: Resale Processing\". The Zoning and Fire Prevention inspectors then call to schedule.","Valid for: The Resale Certificate expires ninety (90) days from issuance (Ordinance #10-16).","All construction permits closed out before the inspection","Legible house numbers clearly visible from the street","Sump pumps not piped into the sanitary sewer and discharged properly","Boilers, hot water heaters and water softeners installed with required permits","Front door dead bolts keyless on the interior side","Damaged or uneven public sidewalks and aprons must be replaced (permit required)","Smoke Detector Certificate of Compliance applied for at the same time","Also: Sidewalks and aprons: Damaged or uneven public sidewalks and driveway aprons must be replaced (permit required) as part of the resale inspection.","Also: Sump pump discharge: Sump pumps may not be piped into the sanitary sewer and must discharge properly.","Also: Open permits and equipment permits: All construction permits must be closed, and boilers, water heaters and water softeners must have had the required permits."]$j$::jsonb, $j$[{"label":"Resale certificate, single-family home","amount":"$100"},{"label":"Resale certificate, two-family home","amount":"$150"},{"label":"Resale certificate re-inspection, if needed","amount":"$50.00"}]$j$::jsonb, $t$https://www.midlandparknj.gov/DocumentCenter/View/494/Application---Resale-Certificate$t$, $t$https://www.midlandparknj.gov/1559/Selling-Your-House$t$, $j$[{"url":"https://www.midlandparknj.gov/1559/Selling-Your-House","label":"Official source (midlandparknj.gov)"},{"url":"https://www.midlandparknj.org/sites/g/files/vyhlif896/f/pages/building_dept_cco_new.pdf","label":"Official source (midlandparknj.org)"},{"url":"https://www.midlandparknj.gov/DocumentCenter/View/494/Application---Resale-Certificate","label":"Official source (midlandparknj.gov)"}]$j$::jsonb, $t$When selling your home in Midland Park, you will need to complete both the Application for a Resale Certificate and the Application for Smoke Detector Certificate of Compliance.$t$, $t$6af10b22751c8c0ebdf517ccdb4c305162b7028bc222b1f492ddf4987b5432c1$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":5,"fee_bad":0,"fee_unchecked":0,"quotes":13,"q_ok":11,"q_bad":0,"q_unchecked":2},"source":"property/data/municipal-requirements/checked/0235.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0235.json$t$, true),
  ($t$0235$t$, $t$Midland Park Borough$t$, $t$BERGEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Midland Park Fire Prevention Bureau (Borough of Midland Park) (town fire bureau)","Contact: Darryl Demott, Fire Official (NJ DCA fire directory) · 201-445-2044 · ddemott@midlandparknj.gov","Apply: Submit at least 20 days before closing together with the resale application; the Fire Prevention inspector calls to schedule. The certificate expires six (6) months after issuance.","How to apply: Submit the Application for Smoke Detector Certificate of Compliance with the $50 fee (check to the Borough of Midland Park, can be combined with the resale fee) by mail or in the \"Tax Payments\" mailbox at Borough Hall, 280 Godwin Avenue, marked \"Attn: Resale Processing\".","Fire official in the NJ state directory (town), updated 2/19/2026: Darryl Demott · (201) 445-2044 · ddemott@midlandparknj.gov","Smoke detectors on every level, including the basement","Smoke and carbon monoxide detectors within 10 feet of all sleeping areas","All detectors in working order","Smoke detectors UL approved with a 10-year sealed battery","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke Detector Certificate of Compliance","amount":"$50"},{"label":"Smoke detector re-inspection, if needed","amount":"$25"}]$j$::jsonb, $t$https://www.midlandparknj.gov/DocumentCenter/View/493/Smoke-Detector-Application$t$, $t$https://www.midlandparknj.gov/1559/Selling-Your-House$t$, $j$[{"url":"https://www.midlandparknj.gov/DocumentCenter/View/493/Smoke-Detector-Application","label":"Official source (midlandparknj.gov)"},{"url":"https://www.midlandparknj.gov/1559/Selling-Your-House","label":"Official source (midlandparknj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$A Certificate of Compliance will expire six (6) months after issuance$t$, $t$a46ad15bc4f225625cdc69fa9dfa03e8ed9d015c3f47b9938519a071592a6e2e$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":5,"fee_bad":0,"fee_unchecked":0,"quotes":13,"q_ok":11,"q_bad":0,"q_unchecked":2},"source":"property/data/municipal-requirements/checked/0235.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0235.json$t$, true),
  ($t$0236$t$, $t$Montvale Borough$t$, $t$BERGEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$New Tenant / Resale Certificate$t$, $j$["Issued by: Borough of Montvale Building Department - Code Enforcement (Construction Official)","Contact: Christopher Gruber, Construction Officer / Zoning Officer / Facilities Manager · (201) 391-5732 · cgruber@montvalenj.gov","Apply: Inspections are Tuesday and Thursday, 9 am to 12. No published processing time; apply early to avoid closing delays.","How to apply: Fill out the New Tenant / Resale Certificate application (Building and Construction page) with a copy of the latest plot survey and pay $150.00 by cash or check payable to the Borough of Montvale at Borough Hall, 12 DePiero Drive. Questions: 201-391-5732.","All construction, electrical and plumbing permits inspected and properly closed","Outstanding Zoning or Property Maintenance violations resolved","Sump pump must not discharge into the sanitary sewer; it must drain outdoors without impacting neighbors","A current certified property survey showing current uses and structures (one/two family homes)","Use of the home (single-family, two-family, etc.) is verified","Inspection items: sealed flue connections, relief valves properly piped, plumbing fixtures working, outlets/switches/panels covered, pools properly fenced, rails on interior stairs of more than two risers, exterior rails secured","Real estate taxes must be current for the certificate to be valid","Separate Smoke Detector / Carbon Monoxide certificate from Fire Prevention","Also: Property survey: A current certified property survey showing current uses and structures must be submitted with the resale application (one/two family homes).","Also: Taxes current: The resale certificate is valid only if all real estate taxes are current.","Also: Sump pump: A sump pump must not discharge into the sanitary sewer; it must drain outdoors."]$j$::jsonb, $j$[{"label":"New Tenant / Resale Certificate inspection, residential property","amount":"$150.00"}]$j$::jsonb, $t$https://media-002-us.cdn.govstack.com/montvalenj-us/media/fo3hd2au/cco-application-oct-2022-1.pdf$t$, $t$https://www.montvalenj.gov/departments/building-and-construction/$t$, $j$[{"url":"https://www.montvalenj.gov/departments/building-and-construction/","label":"Official source (montvalenj.gov)"},{"url":"https://media-002-us.cdn.govstack.com/montvalenj-us/media/fo3hd2au/cco-application-oct-2022-1.pdf","label":"Official source (media-002-us.cdn.govstack.com)"}]$j$::jsonb, $t$If you are selling or renting a house, condominium, or townhouse, New Jersey State Law requires the property owner to obtain:$t$, $t$3bc6e2df92519f8e6ab409c74aad40ca9c45b066b2a13be2df8abc4a415c44af$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":3,"fee_bad":0,"fee_unchecked":0,"quotes":14,"q_ok":13,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/0236.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0236.json$t$, true),
  ($t$0236$t$, $t$Montvale Borough$t$, $t$BERGEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Montvale Fire Prevention Bureau (Borough of Montvale) (town fire bureau)","Contact: John Kurz, Fire Official (Deputy Fire Official Michael Halzack, x256, mhalzack@montvalenj.gov) · (201) 391-5700 x258 · jkurz@montvalenj.gov","Apply: Payment is required to schedule an inspection. Certificate valid six months from the inspection date. No published tiered fee.","How to apply: Fill out the Fire Prevention Change of Occupant application and mail it or hand it in to the Fire Prevention Office at Borough Hall, 12 DePiero Drive, 2nd Floor, during business hours with cash or a check payable to the Borough of Montvale. A home with a fire alarm panel needs a test report from an approved company sent to the Bureau.","Fire official in the NJ state directory (town), updated 9/30/2025: John J Kurz · (201) 391-5800 · jkurz@montvaleboro.org","Smoke alarm on each level including the basement, within 10 feet of each sleeping area entrance or inside each sleeping area, and in the main living area (living room or near the stairs to the upper level)","Two-family homes also need smoke alarms in common stairwells and hallways, outside each doorway, and at the front of the basement stairs","Smoke alarms replaced when they fail testing or are more than 10 years from manufacture","CO alarm on each level with bedrooms (ceiling or wall); not in kitchens, bathrooms, or near forced-air ducts or furnaces; 10-year sealed combination units are acceptable","Homes with a fire alarm control panel need a test report from an approved company sent to the Fire Prevention Bureau","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Certificate of Smoke Alarm and Carbon Monoxide Alarm Compliance","amount":"$100.00"},{"label":"Reinspection, if required by the Fire Official","amount":"$50.00"}]$j$::jsonb, $t$https://media-002-us.cdn.govstack.com/montvalenj-us/media/xh5ed52z/fire-prevention-change-of-occupant-req-app.pdf$t$, $t$https://www.montvalenj.gov/departments/fire-prevention/$t$, $j$[{"url":"https://media-002-us.cdn.govstack.com/montvalenj-us/media/xh5ed52z/fire-prevention-change-of-occupant-req-app.pdf","label":"Official source (media-002-us.cdn.govstack.com)"},{"url":"https://www.montvalenj.gov/departments/fire-prevention/","label":"Official source (montvalenj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$In accordance with borough code; 203-27 entitled Fees; the application fee for a certificate of smoke alarm and carbon monoxide alarm compliance (CSACMAPFEC),$t$, $t$65dee28d34843626078be6efaccf5717a5ed7f10e622a7664dda8b6aea29fc86$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":3,"fee_bad":0,"fee_unchecked":0,"quotes":14,"q_ok":13,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/0236.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0236.json$t$, true),
  ($t$0237$t$, $t$Moonachie Borough$t$, $t$BERGEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Continued Occupancy (CCO)$t$, $j$["Issued by: Borough of Moonachie Building Department (Construction Official)","Contact: Gino Tessaro, Construction Official · 201-641-1857","Apply: By code, the certificate is issued within six business days after the Construction Official receives the application.","How to apply: Fill out the Borough's Residential certificate application, check Certificate of Continued Occupancy, and submit it with a check payable to Borough of Moonachie to the Building Department, 70 Moonachie Road, Moonachie, NJ 07074 (phone 201-641-1857). The Construction Official inspects and issues the certificate.","Seller must get a Certificate of Continued Occupancy from the Construction Official on every transfer of a one to four family home","The certificate confirms the home may keep its current use and that the use is permitted in the zone (or is a valid nonconforming use or approved by variance)","Inspection of the premises by the Construction Official before the certificate is issued","Use the Borough's Residential certificate application (UCC F270) and check Certificate of Continued Occupancy","Also: Zoning use confirmation: The CCO certifies that the current use (one, two, three or four family) is permitted in the zone, a valid nonconforming use, or allowed by variance.","Also: Open permits and sump pump: The fire certificate form asks whether there is a sump pump and any open permits."]$j$::jsonb, $j$[{"label":"Residential certificate application (CO, CCO, temporary CO), per inspection","amount":"$150"},{"label":"Certificate of Continued Occupancy on transfer of a 1 to 4 family home (code)","amount":"$25"}]$j$::jsonb, $t$https://www.moonachie.us/DocumentCenter/View/806/Residential-CO$t$, $t$https://www.moonachie.us/208/Building-Department$t$, $j$[{"url":"https://ecode360.com/36301429","label":"Official source (ecode360.com)"},{"url":"https://www.moonachie.us/DocumentCenter/View/806/Residential-CO","label":"Official source (moonachie.us)"},{"url":"https://www.moonachie.us/208/Building-Department","label":"Official source (moonachie.us)"}]$j$::jsonb, $t$a seller of such property must obtain from the Construction Official a Certificate of Continued Occupancy certifying that the property may be continued to be used as it is currently being used$t$, $t$ccd8bf5b3767154ad6e936cff746d1984385d02c598bfff7e13e5d8e92f03267$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":4,"fee_bad":0,"fee_unchecked":1,"quotes":11,"q_ok":7,"q_bad":0,"q_unchecked":4},"source":"property/data/municipal-requirements/checked/0237.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0237.json$t$, true),
  ($t$0237$t$, $t$Moonachie Borough$t$, $t$BERGEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Moonachie Fire Prevention (Moonachie Fire Department Fire Prevention Bureau) (town fire bureau)","Contact: Frederick Dressel IV, Fire Official · 201-641-1857 · fodressel@moonachie.us","Apply: Fee depends on how many business days before the certificate is needed: more than 10 business days for the lowest fee.","How to apply: The seller fills out the Home Re-sales Certificate of Compliance form (Residential Fire Prevention Inspection) and pays by check payable to Moonachie Fire Prevention. Submit it to Moonachie Fire Prevention, 70 Moonachie Road, Moonachie, NJ 07074, 201-641-1857.","Fire official in the NJ state directory, updated 2/19/2026: Frederick Dressel IV · (201) 641-1857 · fodressel@moonachie.us","Smoke detector on every floor of the home, including basements, hallways and all habitable floors","Hallways more than 20 feet long need two detectors","Carbon monoxide alarm (the form records the number present)","The form also asks about sump pumps and open permits","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Certificate of compliance, requested more than 10 business days ahead","amount":"$45.00"},{"label":"Certificate of compliance, requested 4 to 10 business days ahead","amount":"$90.00"},{"label":"Certificate of compliance, requested less than 4 business days ahead","amount":"$161.00"}]$j$::jsonb, $t$https://www.moonachie.us/DocumentCenter/View/801/Residential-Fire-Prevention-Inspection$t$, $t$https://www.moonachie.us/204/Fire-Department$t$, $j$[{"url":"https://www.moonachie.us/DocumentCenter/View/801/Residential-Fire-Prevention-Inspection","label":"Official source (moonachie.us)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$This application/certificate is to be filled in and paid for by the seller of the property.$t$, $t$0c8a5b1613460544a6f4ae9387d90f2969feebf26a232c31577508bdfced0da9$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":4,"fee_bad":0,"fee_unchecked":1,"quotes":11,"q_ok":7,"q_bad":0,"q_unchecked":4},"source":"property/data/municipal-requirements/checked/0237.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0237.json$t$, true),
  ($t$0238$t$, $t$New Milford Borough$t$, $t$BERGEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Rental / Resale Certificate (continuing certificate of occupancy) for one- and two-family homes$t$, $j$["Issued by: Borough of New Milford Building Department (Construction Official), with Public Works (sidewalks), Zoning and Fire sign-offs","Contact: Nicole Piano, Building Department Technical Assistant (Construction Official: Alan Silverman, asilverman@newmilfordnj.gov, ext. 7572) · 201-967-5044 ext. 5415 · npiano@newmilfordnj.gov","Apply: Schedule all inspections at least two weeks before closing. Inspections are Monday or Thursday, 1:00 to 4:00 pm. Code says the Construction Official acts within 10 days of the application.","How to apply: Complete the Borough's Rental / Resale Certificate Application (One- and Two-Family Homes), with seller, buyer and both attorneys' details, and submit it to the Building Department, 930 River Road, with the $100.00 fee. Inspections are scheduled for Monday or Thursday afternoons. Call (201) 967-5044 ext 5415 or 5560.","Valid for: One certificate valid for six (6) months.","All open permits closed and final inspections done (water heater, furnace, AC, renovations, decks, pools); unpermitted work needs permits","Smoke detector on each level including walk-up attic and basement; 10-year sealed battery type","Carbon monoxide detector within 10 feet of the bedroom areas in the hallway (more if bedrooms are in separate areas)","Sump pump may not drain into the sanitary sewer line","Handrails on any steps with 3 steps and a platform (two handrails if wider than 3 feet)","Bedroom windows must operate properly","House numbers visible from the street","Hydrant on the property visible and not blocked","Property neat and clean, no excessive debris or overgrown shrubs","Sidewalks and aprons must comply; DPW inspects; repairs or a buyer's attorney escrow letter (repair within 30 days of closing)","Secondary power sources (generator, solar) labeled near the main panel and meter","Running bamboo must be disclosed and, if uncontained, abated or escrowed","Application asks about oil tanks, private wells (safety/health test) and sump pumps","For a demolition sale, a buyer's attorney letter is needed and smoke/CO inspection is still required","Also: Sidewalks and aprons (DPW): Public Works inspects sidewalks; broken slabs must be repaired by a registered contractor or homeowner and reinspected, or the buyer's attorney gives an escrow letter that sidewalks will be repaired within 30 days of closing.","Also: Running bamboo disclosure: Seller must tell the buyer about running bamboo; uncontained bamboo must be abated before sale or escrowed (50% prepaid, balance held by the buyer's attorney). Borough ordinance 12-6.","Also: Open permits: All open permits must be closed and final inspections completed before closing; unpermitted water heaters and furnaces need permits.","Also: Sump pump: Sump pumps may not drain into the sanitary sewer line.","Also: Oil tank and private well questions: The application asks whether an oil tank is present (in use or properly abandoned) and whether a private well has had a safety/health test."]$j$::jsonb, $j$[{"label":"Rental/Resale Certificate, one- and two-family homes (one certificate covering fire, building and sidewalk)","amount":"$100.00"},{"label":"Continuing certificate of occupancy application (Borough code 10-7.4)","amount":"$50"}]$j$::jsonb, $t$https://www.newmilfordnj.gov/api/v1/files/60542870-a097-11f1-b618-1bd587c22b65/download$t$, $t$https://www.newmilfordnj.gov/page/building-department$t$, $j$[{"url":"https://www.newmilfordnj.gov/api/v1/files/60542870-a097-11f1-b618-1bd587c22b65/download","label":"Official source (newmilfordnj.gov)"},{"url":"https://www.newmilfordnj.gov/api/v1/files/af17ad30-b4ff-11f0-864d-6b1653162818/download","label":"Official source (newmilfordnj.gov)"},{"url":"https://ecode360.com/35538511","label":"Official source (ecode360.com)"},{"url":"https://www.newmilfordnj.gov/page/contact-directory","label":"Official source (newmilfordnj.gov)"}]$j$::jsonb, $t$RENTAL / RESALE CERTIFICATE APPLICATION ONE- AND TWO-FAMILY HOMES$t$, $t$a3a7f362a69b1dddd500e576aca6a91e884fda2ce8985ad09469f4a51bb807d2$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":2,"fee_bad":0,"fee_unchecked":1,"quotes":13,"q_ok":7,"q_bad":0,"q_unchecked":6},"source":"property/data/municipal-requirements/checked/0238.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0238.json$t$, true),
  ($t$0238$t$, $t$New Milford Borough$t$, $t$BERGEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: New Milford Bureau of Fire Prevention (inspected as part of the Borough Rental/Resale Certificate) (town fire bureau)","Contact: Alan Silverman, Fire Marshal, Construction Official, Fire Sub Code Official · 201-967-7067 · asilverman@newmilfordnj.gov","Apply: Schedule at least two weeks before closing; fire inspections Monday or Thursday 1:00 to 4:00 pm.","How to apply: Included in the Borough's Rental / Resale Certificate Application to the Building Department; the single certificate includes Fire compliance.","Fire official in the NJ state directory, updated 2/27/2026: Alan J Silverman · (201) 967-7067 · Firemusik@aol.com","Smoke detector on each level including walk-up attic and basement","Battery smoke detectors must be 10-year sealed units listed to ANSI/UL 217 (hardwired units are not affected)","Carbon monoxide detector within 10 feet of the bedroom areas in the hallway; extra units if bedrooms are in separate areas","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Rental/Resale Certificate, one- and two-family homes (one certificate covering fire, building and sidewalk)","amount":"$100.00"}]$j$::jsonb, $t$https://www.newmilfordnj.gov/api/v1/files/60542870-a097-11f1-b618-1bd587c22b65/download$t$, $t$https://www.newmilfordnj.gov/page/building-department$t$, $j$[{"url":"https://www.newmilfordnj.gov/api/v1/files/af17ad30-b4ff-11f0-864d-6b1653162818/download","label":"Official source (newmilfordnj.gov)"},{"url":"https://www.newmilfordnj.gov/page/contact-directory","label":"Official source (newmilfordnj.gov)"},{"url":"https://ecode360.com/35553901","label":"Official source (ecode360.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://www.newmilfordnj.gov/api/v1/files/60542870-a097-11f1-b618-1bd587c22b65/download","label":"Official source (newmilfordnj.gov)"}]$j$::jsonb, $t$All smoke detectors must be 10-year sealed battery type as per N.J.A.C. 5:70 effective date January 1, 2019$t$, $t$fa8df7ff9453a28391702c7d22ce977283948955c58ac04bedd62c87242ba6fc$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":2,"fee_bad":0,"fee_unchecked":1,"quotes":13,"q_ok":7,"q_bad":0,"q_unchecked":6},"source":"property/data/municipal-requirements/checked/0238.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0238.json$t$, true),
  ($t$0239$t$, $t$North Arlington Borough$t$, $t$BERGEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Occupancy (certificate of inspection permitting occupancy) for sale$t$, $j$["Issued by: Borough of North Arlington Construction Official (Construction Department)","Contact: Robert A. Kairys, Construction Official (also the Fire Official) · 201-991-6060","How to apply: Fill out the Request for Certificate of Occupancy (Residential) form (closing date, open permits, seller and buyer contacts, fee, pickup or mail) and submit it with payment (check or cash) to the Construction Official, Borough of North Arlington, 214 Ridge Road, North Arlington, NJ 07031. Fees vary; the Department says to call or stop in for exact amounts.","Inspection by the Construction Code Official or agent for compliance with Borough ordinances before any transfer of title or new occupancy","Smoke detector compliance (CSDC) from the Fire Official; no certificate of occupancy is issued until smoke detector rules are met","Carbon monoxide alarm required before a certificate of continuing occupancy issues","Request form lists closing date, open permits, seller and buyer names and phones, and a Use of Building Affidavit","Title may transfer after the application is filed, but no one may occupy until listed corrections are completed","Also: Open permits: The residential CO request form asks about open permits; resolve them with the Construction Department before closing.","Also: Use of Building Affidavit: The residential CO request form records whether a Use of Building Affidavit was received."]$j$::jsonb, $j$[{"label":"Certificate of Occupancy, one family (Construction Department page, as of July 1, 2015)","amount":"$75.00"},{"label":"Certificate of Occupancy, two family (Construction Department page)","amount":"$125"},{"label":"Certificate of continued occupancy, R-3/R-4/R-5, co-ops and condos, per dwelling unit (Borough Code 122-3I)","amount":"$125"}]$j$::jsonb, $t$https://www.northarlington.org/_Content/pdf/forms/Certificate-Occupancy-Forms.pdf$t$, $t$https://www.northarlington.org/Departments/construction-department$t$, $j$[{"url":"https://www.northarlington.org/Departments/construction-department","label":"Official source (northarlington.org)"},{"url":"https://www.northarlington.org/_Content/pdf/forms/Certificate-Occupancy-Forms.pdf","label":"Official source (northarlington.org)"},{"url":"https://ecode360.com/11265146","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/11265128","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$A Certificate of Occupancy is required with a sale or ownership change of a property, each time you rent an apartment or business space.$t$, $t$40ce2efde8f87d2b0c9b705814702b22e8a5d94157f8336b6187ff0d31e15a6d$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":2,"fee_bad":0,"fee_unchecked":2,"quotes":11,"q_ok":6,"q_bad":0,"q_unchecked":5},"source":"property/data/municipal-requirements/checked/0239.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0239.json$t$, true),
  ($t$0239$t$, $t$North Arlington Borough$t$, $t$BERGEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: North Arlington Fire Official (Fire Prevention / Construction Department) (town fire bureau)","Contact: Robert A. Kairys, Fire Official (also Construction Official) · 201-955-5655 · rkairys@northarlington.org","How to apply: Before the sale, the owner applies in writing to the Fire Official for a CSDC on the Borough form, available from the Building Department (214 Ridge Road), with the $50 fee.","Fire official in the NJ state directory, updated 5/8/2025: Robert A Kairys · (201) 955-5655 · rkairys@northarlington.org","Smoke alarm on each level and outside each sleeping area near the bedrooms (Borough Code 165-22); battery smoke alarms are accepted under the Borough Code, but state rules require 10-year sealed battery units","At least one carbon monoxide alarm inside each dwelling unit; battery units accepted","No dwelling may be sold or have its occupancy changed until it complies","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Certification of smoke detector compliance (CSDC), per dwelling unit per inspection","amount":"$50"}]$j$::jsonb, null, $t$https://www.northarlington.org/Departments/construction-department$t$, $j$[{"url":"https://ecode360.com/11265465","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/11265503","label":"Official source (ecode360.com)"},{"url":"https://www.northarlington.org/Departments/construction-department","label":"Official source (northarlington.org)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Prior to the sale of any dwelling unit located in the Borough of North Arlington to which this article applies, the owner thereof shall apply, in writing, to the Fire Official for a CSDC (certification of smoke detector compliance).$t$, $t$3f462f4de2d32fbd2a2496e7285f5a5710d353c2137655821b306ed3eb129f2d$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":2,"fee_bad":0,"fee_unchecked":2,"quotes":11,"q_ok":6,"q_bad":0,"q_unchecked":5},"source":"property/data/municipal-requirements/checked/0239.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0239.json$t$, true),
  ($t$0240$t$, $t$Northvale Borough$t$, $t$BERGEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Residential Occupancy Approval (ROA) / Certificate of Continued Occupancy (CCO)$t$, $j$["Issued by: Borough of Northvale Fire Prevention Bureau / Building Department (Code Compliance Official)","Contact: Richard Hess, Construction Code Official (Technical Assistant: Julia Martino, ext. 213) · 201-767-3330 ext. 213 · building@northvalenj.org","Apply: File and schedule the inspection at least 21 business days before the certificate is needed (the form says at least 21 days)","How to apply: Download the Residential Occupancy Approval packet from the Fire Prevention page, answer all questions on the Application for Certificate of Residential Occupancy Approval and the Smoke Detector and Carbon Monoxide Alarm Compliance application, and submit them with the fees to the Fire Prevention Bureau/Building Department, 116 Paris Avenue (201-767-3330 ext. 213, building@northvalenj.org). Call to set the inspection appointment at least 21 days before you need the certificate and give a name and phone number for access. Any violations must be fixed before a certificate is issued.","Property used as zoned or approved (one family, two family, etc.); three family or more needs legal proof","No sump pump or other unauthorized water connection into the sanitary sewer","All open construction permits inspected, approved and closed","Sidewalks, if installed, in good condition","No interior double key lock on the primary exit/entrance door","At least one handrail on stairs with 4 or more risers","No hazardous items or imminent dangers on a general visual inspection","Pools need an approved barrier (fence) and gates that open out, self-close and latch","Flue connections properly sealed; no violations of the Property Maintenance chapter","Smoke detector and carbon monoxide alarm certificate is issued with the ROA","Also: Sump pump / sewer connection: The resale inspection checks that no sump pump or unauthorized water connection drains into the sanitary sewer.","Also: Open permits: All open construction permits must be inspected, approved and closed for the Residential Occupancy Approval.","Also: Sidewalks: Sidewalks, if installed, must be in good condition for the Residential Occupancy Approval."]$j$::jsonb, $j$[{"label":"Certificate of Residential Occupancy Approval (fee on the Borough form)","amount":"$100.00"},{"label":"CCO on sale of the property (Borough code)","amount":"$50"}]$j$::jsonb, $t$https://www.boroughofnorthvale.com/_files/ugd/6818fc_ba08137c76c348319a937c10b4d256af.pdf$t$, $t$https://www.boroughofnorthvale.com/fire-prevention$t$, $j$[{"url":"https://www.boroughofnorthvale.com/fire-prevention","label":"Official source (boroughofnorthvale.com)"},{"url":"https://ecode360.com/12515154","label":"Official source (ecode360.com)"},{"url":"https://www.boroughofnorthvale.com/_files/ugd/6818fc_ba08137c76c348319a937c10b4d256af.pdf","label":"Official source (boroughofnorthvale.com)"},{"url":"https://www.boroughofnorthvale.com/building-department","label":"Official source (boroughofnorthvale.com)"}]$j$::jsonb, $t$Residents planning to sell homes are required to apply for and$t$, $t$74360c512ea71ace6a0b277b9552ec5a02e22f763628d8b0e1455db9efb629e1$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":0,"fee_bad":0,"fee_unchecked":4,"quotes":19,"q_ok":9,"q_bad":0,"q_unchecked":10},"source":"property/data/municipal-requirements/checked/0240.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0240.json$t$, true),
  ($t$0240$t$, $t$Northvale Borough$t$, $t$BERGEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Northvale Fire Prevention Bureau (Certificate of Smoke Detector and Carbon Monoxide Alarm Compliance, issued with the Residential Occupancy Approval) (town fire bureau)","Contact: Charles Thomas, Fire Official · 201-767-3330 ext. 214 · fireprevention@northvalenj.org","Apply: Schedule at least 21 days before the certificate is needed. A temporary 60-day nonextendable certificate may be issued after the first inspection.","How to apply: Fill out the Application for Certificate Smoke Detector and Carbon Monoxide Alarm Compliance in the Residential Occupancy Approval packet (closing date, owner/agent, block and lot) and submit it with the ROA application and fees. The smoke/CO certificate is issued with the Residential Occupancy Approval.","Fire official in the NJ state directory (town), updated 4/2/2026: Charles Thomas · (201) 767-3330 · fireprevention@northvalenj.org","At least one 10-year sealed battery smoke detector on each level and outside bedrooms","Carbon monoxide alarm within 10 feet of all bedroom doors","Portable fire extinguisher only listed for rentals (within 10 feet of the kitchen, hung no higher than 5 feet, ABC rated, 2.5 to 10 lbs)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke detector and CO alarm certificate, one and two family","amount":"$75"},{"label":"Temporary 60-day nonextendable certificate","amount":"$25"}]$j$::jsonb, $t$https://www.boroughofnorthvale.com/_files/ugd/6818fc_ba08137c76c348319a937c10b4d256af.pdf$t$, $t$https://www.boroughofnorthvale.com/fire-prevention$t$, $j$[{"url":"https://www.boroughofnorthvale.com/fire-prevention","label":"Official source (boroughofnorthvale.com)"},{"url":"https://ecode360.com/12515154","label":"Official source (ecode360.com)"},{"url":"https://www.boroughofnorthvale.com/_files/ugd/6818fc_ba08137c76c348319a937c10b4d256af.pdf","label":"Official source (boroughofnorthvale.com)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$The Fire Prevention Bureau inspects all homes for sale to ensure smoke detectors, and carbon monoxide alarms.$t$, $t$54e3a48e716b7fc7c3079bebabd5bea738fe7148b9c8d84be1e056baf9aa47eb$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":0,"fee_bad":0,"fee_unchecked":4,"quotes":19,"q_ok":9,"q_bad":0,"q_unchecked":10},"source":"property/data/municipal-requirements/checked/0240.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0240.json$t$, true),
  ($t$0241$t$, $t$Norwood Borough$t$, $t$BERGEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Residential Resale Certificate / Certificate of Continued Occupancy (CCO), issued as a Certificate of Zoning Compliance$t$, $j$["Issued by: Borough of Norwood Construction Office (Construction Code Official / Zoning Officer)","Contact: Gino Tessaro, Construction Official / Building Subcode Official and Zoning Officer · 201-767-7420 · gtessaro@norwoodboro.org","How to apply: Download the Residential Resale Application from the Construction/Code Enforcement Forms/Applications page, fill it out and pay $150.00 by check or money order only, payable to the Borough of Norwood. Submit to the Norwood Construction Office, 455 Broadway, Norwood, NJ 07648 (201-767-7420).","Inspection showing no zoning infractions and compliance with the Zoning Ordinance for continued occupancy","General inspection of the visible parts of the building for imminent hazards","Existing property inventory (basement, first floor, second floor, other)","Smoke detector and carbon monoxide detector compliance certified on the same form","Smoke detectors on each level including the basement, in each bedroom and outside the bedrooms; 10-year sealed battery or interconnected system","Carbon monoxide detectors outside the bedroom doors (battery, plug-in or combination)"]$j$::jsonb, $j$[{"label":"Residential Resale Certificate (CCO), including smoke and CO detector compliance","amount":"$150.00"}]$j$::jsonb, $t$https://files-backend.assets.thrillshare.com/documents/asset/uploaded_file/5980/Bon/8d4d8ddc-399b-4466-8fab-0704e8f4db5a/Residential-Resale-Application.pdf?disposition=inline$t$, $t$https://www.norwoodboro.org/page/constructioncode-enforcement$t$, $j$[{"url":"https://ecode360.com/7950759","label":"Official source (ecode360.com)"},{"url":"https://files-backend.assets.thrillshare.com/documents/asset/uploaded_file/5980/Bon/8d4d8ddc-399b-4466-8fab-0704e8f4db5a/Residential-Resale-Application.pdf?disposition=inline","label":"Official source (files-backend.assets.thrillshare.com)"},{"url":"https://www.norwoodboro.org/documents/departments/construction%2Fcode-enforcement/forms%2Fapplications/25496592","label":"Official source (norwoodboro.org)"},{"url":"https://www.norwoodboro.org/page/constructioncode-enforcement","label":"Official source (norwoodboro.org)"}]$j$::jsonb, $t$Any change in use, ownership, or occupancy of an existing building or structure shall require approval of a certificate of continued occupancy by the Construction Code Official.$t$, $t$009c2a3516a7c25910e40ca7a9128012645e22865e6091461c2a7ffc8375f863$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":2,"fee_ok":2,"fee_bad":0,"fee_unchecked":0,"quotes":12,"q_ok":5,"q_bad":0,"q_unchecked":7},"source":"property/data/municipal-requirements/checked/0241.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0241.json$t$, true),
  ($t$0241$t$, $t$Norwood Borough$t$, $t$BERGEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Borough of Norwood Construction Department (smoke and CO certification is part of the Residential Resale Certificate)","Contact: William McGuire, Fire Subcode Official (Borough page); Fire Official · 201-767-7420 · wmcguire@norwoodboro.org","How to apply: Covered by the Residential Resale Application ($150.00, check or money order only) filed with the Construction Office, 455 Broadway.","Fire official in the NJ state directory (town), updated 2/18/2026: William J McGuire · (201) 767-7420 · wmcguire@norwoodboro.org","Smoke detectors on each level including the basement, in each bedroom, and outside and near all bedroom doors (the form says within 10 feet; the checklist says within 21 feet)","Smoke detectors must be 10-year sealed battery or an interconnected system; not in the attic, crawl spaces or immediate kitchen area","Carbon monoxide detectors outside and near all bedroom doors; battery, plug-in or combination smoke/CO type","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Residential Resale Certificate (CCO), including smoke and CO detector compliance","amount":"$150.00"}]$j$::jsonb, $t$https://files-backend.assets.thrillshare.com/documents/asset/uploaded_file/5980/Bon/8d4d8ddc-399b-4466-8fab-0704e8f4db5a/Residential-Resale-Application.pdf?disposition=inline$t$, $t$https://www.norwoodboro.org/page/constructioncode-enforcement$t$, $j$[{"url":"https://ecode360.com/6931031","label":"Official source (ecode360.com)"},{"url":"https://files-backend.assets.thrillshare.com/documents/asset/uploaded_file/5980/Bon/8d4d8ddc-399b-4466-8fab-0704e8f4db5a/Residential-Resale-Application.pdf?disposition=inline","label":"Official source (files-backend.assets.thrillshare.com)"},{"url":"https://www.norwoodboro.org/page/constructioncode-enforcement","label":"Official source (norwoodboro.org)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$In the case of change of occupancy of any building subject to the requirements of §127-9 of this chapter, no owner shall sell, lease or otherwise permit occupancy for residential purposes of that building without first obtaining from the Norwood Construction Department a certificate evidencing compliance with the requirements of this chapter and N.J.S.A. 52:27D-198.1 and 52:27D-198.2.$t$, $t$466d3fc721a8f7f7092a1f382db907815c0845cc0cbf4f81e8139574b10f0fbf$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":2,"fee_ok":2,"fee_bad":0,"fee_unchecked":0,"quotes":12,"q_ok":5,"q_bad":0,"q_unchecked":7},"source":"property/data/municipal-requirements/checked/0241.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0241.json$t$, true),
  ($t$0242$t$, $t$Oakland Borough$t$, $t$BERGEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Approval for Occupancy (CAO), formerly called CCO$t$, $j$["Issued by: Borough of Oakland Fire Prevention Bureau / Code Enforcement Department, with Board of Health, Building Department and Code Enforcement sign-offs","Contact: 201-337-8111 ext. 2025 · fireassistant@oakland-nj.gov","Apply: Submit at least 30 days before closing; can be filed as soon as the house has a buyer","How to apply: Fill out the Application for Certificate of Approval for Occupancy (CAO) and Fire Certificate for Resale of a Single and Two Family Dwelling and return it with the fees to the Fire Prevention office (1 Municipal Plaza, Oakland). Pay by check made out to 'Oakland Borough' or exact cash. The Fire Prevention page also says a CAO can be applied for online through the Borough's GovPilot portal. Choose whether the CAO is mailed, emailed or picked up.","Valid for: The application is valid for 6 months from the application date; approvals expire 90 days from the signature date. After the fire certificate is issued the applicant has 90 days to complete the CAO ($30 for a 30-day extension).","Complete application (owner, buyer or realtor), with a secondary mailing address, phone and email for the buyer and phone and email for the seller","All open building permits and property maintenance violations must be closed before the CAO (and before a fire inspection can be set up)","Board of Health sign-off: septic reports, sewer information, well water reports; cesspools must be upgraded at realty transfer","Fire certificate (smoke alarms, CO alarms, fire extinguisher, house numbers)","Building inspection only if the fire inspector sees a construction code concern (for example water heater and boiler relief pipes within 6 inches of the floor, holes in garage ceiling, extension cords used as permanent wiring)","Also: Board of Health sign-off (septic, cesspool, sewer, well): The application goes to the Board of Health, which must sign off before the CAO. It reviews septic reports, sewer information and well water reports. Cesspools must be upgraded at realty transfer (2012 septic code), and homes on a well need a Private Well Testing Act test at realty transfer with results sent to health@oakland-nj.org and septics@co.bergen.nj.us.","Also: Open permits and property maintenance violations: All building permits and property maintenance violations must be closed before the fire inspection and before the CAO is issued."]$j$::jsonb, $j$[{"label":"Certificate of Approval for Occupancy, sale of single or two family home (includes realtor sign fee and Board of Health review fee)","amount":"$115"},{"label":"CAO extension, 30 days","amount":"$30"}]$j$::jsonb, $t$https://www.oakland-nj.gov/DocumentCenter/View/1122/Residential-Certificate-of-Approval-for-Occupancy-and-Fire-Certificate-Application-for-Resale$t$, $t$https://www.oakland-nj.gov/1241/Certificate-of-Approval-for-Occupancy-an$t$, $j$[{"url":"https://www.oakland-nj.gov/DocumentCenter/View/1122/Residential-Certificate-of-Approval-for-Occupancy-and-Fire-Certificate-Application-for-Resale","label":"Official source (oakland-nj.gov)"},{"url":"https://www.oakland-nj.gov/DocumentCenter/View/1123/Residential-Certificate-of-Approval-for-Occupancy-and-Fire-Certificate-Informational-Packet-for-Resale","label":"Official source (oakland-nj.gov)"},{"url":"https://www.oakland-nj.gov/1241/Certificate-of-Approval-for-Occupancy-an","label":"Official source (oakland-nj.gov)"},{"url":"https://www.oakland-nj.gov/1246/Fire-Prevention","label":"Official source (oakland-nj.gov)"},{"url":"https://ecode360.com/35188097","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$APPLICATION FOR CERTIFICATE OF APPROVAL FOR OCCUPANCY (CAO) AND FIRE CERTIFICATE FOR RESALE OF A SINGLE AND TWO FAMILY DWELLING$t$, $t$9c8d207914e102987f201ab6553dc77ac8aee0775c32010a29228574873ab772$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":5,"fee_bad":0,"fee_unchecked":0,"quotes":14,"q_ok":12,"q_bad":0,"q_unchecked":2},"source":"property/data/municipal-requirements/checked/0242.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0242.json$t$, true),
  ($t$0242$t$, $t$Oakland Borough$t$, $t$BERGEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Oakland Fire Prevention Bureau (town fire bureau)","Contact: Denny Knubel, Fire Official · 201-337-8111 ext. 2025 · fireassistant@oakland-nj.gov","Apply: Apply at least 30 days before closing (same application as the CAO). An expedite fee is available. The office is open Monday to Friday, 8 am to 4 pm.","How to apply: Use the combined CAO and Fire Certificate application (PDF, or the GovPilot portal mentioned on the Fire Prevention page) and pay by check to 'Oakland Borough' or exact cash. The office schedules the fire inspection once open permits and violations are cleared.","Fire official in the NJ state directory, updated 2/18/2026: Denny G Knubel · (201) 337-8111 · fireofficial@oakland-nj.org","Smoke detectors on each level, including the basement, and within 10 feet of each separate sleeping area; hardwired or 10-year sealed battery; any detector older than 10 years must be replaced","Hardwired alarms from original construction stay hardwired (no battery-only replacement)","Carbon monoxide detectors within 10 feet of each separate sleeping area (battery, hardwired or plug-in, UL 2034)","Low voltage (monitored) alarm systems not part of original construction must have been tested in the year of sale with an NFPA 72 report","One fire extinguisher, 2A:10B:C, no more than 10 lbs, within 10 feet of the kitchen in the exit path, top no more than 5 feet above the floor, serviced and tagged in the past 12 months or with a recent purchase receipt (form still lists it)","House numbers in a contrasting color, 3 inches high, permanently affixed and clearly visible near the front door","All building permits and property maintenance violations closed before the fire inspection is scheduled","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Fire certificate, sale of single or two family home","amount":"$85"},{"label":"Expedite fee","amount":"$50"},{"label":"Re-inspection fee","amount":"$50"}]$j$::jsonb, $t$https://www.oakland-nj.gov/DocumentCenter/View/1122/Residential-Certificate-of-Approval-for-Occupancy-and-Fire-Certificate-Application-for-Resale$t$, $t$https://www.oakland-nj.gov/1246/Fire-Prevention$t$, $j$[{"url":"https://www.oakland-nj.gov/1246/Fire-Prevention","label":"Official source (oakland-nj.gov)"},{"url":"https://www.oakland-nj.gov/DocumentCenter/View/1123/Residential-Certificate-of-Approval-for-Occupancy-and-Fire-Certificate-Informational-Packet-for-Resale","label":"Official source (oakland-nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://www.oakland-nj.gov/1241/Certificate-of-Approval-for-Occupancy-an","label":"Official source (oakland-nj.gov)"}]$j$::jsonb, $t$The Fire Prevention office is open Monday through Friday from 8 am to 4 pm.$t$, $t$b9358628e42871b9b71cab603f3ac08092d65acbb7cf53d5d88c5be8efced505$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":5,"fee_bad":0,"fee_unchecked":0,"quotes":14,"q_ok":12,"q_bad":0,"q_unchecked":2},"source":"property/data/municipal-requirements/checked/0242.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0242.json$t$, true),
  ($t$0243$t$, $t$Old Tappan Borough$t$, $t$BERGEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Rental and Resale Certificate (RRC, formerly CCO): Certificate of occupancy, resale and/or rental certificate$t$, $j$["Issued by: Borough of Old Tappan Building Department (Construction Official or his agent), with a fire inspection","Contact: Jennifer Boehm, Technical Assistant (Construction/Zoning Official Bob Rusch, ext. 20) · 201-664-1849 ext. 19","Apply: Code: the Construction Official acts within 10 working days after entry is provided. Inspection times are set by the Borough; no specific time can be requested.","How to apply: Fill out the Rental and/or Resale Certificate Application (Ordinance No. 100-14) and send it with a check payable to the Borough of Old Tappan to the Building Department, 227 Old Tappan Road, Old Tappan, NJ 07675. One check can cover both the building and fire inspections. The Technical Assistant or Borough Inspector schedules the inspection.","All open permits must be closed before the sale; check open permits before applying","Someone over 18 must be at the house until the inspectors finish; inspectors do not call ahead","Furnace/boiler flue connections sealed; replaced water heaters and mechanical equipment need a permit and an approval sticker","Sump pumps discharge outside, not to the sanitary sewer; anti-tip brackets on stoves where required; rigid visible kitchen exhaust ducts","Electrical outlets, switches, boxes and panels covered; no lamp cords on fixed appliances","Handrails on 4 or more risers; guards on landings over 30 inches and open basement stairs; garage walls/ceilings next to the house sheet-rocked","Pool gates and fencing compliant (self-closing, self-latching, latches 54 inches); lawn and bushes trimmed; no property maintenance violations","Smoke alarms on every level (under 10 years old, 10-year sealed battery or hardwired, per the house's construction era) and a CO alarm within 10 feet of every bedroom","Kitchen fire extinguisher 2A:10B:C, no more than 10 lbs, mounted within 10 feet of the kitchen (form still lists it)","Resale-only certificates (buyer not occupying) need a notarized letter from the purchaser's attorney","Also: Open permits: All open permits must be closed before the sale and before the resale inspection.","Also: Pool fence and property upkeep: Pool fencing and gates must match the original approved installation and be self-closing and latching; lawn and bushes trimmed; no property maintenance violations.","Also: Sump pump discharge: Sump pumps must discharge outside and cannot be tied to the sanitary sewer."]$j$::jsonb, $j$[{"label":"Residential inspection fee (application form; one check can cover building and fire inspections)","amount":"$125"},{"label":"Re-inspection (application form)","amount":"$50"},{"label":"Certificate fee, request more than 10 business days before inspection (Code Section 100-14.6)","amount":"$50"},{"label":"Request 4 to 10 business days before inspection (Code)","amount":"$75"},{"label":"Request less than 4 business days before inspection (Code)","amount":"$125"},{"label":"Reinspection if the first inspection fails (Code)","amount":"$50"}]$j$::jsonb, $t$https://oldtappan.net/forms-documents/forms/department-documents/construction/66-cco-rental-and-resale-application/file$t$, $t$https://oldtappan.net/departments/construction$t$, $j$[{"url":"https://ecode360.com/11278456","label":"Official source (ecode360.com)"},{"url":"https://oldtappan.net/forms-documents/forms/department-documents/construction/66-cco-rental-and-resale-application/file","label":"Official source (oldtappan.net)"}]$j$::jsonb, $t$Certificate of occupancy, resale and/or rental certificates are required before occupancy.$t$, $t$bc7f92273d6495d4eca52fa45188b20f958846b50837d3d69b467590cb0a9965$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":7,"fee_ok":3,"fee_bad":0,"fee_unchecked":4,"quotes":14,"q_ok":9,"q_bad":0,"q_unchecked":5},"source":"property/data/municipal-requirements/checked/0243.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0243.json$t$, true),
  ($t$0243$t$, $t$Old Tappan Borough$t$, $t$BERGEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Borough of Old Tappan (Building Department schedules; Fire Prevention Bureau, Fire Marshal) (town fire bureau)","Contact: Evan Kutzin, Fire Marshal · 201-664-1849 Ext. 26 · firemarshal@oldtappan.net","Apply: Fire inspections are listed Wednesday and Friday 2:00pm to 4:00pm on the Building page; scheduled with the Building Department.","How to apply: Use the same Rental and Resale application; the Building Department (201-664-1849 ext. 19) arranges the smoke and CO inspection and certificate.","Fire official in the NJ state directory (town), updated 5/18/2026: Evan J Kutzin · (201) 664-1849 · firemarshal@oldtappan.net","Smoke alarms on every level including the basement, within 10 feet of bedroom doors, under 10 years old; hardwired and interconnected as required by the year the house was built","Carbon monoxide alarm within 10 feet of the bedroom doors (battery or plug-in accepted); CO alarm inside bedrooms with fuel-burning appliances","Portable fire extinguisher 2A:10B:C within 10 feet of the kitchen, mounted no higher than 5 feet, serviced/tagged within 12 months or with a receipt (form still lists it)","Monitored alarm systems: password must be available","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Residential inspection fee covering building and fire inspections (application form)","amount":"$125"}]$j$::jsonb, $t$https://oldtappan.net/forms-documents/forms/department-documents/construction/66-cco-rental-and-resale-application/file$t$, $t$https://oldtappan.net/departments/fire-prevention$t$, $j$[{"url":"https://oldtappan.net/departments/fire-prevention","label":"Official source (oldtappan.net)"},{"url":"https://ecode360.com/11278456","label":"Official source (ecode360.com)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://oldtappan.net/forms-documents/forms/department-documents/construction/66-cco-rental-and-resale-application/file","label":"Official source (oldtappan.net)"}]$j$::jsonb, $t$Residents selling their homes are reminded that a Certificate of Compliance indicating smoke detector and carbon monoxide detector placement and operation is required before a home sale can be completed.$t$, $t$69ac105d3ad107cd6380ebb2416927a598fd10f07824b6d6e3edaba679e6d36a$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":7,"fee_ok":3,"fee_bad":0,"fee_unchecked":4,"quotes":14,"q_ok":9,"q_bad":0,"q_unchecked":5},"source":"property/data/municipal-requirements/checked/0243.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0243.json$t$, true),
  ($t$0244$t$, $t$Oradell Borough$t$, $t$BERGEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Resale / Rental Certificate (RRC), the Borough's Certificate of Continued Occupancy$t$, $j$["Issued by: Borough of Oradell Building Department (Construction Official)","Contact: Stephen A. Depken, Construction Official / Zoning Officer / Building Inspector / Property Inspector (technical assistant: Rosalia Bob) · 201-261-8005 · rbob@oradell.org","Apply: The application form asks for 30 days advance inspection notice; the Code says file no later than 21 days before the change of ownership, and the Construction Official issues or denies within 21 calendar days. Inspections Monday to Friday 10:30am to 2:00pm.","How to apply: Download the RRC Resale / Rental / Certificate Application (Residential), which also contains the smoke detector and CO alarm application, and submit it with the prepaid fee (checks payable to Borough of Oradell, or exact cash) to the Building Department, Room 102, Borough Hall, 355 Kinderkamack Road. An appointment is scheduled only after a complete application and fee are in.","General inspection of the visible parts of the premises for zoning compliance, health and safety, and open violations or orders","Smoke detectors on every level including the basement and within 10 feet of every bedroom door, matched to the type required when the house was built or altered; detectors over ten years old replaced with ten-year sealed battery units; electric detectors may not be replaced with battery units","Carbon monoxide alarm (UL 2034) within 10 feet of each sleeping area","Monitored smoke detection systems must work, with an NFPA-72 test report dated no more than 30 days before closing","Open or unobtained permits are fined; heating equipment and water heaters need an inspection sticker or proof of approval","Sump pump may not discharge into a sewer line, sink or new curb discharge","Anti-tip bracket on the stove if the manufacturer requires it; electrical covers; handrails on stairs with 4 or more risers","Pool barriers and gates must be code compliant; no basement or attic bedrooms without a second means of egress; only one stove in the main kitchen","No open property maintenance violations; corner shrubs trimmed to 30 inches","Damaged sidewalks and aprons (1/2 inch or more trip hazard) must be replaced in concrete or lifted; asphalt sidewalks and aprons must be replaced with concrete","Address numbers displayed at or near the front door","Two-family homes need an application for each unit","Also: Open permits: A fine is issued for open or unobtained permits found at the RRC inspection; heating equipment and water heaters need an inspection sticker or proof of approval.","Also: Sidewalks and aprons: Sidewalks or aprons with a trip hazard of 1/2 inch or more must be replaced in concrete or lifted and regraded (no patching or grinding); asphalt sidewalks and aprons must be replaced with concrete.","Also: Sump pump discharge: A sump pump may not discharge into a sewer line, a sink or a new curb discharge.","Also: Lead-based paint (rentals only): Lead-based paint inspection applies at tenant turnover of pre-1978 rental units, not to owner-occupied sales."]$j$::jsonb, $j$[{"label":"RRC, one and two family dwelling (application form)","amount":"$130"},{"label":"Certificate of continued occupancy resale, R-3 and R-5 one and two family (Borough Code 115-2B)","amount":"$100"},{"label":"Reinspection, one and two family","amount":"$60"},{"label":"Request 5 to 10 business days before closing: original fee plus half","amount":"original fee + 1/2"},{"label":"Request 4 business days or less before closing: double the original fee","amount":"2 x original fee"},{"label":"Penalty for closing before the RRC is issued","amount":"$500"}]$j$::jsonb, $t$https://www.oradell.org/building-department/files/02-rrc-resale-rental-certificate-application-residential$t$, $t$https://www.oradell.org/building-department$t$, $j$[{"url":"https://ecode360.com/9256363","label":"Official source (ecode360.com)"},{"url":"https://www.oradell.org/building-department/files/02-rrc-resale-rental-certificate-application-residential","label":"Official source (oradell.org)"},{"url":"https://www.oradell.org/building-department","label":"Official source (oradell.org)"},{"url":"https://ecode360.com/9256691","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$No person shall occupy a building or portion thereof for residential purposes after said building or portion thereof has been vacated due to the sale of said residential property or for which there has been a change in use or change in tenancy or occupancy until the owner of said premises has applied for and secured a certificate of continued occupancy.$t$, $t$ab449c7dec79afec819f55bb9aaf06b9340b3931cd04cfb516fc919bb123ae72$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":11,"fee_ok":4,"fee_bad":0,"fee_unchecked":7,"quotes":11,"q_ok":7,"q_bad":0,"q_unchecked":4},"source":"property/data/municipal-requirements/checked/0244.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0244.json$t$, true),
  ($t$0244$t$, $t$Oradell Borough$t$, $t$BERGEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Borough of Oradell Building Department (smoke detector and CO application is part of the RRC); fire code LEA is the Oradell Fire Prevention Bureau (town fire bureau)","Contact: Christopher Petronzio, Interim Fire Marshal (Fire Official in the NJ DCA directory) · 201-261-8200 ext. 266 · cpetronzio@oradell.org","Apply: Filed with the RRC; 30 days advance inspection notice is requested.","How to apply: Fill in the smoke detector and carbon monoxide application pages inside the Borough's residential RRC application and file it with the Building Department with the RRC fee. For fire code questions call the Fire Prevention Bureau at 201-261-8200 ext. 266.","Fire official in the NJ state directory, updated 2/26/2026: Christopher R Petronzio · (201) 261-8200 · cpetronzio@oradell.org","Smoke detectors on every level including the basement and within 10 feet of every bedroom door; type depends on the year built or altered","Detectors over ten years old replaced with ten-year sealed battery smoke detectors; electric detectors may not be replaced with battery-only units","Carbon monoxide alarm (UL 2034) in the hallway within 10 feet of every bedroom door","Monitored systems need an NFPA-72 test report dated no later than 30 days before closing","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Certificate of smoke detector and carbon monoxide alarm compliance, more than 10 business days before inspection (Code 115-8)","amount":"$50"},{"label":"4 to 10 business days before inspection","amount":"$75"},{"label":"Fewer than 4 business days before inspection","amount":"$125"},{"label":"Reinspection, per occurrence","amount":"$50"},{"label":"Penalty for failure to obtain the certificate","amount":"$150"}]$j$::jsonb, $t$https://www.oradell.org/building-department/files/02-rrc-resale-rental-certificate-application-residential$t$, $t$https://www.oradell.org/fire-prevention-bureau$t$, $j$[{"url":"https://www.oradell.org/building-department/files/02-rrc-resale-rental-certificate-application-residential","label":"Official source (oradell.org)"},{"url":"https://www.oradell.org/fire-prevention-bureau","label":"Official source (oradell.org)"},{"url":"https://ecode360.com/9256976","label":"Official source (ecode360.com)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://ecode360.com/9256691","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$SMOKE DETECTOR, CARBON MONOXIDE (CO) DETECTOR APPLICATION$t$, $t$02523efa8edafaf9ff7821f7017ed8b5d456589e85569018c4ed739e9771c57c$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":11,"fee_ok":4,"fee_bad":0,"fee_unchecked":7,"quotes":11,"q_ok":7,"q_bad":0,"q_unchecked":4},"source":"property/data/municipal-requirements/checked/0244.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0244.json$t$, true),
  ($t$0245$t$, $t$Palisades Park Borough$t$, $t$BERGEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Continuing Occupancy (CCO / Certificate of Occupancy for resale)$t$, $j$["Issued by: Borough of Palisades Park Building Department (Construction Official as Enforcement Officer)","Contact: Tom O'Malley, Construction Official · (201) 585-4108 · tomalley@palisadesparkbuildingdept.org","Apply: Ordinance: inspection within a reasonable time, not exceeding 30 days after the application is complete.","How to apply: Get the Residential Owner Certificate (Resale) application from the Building Department or the Borough's Applications, Forms and Permits page, have the purchaser sign the affidavit before a notary, and pay the fee to the Borough of Palisades Park. An inspection is scheduled after payment; if it passes the CCO is issued at the inspection. File the separate smoke/CO/extinguisher application with the Bureau of Fire Prevention.","General inspection of the visible parts of the building before a sold or vacated home is occupied","Smoke detector installed as required by state law before the CCO can be issued","Certificate of Smoke Detector, Carbon Monoxide Detector and Fire Extinguisher Compliance from the Bureau of Fire Prevention","Office checklist: all permits finalized, no open building code or property maintenance violations, egress, handrails on stairs with 3 or more risers, extinguisher within 10 feet of the kitchen, working windows, no keyed locks on interior doors, no trash accumulation","Notarized Residential Owner Certificate with purchaser's affidavit on the number of dwelling units (LLCs must name the manager/principal)","If the home is being used as an illegal 3+ family, separate utility services for the illegal units must be removed and owner and buyer must sign a sworn statement","Also: Open permits and violations: The resale inspection checklist requires all permits to be finalized and no outstanding building code or property maintenance violations.","Also: Illegal extra units: If the inspection shows the home is being used as a 3+ family in violation of zoning, the separate utilities for the illegal units must be removed and owner and buyer must sign a sworn statement before the CCO."]$j$::jsonb, $j$[{"label":"Resale CCO, one-family (ordinance)","amount":"$50"},{"label":"Resale CCO, two-family (ordinance)","amount":"$75"},{"label":"Zoning review (ordinance)","amount":"$25"},{"label":"Reinspection (ordinance)","amount":"$15"},{"label":"Residential Owner Certificate form fee, one to two unit dwellings (form dated 06-21-2023)","amount":"$150.00"},{"label":"Reinspection per unit (form dated 06-21-2023)","amount":"$50.00"}]$j$::jsonb, $t$https://palisadesparknj.org/wp-content/uploads/2025/05/Residential-owner-certificate.pdf$t$, $t$https://palisadesparknj.org/departments/building-department/$t$, $j$[{"url":"https://palisadesparknj.org/departments/building-department/","label":"Official source (palisadesparknj.org)"},{"url":"https://ecode360.com/9263173","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/9263189","label":"Official source (ecode360.com)"},{"url":"https://palisadesparknj.org/wp-content/uploads/2025/05/Residential-owner-certificate.pdf","label":"Official source (palisadesparknj.org)"}]$j$::jsonb, $t$The BOROUGH OF PALISADES PARK does require a Certificate of Occupancy (CO) for resale of a property in conjunction with a Certificate of Smoke Detector, Carbon Monoxide Detector, and Fire Extinguisher Compliance.$t$, $t$3ac23a4961314089eb4332eeaa5242a51eeddc98017774f35e0eaf9a7ae4d7c0$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":7,"fee_ok":0,"fee_bad":0,"fee_unchecked":7,"quotes":16,"q_ok":6,"q_bad":0,"q_unchecked":10},"source":"property/data/municipal-requirements/checked/0245.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0245.json$t$, true),
  ($t$0245$t$, $t$Palisades Park Borough$t$, $t$BERGEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Palisades Park Bureau of Fire Prevention (town fire bureau)","Contact: Andrew Chiurazzi, Fire Official (Chief Fire Inspector: Michael Valente) · (201) 585-4132 · fireprevention@palisadesparknj.gov","How to apply: Submit the Bureau's 'Application and Certification in Lieu of Inspection for Certificate of Smoke Detector and Carbon Monoxide Alarm and Portable Fire Extinguisher Compliance' (all boxes must be checked; owner, agent, tenant or NJ licensed electrician certifies) to the Bureau at 275 Broad Ave, with the closing date and contact person. Office hours Monday to Friday, 9:00 A.M. to 4:00 P.M.","Fire official in the NJ state directory, updated 1/12/2026: Andrew Chiurazzi · (201) 585-4132 · achiurazzi@palisadesparknj.gov","Smoke detectors on each level and within 10 feet of sleeping areas (110V with battery backup and interconnected in homes built after 1990); detectors over 10 years old must be replaced","Carbon monoxide detectors within 10 feet of all sleeping areas; detectors over 5 years old must be replaced (per the Borough form)","All smoke and CO alarms in working order","Fire extinguisher of the correct size, properly mounted, within 10 feet of the kitchen (form still lists it)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke detector and CO alarm compliance certificate, per dwelling unit per inspection","amount":"$100"}]$j$::jsonb, $t$https://palisadesparknj.org/wp-content/uploads/2024/10/Bureau-of-Fire-Prevention-only01.pdf$t$, $t$https://palisadesparknj.org/how-do-i/bureau-of-fire-prevention/$t$, $j$[{"url":"https://ecode360.com/9261538","label":"Official source (ecode360.com)"},{"url":"https://palisadesparknj.org/how-do-i/bureau-of-fire-prevention/","label":"Official source (palisadesparknj.org)"},{"url":"https://palisadesparknj.org/wp-content/uploads/2024/10/Bureau-of-Fire-Prevention-only01.pdf","label":"Official source (palisadesparknj.org)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Before any Use Group R-3 or R-4 structure is sold, leased or otherwise made subject to a change of occupancy for residential purposes, the owner shall obtain a certificate of smoke detector and carbon monoxide alarm compliance (CSDCMAC), evidencing compliance with N J.A.C. 5:70-4.19, from the Bureau of Fire Prevention.$t$, $t$e97d09bc84fccdbfc2d2cbe9568b2a1aa283b2498db2a76b6e311e7985e44e8d$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":7,"fee_ok":0,"fee_bad":0,"fee_unchecked":7,"quotes":16,"q_ok":6,"q_bad":0,"q_unchecked":10},"source":"property/data/municipal-requirements/checked/0245.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0245.json$t$, true),
  ($t$0246$t$, $t$Paramus Borough$t$, $t$BERGEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Compliance for Residential Resale (Continued Certificate of Compliance)$t$, $j$["Issued by: Borough of Paramus Building Department (Construction Code Official), with the Fire Official or designee for smoke alarms","Contact: (201) 265-2100 Ext. 2230 · Building@paramusborough.gov","Apply: All open construction permits must be closed at least one week before the resale inspection is scheduled. Inspections are Monday to Friday, 9:00 am to 12:00 pm.","How to apply: Confirm with the Building Department that all prior permits are closed, then apply online through the SDL portal or fill out the PDF Residential Resale Application and submit it with the $100 fee. The Borough then calls to schedule the inspection. The certificate is emailed or picked up at the Building Department, One Jockish Square.","All open construction permits closed out at least one week before scheduling","Zoning conformance and no clear-water discharge (sump, roof, yard drainage) into the public sewer (Borough Code §363-5G)","Smoke alarms on each level and near bedrooms; ten-year sealed battery alarms where hardwired were not required; hardwired alarms may not be replaced with battery units","Carbon monoxide detectors near all bedrooms and sleeping areas (UL 2034)","Secondary power source label (generator, solar, battery storage) within 18 inches of the main panel and meter","House address displayed; Borough-issued garbage and recycling containers on the property; pools fenced","Work done without permits must be permitted and inspected before the certificate is issued","Also: Open permits: All open construction permits must be closed at least one week before the resale inspection; unpermitted work must be permitted and inspected first.","Also: Clear-water discharge into sewer: The resale inspection checks conformance with Borough Code §363-5 Subsection G, which bars discharging sump, roof, yard or groundwater into the public sewer.","Also: Garbage and recycling containers: Borough-issued containers with matching serial numbers must be on the property; missing ones must be bought at DPW before the inspection.","Also: Secondary power source label: Homes with generators, solar or battery storage need a permanent 'CAUTION: MULTIPLE SOURCES OF POWER' type label near the panel and meter."]$j$::jsonb, $j$[{"label":"Certificate of Compliance for residential resale","amount":"$100"},{"label":"Certificate of compliance, inspection and issuance (Borough Code §197-3)","amount":"$100"}]$j$::jsonb, $t$https://www.paramusborough.org/DocumentCenter/View/3393/Continued-Certificate-of-Occupancy-Residental-Resale$t$, $t$https://www.paramusborough.gov/187/Certificate-of-Occupancy$t$, $j$[{"url":"https://www.paramusborough.gov/187/Certificate-of-Occupancy","label":"Official source (paramusborough.gov)"},{"url":"https://www.paramusborough.org/DocumentCenter/View/1495/Certificate-of-Compliance-for-Residental-Resale","label":"Official source (paramusborough.org)"},{"url":"https://www.paramusborough.org/DocumentCenter/View/3393/Continued-Certificate-of-Occupancy-Residental-Resale","label":"Official source (paramusborough.org)"},{"url":"https://ecode360.com/8540928","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/8548123","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$An application for Certificate of Compliance is required for selling or renting a home in Paramus.$t$, $t$0b7daea733ba0dd6fd18ecd5d2ec8b1c6c9923829437f5711d8288bd7688f531$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":2,"fee_bad":0,"fee_unchecked":1,"quotes":13,"q_ok":9,"q_bad":0,"q_unchecked":4},"source":"property/data/municipal-requirements/checked/0246.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0246.json$t$, true),
  ($t$0246$t$, $t$Paramus Borough$t$, $t$BERGEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Borough of Paramus Building Department with the Paramus Fire Prevention Bureau (smoke/CO check is part of the resale Certificate of Compliance) (town fire bureau)","Contact: Daniel Perez, Fire Official (NJ DCA directory) · (201) 265-2100 · dperez@paramusborough.org","Apply: Inspections Monday to Friday, 9:00 am to 12:00 pm, scheduled after the application and fee are received.","How to apply: Included in the Residential Resale Certificate of Compliance application to the Building Department (SDL portal or PDF form).","Fire official in the NJ state directory (town), updated 2/19/2026: Daniel Perez · (201) 265-2100 · dperez@paramusborough.org","Smoke alarms located per NFPA 72, at least one on each level and in the immediate vicinity of all bedrooms","Hardwired alarms from original construction may not be replaced with battery units; elsewhere use ten-year sealed battery alarms (ANSI/UL 217)","Carbon monoxide detectors near all bedrooms and sleeping areas (UL 2034, NFPA 720)","If smoke alarms are tied to a burglar alarm, call the alarm company 15 minutes before the inspector arrives and know the reset code","Secondary power source label within 18 inches of the main electrical panel and meter","Fire extinguisher no longer required, only recommended (Borough guidelines revised 06/12/25)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke/CO check within the resale Certificate of Compliance (same fee, not an extra charge)","amount":"$100"}]$j$::jsonb, $t$https://www.paramusborough.org/DocumentCenter/View/3393/Continued-Certificate-of-Occupancy-Residental-Resale$t$, $t$https://www.paramusborough.gov/187/Certificate-of-Occupancy$t$, $j$[{"url":"https://ecode360.com/8540928","label":"Official source (ecode360.com)"},{"url":"https://www.paramusborough.org/DocumentCenter/View/1495/Certificate-of-Compliance-for-Residental-Resale","label":"Official source (paramusborough.org)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.paramusborough.gov/187/Certificate-of-Occupancy","label":"Official source (paramusborough.gov)"}]$j$::jsonb, $t$Also, the Fire Official or designee shall inspect property for conformance with New Jersey P.L. 1991, c. 92, Smoke-Sensitive Alarm Devices.$t$, $t$16430cea9ddab7318d8463bbb04ff2d852537389f9a11994af7e14f2fd467b34$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":2,"fee_bad":0,"fee_unchecked":1,"quotes":13,"q_ok":9,"q_bad":0,"q_unchecked":4},"source":"property/data/municipal-requirements/checked/0246.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0246.json$t$, true),
  ($t$0247$t$, $t$Park Ridge Borough$t$, $t$BERGEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Continued Occupancy (CCO), Zoning Resale of Residential Dwelling$t$, $j$["Issued by: Borough of Park Ridge Zoning Office (Zoning Officer)","Contact: Tonya Janeiro, Zoning Officer · 201-391-5673","Apply: A two-week notice is required for all certificates. Both certificates are issued together and e-mailed within five business days after the inspection.","How to apply: Read the Residential Resale packet, then submit page 4 (Application for Certificate of Continued Occupancy, Zoning Resale of Residential Dwelling) with two separate checks: $125 to Borough of Park Ridge (zoning CCO) and $100 to Park Ridge Fire Prevention (fire certificate). Give at least two weeks notice. You will get a call to set up the fire prevention inspection.","Valid for: 180 days from date of issue","Review of Borough files for open building permits and zoning violations, and that utilities and taxes are current","Certificates will not be issued if taxes or utilities are delinquent or there are open building permits (clear these before applying)","Street numbers visible; no open-ended wires; no illegal conversions (for example one family to two-family)","Sump pump must not be connected to the sanitary sewer (Chapter 81A, no illicit connections)","Smoke detector and carbon monoxide certification from Park Ridge Fire Prevention (separate $100 check)","Submit only page 4 of the packet with two separate checks","Also: Sump pump / sewer connection check: The CCO checklist requires that the sump pump not be connected to the sanitary sewer (Chapter 81A, no illicit connections).","Also: Taxes, utilities and open permits: Certificates are not issued if taxes or utilities are delinquent or there are open building permits; clear these before applying.","Also: Smoke/CO waiver for renovation purchases: Purchasers can sign a notarized Waiver of Smoke/Carbon Monoxide Detector Inspection when the home will be renovated; the home cannot be occupied until the requirements are met."]$j$::jsonb, $j$[{"label":"Certificate of Continued Occupancy (zoning), residential resale","amount":"$125"}]$j$::jsonb, $t$https://www.parkridgeboro.com/forms-documents/forms/resident-forms/cco/1107-residential-resale-cco-zoning-fire/file$t$, $t$https://www.parkridgeboro.com/departments/cco$t$, $j$[{"url":"https://www.parkridgeboro.com/departments/cco","label":"Official source (parkridgeboro.com)"},{"url":"https://www.parkridgeboro.com/forms-documents/forms/resident-forms/cco/1107-residential-resale-cco-zoning-fire/file","label":"Official source (parkridgeboro.com)"}]$j$::jsonb, $t$The Borough of Park Ridge requires a smoke certificate and zoning certificate for the sale of your home.$t$, $t$502d1624a7dba7b55ec16395adb33cbf284467450d5b8601fe7a3b2e2dcbe296$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":3,"fee_bad":0,"fee_unchecked":0,"quotes":17,"q_ok":16,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/0247.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0247.json$t$, true),
  ($t$0247$t$, $t$Park Ridge Borough$t$, $t$BERGEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Park Ridge Fire Prevention (Fire Official, Borough of Park Ridge) (town fire bureau)","Contact: John Hansen, Fire Official · 201-573-1800 X 505","Apply: Two-week notice required. You will receive a call to set up the inspection after the application is received; certificates are e-mailed within five business days after the inspection. No same-day reinspections.","How to apply: Submit the Residential Resale packet's page 4 with a $100 check payable to Park Ridge Fire Prevention (separate from the $125 zoning check). The Fire Official calls to schedule the inspection.","Fire official in the NJ state directory (town), updated 3/31/2026: John Hansen · (201) 391-2746 · jotrhansen@gmail.com","Smoke alarms: sealed 10-year lithium battery type; smoke detector outside each sleeping area and within 10 feet of bedrooms; one on each level of multi-level homes","Carbon monoxide alarm: 10-year battery or plug-in type, within 10 feet of each sleeping area (combination units are acceptable)","Hardwired systems must be fully functional and cannot be replaced with battery-only detectors","Central monitored fire alarms must be inspected by the owner's alarm company with a copy of the test report given to the Fire Official at the inspection","Fire extinguishers are no longer required (packet dated 9/4/25)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke Detector & Carbon Monoxide Certification (Fire Certificate)","amount":"$100"},{"label":"Fire certificate reinspection","amount":"$50"}]$j$::jsonb, $t$https://www.parkridgeboro.com/forms-documents/forms/resident-forms/cco/1107-residential-resale-cco-zoning-fire/file$t$, $t$https://www.parkridgeboro.com/departments/cco$t$, $j$[{"url":"https://www.parkridgeboro.com/forms-documents/forms/resident-forms/cco/1107-residential-resale-cco-zoning-fire/file","label":"Official source (parkridgeboro.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$The fee for the Fire Certificate is $100 and is payable to Park Ridge Fire Prevention.$t$, $t$e47d83544e14bac16996acf6355995895cdb19b770b3e3694328064f6a35e30e$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":3,"fee_bad":0,"fee_unchecked":0,"quotes":17,"q_ok":16,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/0247.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0247.json$t$, true),
  ($t$0248$t$, $t$Ramsey Borough$t$, $t$BERGEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Inspection on sale of a dwelling (Borough Code Section 13-2)$t$, $j$["Issued by: Ramsey Construction Code Department (Construction Code Official)","Contact: Jim Dougherty, Construction Official/Building Subcode · 201-825-3400 ext. 251 · jdougherty@ramseynj.com","How to apply: Contact the Building Department (Construction Code Official), 33 N Central Avenue, 2nd floor, 201-825-3400 ext. 251. No resale application form is posted online; ask whether the Borough will accept a home inspection report in place of its own inspection.","Dwelling's electrical, plumbing, heating, sanitary and structural systems must be in safe condition under the Uniform Construction Code","Seller corrects apparent code violations that arose since the last certificate of occupancy or certificate of inspection before the sale","Instead of a Borough inspection, the seller may have the Construction Code Official rely on a home inspection or engineering report obtained for the sale (no fee in that case)","A buyer may get a conditional certificate by signing an affidavit to correct violations within six months of purchase"]$j$::jsonb, $j$[{"label":"Certificate of inspection on sale","amount":"$50"},{"label":"Certificate of inspection when the smoke detector certificate fee has also been paid","amount":"$25"}]$j$::jsonb, null, $t$https://www.ramseynj.com/153/Building-Department$t$, $j$[{"url":"https://ecode360.com/13228792","label":"Official source (ecode360.com)"},{"url":"https://www.ramseynj.com/153/Building-Department","label":"Official source (ramseynj.com)"}]$j$::jsonb, $t$Upon the sale of a dwelling or upon the completion or rehabilitation work to the dwelling funded by the Borough, County of Bergen, State of New Jersey, or federal government, the seller shall obtain from the Borough's Construction Code Department a Certificate of Inspection stating that the dwelling is in compliance with the State of New Jersey Uniform Construction Code provisions with regard to the safe condition of the dwelling's electrical, plumbing, heating, sanitary and structural systems.$t$, $t$34ff53433e40764039c20987065b271335e7d6e20c27eaaa14bfce3b400433e7$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":4,"fee_bad":0,"fee_unchecked":2,"quotes":13,"q_ok":8,"q_bad":0,"q_unchecked":5},"source":"property/data/municipal-requirements/checked/0248.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0248.json$t$, true),
  ($t$0248$t$, $t$Ramsey Borough$t$, $t$BERGEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Ramsey Bureau of Fire Prevention (town fire bureau)","Contact: Darryl DeMott, Fire Official (ddemott@ramseynj.com, ext. 256); applications go to Kelly at kdispoto@ramseynj.com · 201-825-3400 ext. 252 · kdispoto@ramseynj.com","Apply: Fee depends on business days before the expected change of ownership; more than 10 business days for the lowest fee. Inspections Tuesdays and Thursdays, 9:00 to 11:00 am.","How to apply: Complete the Fire Prevention Smoke Detector Inspection Application (Forms, Permits, Licenses & Publications page) and send it to Kelly at kdispoto@ramseynj.com. Pay by check or money order to \"Borough of Ramsey\" or by credit card through the Borough's Municipay link.","Fire official in the NJ state directory (town), updated 3/25/2026: Darryl J DeMott · (201) 825-3400 · ddemott@ramseynj.com","Smoke detectors at the base of each stairway on each level including the basement, and outside each sleeping area within 10 feet of each bedroom door","Hardwired or low-voltage detectors required at original construction or renovation must be kept; otherwise 10-year sealed lithium battery alarms (ANSI/UL 217)","Detectors with no date, or more than 10 years past the manufacture date, must be replaced","Carbon monoxide alarms (UL 2034, NFPA 720) within 10 feet outside every bedroom; battery, hardwired or plug-in","Low-voltage systems need a certified NFPA 72 fire alarm test report submitted before the inspection","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke/CO certificate, application received more than 10 business days ahead","amount":"$50.00"},{"label":"Application received 4 to 10 business days ahead","amount":"$70.00"},{"label":"Application received fewer than 4 business days ahead","amount":"$125.00"},{"label":"Reinspection (non-working, recalled or missing alarms, or no-show)","amount":"$35.00"}]$j$::jsonb, $t$https://www.ramseynj.com/DocumentCenter/View/5704/Fire-Prevention-Smoke-Detector-Inspection-Application-$t$, $t$https://www.ramseynj.com/238/Bureau-of-Fire-Prevention$t$, $j$[{"url":"https://www.ramseynj.com/DocumentCenter/View/5704/Fire-Prevention-Smoke-Detector-Inspection-Application-","label":"Official source (ramseynj.com)"},{"url":"https://ecode360.com/13229057","label":"Official source (ecode360.com)"},{"url":"https://www.ramseynj.com/238/Bureau-of-Fire-Prevention","label":"Official source (ramseynj.com)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$PLEASE CONTACT KELLY AT kdispoto@ramseynj.com$t$, $t$aacfd7031e48cb6b7536fda378d4180a168168ba46263efff428cce6e82a9abe$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":4,"fee_bad":0,"fee_unchecked":2,"quotes":13,"q_ok":8,"q_bad":0,"q_unchecked":5},"source":"property/data/municipal-requirements/checked/0248.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0248.json$t$, true),
  ($t$0249$t$, $t$Ridgefield Borough$t$, $t$BERGEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Inspection (Residential Real Estate Inspection), also listed in the fee schedule as a Certificate for resale$t$, $j$["Issued by: Borough of Ridgefield Building Department (Construction Official or designee)","Contact: Gregory K. Yfantis, Construction Official · 201-943-5546 · gyfantis@ridgefieldboro.com","Apply: By code, the Construction Official inspects within five days of the application and issues or denies the certificate within 10 days. Violations must be corrected within 14 days, with a reinspection within 14 days.","How to apply: Apply in writing to the Building Department, 700 Shaler Boulevard, Ridgefield, NJ 07657 (Monday to Friday 8:00 a.m. to 4:00 p.m., no financial transactions after 3:00 p.m.), paying the fee with the application. The Borough website does not post the application form; call (201) 943-5546 or email the Construction Official to get it. Zoning appointments are Tuesday and Thursday after 4:00 p.m. (email jsetticase@ridgefieldboro.com).","Valid for: A temporary certificate of inspection (for repairs that do not affect safety or habitability) expires 60 days after issuance.","Inspection showing the home and its intended use comply with Borough and State building, zoning, health, safety and fire codes","Smoke and carbon monoxide Certificate of Compliance, also issued by the Building Department / Construction Official","Carbon monoxide sensor device in each dwelling unit with a fuel-burning source (Borough Chapter 146 applies to newly sold homes)","Correct any violations within 14 days of the notice","Also: Zoning resale certificate fee: The Chapter 140 fee schedule lists zoning fees for a certificate for resale ($150 one-family, $250 two-family, $75 reinspection); confirm whether this is a separate zoning review from the certificate of inspection."]$j$::jsonb, $j$[{"label":"Certificate of inspection, one-family (Code Section 390-264)","amount":"$125"},{"label":"Certificate of inspection, two-family (Code Section 390-264)","amount":"$250"},{"label":"Certificate of inspection reinspection after violations (Code Section 390-264)","amount":"$50"},{"label":"Zoning certificate for resale of a one-family (Chapter 140 fee schedule)","amount":"$150"},{"label":"Zoning certificate for resale of a two-family (Chapter 140 fee schedule)","amount":"$250"},{"label":"Resale or rental reinspection (Chapter 140 zoning fee schedule)","amount":"$75"}]$j$::jsonb, null, $t$https://www.ridgefieldnj.gov/index.asp?SEC=F257D928-5B82-4109-87AC-1E2D4FF7FA39$t$, $j$[{"url":"https://ecode360.com/9125889","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/9122997","label":"Official source (ecode360.com)"},{"url":"https://www.ridgefieldnj.gov/index.asp?SEC=F257D928-5B82-4109-87AC-1E2D4FF7FA39","label":"Official source (ridgefieldnj.gov)"},{"url":"https://ecode360.com/9122867","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$No person shall convey or transfer title or ownership to any residential real property within the Borough of Ridgefield, nor shall any person accept conveyance or transfer of title to residential real property, unless and until a certificate of inspection is issued in accordance with this article.$t$, $t$c937b18fa2382e28b38afa448336decb046bf9f5e25238c1f2c5938712852c55$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":0,"fee_bad":0,"fee_unchecked":6,"quotes":11,"q_ok":6,"q_bad":0,"q_unchecked":5},"source":"property/data/municipal-requirements/checked/0249.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0249.json$t$, true),
  ($t$0249$t$, $t$Ridgefield Borough$t$, $t$BERGEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Borough of Ridgefield Building Department (Construction Official); the Fire Prevention Bureau does not issue these certificates","Contact: Gregory K. Yfantis, Construction Official · 201-943-5546 · gyfantis@ridgefieldboro.com","How to apply: Contact the Building Department at (201) 943-5546 or gyfantis@ridgefieldboro.com; the Borough page says the Building Department and Construction Official issue the smoke and carbon monoxide Certificate of Compliance for a transfer of ownership.","Fire official in the NJ state directory (town), updated 3/24/2026: John J Hoffman · (201) 945-6008 · jhoffman@ridgefieldboro.com","Smoke detectors on every level of the dwelling, including basements, and outside each sleeping area","Carbon monoxide detectors in the immediate vicinity of sleeping areas, unless the home has no fuel-burning appliance and no attached garage","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[]$j$::jsonb, null, $t$https://www.ridgefieldnj.gov/index.asp?SEC=639B5F99-CCD8-42DF-AB61-6B42AADCEBE3$t$, $j$[{"url":"https://www.ridgefieldnj.gov/index.asp?SEC=639B5F99-CCD8-42DF-AB61-6B42AADCEBE3","label":"Official source (ridgefieldnj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$A Certificate of Compliance for smoke and carbon monoxide detectors is required for the transfer of ownership of a dwelling.$t$, $t$75722b7e5d0628e89ba57bb667a2099b3441ec0fd3b87c79d3f4d2bfe8ee8e11$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":0,"fee_bad":0,"fee_unchecked":6,"quotes":11,"q_ok":6,"q_bad":0,"q_unchecked":5},"source":"property/data/municipal-requirements/checked/0249.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0249.json$t$, true),
  ($t$0250$t$, $t$Ridgefield Park Village$t$, $t$BERGEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Compliance for Sale of 1 or 2 Family Dwelling$t$, $j$["Issued by: Village of Ridgefield Park Building Department (Housing Inspector under the Construction Official)","Contact: Michael Landolfi, Construction Official · 201-641-4950 Ext. 4","Apply: File at least 12 days before closing (a higher fee applies after that). The application is reviewed and the certificate issued within 10 days.","How to apply: Fill out the Application for Certificate of Compliance - Sale of 1 or 2 Family Dwelling (Building Department Forms & Applications page) and file it with the fee at the Building Department, 234 Main Street, Room 209, at least 12 days before closing. The same inspection covers smoke alarms, CO alarms and the extinguisher.","Valid for: Not transferable; if the change of occupancy does not happen within six months, a new application, inspection and certificate are needed.","Inspection confirms the home is legally occupied under the Village Zoning Code (1 family or 2 family)","Smoke alarms on each level and within 10 feet of each sleeping area (UL 217; battery or AC)","CO alarms (UL 2034, NFPA 720) in the immediate vicinity of sleeping rooms in homes with fuel-burning appliances or attached garages","Fire extinguisher in the kitchen of 1 and 2 family homes, 2A:10B:C, no more than 10 pounds, within 10 feet of the kitchen, top no more than 5 feet above the floor (code and form still list it)","Inspector also notes finished attic or basement, attic bathroom, basement kitchen or bath, exterior locks on bedroom doors, property maintenance (cut grass, shrubs, hedges) and a 4-inch house number visible from the street","Notarized acknowledgment signed by the owner/new owner (and tenant) that attics in two-story 1-2 family homes and basements may not be used as bedrooms or habitable space","Also: Attic and basement occupancy affidavit: Buyers (and any tenants) sign a notarized acknowledgment that attics in two-story 1-2 family homes may not be habitable space and basements may not be bedrooms.","Also: Rental registration letter: New owners return a Fire Prevention letter saying whether they will rent the home; non-owner-occupied 1-2 family homes must register with the Bureau of Fire Prevention (rental-only)."]$j$::jsonb, $j$[{"label":"Certificate of compliance, application at least 12 days before the change of occupancy","amount":"$75"},{"label":"Application fewer than 12 days before the change of occupancy","amount":"$95"},{"label":"Reinspection","amount":"$25"}]$j$::jsonb, $t$https://www.ridgefieldpark.org/DocumentCenter/View/134/Application-for-Certificate-of-Compliance---Sale-of-1-of-2-Family-Dwelling-PDF$t$, $t$https://www.ridgefieldpark.org/199/Building-Department$t$, $j$[{"url":"https://ecode360.com/13318092","label":"Official source (ecode360.com)"},{"url":"https://www.ridgefieldpark.org/196/Fire-Prevention","label":"Official source (ridgefieldpark.org)"},{"url":"https://www.ridgefieldpark.org/202/Forms-Applications","label":"Official source (ridgefieldpark.org)"},{"url":"https://www.ridgefieldpark.org/199/Building-Department","label":"Official source (ridgefieldpark.org)"},{"url":"https://www.ridgefieldpark.org/DocumentCenter/View/134/Application-for-Certificate-of-Compliance---Sale-of-1-of-2-Family-Dwelling-PDF","label":"Official source (ridgefieldpark.org)"}]$j$::jsonb, $t$A certificate of compliance shall be required in all changes of occupancy in all residential dwelling units.$t$, $t$12e43004aa9ff64b62b6a722e130e1730a37e672b9c489dde46076c152dfa836$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":0,"fee_bad":0,"fee_unchecked":6,"quotes":14,"q_ok":7,"q_bad":0,"q_unchecked":7},"source":"property/data/municipal-requirements/checked/0250.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0250.json$t$, true),
  ($t$0250$t$, $t$Ridgefield Park Village$t$, $t$BERGEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Village of Ridgefield Park Building Department (Certificate of Compliance covers smoke/CO; Bureau of Fire Prevention is the fire code agency) (town fire bureau)","Contact: 201-641-4950 Ext. 4","Apply: File at least 12 days before closing for the lower fee. Certificate valid six months for the stated change of occupancy.","How to apply: The smoke alarm, CO alarm and extinguisher check is part of the Building Department's Certificate of Compliance inspection; there is no separate fire application for a 1-2 family sale. File the Certificate of Compliance application at 234 Main Street, Room 209.","Fire official in the NJ state directory (town), updated 2/19/2026: Peter A Danzo · (201) 440-2570 · pdanzo@ridgefieldpark.org","Smoke alarms on each level and within 10 feet of each sleeping area (NFPA 74 placement, UL 217; battery or AC powered)","CO alarms (UL 2034, NFPA 720; battery, hardwired or plug-in) in the immediate vicinity of all sleeping rooms, no more than 10 feet away, in homes with fuel-burning appliances or attached garages","Fire extinguisher 2A:10B:C, no more than 10 pounds, manufacturer's bracket, within 10 feet of the kitchen, top no more than 5 feet above the floor; serviced and tagged within 12 months or a recent purchase receipt (code and form still list it)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Certificate of compliance, application at least 12 days before the change of occupancy","amount":"$75"},{"label":"Application fewer than 12 days before the change of occupancy","amount":"$95"},{"label":"Reinspection","amount":"$25"}]$j$::jsonb, $t$https://www.ridgefieldpark.org/DocumentCenter/View/134/Application-for-Certificate-of-Compliance---Sale-of-1-of-2-Family-Dwelling-PDF$t$, $t$https://www.ridgefieldpark.org/196/Fire-Prevention$t$, $j$[{"url":"https://www.ridgefieldpark.org/196/Fire-Prevention","label":"Official source (ridgefieldpark.org)"},{"url":"https://ecode360.com/13318092","label":"Official source (ecode360.com)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Existing Buildings - Before any change of occupancy may take place, a Certificate of Smoke Detector and CO Detector Compliance shall be obtained from the Village Building Department.$t$, $t$58cd64565b02e2dc6d208a5376b65d8515ae7eea896f510de2915644b20645bb$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":0,"fee_bad":0,"fee_unchecked":6,"quotes":14,"q_ok":7,"q_bad":0,"q_unchecked":7},"source":"property/data/municipal-requirements/checked/0250.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0250.json$t$, true),
  ($t$0251$t$, $t$Ridgewood Village$t$, $t$BERGEN$t$, $t$resale_cco$t$, $t$official_process_found$t$, $t$Resale / Continued Certificate of Occupancy (CCO)$t$, $j$["Not required for sales, per Ridgewood Village. Confirm with the office if the buyer's lender or title company asks.","Contact: Raymond Keeley, Director of the Building Department & Construction Official · 201-670-5500 ext. 2281 · rkeeley@ridgewoodnj.net","How to apply: No Village resale Certificate of Occupancy for a one or two family home. The Building Department FAQ says only the smoke detector / carbon monoxide certification from the Fire Prevention Bureau is required before closing (see fire certificate).","Also: Monitored fire alarm registration: Homes with a monitored central station fire alarm must register it with the Ridgewood Fire Department (201-444-8822 x4112). This is ongoing, not a sale item, but buyers often ask.","Also: Underground oil tank: The Village FAQ notes abandoning or removing a residential oil tank needs a permit, and lenders and insurers often want tanks removed at sale. Not a Village sale requirement."]$j$::jsonb, $j$[]$j$::jsonb, null, $t$https://www.ridgewoodnj.net/170/Building$t$, $j$[{"url":"https://www.ridgewoodnj.net/Faq.aspx?TID=16","label":"Official source (ridgewoodnj.net)"},{"url":"https://www.ridgewoodnj.net/170/Building","label":"Official source (ridgewoodnj.net)"}]$j$::jsonb, $t$The Building Department does not issue a CO for the resale of a one or two-family dwelling, however, a smoke detector/carbon monoxide detector certification is required from the village's fire prevention bureau before you close the title.$t$, $t$83e2805d8fbe77477470d2e3a39d2594ac73787bdc46a1036421f4bcaad88df6$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":5,"fee_bad":0,"fee_unchecked":0,"quotes":10,"q_ok":6,"q_bad":0,"q_unchecked":4},"source":"property/data/municipal-requirements/checked/0251.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0251.json$t$, true),
  ($t$0251$t$, $t$Ridgewood Village$t$, $t$BERGEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Ridgewood Fire Department, Fire Prevention Bureau (town fire bureau)","Contact: John Young, Fire Official · 201-444-7898 ext. 5480 · jyoung@ridgewoodnj.net","Apply: Fee depends on how far before the closing the inspection is scheduled: more than 10 days for the lowest fee. The code says the inspection happens within 10 business days of receiving a prepaid application. An inspection after the closing adds a $500 penalty.","How to apply: Call the Inspection Office at 201-444-7898 ext. 5480, Monday to Friday 8:30 a.m. to 4:30 p.m., to schedule. Pay by cash or check payable to the Village of Ridgewood, sent to the Fire Prevention Bureau, 201 East Glen Avenue, Ridgewood, NJ 07450; credit cards are taken in person only (3% fee).","Fire official in the NJ state directory, updated 2/17/2026: John Young · (201) 444-7898 · jyoung@ridgewoodnj.net","Smoke detector on each level, with a floor area separated by 3 or more risers counted as a separate level; basement detector on the basement ceiling (not required in an unoccupied attic)","Smoke detectors must be UL or FM approved and audible in all rooms on that level with doors closed","Carbon monoxide alarm inspection (the Village calls it a smoke detector and carbon monoxide inspection, under N.J.A.C. 5:70)","Fee is per dwelling unit, so a two family home pays for each unit","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke/CO inspection scheduled more than 10 days before closing, per dwelling unit","amount":"$120"},{"label":"Scheduled less than 10 days before closing, per dwelling unit","amount":"$150"},{"label":"Scheduled within 3 days of closing, per dwelling unit","amount":"$200"},{"label":"Penalty if the inspection is done after the closing (on top of the $200 fee)","amount":"$500"},{"label":"Credit card technology fee (in person only)","amount":"3%"}]$j$::jsonb, null, $t$https://www.ridgewoodnj.net/311/Fire-Prevention$t$, $j$[{"url":"https://www.ridgewoodnj.net/311/Fire-Prevention","label":"Official source (ridgewoodnj.net)"},{"url":"https://ecode360.com/6690353","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/6690240","label":"Official source (ecode360.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$If you are selling or renting your home, you need a smoke detector and carbon monoxide inspection!$t$, $t$ceb82e554d79e94e87b3b3c66cd55414c31950c5c3aa53120b5632c64c674b7f$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":5,"fee_bad":0,"fee_unchecked":0,"quotes":10,"q_ok":6,"q_bad":0,"q_unchecked":4},"source":"property/data/municipal-requirements/checked/0251.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0251.json$t$, true),
  ($t$0252$t$, $t$River Edge Borough$t$, $t$BERGEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Resale (certificate of occupancy / continued certificate of occupancy on resale of a residential dwelling)$t$, $j$["Issued by: Borough of River Edge Building Department (Construction Official)","Contact: Stephen Depken, Construction Official/Zoning Official (sdepken@riveredgenj.org) · 201-599-6322 · inspections@riveredgenj.org","How to apply: Complete the Borough's Application for Certificate of Resale (Resale of Residential Dwelling): property, closing date, single or two family, seller, buyer, contact person. Submit to the Building Department, 10 River Edge Road (office hours Monday to Friday 9:00 am to 3:00 pm; no applications accepted after 3:00 pm), with the fee from the Borough fee schedule (pay by cash or check). Questions: (201) 599-6322 or inspections@riveredgenj.org.","Seller must close out all permits before the CO inspection","Smoke detector on every level including the basement and within 10 feet of every bedroom door; type depends on the year built or altered (battery before 1977, hardwired/interconnected for later homes); detectors over 10 years old must be replaced; electric detectors cannot be replaced with battery units","Monitored smoke detection systems need an NFPA-72 test report from the monitoring company dated no more than 30 days before closing","Carbon monoxide detector on every level and on the sleeping levels of 1 and 2 family dwellings, in the hallway within 10 feet of every bedroom door","Portable fire extinguisher within 10 feet of the kitchen: 2.5 to 10 pounds, 2A-10B:C (ABC), tagged within the past year or new with receipt, mounted with top no more than 5 feet up, owner's manual present (checklist revised 08/28/2019 still lists it)","Homes with a residential sprinkler system need an inspection report from a licensed contractor","Sump pumps may not discharge into a sewer line or sink; handrails on interior and exterior stairs; no extension cords as permanent wiring","Sidewalks in disrepair must be repaired or replaced before inspection (sidewalk permit needed to replace slabs)","Common hallways and stairways in two-family houses need smoke detectors on each level","Also: Sidewalks and curbs: The Construction Code Officer inspects sidewalks and curbs with the certificate of continued occupancy on resale; damaged slabs must be repaired before inspection (sidewalk permit required).","Also: Open permits: The seller must close out all permits before the CO inspection.","Also: Sump pump: Sump pumps may not discharge into a sewer line or sink.","Also: Fire sprinkler inspection report: Homes with a residential fire suppression (sprinkler) system need an inspection report from a licensed contractor."]$j$::jsonb, $j$[{"label":"Continued certificate of occupancy (resale), Use Groups R-3, R-4 and R-5 (one- and two-family homes) (Borough code 206-2Q)","amount":"$100"},{"label":"Certificate of continued occupancy, structure Use Group R-2, R-3, R-4 or R-5 (construction code fees, Borough code 206-2I)","amount":"$75"},{"label":"Certificate of continued occupancy, each added dwelling unit (Borough code 206-2I)","amount":"$35"}]$j$::jsonb, $t$https://www.riveredgenj.org/media/Borough/Forms%20and%20Permits/Building%20Forms/Certificate%20of%20Resale-Residential(1).pdf$t$, $t$https://www.riveredgenj.org/departments/BuildingDepartment$t$, $j$[{"url":"https://ecode360.com/11323401","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/11320342","label":"Official source (ecode360.com)"},{"url":"https://www.riveredgenj.org/media/Borough/Forms%20and%20Permits/Building%20Forms/Certificate%20of%20Resale-Residential(1).pdf","label":"Official source (riveredgenj.org)"},{"url":"https://www.riveredgenj.org/departments/BuildingDepartment","label":"Official source (riveredgenj.org)"}]$j$::jsonb, $t$No dwelling unit, including but not limited to single-family homes, two-family homes and condominium apartment/townhouse units, shall be sold unless the selling owner first obtains from the Construction Official a certificate of occupancy.$t$, $t$f05be3a4ca6ff1c98468967e9af657a511b97f1301edb598d6c4f4a31e9f1575$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":0,"fee_bad":0,"fee_unchecked":4,"quotes":14,"q_ok":5,"q_bad":0,"q_unchecked":9},"source":"property/data/municipal-requirements/checked/0252.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0252.json$t$, true),
  ($t$0252$t$, $t$River Edge Borough$t$, $t$BERGEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: River Edge Building Department (smoke/CO/extinguisher checked during the Certificate of Resale inspection); River Edge Fire Prevention Bureau handles rentals (town fire bureau)","Contact: Alan Silverman, Fire Official · 201-599-6323 · asilverman@riveredgenj.org","How to apply: For a sale, the alarm and extinguisher items are inspected as part of the Building Department's Certificate of Resale; there is no separate fire application for sales on the Borough site.","Fire official in the NJ state directory, updated 2/27/2026: Alan J Silverman · (201) 599-6323 · firemusik@aol.com","Smoke detectors on all levels including the basement and within 10 feet of every bedroom door, per the year the house was built or altered","Smoke detectors over 10 years old must be replaced; electric detectors may not be replaced with battery units","Carbon monoxide detector in the hallway within 10 feet of every bedroom door, on every level of 1 and 2 family dwellings","Portable fire extinguisher (2A-10B:C, 2.5 to 10 lb) within 10 feet of the kitchen, serviced within a year or new with receipt (checklist still lists it)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Continued certificate of occupancy (resale), Use Groups R-3, R-4 and R-5 (one- and two-family homes) (Borough code 206-2Q)","amount":"$100"}]$j$::jsonb, $t$https://www.riveredgenj.org/media/Borough/Forms%20and%20Permits/Building%20Forms/Certificate%20of%20Resale-Residential(1).pdf$t$, $t$https://www.riveredgenj.org/departments/FirePrevention$t$, $j$[{"url":"https://www.riveredgenj.org/departments/FirePrevention","label":"Official source (riveredgenj.org)"},{"url":"https://ecode360.com/11320566","label":"Official source (ecode360.com)"},{"url":"https://www.riveredgenj.org/media/Borough/Forms%20and%20Permits/Building%20Forms/Certificate%20of%20Resale-Residential(1).pdf","label":"Official source (riveredgenj.org)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://ecode360.com/11320342","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$ALL RENTALS OF 1 & 2 FAMILY NON-OWNER OCCUPIED HOMES REQUIRE AN INSPECTION BY THE FIRE PREVENTION BUREAU$t$, $t$7dc52d91f810f4d0d62d15429090717b12aef6af2b1a29f2c85757fcffa5ed0c$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":0,"fee_bad":0,"fee_unchecked":4,"quotes":14,"q_ok":5,"q_bad":0,"q_unchecked":9},"source":"property/data/municipal-requirements/checked/0252.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0252.json$t$, true),
  ($t$0253$t$, $t$River Vale Township$t$, $t$BERGEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Resale and/or Rental Certificate (RRC)$t$, $j$["Issued by: River Vale Building Department (Construction Official / Zoning Official), with the Fire Prevention Bureau doing the smoke/CO part","Contact: Maria Haag, Zoning & RRC Coordinator / Land Use Administrator · 201-664-2346 ext. 1065 · mhaag@rivervalenj.org","Apply: Fee depends on business days of notice before the inspection: 11 or more business days for the lowest combined fee. Inspections are Monday or Wednesday afternoons or Friday mornings; no specific time can be requested.","How to apply: Complete the Resale and/or Rental Certificate (RRC) application, leaving nothing blank, and submit it with a check payable to the Township of River Vale (one check can cover both the building and fire inspections). Requests can also be made online through the Township's SDL Portal or by email to inspections@rivervalenj.org. Applications and checks can be dropped in the Town Hall vestibule lockbox at 406 Rivervale Road.","Building inspection for compliance with Township ordinances, including: sealed furnace/boiler flue connections; permitted and inspected water heaters and mechanical equipment; sump pumps discharging outside, not to the sanitary sewer; anti-tip brackets on stoves where required; rigid visible kitchen exhaust ducts; covered outlets, switches, boxes and panels; no lamp cords on fixed appliances","Handrails on 4 or more risers; guards on landings 30 inches above floor or grade and on open basement stairs; sheetrock on garage walls/ceilings next to the house","Pool fence and gate rules (self-closing, self-latching, outward swing, latches 54 inches high); hot tubs need approved latches","Lawn and bushes neatly trimmed","No open permits, unpaid fees or property maintenance violations; open permits must be inspected and closed before the RRC inspection","Number of bedrooms and bathrooms must match the current property tax record","Smoke/CO and secondary power source label inspection by the Fire Prevention Bureau","Someone 18 or older must be at the house for the whole inspection window","Also: Open permits and unpaid fees: All open permits must be inspected and closed before the RRC inspection, and there can be no unpaid fees or property maintenance violations.","Also: Bedroom and bathroom count: The number of bedrooms and bathrooms must match the current property tax record.","Also: Secondary power source label: Homes with a generator, solar panels or battery storage need a permanent warning label within 18 inches of the main electric panel and meter."]$j$::jsonb, $j$[{"label":"Resale/Rental Certificate, residential, combined building and fire, 11 or more business days notice","amount":"$200"},{"label":"Combined building and fire, 4 to 10 business days notice","amount":"$250"},{"label":"Combined building and fire, less than 4 business days notice","amount":"$300"},{"label":"Building reinspection","amount":"$50"},{"label":"Resale and/or rental certificate, building portion, more than 10 business days before inspection (Township Code 142-27)","amount":"$100"},{"label":"Building portion, 4 through 10 business days before inspection","amount":"$125"},{"label":"Building portion, less than 4 business days before inspection","amount":"$150"}]$j$::jsonb, $t$https://files-backend.assets.thrillshare.com/documents/asset/uploaded_file/4491/Trv/3bb0cf3c-093c-47f6-85b5-d8fc71a3ccc2/Resale_Rental_Certificate__RRC__Residential_Co.pdf?disposition=inline$t$, $t$https://rivervalenj.org/page/building-department$t$, $j$[{"url":"https://rivervalenj.org/page/building-department","label":"Official source (rivervalenj.org)"},{"url":"https://files-backend.assets.thrillshare.com/documents/asset/uploaded_file/4491/Trv/3bb0cf3c-093c-47f6-85b5-d8fc71a3ccc2/Resale_Rental_Certificate__RRC__Residential_Co.pdf?disposition=inline","label":"Official source (files-backend.assets.thrillshare.com)"},{"url":"https://ecode360.com/11325986","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/11325763","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$Please contact Maria Haag 201-664-2346 ext. 1065 for Zoning, Land Use, or Resale/Rental Certificates.$t$, $t$5d0f67fd24ca435ebbcb04dbaadfbf9a836dc49e88a6f5e6e6cd557198b6214f$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":12,"fee_ok":9,"fee_bad":0,"fee_unchecked":3,"quotes":14,"q_ok":6,"q_bad":0,"q_unchecked":8},"source":"property/data/municipal-requirements/checked/0253.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0253.json$t$, true),
  ($t$0253$t$, $t$River Vale Township$t$, $t$BERGEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: River Vale Fire Prevention Bureau (town fire bureau)","Contact: David Haenelt, Fire Marshal (Coordinator: Maria Haag, ext. 1065; Fire Inspector: Danessa Real, ext. 1018) · 201-664-2346 ext. 1201 · dhaenelt@rivervalenj.org","Apply: Fee depends on business days between the request and the inspection: more than 10 business days for the lowest fee. The certificate is valid for 6 months from issue unless occupancy or ownership changes first; it is not transferable.","How to apply: Use the Township's Resale and/or Rental Certificate (RRC) application, which schedules both the building and fire inspections; one check payable to the Township of River Vale covers both. Requests can also go through the SDL Portal or inspections@rivervalenj.org.","Fire official in the NJ state directory, updated 7/28/2026: David Haenelt · (201) 664-2346 · fireprevention@rivervalenj.org","Smoke alarms on every level including the basement, within 10 feet of all bedroom doors on sleeping floors; type depends on build/renovation date (battery before 1977, electric for later homes, interconnected with battery backup for March 1991 and later)","Electric alarms cannot be replaced with battery alarms; smoke alarms over 10 years old must be replaced; no Velcro or tape mounting","Two-family homes need a smoke alarm at each landing of common hallways and stairs","Carbon monoxide alarm outside each sleeping area within 10 feet of all bedroom doors (UL 2034, NFPA 720); CO alarms over 5 years old are treated as expired unless the maker documents a longer life","Secondary Power Source Identification Label within 18 inches of the main electric panel and meter if there is a generator, solar panels or battery storage","Low voltage fire alarm systems need an NFPA 72 Report of Inspection from an approved contractor done no more than 30 days before","An agent, owner or representative must be present during the inspection window","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke alarm, CO alarm and secondary power source label certificate (CSACMASPSIL), requested more than 10 business days before inspection","amount":"$100"},{"label":"Requested 4 to 10 business days before inspection","amount":"$125"},{"label":"Requested fewer than 4 business days before inspection","amount":"$150"},{"label":"Reinspection, per occurrence","amount":"$50"},{"label":"Penalty for failing to obtain the certificate","amount":"$500"}]$j$::jsonb, $t$https://files-backend.assets.thrillshare.com/documents/asset/uploaded_file/4491/Trv/3bb0cf3c-093c-47f6-85b5-d8fc71a3ccc2/Resale_Rental_Certificate__RRC__Residential_Co.pdf?disposition=inline$t$, $t$https://rivervalenj.org/page/fire-prevention$t$, $j$[{"url":"https://files-backend.assets.thrillshare.com/documents/asset/uploaded_file/4491/Trv/67a1be4e-9059-483d-82a0-27b678a6f49b/RV_Smoke-CO_Requirements_042125.pdf?disposition=inline","label":"Official source (files-backend.assets.thrillshare.com)"},{"url":"https://ecode360.com/48286020","label":"Official source (ecode360.com)"},{"url":"https://rivervalenj.org/page/fire-prevention","label":"Official source (rivervalenj.org)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$A Certificate of Smoke Alarm and Carbon Monoxide Alarm Secondary Power Source Identification Label (CSACMASPSIL) is required before any residential unit is sold, leased or otherwise made subject to change of occupancy for residential purposes.$t$, $t$044f16cfe2396768846f3ca6d407fb98977409e6848a921b74218c44b1659968$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":12,"fee_ok":9,"fee_bad":0,"fee_unchecked":3,"quotes":14,"q_ok":6,"q_bad":0,"q_unchecked":8},"source":"property/data/municipal-requirements/checked/0253.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0253.json$t$, true),
  ($t$0254$t$, $t$Rochelle Park Township$t$, $t$BERGEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Compliance (Resale/CCO inspection)$t$, $j$["Issued by: Township of Rochelle Park Building Department / Code Enforcement (enforcement officer)","Contact: James DiMaria, Director of Code Enforcement / Construction Official / Zoning Officer (201-379-7104 ext. 1020… · 201-379-7104 ext. 1000 · lruff@rochelleparknj.gov","Apply: Code says the inspection is done within a reasonable time, not more than 30 days after a complete application. Allow time before closing in case a re-inspection is needed.","How to apply: Apply to the Building Department (Code Enforcement), 151 West Passaic Street, on the Township form with the fee (check payable to Township of Rochelle Park; payment must accompany the application) and the Tax Collector's paid-taxes certification. Call 201-379-7104 ext. 1000 to schedule. The CCO is not released until all items pass. Apply separately to the Fire Prevention Bureau for the smoke/CO certificate.","Handrails on inside and outside stairs with more than 3 risers","Vents for all gas appliances in good repair","Hot water heater must have a Township Building Department inspection sticker","GFCI receptacles within 5 feet of kitchen and bathroom sinks","House number visible near the front door, at least 3 1/2 inches high","No oil drippings from oil-fired units; oil tanks not in use must be removed","Sump pump must discharge outside, not into the sanitary sewer","Additions and alterations less than 5 years old must have a valid permit on file; no open permits","No visible safety issues; property maintenance violations corrected","Approved smoke detector installed (Township code)","Tax Collector certification that all property taxes are paid (required for all resale certificates)","Sidewalks and curbs inspected with the resale CCO","Also: Paid taxes certification: A Tax Collector certification that all property taxes are paid is required for all resale certificates.","Also: Sidewalks and curbs: The Construction Official inspects sidewalks and curbs with applications for certificates of continued occupancy on resale of a residence (Code 161-22G).","Also: Oil tanks: Oil tanks not in use must be removed for the resale CCO.","Also: Water heater sticker: The hot water heater must carry a Township Building Department inspection sticker."]$j$::jsonb, $j$[{"label":"Certificate of compliance, sale of a one family home","amount":"$100"},{"label":"Certificate of compliance, sale of a two family home","amount":"$200"}]$j$::jsonb, $t$https://drive.google.com/open?id=1xb-Ic46oM_1hGOcZ0PutfMpPdNt9UY57$t$, $t$https://rochelleparknj.gov/building-department-2/$t$, $j$[{"url":"https://ecode360.com/13727721","label":"Official source (ecode360.com)"},{"url":"https://drive.google.com/open?id=1xb-Ic46oM_1hGOcZ0PutfMpPdNt9UY57","label":"Official source (drive.google.com)"},{"url":"https://rochelleparknj.gov/building-department-2/","label":"Official source (rochelleparknj.gov)"}]$j$::jsonb, $t$Prior to the rental, sale or lease of any residential or commercial property or the sale of any individual unit in a multiple-family dwelling involving a new occupancy or change of use or tenancy, the enforcement officer shall issue a certificate of compliance in accordance with the standards set forth in$t$, $t$bf157911d90dd14cf2027b394e5b2bb72dff4d433216d1967a24115efc328298$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":3,"fee_bad":0,"fee_unchecked":2,"quotes":18,"q_ok":8,"q_bad":0,"q_unchecked":10},"source":"property/data/municipal-requirements/checked/0254.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0254.json$t$, true),
  ($t$0254$t$, $t$Rochelle Park Township$t$, $t$BERGEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Rochelle Park Bureau of Fire Code Enforcement (Fire Prevention Bureau) (town fire bureau)","Contact: Sean Redl, Bureau Chief (Sredl@rochelleparknj.gov); Secretary Lisa Ruff receives applications · 201-587-7750 · Lruff@rochelleparknj.gov","Apply: Fee depends on calendar/business days between the application and the anticipated closing date. The application is valid for six months; a certificate not used within six months needs a new application.","How to apply: Complete the Home Resale Fire Inspection (CSACMAC) application and email it with the fee to Lisa Ruff (Lruff@rochelleparknj.gov). After submitting, the applicant must contact the Bureau by email or at 201-587-7750 to schedule; the Bureau no longer calls to schedule. The fee is not refundable.","Fire official in the NJ state directory, updated 3/20/2026: Sean Redl · (201) 587-7750 · sredl@rochelleparknj.gov","Smoke alarms meeting NFPA 72 for quantity, type and location, all in working order","Carbon monoxide detector(s) within ten feet of sleeping areas","Secondary power source labeled, if the home has one","No fire extinguisher required since April 2025 (still recommended)","Vacant homes must be scheduled with a property representative present","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"CSACMAC, all other occupancies (1 and 2 family), more than 5 calendar days before closing","amount":"$75.00"},{"label":"CSACMAC, less than 4 calendar days before closing","amount":"$125.00"},{"label":"Re-inspection","amount":"Same as the initial fee paid ($75.00 or $125.00)"}]$j$::jsonb, $t$https://rochelleparknj.gov/wp-content/uploads/2026/06/REVISED-FIRE-PREVENTION-HOME-SALE-APPLICATION-6-2-2026.pdf$t$, $t$https://rochelleparknj.gov/fire-prevention/$t$, $j$[{"url":"https://rochelleparknj.gov/fire-prevention/","label":"Official source (rochelleparknj.gov)"},{"url":"https://rochelleparknj.gov/wp-content/uploads/2026/06/REVISED-FIRE-PREVENTION-HOME-SALE-APPLICATION-6-2-2026.pdf","label":"Official source (rochelleparknj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$How Do I File for a Home Re-sale inspection?$t$, $t$4faf1b18c0460cfd9671ec6928897ebbfeacc3a3b16fe9d0a241f484625aa3b3$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":3,"fee_bad":0,"fee_unchecked":2,"quotes":18,"q_ok":8,"q_bad":0,"q_unchecked":10},"source":"property/data/municipal-requirements/checked/0254.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0254.json$t$, true),
  ($t$0255$t$, $t$Rockleigh Borough$t$, $t$BERGEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Continuing Occupancy (CCO) / Certificate of Resale/Rental Residential Property$t$, $j$["Issued by: Borough of Rockleigh Construction Office (Construction Official)","Contact: William McGuire, Construction Official / Construction/Zoning Official · 201-768-4217 · clerk@rockleighnj.org","Apply: Inspections are conducted Monday through Friday between 9 a.m. and 5 p.m.","How to apply: Download the Application for Certificate of Resale/Rental Residential Property from the Borough's Forms & Permits page, fill in owner, buyer and inspection-day contact, and submit it to the Construction Office, 26 Rockleigh Road, Rockleigh, NJ 07647, with a $150.00 check payable to the Borough of Rockleigh.","Written application by the owner or agent, saying whether the property is to be sold","General inspection showing no apparent violations and no pending violations, orders or open matters with the Construction Official","Use of the building must have existed before (no unapproved change of use)"]$j$::jsonb, $j$[{"label":"Inspection / CCO issuance, residential resale or rental","amount":"$150.00"},{"label":"Certificate of continued occupancy letter (Borough Code Section 9-1.3)","amount":"$150"}]$j$::jsonb, $t$https://rockleighnj.org/s/Application-for-Certificate-of-Resale-Rental-Residential-Property.pdf$t$, $t$https://rockleighnj.org/building$t$, $j$[{"url":"https://ecode360.com/34757033","label":"Official source (ecode360.com)"},{"url":"https://rockleighnj.org/s/Application-for-Certificate-of-Resale-Rental-Residential-Property.pdf","label":"Official source (rockleighnj.org)"},{"url":"https://rockleighnj.org/forms","label":"Official source (rockleighnj.org)"},{"url":"https://rockleighnj.org/building","label":"Official source (rockleighnj.org)"},{"url":"https://ecode360.com/34754940","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$Any such vacation, sale or change of use without obtaining a certificate of continuing occupancy shall constitute a violation of this Article and subject the owner or occupier to the penalties provided in § 34-57.$t$, $t$96027fda71a1e78174dc40e836cbd0d698fbde44d93078e62d400eab5b98e2b5$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":0,"fee_bad":0,"fee_unchecked":5,"quotes":11,"q_ok":4,"q_bad":0,"q_unchecked":7},"source":"property/data/municipal-requirements/checked/0255.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0255.json$t$, true),
  ($t$0255$t$, $t$Rockleigh Borough$t$, $t$BERGEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Rockleigh Fire Prevention Bureau (Borough of Rockleigh) (town fire bureau)","Contact: William McGuire, Fire Inspector/Prevention Official (Alternate Fire Inspector: Kenneth Shepard) · (201) 768-4217 · wmcguire@rockleighnj.org","Apply: Fee depends on business days between the application and the change of occupant: more than 10 business days for the lowest fee.","How to apply: Contact the Borough office at 26 Rockleigh Road (201-768-4217). No separate smoke/CO application form is posted; it is likely handled with the CCO inspection by William McGuire, but confirm.","Fire official in the NJ state directory (town), updated 2/18/2026: William Mc Guire · (201) 768-4217 · wmcguire@rockleighnj.org","Smoke alarm on each level and outside each separate sleeping area, near the bedrooms (Borough code)","Carbon monoxide detectors as required by N.J.S.A. 52:27D-133.3","Portable fire extinguisher (ABC type, no larger than 10 pounds, mounted within 10 feet of the kitchen) (Borough code still lists it)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke detector compliance certificate, application more than 10 business days before change of occupant","amount":"$50.00"},{"label":"Application four to 10 business days before change of occupant","amount":"$100.00"},{"label":"Application less than four business days before change of occupant","amount":"$150.00"}]$j$::jsonb, null, $t$https://rockleighnj.org/fire-prevention$t$, $j$[{"url":"https://ecode360.com/34755071","label":"Official source (ecode360.com)"},{"url":"https://rockleighnj.org/fire-prevention","label":"Official source (rockleighnj.org)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$In the case of change of occupancy of any building subject to the requirements of subsection 11-1.9, no owner shall sell, lease or otherwise permit occupancy for residential purposes of that building without first obtaining from the Rockleigh Fire Prevention Bureau a certificate evidencing compliance with the requirements of this chapter and N.J.S.A. 52:27D-198.1 and 52:27D-198.2.$t$, $t$0f14a65d68719d6cc3c4a5422dc548c8d42432f826a429f34078ffba283d7976$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":0,"fee_bad":0,"fee_unchecked":5,"quotes":11,"q_ok":4,"q_bad":0,"q_unchecked":7},"source":"property/data/municipal-requirements/checked/0255.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0255.json$t$, true),
  ($t$0256$t$, $t$Rutherford Borough$t$, $t$BERGEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Residential Certificate of Zoning Compliance (CZC), previously called Certificate of Occupancy$t$, $j$["Issued by: Borough of Rutherford Construction Official (Building and Zoning Department)","Contact: Thomas Delia, Zoning Officer (Construction Official: Chris Salviano) · 201-460-3042 · zoning@rutherfordboronj.com","Apply: Inspections are scheduled after the form is received; the certificate is issued no sooner than 48 hours after all inspections pass (the form says 24 hours). The CZC inspection is not scheduled until all open permits are closed.","How to apply: Fill out the Residential Certificate of Zoning Compliance Application and Requirements (Includes Transfer of Title) and submit it with a $100 check (or exact cash) payable to the Borough of Rutherford at the Building and Zoning office, Borough Hall, 176 Park Avenue, Main Level. Inspections are then scheduled; call 201-460-3042 to schedule the zoning inspection and 201-460-3010 about open permits. Choose pick-up or email delivery of the certificate on the form.","Open or outstanding permits must have final inspections and be closed before the CZC inspection is scheduled","Street numbers at least 3 inches high with a 1/2 inch stroke, visible from the street","Garages, fences, sheds and walls in good repair; sidewalks, stairs, driveways and walkways free of hazards","Attached garage fire rating maintained, holes patched, and a listed self-closing device on any door into the house","No sump pump may discharge to the sewer","Pressure relief discharge pipe on heating units and water heaters, full size, ending no more than 6 inches off the floor","Clearances around fuel burning appliances; roof sound and leaders discharging away from the foundation","Smoke and carbon monoxide alarms (checked during the CZC inspection; see fire certificate)","Transfer of Title Certificate instead of a CZC only if the home will not be occupied after purchase, with a letter from the buyer's attorney","Also: Open permits: All open or outstanding construction permits must be finaled and closed before the CZC inspection is scheduled; sellers are asked to call 201-460-3010 ahead of time.","Also: Sump pump not to sewer: The CZC checklist says no sump pump may discharge to the sewer.","Also: Sidewalks, stairs, driveways and walkways: Checked during the CZC inspection; must be in good repair and free of tripping hazards."]$j$::jsonb, $j$[{"label":"Residential Certificate of Zoning Compliance (1 or 2 family, condo, co-op)","amount":"$100"},{"label":"Certificate of occupancy for resale, R-2, R-3, R-4 and R-5 uses (Code Section 22-6A(1)(a))","amount":"$100 per dwelling unit"}]$j$::jsonb, $t$https://www.rutherfordboronj.com/government/forms/construction/1180-residential-certificate-of-zoning-compliance-application-including-transfer-of-title/file$t$, $t$https://www.rutherfordboronj.com/departments/building$t$, $j$[{"url":"https://ecode360.com/11349902","label":"Official source (ecode360.com)"},{"url":"https://www.rutherfordboronj.com/building-page-list/308-certificate-of-zoning-compliance","label":"Official source (rutherfordboronj.com)"},{"url":"https://www.rutherfordboronj.com/government/forms/construction/1180-residential-certificate-of-zoning-compliance-application-including-transfer-of-title/file","label":"Official source (rutherfordboronj.com)"},{"url":"https://www.rutherfordboronj.com/departments/building","label":"Official source (rutherfordboronj.com)"},{"url":"https://ecode360.com/11343417","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$A certificate of zoning compliance shall be applied for and obtained prior to the use or occupancy of the whole or any part of any building:$t$, $t$1d65d36bb163de80a785b712d3fe259c115be25c2687b8cd9b8b7de53408ab1e$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":2,"fee_ok":1,"fee_bad":0,"fee_unchecked":1,"quotes":15,"q_ok":11,"q_bad":0,"q_unchecked":4},"source":"property/data/municipal-requirements/checked/0256.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0256.json$t$, true),
  ($t$0256$t$, $t$Rutherford Borough$t$, $t$BERGEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Borough of Rutherford Building and Zoning Department (smoke/CO checked during the Certificate of Zoning Compliance inspection); fire code enforcing agency: Rutherford Bureau of Fire Safety","Contact: Paul T. Dansbach, Fire Marshal · 201-460-3011 · firesafety@rutherfordboronj.com","Apply: Same as the Certificate of Zoning Compliance: certificate issued no sooner than 48 hours after all inspections pass.","How to apply: No separate smoke/CO application was found for 1 and 2 family homes. The smoke and carbon monoxide alarm requirements are printed in the Residential Certificate of Zoning Compliance packet, and the inspector's sheet has an SD/CO line, so the check appears to be part of the $100 CZC. 3-family and larger homes are inspected by the Bureau of Fire Safety (201-460-3011).","Fire official in the NJ state directory (town), updated 5/14/2026: Paul T Dansbach · (201) 460-3011 · pdansbach@rutherfordboronj.com","Smoke alarms on each level and outside/in the vicinity of each separate sleeping area, per NFPA 72 (interconnection not required)","Ten-year sealed battery smoke alarms listed to ANSI/UL 217; hardwired alarms from original construction or rehabilitation may not be replaced with battery alarms","Carbon monoxide alarms within 10 feet of the sleeping areas in homes with a fuel burning device or attached garage (battery, hardwired or plug-in, UL 2034, NFPA 720)","Ten-year sealed battery combination smoke and CO alarms are permitted","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[]$j$::jsonb, $t$https://www.rutherfordboronj.com/government/forms/construction/1180-residential-certificate-of-zoning-compliance-application-including-transfer-of-title/file$t$, $t$https://www.rutherfordboronj.com/departments/fire-safety$t$, $j$[{"url":"https://www.rutherfordboronj.com/government/forms/construction/1180-residential-certificate-of-zoning-compliance-application-including-transfer-of-title/file","label":"Official source (rutherfordboronj.com)"},{"url":"https://www.rutherfordboronj.com/departments/fire-safety","label":"Official source (rutherfordboronj.com)"},{"url":"https://ecode360.com/11343827","label":"Official source (ecode360.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Smoke & Carbon Monoxide Alarm Requirements$t$, $t$ca61a2f5a9c76d9c999b269f0505d9dad1f1f30b5c7e2a0d97962fae25ea9c76$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":2,"fee_ok":1,"fee_bad":0,"fee_unchecked":1,"quotes":15,"q_ok":11,"q_bad":0,"q_unchecked":4},"source":"property/data/municipal-requirements/checked/0256.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0256.json$t$, true),
  ($t$0257$t$, $t$Saddle Brook Township$t$, $t$BERGEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Resale Certificate$t$, $j$["Issued by: Township of Saddle Brook Building Department (Construction Official / Fire Official inspection; Property Maintenance Officer checks the exterior)","Contact: Anthony Ambrogio, Construction Official / Building Subcode Official / Zoning Officer / Property Maintenance Official · (201) 843-7111 · permits@saddlebrooknj.gov","Apply: Inspections are on Wednesdays between 10:00 a.m. and 2:00 p.m. If fees are paid by check, allow a one week wait for the check to clear. No same-day re-inspections.","How to apply: Pay the $200 water meter fee at the Water Department (call Donna, 201-587-2905) and get a receipt, then submit the Resale Certificate application with the fee to the Building Department, 55 Mayhill Street, Saddle Brook, NJ 07663 (Monday to Friday 8:30 a.m. to 4:00 p.m.). Re-inspections cost the same as the first inspection.","Valid for: 60 days from issue date","Proof of payment of the $200 water meter fee (Water Department)","Payment of the Resale Certificate fee, a completed application and an approved inspection","Ten-year sealed battery smoke alarms on each level and outside each sleeping area; hardwired alarms (installed after 1995) in bedrooms, near bedrooms and on each story, not replaced with battery units","Carbon monoxide detector within 10 feet of all sleeping areas","Low voltage fire alarm systems tested by a licensed electrician or fire alarm contractor, with the report submitted before the inspection","Secondary power source warning label (generators, solar, battery storage) within 18 inches of the main panel and meter","Property Maintenance Officer inspects the sidewalk and the whole exterior","Open permits are checked on the application","Also: Water meter fee: A $200 water meter fee applies to the sale of any home (Ordinance 1472-09); pay the Water Department (201-587-2905) and bring the receipt.","Also: Sidewalk and exterior inspection: The Property Maintenance Officer inspects the sidewalk and the whole exterior.","Also: Open permits: The Building Department checks for open permits on the application."]$j$::jsonb, $j$[{"label":"Resale Certificate fee","amount":"$125"},{"label":"New application if the closing does not happen within 60 days","amount":"$100"},{"label":"Water meter fee on the sale of any home (paid to the Water Department; proof needed)","amount":"$200"}]$j$::jsonb, $t$https://saddlebrooknj.us/wp-content/uploads/2025/08/RESALE-CERTIFICATE-REQUIREMENTS-AND-APPLICATION-August-2025.pdf$t$, $t$https://saddlebrooknj.us/building-department/$t$, $j$[{"url":"https://saddlebrooknj.us/wp-content/uploads/2025/08/RESALE-CERTIFICATE-REQUIREMENTS-AND-APPLICATION-August-2025.pdf","label":"Official source (saddlebrooknj.us)"},{"url":"https://saddlebrooknj.us/building-department/","label":"Official source (saddlebrooknj.us)"}]$j$::jsonb, $t$The Saddle Brook Building Department must have the following prior to the issuance of a Resale Certificate:$t$, $t$0b929261a531d43be932eaa3ef630881204ecab0c062265fcbeae4f30cf0d6b7$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":3,"fee_bad":0,"fee_unchecked":1,"quotes":13,"q_ok":11,"q_bad":0,"q_unchecked":2},"source":"property/data/municipal-requirements/checked/0257.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0257.json$t$, true),
  ($t$0257$t$, $t$Saddle Brook Township$t$, $t$BERGEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Saddle Brook Township Fire Prevention Bureau / Fire Official, inspected as part of the Building Department Resale Certificate (town fire bureau)","Contact: Michael Seitz, Fire Official; Fire Subcode Official / Fire Inspector (Building Department page) · (201) 587-8184 · mseitz@saddlebrooknj.gov","Apply: Same Wednesday 10:00 a.m. to 2:00 p.m. resale inspection.","How to apply: The smoke and CO check is part of the Resale Certificate inspection; the application grants the Fire Official or Construction Official permission to inspect. Apply through the Building Department.","Fire official in the NJ state directory, updated 7/1/2025: Michael Seitz · (201) 587-8184 · mseitz@saddlebrooknj.gov","Ten-year sealed battery smoke alarms on each level and outside each separate sleeping area; hardwired alarms (post-1995) kept and not replaced with battery units","Carbon monoxide detector within 10 feet of all sleeping areas","Low voltage fire alarm systems tested with a report","Secondary power source warning label for generators, solar or battery storage","The August 2025 form no longer lists a fire extinguisher","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke and carbon monoxide detector certificate, per inspection (Code Section 93-10F); reinspections cost the same","amount":"$50"}]$j$::jsonb, $t$https://saddlebrooknj.us/wp-content/uploads/2025/08/RESALE-CERTIFICATE-REQUIREMENTS-AND-APPLICATION-August-2025.pdf$t$, $t$https://saddlebrooknj.us/building-department/$t$, $j$[{"url":"https://ecode360.com/6386464","label":"Official source (ecode360.com)"},{"url":"https://saddlebrooknj.us/wp-content/uploads/2025/08/RESALE-CERTIFICATE-REQUIREMENTS-AND-APPLICATION-August-2025.pdf","label":"Official source (saddlebrooknj.us)"},{"url":"https://saddlebrooknj.us/building-department/","label":"Official source (saddlebrooknj.us)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Smoke and carbon monoxide detector certificate, per inspection: $50. All reinspections will be charged a reinspection fee equal to the first inspection fee for each additional time an inspection official is required to return to the premises.$t$, $t$8f6658341ad49857050271bf3ca015fd607a3c714a0f6d7b1ec198c09c02dc50$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":3,"fee_bad":0,"fee_unchecked":1,"quotes":13,"q_ok":11,"q_bad":0,"q_unchecked":2},"source":"property/data/municipal-requirements/checked/0257.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0257.json$t$, true),
  ($t$0258$t$, $t$Saddle River Borough$t$, $t$BERGEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Continued Inspection (CCI)$t$, $j$["Issued by: Borough of Saddle River Construction Department (Construction Official/Building Inspector)","Contact: Robert Sherrow, Construction Official · 201-327-2609 · rsherrow@saddleriver.gov","Apply: The Construction Official inspects within 10 days of a fully completed application and fee; the form says the department has ten working days to approve or deny.","How to apply: Download the Application for Continued Certificate of Inspection from the Building and Construction page, sign it and file it with the $200.00 fee at the Construction Department, Municipal Building, 100 East Allendale Road. Apply for the separate Fire Prevention certificate at the same time; one does not replace the other. Inspection requests can be emailed to inspections@saddleriver.gov.","Valid for: Construction Department approval is good for 60 days from date of issue.","General inspection of the visible parts of the premises for apparent zoning violations","Pool must have a pool fence with self-closing, self-latching gates that swing away from the pool","Application lists kitchens, baths, bedrooms and the number of families before and after the sale","If the building will not be occupied, the buyer submits a certification instead and gets the Construction Official's approval document","If violations cannot be fixed before closing, the applicant can certify a cure date and get a temporary certificate; a $50 a day fine applies if not cured by that date","No CCI is issued on resale while a tree removal violation is outstanding","Also: Tree removal violations: The Borough will not issue a certificate of continuing occupancy on resale while a served tree removal violation is unresolved.","Also: Pool fence: Pools need a fence with self-closing, self-latching gates that swing away from the pool; a failed inspection costs $100.00 to reinspect.","Also: Address identification: Street numbers must be clearly visible from the street and clear of obstructions."]$j$::jsonb, $j$[{"label":"Certificate of Continued Inspection application","amount":"$200"},{"label":"Each subsequent inspection or temporary certificate","amount":"$100"},{"label":"Building fee (application form)","amount":"$200.00"}]$j$::jsonb, $t$https://saddleriver.gov/uploads/dm/12058/CCIBUILDINGUPDATED$t$, $t$https://saddleriver.gov/building_const$t$, $j$[{"url":"https://ecode360.com/14043759","label":"Official source (ecode360.com)"},{"url":"https://saddleriver.gov/uploads/dm/12058/CCIBUILDINGUPDATED","label":"Official source (saddleriver.gov)"},{"url":"https://saddleriver.gov/building_const","label":"Official source (saddleriver.gov)"},{"url":"https://ecode360.com/30377097","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$A certificate of continued inspection shall be required upon any transfer of title to an existing premises which is accompanied by a change in the occupancy of such premises.$t$, $t$7ec7406b8d49b673be8333c20319410aac66af2c8752cb1770b760958ad407c9$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":1,"fee_bad":0,"fee_unchecked":5,"quotes":11,"q_ok":5,"q_bad":0,"q_unchecked":6},"source":"property/data/municipal-requirements/checked/0258.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0258.json$t$, true),
  ($t$0258$t$, $t$Saddle River Borough$t$, $t$BERGEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Saddle River Fire Prevention Bureau (town fire bureau)","Contact: Samuel Antoshak, Fire Official and Fire Marshal · 201-327-2609 ext. 237 · santoshak@saddleriver.gov","Apply: The Bureau issues the certificate within 20 business days of receipt of a completed application, fee and inspection.","How to apply: Fill out the Fire Prevention Bureau's Application for Smoke Detector Inspection and Certificate of Compliance completely (unsigned or incomplete forms are not accepted) and pay by check only, payable to the Borough of Saddle River. Questions: Fire Marshal at 201-327-2609 ext. 237.","At least one smoke detector on each level including the basement; prewired interconnected detectors must work and cannot be replaced by battery units","Detectors 10 years or older must be replaced","Carbon monoxide detectors on each level with bedrooms, within 10 feet of each bedroom","Fire alarm systems: someone must know how to silence and reset; an alarm company report from the last 6 months avoids on-site testing","Portable fire extinguisher, 5 to 10 pound ABC, minimum 2A:10B:C, mounted within 10 feet of the kitchen and serviced/tagged within 12 months or with a purchase receipt (form still lists it)","Building information sheet (solar panels, pools, gates, Knox box, sprinklers, truss roof) and emergency contacts; the inspector photographs the exterior for preplans","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"CSACMAPFEC inspection","amount":"$200"},{"label":"Reinspection","amount":"$100"},{"label":"Inspection fee (application form)","amount":"$200"}]$j$::jsonb, $t$https://saddleriver.gov/vertical/sites/%7B2E7E07BD-0A79-4A05-9B79-960D47AACDC0%7D/uploads/FIRE_PREVENTION_CCO_APPLICATON.pdf$t$, $t$https://saddleriver.gov/fire_prevention$t$, $j$[{"url":"https://ecode360.com/10637197","label":"Official source (ecode360.com)"},{"url":"https://saddleriver.gov/fire_prevention","label":"Official source (saddleriver.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://saddleriver.gov/vertical/sites/%7B2E7E07BD-0A79-4A05-9B79-960D47AACDC0%7D/uploads/FIRE_PREVENTION_CCO_APPLICATON.pdf","label":"Official source (saddleriver.gov)"}]$j$::jsonb, $t$Before any Use Group R-3 structure is sold, leased or otherwise subject to a change of occupancy for residential purposes, the owner shall obtain a certificate of smoke alarm, carbon monoxide alarm, and portable fire extinguisher compliance (CSACMAPFEC) from the Fire Prevention Bureau.$t$, $t$8bf58d308065ec3e5525c2c6e255838e44524ac69258c8ba9a26ae70fe92c805$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":1,"fee_bad":0,"fee_unchecked":5,"quotes":11,"q_ok":5,"q_bad":0,"q_unchecked":6},"source":"property/data/municipal-requirements/checked/0258.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0258.json$t$, true),
  ($t$0259$t$, $t$South Hackensack Township$t$, $t$BERGEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Inspection (COI) / Certificate of Continued Occupancy, with Zoning Permit$t$, $j$["Issued by: South Hackensack Township Building Department","Contact: Armand Marini III, Construction Official (Zoning Officer: Raymond DeRiso, ZoningOfficer@southhackensacknj.org) · (201) 440-1815 x106 · BuildingOfficial@southhackensacknj.org","Apply: Contact the Building Department at least 7 days before closing to schedule the inspections and correct any issues.","How to apply: Contact the Building Department (227 Phillips Ave., (201) 440-1815 x106) at least 7 days before closing to apply for the Zoning Permit, the smoke and carbon monoxide inspection and the Certificate of Inspection. Inspections are by appointment; permit submittal hours are Monday to Friday 9:00am to 4:00pm.","Zoning Permit","Smoke and carbon monoxide inspection","Certificate of Inspection (COI)","Portable fire extinguisher within 10 feet of the kitchen (Fire Prevention page still lists it)","Also: Zoning permit: A Zoning Permit is required for every home sale: $25 owner occupied, $75 non-owner occupied."]$j$::jsonb, $j$[{"label":"Zoning Permit, owner occupied property","amount":"$25"},{"label":"Zoning Permit, non-owner occupied property","amount":"$75"},{"label":"Certificate of Inspection, one-family residence","amount":"$25"},{"label":"Certificate of Inspection, two-family residence","amount":"$50"},{"label":"Certificate of Inspection reinspection","amount":"$25"}]$j$::jsonb, null, $t$https://southhackensacknj.org/building/cco.php$t$, $j$[{"url":"https://southhackensacknj.org/building/cco.php","label":"Official source (southhackensacknj.org)"},{"url":"https://southhackensacknj.org/fireprevention/selling_your_home.php","label":"Official source (southhackensacknj.org)"},{"url":"https://southhackensacknj.org/building/","label":"Official source (southhackensacknj.org)"}]$j$::jsonb, $t$If you are selling a home in South Hackensack a Zoning Permit, Smoke & Carbon Monoxide inspection, and Certificate of Inspection (COI) are all required prior to closing.$t$, $t$346f99cdcb6ec4f1e73559dc79bb6e04951b4e13f56c0efa34af3efc4f0a643a$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":6,"fee_bad":0,"fee_unchecked":0,"quotes":11,"q_ok":7,"q_bad":0,"q_unchecked":4},"source":"property/data/municipal-requirements/checked/0259.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0259.json$t$, true),
  ($t$0259$t$, $t$South Hackensack Township$t$, $t$BERGEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: South Hackensack Building Department with the South Hackensack Fire Prevention Bureau (town fire bureau)","Contact: Fred Dressel, Fire Official · (201) 440-1815 x107 · fireprevention@southhackensacknj.org","Apply: Contact the Building Department at least 7 days before closing.","How to apply: Request the smoke and carbon monoxide inspection through the Building Department as part of the resale package (Fire Prevention Bureau performs home-sale smoke/CO/extinguisher inspections).","Fire official in the NJ state directory, updated 5/18/2026: Fredrick J Dressel IV · (201) 440-1815","At least one smoke detector on every floor including the basement","Carbon monoxide alarm within 10 feet of all bedroom doors","Portable fire extinguisher within 10 feet of the kitchen, hung no higher than 5 feet, rated ABC, 2.5 to 10 lbs (page still lists it)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke and carbon monoxide detector inspection","amount":"$25"}]$j$::jsonb, null, $t$https://southhackensacknj.org/fireprevention/selling_your_home.php$t$, $j$[{"url":"https://southhackensacknj.org/building/cco.php","label":"Official source (southhackensacknj.org)"},{"url":"https://southhackensacknj.org/fireprevention/selling_your_home.php","label":"Official source (southhackensacknj.org)"},{"url":"https://southhackensacknj.org/fireprevention/","label":"Official source (southhackensacknj.org)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Smoke & Carbon Monoxide Detector Inspection $25$t$, $t$14c2d760f8bf916522fca54fab039bd5018606bfe096765b62821cd849e5c232$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":6,"fee_bad":0,"fee_unchecked":0,"quotes":11,"q_ok":7,"q_bad":0,"q_unchecked":4},"source":"property/data/municipal-requirements/checked/0259.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0259.json$t$, true),
  ($t$0262$t$, $t$Teterboro Borough$t$, $t$BERGEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Occupancy on change of ownership (Borough Code Chapter 75)$t$, $j$["Issued by: Teterboro Construction Code Official","Contact: 201-288-7204 · code@teterboronj.org","How to apply: Apply in writing to the Construction Code Official on the office's form; the Building Department is at 250 Hollister Road, 2nd floor. Office hours vary, so email code@teterboronj.org or call first.","General inspection of the visible parts of the building; no violations of law or pending orders of the Construction Official","Inspection and review of municipal records must show the use of the dwelling has lawfully existed"]$j$::jsonb, $j$[{"label":"Certificate of occupancy on change of ownership, dwelling","amount":"$50"}]$j$::jsonb, null, $t$https://www.teterboronj.org/departments/construction$t$, $j$[{"url":"https://ecode360.com/12523408","label":"Official source (ecode360.com)"},{"url":"https://www.teterboronj.org/departments/construction","label":"Official source (teterboronj.org)"}]$j$::jsonb, $t$In the event of reoccupancy, alteration, renovation, addition, change of use or ownership of a building, structure or dwelling, written application shall be made by the owner or his or her agent for a certificate of occupancy.$t$, $t$f67b6b0f70d579ecb148ea70715367821f7a5ba7f5f3ff224b42164d8741b1a0$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":1,"fee_ok":0,"fee_bad":0,"fee_unchecked":1,"quotes":9,"q_ok":3,"q_bad":0,"q_unchecked":6},"source":"property/data/municipal-requirements/checked/0262.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0262.json$t$, true),
  ($t$0262$t$, $t$Teterboro Borough$t$, $t$BERGEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Teterboro Fire Official / Construction Office (Teterboro Boro Constr Off) (town fire bureau)","Contact: Robert A. Knobloch, Fire Official (per NJ DCA fire directory) · 201-288-7204 · fire@teterboronj.org","How to apply: No online form. Contact the Fire Official's office at 250 Hollister Road, 2nd floor, (201) 288-7204, fire@teterboronj.org.","Fire official in the NJ state directory (town), updated 9/26/2025: Robert A. Knobloch · (201) 288-7204 · fire@teterboronj.org","Smoke alarms and carbon monoxide alarms as required by N.J.A.C. 5:70-4.19 (no local checklist posted)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[]$j$::jsonb, null, $t$https://www.teterboronj.org/departments/construction$t$, $j$[{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://www.teterboronj.org/departments/construction","label":"Official source (teterboronj.org)"},{"url":"https://ecode360.com/12523553","label":"Official source (ecode360.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Name: Teterboro Boro Constr Off$t$, $t$3d76712f87bd3b0d3f7ef694000c6e61dde491b93d91ab47ffdd3b1dc905d8df$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":1,"fee_ok":0,"fee_bad":0,"fee_unchecked":1,"quotes":9,"q_ok":3,"q_bad":0,"q_unchecked":6},"source":"property/data/municipal-requirements/checked/0262.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0262.json$t$, true),
  ($t$0263$t$, $t$Upper Saddle River Borough$t$, $t$BERGEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Resale/Rental (Certificate of Continued Occupancy)$t$, $j$["Issued by: Borough of Upper Saddle River Building Department / Code Compliance Office (Construction Official), with sign-offs from Fire Prevention, the Board of Health and Property Maintenance/Zoning","Contact: Gina DeMott, Technical Assistant, Building Department · 201-327-2196 ext. 231 · usrpermits@usrtoday.org","Apply: The Borough packet says the process could take up to 30 days. No exemptions or conditional certificates are issued.","How to apply: Download the Certificate of Resale or Rental Application packet from the Borough Forms page, complete the entire top section, and drop it off at the Building Department (376 West Saddle River Road; after-hours drop box by the side entrance) with two checks payable to the Borough of Upper Saddle River: $100.00 for the certificate and the separate Fire Prevention fee. The Building office distributes the packet; the Zoning Official and Fire Prevention Bureau will call to inspect. Contact the Health Department yourself.","Valid for: Certificate valid for 6 months (per the application form).","Building Department review for open permits, unpaid permits or violations","Zoning Official site inspection","Fire Prevention Bureau smoke/CO alarm inspection and approval","Health Department requirements (contact them directly): wells tested by a certified lab and cesspools or non-compliant septic systems updated at realty transfer, per the Bergen County sheet in the packet","No violations of law or Construction Official orders pending, and the existing use must have lawfully existed","Also: Well test and septic/cesspool (Health Department): The resale packet requires the seller to contact the Health Department; the Bergen County sheet in the packet says wells must be tested by a certified lab and cesspools or non-compliant septic systems must be updated at realty transfer.","Also: Open or unpaid permits and violations: The Building Department checks the address for open permits, unpaid permits or violations before the certificate is issued."]$j$::jsonb, $j$[{"label":"Certificate of continued occupancy (Code Chapter 40)","amount":"$100"},{"label":"Certificate of continued occupancy reinspection (Code Chapter 40)","amount":"$50"},{"label":"Certificate of Resale/Rental application fee (Borough packet)","amount":"$100"}]$j$::jsonb, $t$https://www.usrtoday.org/DocumentCenter/View/380/Certificate-of-ResaleRental-Application-PDF$t$, $t$https://www.usrtoday.org/159/Building-Department$t$, $j$[{"url":"https://ecode360.com/12199576","label":"Official source (ecode360.com)"},{"url":"https://www.usrtoday.org/DocumentCenter/View/380/Certificate-of-ResaleRental-Application-PDF","label":"Official source (usrtoday.org)"},{"url":"https://www.usrtoday.org/159/Building-Department","label":"Official source (usrtoday.org)"}]$j$::jsonb, $t$No person shall change ownership or otherwise transfer title or lease a dwelling to a new owner or tenant of such dwelling unless and until that person shall have first obtained from the Construction Official, or his/her designee, a certificate of continued occupancy.$t$, $t$640643711ac9bd73a8083408d06f0b9be2707fdb2fd9293b3a7e189e8297cc9f$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":8,"fee_ok":0,"fee_bad":0,"fee_unchecked":8,"quotes":14,"q_ok":3,"q_bad":0,"q_unchecked":11},"source":"property/data/municipal-requirements/checked/0263.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0263.json$t$, true),
  ($t$0263$t$, $t$Upper Saddle River Borough$t$, $t$BERGEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Upper Saddle River Bureau of Fire Prevention (town fire bureau)","Contact: Darryl J DeMott, Fire Official (NJ DCA fire directory); packet contact Gina De Mott, (201) 932-0350, fpassistant@usrtoday.org · 201-327-4343 · usrfireofficial@usrtoday.org","Apply: Regular fee applies when the application comes in at least five calendar days before the change of occupancy (code); the packet's fee sheet says more than 10 business days. Inspection dates are set by the office. The certificate is valid for six (6) months.","How to apply: Fill out the Fire Prevention Application (Certificate of Smoke Detector / Carbon Monoxide Alarm Compliance) in the resale packet and include the fee check payable to the Borough of Upper Saddle River with the packet at the Building Department. The Fire Prevention Bureau then contacts you to schedule.","Fire official in the NJ state directory, updated 7/13/2026: Darryl J DeMott · (201) 327-4343 · usrfireofficial@usrtoday.org","Smoke detectors at the base of each stairway on each level (including the basement) and outside each sleeping area within 10 feet of bedroom doors","Hardwired or interconnected alarms from original construction must stay hardwired; others may be 10-year sealed battery (UL 217) or central-station monitored","Proof of end of life is required for any device more than 7 years old","Carbon monoxide alarms (UL 2034, NFPA 720) within 10 feet outside every bedroom; battery, hardwired or plug-in","Central station systems need a certified central station test document plus a field inspection","Portable ABC fire extinguisher (Code Section 51-9 and the packet still list it)","Someone 18 or older (owner, tenant, realtor or agent) with a driver license must let the inspector in","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke/CO/extinguisher certificate, application received prior to five calendar days before change of occupancy (Code Section 51-9)","amount":"$70"},{"label":"Smoke/CO/extinguisher certificate, four days or less notice (Code Section 51-9)","amount":"$125"},{"label":"Fire Prevention application, regular inspection (Borough packet)","amount":"$70.00"},{"label":"Fire Prevention application, expedited inspection (Borough packet)","amount":"$125.00"},{"label":"Reinspection (non-working, recalled or missing alarms, or no-shows)","amount":"$35.00"}]$j$::jsonb, $t$https://www.usrtoday.org/DocumentCenter/View/380/Certificate-of-ResaleRental-Application-PDF$t$, $t$https://www.usrtoday.org/159/Building-Department$t$, $j$[{"url":"https://ecode360.com/8645520","label":"Official source (ecode360.com)"},{"url":"https://www.usrtoday.org/DocumentCenter/View/380/Certificate-of-ResaleRental-Application-PDF","label":"Official source (usrtoday.org)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Before any residential structure, unit, apartment, condo, or townhouse is sold, leased, or otherwise made subject to a change of occupancy for residential purpose, the owner shall obtain a certificate of compliance from the Bureau of Fire Code Enforcement.$t$, $t$968d6e0686700e9322f16bb4602e40b31d5e1f2aa07f1c6b3ed56c726567f16c$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":8,"fee_ok":0,"fee_bad":0,"fee_unchecked":8,"quotes":14,"q_ok":3,"q_bad":0,"q_unchecked":11},"source":"property/data/municipal-requirements/checked/0263.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0263.json$t$, true),
  ($t$0264$t$, $t$Waldwick Borough$t$, $t$BERGEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Compliance (COC), Home Re-Sale or Rental$t$, $j$["Issued by: Borough of Waldwick Building Department (Construction Department)","Contact: Joseph G. Mysliwiec, Construction Official, Zoning Official (Technical Assistant: Nancy Koch, ext:232, nkoch@waldwicknj.gov) · 201-652-5300 ext:233 · jmysliwiec@waldwicknj.gov","Apply: Fee depends on how soon the inspection is needed (more than 14 days out is cheapest). The FAQ suggests applying 2 to 3 weeks before closing. Inspections by appointment, Monday to Friday 10 AM to 12 PM (FAQ). Certificate issued on site at the inspection.","How to apply: Fill out the Certificate of Compliance Home Re-Sale or Rental Application (page 2 of the COC Inspections PDF on the Building page) and pay by check (no cash) at the Building Department, 63 Franklin Turnpike. Call (201) 652-5300 x240 for the final water bill.","Valid for: Six (6) months or until another change in occupancy, whichever comes first","Handrails on steps of four risers or more","Sump pump connections removed from sewer piping","All open permits closed; newly installed furnace, water heater, roof, siding, finished basement, electrical or plumbing work must have had permits","Sidewalks in good condition","Garages converted without permit or approval must be returned to usable garage (written proof required)","Smoke alarms on each floor and CO alarm within 10 feet of sleeping areas; the department witnesses the owner's test of all smoke detectors","Portable fire extinguisher within 10 feet of the kitchen (Building page and FAQ still list it)","Final water meter reading and final water bill before closing","Also: Final water reading: Final water meter reading is due before closing; call (201) 652-5300 x240 for the final water bill.","Also: Sidewalks and sump pump: Sidewalks must be in good condition and sump pump connections must be removed from sewer piping before the COC is issued."]$j$::jsonb, $j$[{"label":"COC inspection, more than 14 days out","amount":"$55.00"},{"label":"COC inspection within 14 days (11 to 14 days)","amount":"$75.00"},{"label":"COC inspection within 10 days (4 to 10 days)","amount":"$150.00"},{"label":"COC inspection within 3 days","amount":"$200.00"},{"label":"Reinspection after a failure or a no-show","amount":"$15.00"}]$j$::jsonb, $t$https://www.waldwicknj.gov/media/departments/building/COC%20Inspections.pdf$t$, $t$https://www.waldwicknj.gov/departments/Building$t$, $j$[{"url":"https://www.waldwicknj.gov/departments/Building","label":"Official source (waldwicknj.gov)"},{"url":"https://www.waldwicknj.gov/media/departments/building/COC%20Inspections.pdf","label":"Official source (waldwicknj.gov)"},{"url":"https://www.waldwicknj.gov/departments/Building/BuildingFAQs","label":"Official source (waldwicknj.gov)"}]$j$::jsonb, $t$State law requires an inspection of the smoke alarm(s), carbon monoxide alarm(s) and portable fire extinguisher(s) before the sale, transfer or rental of residential property can occur$t$, $t$c8cb762488878b3c88051054ca596fe83fe7153acd3a58208b516a7c6d52cde2$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":10,"fee_ok":10,"fee_bad":0,"fee_unchecked":0,"quotes":13,"q_ok":12,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/0264.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0264.json$t$, true),
  ($t$0264$t$, $t$Waldwick Borough$t$, $t$BERGEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Borough of Waldwick Building Department (Certificate of Compliance); Waldwick Fire Prevention Bureau is the fire code agency (town fire bureau)","Contact: 201-652-5300","Apply: More than 14 days out for the lowest fee. Certificate issued on site, valid six months.","How to apply: Smoke and CO alarms are checked in the Building Department's COC inspection; use the COC application and pay by check. Owner or representative must test all detectors while the inspector watches. Have the alarm specifications and installation instructions on hand.","Fire official in the NJ state directory, updated 4/10/2026: Jim O'Connell · (201) 652-5300 · joconnell@waldwicknj.gov","Smoke alarms on each floor; 10-year sealed battery single station alarms (ANSI/UL 217) where battery alarms are used; AC alarms from original construction or rehabilitation may not be replaced with battery alarms","CO alarm within 10 feet of sleeping areas","Portable fire extinguisher (Building page and FAQ still list it; FAQ says within 10 feet of the kitchen)","Owner or representative performs the test of every smoke detector while the department watches","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"COC inspection, more than 14 days out","amount":"$55.00"},{"label":"COC inspection within 14 days (11 to 14 days)","amount":"$75.00"},{"label":"COC inspection within 10 days (4 to 10 days)","amount":"$150.00"},{"label":"COC inspection within 3 days","amount":"$200.00"},{"label":"Reinspection after a failure or a no-show","amount":"$15.00"}]$j$::jsonb, $t$https://www.waldwicknj.gov/media/departments/building/COC%20Inspections.pdf$t$, $t$https://www.waldwicknj.gov/departments/Building$t$, $j$[{"url":"https://www.waldwicknj.gov/media/departments/building/COC%20Inspections.pdf","label":"Official source (waldwicknj.gov)"},{"url":"https://www.waldwicknj.gov/media/departments/building/Fire_Prevention_Bureau.pdf","label":"Official source (waldwicknj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$State law requires and inspection of the smoke alarm(s) and carbon monoxide alarm(s) before the sale, transfer or rental of residential property can occur$t$, $t$c70162f20fb35d7b9b2d77d285c3e3a73b6a3c2846e0a1e4af0ba4989dda8640$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":10,"fee_ok":10,"fee_bad":0,"fee_unchecked":0,"quotes":13,"q_ok":12,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/0264.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0264.json$t$, true),
  ($t$0265$t$, $t$Wallington Borough$t$, $t$BERGEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Continued Occupancy (CCO)$t$, $j$["Issued by: Borough of Wallington Code Enforcement Officer","Contact: 973-777-0318 ext. 207 · codeenforcement@wallingtonnj.org","Apply: By code, the certificate is issued or rejected within 10 business days after the application is received.","How to apply: Apply to the Borough Code Enforcement Officer and pay the fee with the application. Code Enforcement: 973-777-0318 ext. 207, codeenforcement@wallingtonnj.org, Municipal Building, 159-161 Maple Ave, Wallington, NJ 07057. No application form is posted online; call or email for it.","Valid for: 60 days after issuance, and good for one transfer only","No sale or transfer of title of any structure or unit until a certificate of continued occupancy is obtained","Inspection by the Code Enforcement Officer (the Tax Assessor may come along to update property records) to confirm the home complies with all Borough ordinances","The certificate states the property may continue to be used as before and lists the number and designation of the units","Not required for new construction if the original CO was issued within 18 months of the transfer","Existing lawful tenants may stay, but the transfer cannot close until the CCO is obtained","Also: Tax assessor visit: The Tax Assessor or a designee may come along on the CCO inspection to update property record cards."]$j$::jsonb, $j$[{"label":"Certificate of continued occupancy, transfer, per unit","amount":"$25"}]$j$::jsonb, null, $t$https://www.wallingtonnj.org/1419/Property-Maintenance-Code-Enforcement$t$, $j$[{"url":"https://ecode360.com/15121364","label":"Official source (ecode360.com)"},{"url":"https://www.wallingtonnj.org/1389/Property-Maintenance","label":"Official source (wallingtonnj.org)"}]$j$::jsonb, $t$No person, persons or organization of persons shall sell or transfer title to any structure or unit in a structure or relet or release any structure, portion of a structure or unit in a structure until such person, persons or organization of persons shall have first obtained a certificate of continued occupancy$t$, $t$a59acc37b17a9428569e94269284c82566710737d502053a43e53e6a53b6f123$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":0,"fee_bad":0,"fee_unchecked":5,"quotes":11,"q_ok":3,"q_bad":0,"q_unchecked":8},"source":"property/data/municipal-requirements/checked/0265.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0265.json$t$, true),
  ($t$0265$t$, $t$Wallington Borough$t$, $t$BERGEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Wallington Fire Department, Bureau of Fire Prevention (Bureau of Fire Safety) (town fire bureau)","Contact: Edward Tanderis, Fire Official · 973-777-0318 ext. 215 · wfd207fo@aol.com","Apply: Expedited inspections cost extra: within 4 business days of the request or within 5 to 7 business days.","How to apply: Contact the Fire Official at the Bureau of Fire Prevention, 973-777-0318 ext. 215 (email wfd207fo@aol.com), to request the inspection and pay the fee. No online form is posted.","Fire official in the NJ state directory, updated 8/12/2025: Edward J Tanderis · (973) 777-0318 · WFD207FO@aol.com","Smoke detector on each level of the dwelling, including basements (not attics or crawl spaces)","Smoke detector and carbon monoxide alarm outside each separate sleeping area, within 10 feet of all bedrooms","At least one carbon monoxide detector on each level of the building","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke detector / CO certificate of compliance before sale (code)","amount":"$75"},{"label":"Reinspection after violations (first reinspection free)","amount":"$50"},{"label":"Expedited inspection within 4 business days of request (added fee)","amount":"$100"},{"label":"Expedited inspection within 5 to 7 business days of request (added fee)","amount":"$50"}]$j$::jsonb, null, $t$https://www.wallingtonnj.org/1390/Fire-Prevention$t$, $j$[{"url":"https://ecode360.com/15121584","label":"Official source (ecode360.com)"},{"url":"https://www.wallingtonnj.org/1390/Fire-Prevention","label":"Official source (wallingtonnj.org)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Any property containing two or more dwelling units must have at least one smoke detector on each level of the dwelling, including basements, excluding attic or crawl space, and a smoke detector and carbon monoxide alarm outside each separate sleeping area within 10 feet of all bedrooms.$t$, $t$23d40d31c5f5147b63113fefd91d99a0b720fa0ab8449e66345724c42c946257$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":0,"fee_bad":0,"fee_unchecked":5,"quotes":11,"q_ok":3,"q_bad":0,"q_unchecked":8},"source":"property/data/municipal-requirements/checked/0265.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0265.json$t$, true),
  ($t$0266$t$, $t$Washington Township$t$, $t$BERGEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Continued Occupancy (CCO)$t$, $j$["Issued by: Township of Washington Building Department (Chief Construction Official)","Contact: Darius Pokoj, Construction Official / Building Inspector · 201-666-0462 · building@twpofwashington.us","Apply: Code says the Construction Official inspects within 10 days of receiving a complete application and fee.","How to apply: Contact the Building Department (Room 4, lower level; phone 201-666-0462; building@twpofwashington.us) for the CCO application form. The same office schedules the smoke detector inspection (call the Building Department, not Fire Prevention). Inspection requests are taken online or in writing, not by phone.","General inspection of the visible parts of the principal building: no apparent zoning, construction or health violations and no open permits","If violations cannot be fixed before closing, the applicant certifies they will be cured by a set date and gets a temporary certificate; $100 per day fine if not cured by then","Not required if the principal building will not be occupied (submit a certification to the Construction Official)","Smoke/CO/fire extinguisher certificate is a separate inspection (see fire certificate)","Also: Open permits: The CCO inspection checks for open permits; close them before applying.","Also: Vacant property / not occupied: A CCO is not required when the principal building will not be occupied, but the applicant must submit a certification to the Chief Construction Official."]$j$::jsonb, $j$[{"label":"Certificate of continued occupancy application, includes initial inspection and one reinspection (Township code 212-27D)","amount":"$100"},{"label":"Each later CCO inspection (Township code 212-27D)","amount":"$100"},{"label":"Inspection of a home for resale/tenancy change, initial inspection and first reinspection (Township code 212-9N)","amount":"$200"},{"label":"Each additional reinspection for resale/tenancy change (Township code 212-9N)","amount":"$100"},{"label":"Temporary certificate of occupancy (Township code 212-27D)","amount":"$100"}]$j$::jsonb, null, $t$https://www.twpofwashington.us/page/building-engineering$t$, $j$[{"url":"https://www.twpofwashington.us/page/bureau-of-fire-prevention","label":"Official source (twpofwashington.us)"},{"url":"https://ecode360.com/31164079","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/7974577","label":"Official source (ecode360.com)"},{"url":"https://www.twpofwashington.us/page/building-engineering","label":"Official source (twpofwashington.us)"}]$j$::jsonb, $t$Please remember to contact the Building Department as a Certificate of Continued Occupancy (CCO) is required prior to the sale of any house.$t$, $t$5dffa30516e9e644084553dc57ec7f3efc6a7f1733e0a21527fa4676114cd73e$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":11,"fee_ok":0,"fee_bad":0,"fee_unchecked":11,"quotes":13,"q_ok":1,"q_bad":0,"q_unchecked":12},"source":"property/data/municipal-requirements/checked/0266.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0266.json$t$, true),
  ($t$0266$t$, $t$Washington Township$t$, $t$BERGEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Township of Washington Bureau of Fire Prevention (inspection scheduled through the Building Department) (town fire bureau)","Contact: Thomas Derienzo Jr, Fire Official (NJ DCA fire directory) · 201-666-0462 · fp@twpofwashington.us","Apply: Smoke detector inspections Tuesday and Wednesday 2:30 to 4:00 pm. Lowest fee when 10 or more days before closing.","How to apply: Call the Building Department at 201-666-0462 to schedule the smoke/CO inspection (the Township says to call the Building Department, not Fire Prevention). Have the extinguisher, smoke and CO alarms in place to avoid a re-inspection fee.","Fire official in the NJ state directory, updated 3/2/2026: Thomas Derienzo Jr · (201) 664-4404 · fp@twpofwashington.us","2A:10BC fire extinguisher mounted on the kitchen wall, within 10 feet of the kitchen and not behind any door (Township page still lists it)","At least one smoke detector on each level of the home","One carbon monoxide detector within 10 feet of any bedroom (plug-in or battery)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke, CO and fire extinguisher compliance, 10 days or more before closing (Township page)","amount":"$45.00"},{"label":"Smoke/CO re-inspection (Township page)","amount":"$50.00"},{"label":"Smoke/CO/extinguisher certificate, more than 10 business days before closing (Township code 212-9N)","amount":"$45"},{"label":"Smoke/CO/extinguisher certificate, 4 to 10 business days before closing (Township code 212-9N)","amount":"$90"},{"label":"Smoke/CO/extinguisher certificate, 3 or fewer business days before closing (Township code 212-9N)","amount":"$161"},{"label":"Smoke/CO/extinguisher reinspection (Township code 212-9N)","amount":"$50"}]$j$::jsonb, null, $t$https://www.twpofwashington.us/page/bureau-of-fire-prevention$t$, $j$[{"url":"https://www.twpofwashington.us/page/bureau-of-fire-prevention","label":"Official source (twpofwashington.us)"},{"url":"https://www.twpofwashington.us/page/building-engineering","label":"Official source (twpofwashington.us)"},{"url":"https://ecode360.com/7657993","label":"Official source (ecode360.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://ecode360.com/7974577","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$Upon sale of your home, an inspection to ensure that your home is compliant with NJ State Fire Codes with respect to Carbon Monoxide and Smoke Detector inspections must be performed prior to closing.$t$, $t$906859583f988d73cb0d390f035024490de6d3b3d201672cc0bcef5d8d117e9b$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":11,"fee_ok":0,"fee_bad":0,"fee_unchecked":11,"quotes":13,"q_ok":1,"q_bad":0,"q_unchecked":12},"source":"property/data/municipal-requirements/checked/0266.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0266.json$t$, true),
  ($t$0267$t$, $t$Westwood Borough$t$, $t$BERGEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Zoning Certificate of Compliance for Residential Sale and Rental$t$, $j$["Issued by: Borough of Westwood Office of Construction & Zoning (Building Department)","Contact: Armand Marini, Zoning Officer (ext. 305 at 201-664-7100; amarini@westwoodnj.gov) · 201-664-5900","Apply: Fee depends on how far away the closing is when the form is submitted: over 2 weeks for the lower fee. The inspection is not scheduled until payment is received.","How to apply: Fill out the Zoning Certificate of Compliance Application / Smoke Alarm and Carbon Monoxide Detector Application and submit it with a check or money order payable to Borough of Westwood to the Westwood Building Department, 101 Washington Avenue, Westwood, NJ 07675. The application cannot be processed or the inspection scheduled without payment.","Physical safety inspection plus a block and lot file review to confirm the home is used as designed under zoning (for example one-family vs. two-family status)","Exterior: level sidewalks and walkways with no trip hazards; no debris or overgrowth; pool barrier with proper height and self-closing, outward-opening gate with lock 54 inches high; garage door opener plugged directly into an outlet","Interior: all utilities on; no keyed bedroom locks; thumb-turn deadbolts inside; working GFCI outlets; sound fireplace firebox; furnace emergency switch at top of basement stairs; secure boiler/water heater flue; relief valve pipe within 6 inches of the floor; leak-free aboveground oil tanks; handrails on stairs with more than 4 risers and guards over 30 inches","Smoke and carbon monoxide alarms to the Borough checklist (see fire certificate)","Sump pumps must discharge to a storm sewer or street gutter line, not the sanitary sewer, roadway or sidewalk","House numbers clearly visible from the street","All building permits must be closed; the CCO inspection will not be scheduled with any open permits","Rentals must attach a Lead Safe or Lead Free certificate","Also: Open building permits: All building permits must be closed by scheduling final inspections; the CCO inspection will not be scheduled and certificates will not be issued with open permits.","Also: Sump pump discharge: Sump pumps must discharge to a storm sewer or the street gutter line, not the sanitary sewer, roadway or sidewalk.","Also: Sidewalks: Sidewalks and walkways must be even, free of trip hazards and in good repair for the CCO inspection."]$j$::jsonb, $j$[{"label":"Zoning certificate of compliance / smoke and CO inspection, closing more than 2 weeks away","amount":"$100.00"},{"label":"Closing less than 2 weeks away","amount":"$150.00"},{"label":"Re-inspection","amount":"$50.00"}]$j$::jsonb, $t$https://www.westwoodnj.gov/DocumentCenter/View/2800/Zoning-Certificate-of-Compliance-for-Residential-Sale-and-Rental-CCO--pdf$t$, $t$https://www.westwoodnj.gov/$t$, $j$[{"url":"https://www.westwoodnj.gov/DocumentCenter/View/2800/Zoning-Certificate-of-Compliance-for-Residential-Sale-and-Rental-CCO--pdf","label":"Official source (westwoodnj.gov)"},{"url":"https://www.westwoodnj.gov/","label":"Official source (westwoodnj.gov)"},{"url":"https://www.westwoodnj.gov/250/Zoning-Office","label":"Official source (westwoodnj.gov)"},{"url":"https://ecode360.com/13846898","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$If you are selling your home or have a new tenant moving into your rental property, this is the form you need!$t$, $t$ce516389af7dcac217c94bc407938ef8f0d4ad64f3e1bd660b549744b2c4a3a7$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":3,"fee_bad":0,"fee_unchecked":1,"quotes":13,"q_ok":9,"q_bad":0,"q_unchecked":4},"source":"property/data/municipal-requirements/checked/0267.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0267.json$t$, true),
  ($t$0267$t$, $t$Westwood Borough$t$, $t$BERGEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Westwood Fire Prevention Bureau (Fire Inspector), through the Building Department's combined CCO application (town fire bureau)","Contact: Darren Blankenbush, Fire Marshal / OEM Coordinator · 201-664-7100 ext. 308 · dblankenbush@westwoodnj.gov","Apply: Same as the CCO: lower fee when the closing is more than 2 weeks away. The Borough Code says the inspection is made within 10 business days of the application.","How to apply: Use the combined Zoning Certificate of Compliance / Smoke Alarm and Carbon Monoxide Detector Application filed with the Building Department; the Borough Code says applications go to the Building Department with a copy to the Fire Prevention Bureau, and the separate $25 smoke fee is waived when done with the CO inspection.","Fire official in the NJ state directory, updated 7/28/2026: Darren Blankenbush · (201) 664-7100 · dblankenbush@westwoodnj.gov","Smoke alarms per build date: before 1977 sealed 10-year battery alarms on all levels; 1977 to 1978 electric on sleeping levels; 1978 to 1983 electric on sleeping and basement levels; 1983 to 1984 electric on all levels; 1984 to 1991 electric and interconnected; March 1991 to now electric, interconnected, with battery backup on all levels and inside each bedroom","Battery alarms must be 10-year sealed; hardwired alarms cannot be replaced with battery alarms; no alarm older than 10 years; UL listed with a test button; not painted","Smoke alarm near every bedroom door; basement and non-sleeping levels near the stairway up; two-family common halls and stairs need an alarm at each landing","Carbon monoxide alarm on each sleeping level, in the hallway near every bedroom door, in homes with fuel-burning appliances or an attached garage","Central station monitored systems need certification from a licensed NJ fire protection contractor before the Borough inspection","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke detector compliance certificate (Borough Code 166, waived when done with the CO inspection)","amount":"$25"}]$j$::jsonb, $t$https://www.westwoodnj.gov/DocumentCenter/View/2800/Zoning-Certificate-of-Compliance-for-Residential-Sale-and-Rental-CCO--pdf$t$, $t$https://www.westwoodnj.gov/167/Fire-Prevention-Bureau$t$, $j$[{"url":"https://www.westwoodnj.gov/167/Fire-Prevention-Bureau","label":"Official source (westwoodnj.gov)"},{"url":"https://ecode360.com/13847160","label":"Official source (ecode360.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Conduct required residential smoke and carbon monoxide detector inspections for all home sales as required under the NJ Uniform Fire Code.$t$, $t$92c1901119f3c06b38a52212e5e092ea8724ee0e8a1db009807da2e0dc175a3e$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":3,"fee_bad":0,"fee_unchecked":1,"quotes":13,"q_ok":9,"q_bad":0,"q_unchecked":4},"source":"property/data/municipal-requirements/checked/0267.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0267.json$t$, true),
  ($t$0268$t$, $t$Woodcliff Lake Borough$t$, $t$BERGEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Resale Certificate / Certificate of Continued Occupancy (CCO), Residential$t$, $j$["Issued by: Borough of Woodcliff Lake Building Department (Construction/Zoning Official), with Fire Prevention","Contact: Clairesse Aquilino, Technical Assistant, Building Department (Construction Code Official: Mark Berninger, ext 213, mberninger@wclnj.com) · 201-391-4977 ext. 210 · caquilino@wclnj.com","Apply: Submit the form no less than 20 days before the closing date. The Borough inspects within 10 business days after the application is complete and permits are verified closed.","How to apply: Complete the Application - Certificate of Continued Occupancy - Residential (posted under Fire Prevention forms) and submit it to the Borough of Woodcliff Lake, 188 Pascack Road, at least 20 days before closing, with the fee. The Construction/Zoning Official calls the contact on the form to schedule. Call the Building Department to confirm permits are closed before the inspection.","Valid for: The application form says 90 days from issuance; the Borough code (Section 135-3, amended 2024) says six months","All construction permits issued must be closed out before the inspection","Legible house numbers clearly visible from the street","Sump pumps not piped into the sanitary sewer system and discharged properly","Boilers, hot water heaters and water softeners must have had the required permits","Front door dead bolts keyless on the interior side","Damaged or uneven public sidewalks and aprons must be replaced (permit required)","Smoke detector, carbon monoxide detector and portable fire extinguisher installed (code and form still list the extinguisher)","Secondary power sources (generators, solar, batteries) need a printed CAUTION: MULTIPLE SOURCES OF POWER label within 18 inches of the main panel and the meter","Monitored or low-voltage alarm systems must pass an alarm test with monitoring active","Also: Open permits: All construction permits must be closed before the resale inspection; boilers, hot water heaters and water softeners must have had permits.","Also: Sump pump discharge: Sump pumps may not be piped into the sanitary sewer system.","Also: Sidewalks and aprons: Damaged or uneven public sidewalks and driveway aprons must be replaced (permit required) as part of the resale certificate."]$j$::jsonb, $j$[{"label":"Certificate of Continued Occupancy / Resale Certificate, single family (includes smoke and CO detector compliance)","amount":"$100"},{"label":"Certificate of Continued Occupancy / Resale Certificate, two-family","amount":"$150"},{"label":"Re-inspection, if needed","amount":"$50.00"},{"label":"Certificate of Continuing Occupancy, one-family homes (Borough fee code, Chapter 163)","amount":"$100"}]$j$::jsonb, $t$https://wclnj.com/meetings/forms-documents/board-department-forms-documents/fire-prevention/15-cco-application/file$t$, $t$https://wclnj.com/departments/construction$t$, $j$[{"url":"https://ecode360.com/37183018","label":"Official source (ecode360.com)"},{"url":"https://wclnj.com/meetings/meeting-documents/mayor-council-meeting/ordinances/2024/938-24-14-ordinance-amend-chapter-135-cco-resale-certificate/file","label":"Official source (wclnj.com)"},{"url":"https://wclnj.com/meetings/forms-documents/board-department-forms-documents/fire-prevention/15-cco-application/file","label":"Official source (wclnj.com)"},{"url":"https://wclnj.com/departments/construction","label":"Official source (wclnj.com)"},{"url":"https://ecode360.com/11417764","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$No person shall occupy or use any portion of a residential building after such building or portion thereof has been vacated or sold, until the owner or landlord thereof shall have applied for and secured a resale certificate.$t$, $t$77561a31f0d4c89436c2ee2a60c352e7b173a43b120de7c930c3994aa4e6ac81$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":7,"fee_ok":2,"fee_bad":0,"fee_unchecked":5,"quotes":17,"q_ok":6,"q_bad":0,"q_unchecked":11},"source":"property/data/municipal-requirements/checked/0268.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0268.json$t$, true),
  ($t$0268$t$, $t$Woodcliff Lake Borough$t$, $t$BERGEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Woodcliff Lake Fire Prevention (Borough of Woodcliff Lake), inspected as part of the Resale Certificate / CCO (town fire bureau)","Contact: Raphael-Jose Maurrasse, Fire Official · 201-391-4977 x 279 · fireprevention@wclnj.com","Apply: Submit at least 20 days before closing; inspection within 10 business days of a complete application.","How to apply: Covered by the Resale Certificate / CCO application filed with the Borough at 188 Pascack Road. Fire Prevention can be reached at 201-391-4977 ext. 200 / 225.","Fire official in the NJ state directory (town), updated 2/19/2026: Raphael-Jose Maurrass · (201) 391-4977 · rmaurrasse@wclnj.com","Smoke detectors UL approved, 10-year sealed battery, on each level including the basement, and within 10 feet of each sleeping area entrance or inside each sleeping area; hardwired alarms must be replaced with hardwired","Two-family homes also need alarms in common stairwells and hallways, outside each doorway, in the main living area, and at the front of the basement stairs","Carbon monoxide detectors within 10 feet of each sleeping area entrance or inside each sleeping area; the form says CO detectors older than 5 years must be replaced","All detectors must be less than 10 years old","Fire extinguisher 2A:10B:C, under 10 pounds, within 10 feet of the kitchen, with bracket, dated or tagged within 12 months (form still lists it)","Secondary power source label within 18 inches of the main electrical panel and the meter, if applicable","Central or low-voltage alarm systems need a passing alarm test and active monitoring","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Certificate of Continued Occupancy / Resale Certificate, single family (includes smoke and CO detector compliance)","amount":"$100"},{"label":"Certificate of Continued Occupancy / Resale Certificate, two-family","amount":"$150"},{"label":"Re-inspection, if needed","amount":"$50.00"}]$j$::jsonb, $t$https://wclnj.com/meetings/forms-documents/board-department-forms-documents/fire-prevention/15-cco-application/file$t$, $t$https://wclnj.com/departments/construction$t$, $j$[{"url":"https://ecode360.com/13530546","label":"Official source (ecode360.com)"},{"url":"https://wclnj.com/meetings/forms-documents/board-department-forms-documents/fire-prevention/15-cco-application/file","label":"Official source (wclnj.com)"},{"url":"https://wclnj.com/departments/construction","label":"Official source (wclnj.com)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Upon the sale of a one- or two-family residence or the rental, lease or transfer of any dwelling unit, the seller, landlord or transferor is required to obtain from the Borough of Woodcliff Lake a smoke detector compliance certificate with the provisions of this article.$t$, $t$a8db9ceaecd5880accbb5ef860f1a7f599cc72b9508767be8cc144e47ea93a77$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":7,"fee_ok":2,"fee_bad":0,"fee_unchecked":5,"quotes":17,"q_ok":6,"q_bad":0,"q_unchecked":11},"source":"property/data/municipal-requirements/checked/0268.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0268.json$t$, true),
  ($t$0269$t$, $t$Wood-Ridge Borough$t$, $t$BERGEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Continued Occupancy - Residential (Certificate of Zoning, Smoke Detector, Carbon Monoxide, Fire Extinguisher Compliance)$t$, $j$["Issued by: Borough of Wood-Ridge Zoning Official and Fire Prevention Official (one combined application)","Contact: Rich Pronti, Zoning Officer (Construction Code Official: Chris Cunningham) · 201-939-5188 · construction@woodridgenj.gov","How to apply: Fill out the Certificate of Continued Occupancy / Zoning Compliance - Residential application (seller, buyer, attorneys, realtor and a room inventory), attach the Certification of Payment of Taxes signed by the Tax Collector, and file it with cash or a check to the Borough of Wood-Ridge at the Construction Code Office, Municipal Building, 85 Humboldt Street, second floor. Call 201-939-5188 for inspections.","No open permits; owner certifies permits were issued for all alterations","Room inventory by floor, which the Zoning Officer compares with tax records, permits and variances","Smoke detector on each floor including the basement (and finished attic), within 10 feet of each bedroom, attached with screws","Carbon monoxide detector within 10 feet of each bedroom","ABC fire extinguisher (at least 2A:10B:C, no more than 10 lbs) in or within 10 feet of the kitchen (form still lists it)","Certification of Payment of Taxes signed by the Wood-Ridge Tax Collector","Payment by cash or check to the Borough of Wood-Ridge; credit cards not accepted","Also: Paid taxes: The CCO application must include a Certification of Payment of Taxes signed by the Wood-Ridge Tax Collector.","Also: Open permits: No open permits may exist for the property; the owner certifies that permits were issued for all alterations."]$j$::jsonb, $j$[{"label":"Single family","amount":"$75"},{"label":"Two family","amount":"$100"},{"label":"Owner-occupied transfer of one-family dwelling (Borough code)","amount":"$75"},{"label":"Owner-occupied transfer of two-family dwelling (Borough code)","amount":"$100"}]$j$::jsonb, $t$https://www.woodridgenj.gov/_Content/pdf/forms/CO-CERTIFICATE-RESIDENTIAL.pdf$t$, $t$https://www.woodridgenj.gov/Departments/construction-department$t$, $j$[{"url":"https://www.woodridgenj.gov/_Content/pdf/forms/CO-CERTIFICATE-RESIDENTIAL.pdf","label":"Official source (woodridgenj.gov)"},{"url":"https://ecode360.com/28840411","label":"Official source (ecode360.com)"},{"url":"https://www.woodridgenj.gov/forms","label":"Official source (woodridgenj.gov)"},{"url":"https://www.woodridgenj.gov/Departments/construction-department","label":"Official source (woodridgenj.gov)"}]$j$::jsonb, $t$The seller is required by order of Borough Ordinance #530-88 and N.J.A.C. 570-4.19 to obtain$t$, $t$f5d80b8a3d249d9bb5d261018b8f6760740ff203f82cefdd2ec0b5f6970892fe$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":2,"fee_bad":0,"fee_unchecked":2,"quotes":15,"q_ok":10,"q_bad":0,"q_unchecked":5},"source":"property/data/municipal-requirements/checked/0269.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0269.json$t$, true),
  ($t$0269$t$, $t$Wood-Ridge Borough$t$, $t$BERGEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Wood-Ridge Fire Prevention Bureau (smoke/CO inspected under the Borough's combined Certificate of Continued Occupancy - Residential) (town fire bureau)","Contact: John J. Kurz, Fire Official · (201) 460-0282 · jkurz@njwoodridge.org","How to apply: Use the Borough's Certificate of Continued Occupancy - Residential application; it is a combined zoning and smoke/CO/fire extinguisher application signed off by the Zoning Official and the Fire Prevention Official. No separate smoke certificate fee is published.","Fire official in the NJ state directory, updated 2/27/2026: John J Kurz · (201) 460-0282 · jkurz@njwoodridge.org","Smoke detector on each floor including the basement (and finished attic), within 10 feet of each bedroom on that floor","Carbon monoxide detector within 10 feet of each bedroom","Detectors attached to the ceiling or wall with screws; double-sided tape is not acceptable","ABC fire extinguisher at least 2A:10B:C, no more than 10 lbs, in or within 10 feet of the kitchen (form still lists it)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[]$j$::jsonb, $t$https://www.woodridgenj.gov/_Content/pdf/forms/CO-CERTIFICATE-RESIDENTIAL.pdf$t$, $t$https://www.woodridgenj.gov/Departments/fire-prevention-bureau$t$, $j$[{"url":"https://www.woodridgenj.gov/_Content/pdf/forms/CO-CERTIFICATE-RESIDENTIAL.pdf","label":"Official source (woodridgenj.gov)"},{"url":"https://www.woodridgenj.gov/Departments/fire-prevention-bureau","label":"Official source (woodridgenj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Certificate of Zoning, Smoke Detector, Carbon Monoxide, Fire Extinguisher$t$, $t$197f48f3cf691a85b8a9b2b9418330dad2d5c80d3eb071cf6d45bc0b6207d49f$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":2,"fee_bad":0,"fee_unchecked":2,"quotes":15,"q_ok":10,"q_bad":0,"q_unchecked":5},"source":"property/data/municipal-requirements/checked/0269.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0269.json$t$, true),
  ($t$0270$t$, $t$Wyckoff Township$t$, $t$BERGEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Approval for Resale (also called Continued Certificate of Occupancy)$t$, $j$["Issued by: Township of Wyckoff Construction Official (Building, Zoning and Property Maintenance), with inspections by the Tax Assessor, Water Department and Board of Health as needed","Contact: (201) 891-7000 ext. 3060","Apply: Issued or denied within 10 days of filing. The fee is lowest when the request is received more than 10 business days before the change of occupancy. The Township suggests planning the inspection at least two weeks before closing; inspections are Monday to Friday, 10am to 3pm, and the resale and smoke inspections are usually set for the same date.","How to apply: Apply online with the Township's Application for Certificate of Approval at Resale (SeamlessDocs form linked from the Building Department Forms and Applications page), choose septic or sewer and whether the buyer will occupy, and pay the inspection fee. Apply for the smoke detector certificate separately (GovPilot) and pick the same inspection date for both. Questions: Building, Zoning and Property Maintenance, 340 Franklin Avenue, (201) 891-7000 ext. 3060.","Valid for: 120 days from the date of issuance","Smoke and carbon monoxide detectors installed","Handrails on all stairways with three or more risers","Sump pumps proven not to discharge into the sanitary sewer","All open construction permits closed, and permits on file for newly installed items (furnace, water heater, roof, siding, finished basement, kitchen and bath, electrical and plumbing work)","Sidewalks and driveways in the public right-of-way in good condition","House numbers visible from the street","General compliance with the property maintenance and zoning codes","Homes not on municipal sewer: septic system tested and report reviewed by the Construction Official, Township Engineer and Board of Health; cesspools must comply with N.J.A.C. 7:9A-3.16","An adult must be present to give the inspector access; all inspection correspondence is by email","Also: Septic system test (homes not on municipal sewer): Homes not served by municipal sewer must have the septic system tested and the report reviewed by the Construction Official, Township Engineer and Board of Health before the resale certificate; cesspools must be dealt with under N.J.A.C. 7:9A-3.16.","Also: Sump pump discharge: Sump pumps must be proven not to discharge into the sanitary sewer.","Also: Sidewalks and driveway aprons: Sidewalks and driveways in the public right-of-way must be in good condition for the resale certificate.","Also: Open permits: All open construction permits must be closed, and recent work (furnace, water heater, roof, siding, finished basement, kitchen, bath, electrical, plumbing) must have had permits.","Also: Water Department and Tax Assessor inspection: The resale inspection may include the Tax Assessor and Water Department (for example a final meter check); confirm with the Township."]$j$::jsonb, $j$[{"label":"Certificate of approval for resale, 1 or 2 family, request received more than 10 business days before the change of occupancy","amount":"$160"},{"label":"Certificate of approval for resale, 1 or 2 family, request received 4 to 10 business days before","amount":"$240"},{"label":"Certificate of approval for resale, 1 or 2 family, request received fewer than 4 business days before","amount":"$300"},{"label":"Reinspection fee","amount":"$75"}]$j$::jsonb, $t$http://wyckoffnj.seamlessdocs.com/f/app_for_cert_of_approval_for_resale/$t$, $t$https://www.wyckoffnj.gov/building-zoning-property-maintenance/faq/what-required-when-i-sell-or-rent-property$t$, $j$[{"url":"https://ecode360.com/16124642","label":"Official source (ecode360.com)"},{"url":"https://www.wyckoffnj.gov/building-zoning-property-maintenance/faq/what-required-when-i-sell-or-rent-property","label":"Official source (wyckoffnj.gov)"},{"url":"http://wyckoffnj.seamlessdocs.com/f/app_for_cert_of_approval_for_resale/","label":"Official source (wyckoffnj.seamlessdocs.com)"}]$j$::jsonb, $t$Transfer of title to real property containing a building, structure of any kind, or sidewalks.$t$, $t$3c8a7c1f9beac9a665005c45ff0eeb0cbaaebdbed04bce22417716d2ca835143$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":8,"fee_ok":4,"fee_bad":0,"fee_unchecked":4,"quotes":14,"q_ok":10,"q_bad":0,"q_unchecked":4},"source":"property/data/municipal-requirements/checked/0270.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0270.json$t$, true),
  ($t$0270$t$, $t$Wyckoff Township$t$, $t$BERGEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Wyckoff Fire Prevention Bureau (town fire bureau)","Contact: EJ Lawler, Fire Official · (201) 891-7000 ext. 2030 · elawler@wyckoffnj.gov","Apply: Fee depends on business days between scheduling and the inspection date: 10 or more business days for the lowest fee. Fees must be paid before the inspection.","How to apply: Apply and pay online with the Township's Smoke Alarm application (GovPilot), or pay in person at Town Hall, 340 Franklin Avenue. Schedule the same date as the resale inspection.","Fire official in the NJ state directory, updated 2/19/2026: Edward Lawler · (201) 891-7000 · ejlawler@wyckoffnj.gov","One smoke detector in the basement and on each floor (unfinished attics excluded), and within 10 feet of the doorway of bedrooms on any floor with bedrooms","Battery smoke detectors must be 10-year sealed lithium units; all smoke detectors less than 10 years old and ANSI/UL 217 listed; hardwired detectors stay hardwired","Carbon monoxide detectors within 10 feet of the bedrooms (outside the bedroom), less than 10 years old, UL 2034 listed","Low voltage or monitored alarm systems must be tested/serviced first, with a report from the alarm company available at the inspection","Fire extinguisher 2A:10BC, no more than 10 lbs, listed, labeled, charged and operable, brand new with receipt or tagged within 12 months, present on the main level with mounting hardware and instructions left for the new owner (form still lists it)","Secondary power source warning label (for example 'CAUTION: MULTIPLE SOURCES OF POWER') within 18 inches of the main electrical panel and meter if the home has a generator, solar panels or battery storage","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke, CO and fire extinguisher inspection scheduled 10 business days or more before the inspection date","amount":"$90.00"},{"label":"Inspection scheduled 4 to 10 business days before","amount":"$145.00"},{"label":"Inspection scheduled 3 business days or less before","amount":"$205.00"},{"label":"Re-inspection","amount":"$75.00"}]$j$::jsonb, $t$https://main.govpilot.com/web/public/843a754f-bf9_Smoke-Alarm-Township-of-Wyckoff?uid=6985&ust=NJ&pu=1&id=0$t$, $t$https://www.wyckoffnj.gov/fire-prevention/pages/smoke-detector-carbon-monoxide-detector-fire-extinguisher-compliance$t$, $j$[{"url":"https://www.wyckoffnj.gov/fire-prevention/pages/smoke-detector-carbon-monoxide-detector-fire-extinguisher-compliance","label":"Official source (wyckoffnj.gov)"},{"url":"https://www.wyckoffnj.gov/sites/g/files/vyhlif12106/f/pages/smoke_requirments_june_2026.pdf","label":"Official source (wyckoffnj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$INSPECTION FEES MUST BE PAID PRIOR TO INSPECTION ONLINE OR IN PERSON$t$, $t$46c920b5640552c80141532654aff3d7bea87d91dc454527e7e8474764eca27b$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":8,"fee_ok":4,"fee_bad":0,"fee_unchecked":4,"quotes":14,"q_ok":10,"q_bad":0,"q_unchecked":4},"source":"property/data/municipal-requirements/checked/0270.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/0270.json$t$, true),
  ($t$1401$t$, $t$Boonton$t$, $t$MORRIS$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Compliance (C of C, also called the 'Smoke Certificate')$t$, $j$["Issued by: Town of Boonton Code Enforcement / Housing (Code Official)","Contact: 973-402-9410 ext. 625 or 626","Apply: Apply at least two weeks before closing to avoid a late fee (inspection packet says no less than 10 working days); inspections are Tuesdays 9:00 AM to 11:00 AM; a final certificate takes at least 3 working days after a clean inspection.","How to apply: Submit the Certificate of Compliance Application - Residential (Forms, Permits & Applications page or the SDL Portal, choosing Boonton Town not Township) with the fee to Town Hall, 100 Washington Street, Boonton, NJ 07005. Payment by cash, check or credit card. The fee includes the first inspection and one re-inspection.","Valid for: Temporary C of C: violations must be corrected within 30 days","Completed application and fee paid before an inspection is scheduled","Full interior and exterior property maintenance inspection, including room measurements for sleeping capacity","All open construction permits inspected and approved before the C of C is issued","Exterior: sidewalks, drainage, weeds, accessory structures, unlicensed vehicles, siding, roof, gutters, windows, doors","Interior: stairs, handrails and guards, bathroom venting, dryer exhaust, plumbing, heating, electrical (GFCI), means of egress, sanitation and pests","Smoke detectors (10-year sealed battery units), carbon monoxide detectors and fire extinguishers","If violations remain, a Temporary C of C may be issued with the buyer's letter agreeing to correct them within 30 days","Also: Open construction permits: All outstanding construction permits must be inspected and approved before the Certificate of Compliance is issued. Work done without permits needs a retro permit.","Also: Sidewalks and exterior: The inspection covers sidewalks, drainage, grass and weeds, accessory structures and the building exterior.","Also: Temporary C of C buyer's certification: If the seller does not fix all violations, the buyer signs a certification to correct them within 30 days of the Temporary C of C."]$j$::jsonb, $j$[{"label":"Certificate of Compliance, residential detached single family (Housing page)","amount":"$100"},{"label":"Certificate of Compliance, two family or multi-family (Housing page)","amount":"$100 first unit + $50 each additional unit"},{"label":"Late fee, request fewer than 5 business days before the sale (Housing page; the application says fewer than 4)","amount":"$75.00"},{"label":"Additional re-inspections after the one included re-inspection (application form)","amount":"$100.00"}]$j$::jsonb, $t$https://www.boonton.org/DocumentCenter/View/4138/Certificate-of-Compliance-Residential$t$, $t$https://www.boonton.org/654/Housing$t$, $j$[{"url":"https://www.boonton.org/654/Housing","label":"Official source (boonton.org)"},{"url":"https://www.boonton.org/DocumentCenter/View/4138/Certificate-of-Compliance-Residential","label":"Official source (boonton.org)"},{"url":"https://www.boonton.org/DocumentCenter/View/3776/Certificate-of-Compliance-Inspection-Packet","label":"Official source (boonton.org)"}]$j$::jsonb, $t$All properties must be registered and inspected upon a change of ownership or tenancy.$t$, $t$5257c45e5b9385d04e52234f25ee4454a928e91ccca8fa0295e66f68fa3c03a0$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":7,"fee_ok":7,"fee_bad":0,"fee_unchecked":0,"quotes":16,"q_ok":14,"q_bad":0,"q_unchecked":2},"source":"property/data/municipal-requirements/checked/1401.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1401.json$t$, true),
  ($t$1401$t$, $t$Boonton$t$, $t$MORRIS$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Town of Boonton Code Enforcement / Housing (Certificate of Compliance, the 'Smoke Certificate'); LEA: Boonton Fire Department Bureau of Fire Prevention (town fire bureau)","Contact: John Webber, Fire Official (phone 973-402-9410 ext 626) · 973-402-9410 ext. 625 or 626 · jwebber@boonton.org","Apply: Apply at least two weeks before closing; Tuesday 9 to 11 AM inspections; late fee for requests fewer than 5 business days before the sale.","How to apply: The smoke/CO certificate is the Town's Certificate of Compliance; apply with the residential Certificate of Compliance application (see resale certificate).","Fire official in the NJ state directory, updated 1/23/2026: John Webber · (973) 402-9410 · jwebber@boonton.org","Smoke alarms per N.J.A.C. 5:70-4.19; battery-operated units must be 10-year sealed battery units","Carbon monoxide alarms","Fire extinguishers (still listed in the inspection packet)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Certificate of Compliance, residential detached single family (Housing page)","amount":"$100"},{"label":"Certificate of Compliance, two family or multi-family (Housing page)","amount":"$100 first unit + $50 each additional unit"},{"label":"Late fee, request fewer than 5 business days before the sale (Housing page; the application says fewer than 4)","amount":"$75.00"}]$j$::jsonb, $t$https://www.boonton.org/DocumentCenter/View/4138/Certificate-of-Compliance-Residential$t$, $t$https://www.boonton.org/654/Housing$t$, $j$[{"url":"https://www.boonton.org/654/Housing","label":"Official source (boonton.org)"},{"url":"https://www.boonton.org/681/Fire-Prevention","label":"Official source (boonton.org)"},{"url":"https://www.boonton.org/DocumentCenter/View/3776/Certificate-of-Compliance-Inspection-Packet","label":"Official source (boonton.org)"},{"url":"https://ecode360.com/7160345","label":"Official source (ecode360.com)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$This certificate is also referred to as a "Smoke Certificate" and is required when closing on real estate.$t$, $t$2fde7f7b11e68fac45b3162af875e7ee0d0ab9496bef34c98851cfc5472a394a$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":7,"fee_ok":7,"fee_bad":0,"fee_unchecked":0,"quotes":16,"q_ok":14,"q_bad":0,"q_unchecked":2},"source":"property/data/municipal-requirements/checked/1401.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1401.json$t$, true),
  ($t$1402$t$, $t$Boonton Township$t$, $t$MORRIS$t$, $t$resale_cco$t$, $t$official_process_found$t$, $t$Resale / Continued Certificate of Occupancy (CCO)$t$, $j$["Not required for sales, per Boonton Township. Confirm with the office if the buyer's lender or title company asks.","Contact: 973-402-4002 ext. 1107","How to apply: No Township resale Certificate of Occupancy. The Township only requires the smoke detector / carbon monoxide alarm / fire extinguisher inspection before closing (see fire certificate)."]$j$::jsonb, $j$[]$j$::jsonb, null, $t$https://www.boontontownship.com/construction-department$t$, $j$[{"url":"https://www.boontontownship.com/construction-department","label":"Official source (boontontownship.com)"}]$j$::jsonb, $t$A Certificate of Occupancy is not required when selling your home, but a smoke detector/carbon monoxide alarm inspection is required.$t$, $t$ab5504078d8ba15bfe5ff60f72fd8e755a61a5f3d8dc480558e3cd69fcedccc1$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":4,"fee_bad":0,"fee_unchecked":0,"quotes":9,"q_ok":7,"q_bad":0,"q_unchecked":2},"source":"property/data/municipal-requirements/checked/1402.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1402.json$t$, true),
  ($t$1402$t$, $t$Boonton Township$t$, $t$MORRIS$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Boonton Township Fire Prevention (Fire Official), scheduled through the Township Clerk's Office (town fire bureau)","Contact: Scott Para, Fire Official & OEM Coordinator · 973-402-4017 · spara@boontontownship.com","Apply: Fee depends on business days before the change of occupant: more than 10 business days for the lowest fee. The certificate stays valid for 6 months.","How to apply: Fill out the online Application for Smoke Detector, Carbon Monoxide Alarm and Fire Extinguisher Compliance (Boonton Township residents only) or hand deliver the application to the Municipal Building, 155 Powerville Road. The Construction Department page says to call the Clerk's Office at 973-402-4002 ext. 1107, but residents must come in to schedule; inspections cannot be scheduled over the phone. Payment must be received before the inspection date.","Fire official in the NJ state directory, updated 2/6/2026: Scott Para · (973) 402-4017 · spara@boontontownship.com","Smoke detector on each level of the dwelling, including basements (not attics or crawl spaces)","Smoke detector and carbon monoxide alarm outside each separate sleeping area, within 10 feet of bedrooms","All smoke detectors and carbon monoxide alarms in working order","One portable fire extinguisher within 10 feet of the kitchen, not more than 5 feet above the floor (page still lists it)","A person over 18 must be present for the inspection; payment must be received before the inspection date","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke/CO alarm and extinguisher certificate, more than 10 business days before the change of occupant","amount":"$45.00"},{"label":"4 to 10 business days before the change of occupant","amount":"$90.00"},{"label":"Fewer than 4 business days before the change of occupant","amount":"$161.00"},{"label":"Third re-inspection after two failed inspections","amount":"$45.00"}]$j$::jsonb, $t$https://www.boontontownship.com/FireCompliance$t$, $t$https://www.boontontownship.com/fire-department$t$, $j$[{"url":"https://www.boontontownship.com/FireCompliance","label":"Official source (boontontownship.com)"},{"url":"https://www.boontontownship.com/construction-department","label":"Official source (boontontownship.com)"},{"url":"https://www.boontontownship.com/fire-department","label":"Official source (boontontownship.com)"},{"url":"https://ecode360.com/8467224","label":"Official source (ecode360.com)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Once issued the certification shall remain valid for 6 months.$t$, $t$abebcf9762f09590a01e8f09d7c51cb1beb3bd93498c015f1b35be0a89f5b6b4$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":4,"fee_bad":0,"fee_unchecked":0,"quotes":9,"q_ok":7,"q_bad":0,"q_unchecked":2},"source":"property/data/municipal-requirements/checked/1402.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1402.json$t$, true),
  ($t$1403$t$, $t$Butler Borough$t$, $t$MORRIS$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Continued Certificate of Occupancy (CCO) for Sale of Residential Property$t$, $j$["Issued by: Borough of Butler Zoning Department / Enforcement Officer","Contact: 973-838-7200 x224 · Zoning@butlerborough.com","Apply: Minimum of 7 full business days notice required for inspections. The Enforcement Officer may waive the inspection and fee if the same premises was inspected within 60 days.","How to apply: Submit the CCO Application for Sale of Residential Property with the $200 per unit fee (cash or check payable to Borough of Butler, 1 Ace Rd; no credit cards at the counter), or apply and pay online through the Borough's E-Permits webforms. List the emails of the parties and attorneys; the approved CCO is e-mailed. Give a contact who will let the Fire Inspector in; allow at least 7 full business days for the inspection.","Inspection for compliance with the Borough Property Maintenance Code (Chapter 180), Land Use Ordinance, NJ Housing Code and NJ smoke detector regulations","House number clearly visible, at least 2 1/4 inches high and contrasting with the background","Pools and hot tubs: 48 inch fence or wall, self-closing self-latching gates opening out with release at least 54 inches high; zoning and construction permits on file (no CCO until permits are obtained and inspected)","Smoke and carbon monoxide alarms in proper working order (smoke/CO certification done with the CCO)","Secondary power source caution label near the main panel and meter if the home has a generator, solar panels or battery storage","Survey attached if available","Also: Pool and hot tub permits: If a pool or hot tub has no permits, the CCO will not be issued until permits are obtained and inspections pass."]$j$::jsonb, $j$[{"label":"Residential sale CCO, per dwelling unit","amount":"$200"}]$j$::jsonb, $t$https://www.butlerborough.com/FCpdf/Residential%20CCO%2Epdf$t$, $t$https://www.butlerborough.com/cn/webpage.cfm?tpid=15405$t$, $j$[{"url":"https://www.butlerborough.com/FCpdf/Residential%20CCO%2Epdf","label":"Official source (butlerborough.com)"},{"url":"https://www.butlerborough.com/documents/code%20book/butler%20borough%20code%20book.pdf","label":"Official source (butlerborough.com)"},{"url":"https://www.butlerborough.com/cn/webpage.cfm?tpid=15405","label":"Official source (butlerborough.com)"}]$j$::jsonb, $t$CCO APPLICATION for SALE of RESIDENTIAL PROPERTY$t$, $t$0d733274b228a0669f1eee8d8c00e5ca3968626fa60b92604d534b65499eed84$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":3,"fee_bad":0,"fee_unchecked":0,"quotes":13,"q_ok":12,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/1403.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1403.json$t$, true),
  ($t$1403$t$, $t$Butler Borough$t$, $t$MORRIS$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Butler Fire Prevention Bureau (inspection done with the Borough residential sale CCO) (town fire bureau)","Contact: Mark Lime, Fire Official · 973-838-1680 · mlime@butlerborough.com","Apply: Minimum of 7 full business days notice for inspections.","How to apply: The smoke and CO inspection is requested on the Borough's CCO Application for Sale of Residential Property; the Fire Inspector contacts the person named on the form to set up the appointment. A $25 reinspection fee must be paid before a reinspection.","Fire official in the NJ state directory, updated 7/31/2026: Mark W Lime · (973) 838-1680 · mlime@butlerborough.com","Hardwired interconnected smoke alarms must be kept working and may not be converted to battery alarms","All smoke alarms less than 10 years old and UL listed; new battery alarms must be sealed 10-year units","At least one smoke alarm on every level including the basement and habitable attic, plus attics/crawl spaces containing fuel-burning equipment; alarms in the hallway within 10 feet of all bedroom doors","Carbon monoxide alarms on all levels with bedrooms, within 10 feet of all bedroom doors (hardwired, plug-in or battery)","Secondary power source caution label within 18 inches of the main electrical panel and meter, if applicable","Fire extinguishers are no longer required (Borough form)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke/CO reinspection after a failed inspection","amount":"$25"},{"label":"Smoke detector certification, resale (Borough fee schedule, Ord. 2000-26; the current CCO form shows only the $200 CCO fee)","amount":"$50.00"}]$j$::jsonb, $t$https://www.butlerborough.com/FCpdf/Residential%20CCO%2Epdf$t$, $t$https://www.butlerborough.com/cn/webpage.cfm?tpid=18523$t$, $j$[{"url":"https://www.butlerborough.com/FCpdf/Residential%20CCO%2Epdf","label":"Official source (butlerborough.com)"},{"url":"https://www.butlerborough.com/documents/code%20book/butler%20borough%20code%20book.pdf","label":"Official source (butlerborough.com)"},{"url":"https://www.butlerborough.com/cn/webpage.cfm?tpid=18523","label":"Official source (butlerborough.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$there will be a $25 Re-Inspection Fee for each Inspection Failure regarding the Smoke and Carbon Monoxide Detectors.$t$, $t$e158d915b3bf93079740f421a9d22b5574ebf20263d28a462f0a6bb6f2caca28$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":3,"fee_bad":0,"fee_unchecked":0,"quotes":13,"q_ok":12,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/1403.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1403.json$t$, true),
  ($t$1404$t$, $t$Chatham Borough$t$, $t$MORRIS$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Residential Certificate of Continuing Occupancy (CCO)$t$, $j$["Issued by: Borough of Chatham, Office of the Borough Clerk (CCO inspection with the smoke/CO check)","Contact: Hillary Singer, Assistant to the Borough Clerk (handles CCO inspections) · 973-635-0674 ext.210 · clerkadmin@chathamborough.org","Apply: CCOs take about 3 weeks to process after a complete application (the Borough page says two to three weeks, not counting the inspection). Inspections are Thursdays between 11 am and 1 pm, scheduled once permits are closed and utilities are current.","How to apply: Fill in the Residential CCO Application, attach the open-permit summary, Tax Collector and Utilities Clerk sign-offs and the inspection checklist, and submit it to the Borough Clerk's Office, 54 Fairmount Avenue, with $100 by check or cash payable to Borough of Chatham. The Clerk's Office schedules the Thursday inspection and issues the CCO once the signed checklist and proof of closed permits are in.","Residential CCO application (Sale) signed by the owner or authorized agent","For a sale: proof of no open permits (a 'Permit Summary' requested from the Clerk through an OPRA request)","For a sale: Tax Collector sign-off on page 2 that Lead Line Replacement fees are paid in full","Utilities Clerk sign-off that water/sewer utilities are paid in full","Inspection checklist items: street number, smoke detectors, carbon monoxide, furnace and flues, hot water heater, electric panel, secondary power source, garage door opener, temporary wiring, cover plates, sump pump, handrails, sidewalk, general safety","Certificate from the service provider if the home is on a central station police or fire alarm system","Also: Lead water service line fees: For a sale, the Tax Collector must confirm Lead Line Replacement fees are paid in full; Borough Code §267-25 ties proof of lead service line replacement to the CCO on a sale or transfer.","Also: Utilities paid: Utilities Clerk must confirm water/sewer accounts are paid in full (973-635-0674 ext. 214).","Also: Open permits: Proof of no open permits (Permit Summary through an OPRA request) is required for a sale; all permits must be closed before the CCO is issued.","Also: Sump pump: Sump pumps may not discharge into the sanitary sewer and must have sturdy pit covers.","Also: Sidewalk: Sidewalk condition is on the CCO checklist."]$j$::jsonb, $j$[{"label":"Residential CCO application","amount":"$100"},{"label":"Certificate of continued occupancy (Borough Code §111-4)","amount":"$100"}]$j$::jsonb, $t$https://www.chathamborough.org/applications/156-continuing-certificate-of-occupancy-permit-residential-property-application-fillable-form/file$t$, $t$https://www.chathamborough.org/departments/construction$t$, $j$[{"url":"https://www.chathamborough.org/applications/156-continuing-certificate-of-occupancy-permit-residential-property-application-fillable-form/file","label":"Official source (chathamborough.org)"},{"url":"https://www.chathamborough.org/departments/construction","label":"Official source (chathamborough.org)"},{"url":"https://ecode360.com/6792203","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/44601858","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$Residential Certificate of Continuing Occupancy (CCO) Application$t$, $t$189a383e23788410a2fafbe8ab611e32ba27dc955b4fd0976f680139232e8fc3$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":2,"fee_bad":0,"fee_unchecked":1,"quotes":16,"q_ok":13,"q_bad":0,"q_unchecked":3},"source":"property/data/municipal-requirements/checked/1404.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1404.json$t$, true),
  ($t$1404$t$, $t$Chatham Borough$t$, $t$MORRIS$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Borough of Chatham (smoke/CO check on the Clerk's CCO inspection); fire code enforcing agency: Chatham Borough Bureau of Fire Safety (Code Enforcement) (town fire bureau)","Contact: Scott Loyek, Fire Marshal · 973-701-6815 · firemarshal@chathamborough.org","Apply: Same as the CCO: about 3 weeks; inspections Thursdays 11 am to 1 pm.","How to apply: Part of the Residential CCO application filed with the Borough Clerk's Office. Fire safety questions go to the Bureau of Fire Safety, 54 Fairmount Ave (hours by appointment).","Fire official in the NJ state directory (town), updated 1/13/2025: Scott Loyek · (973) 635-0674 · firemarshal@chathamborough.org","Smoke detectors with 10-year sealed batteries on each level, on the ceiling at the base of the stairs and not more than ten feet from each bedroom","Carbon monoxide detectors within ten feet of each bedroom; combination smoke/CO units allowed","Certificate from the alarm company if the home is connected to a central station alarm system","Secondary power source warning label within 18 inches of the main electrical panel and meter","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke/CO check within the residential CCO (same fee, not an extra charge)","amount":"$100"}]$j$::jsonb, $t$https://www.chathamborough.org/applications/156-continuing-certificate-of-occupancy-permit-residential-property-application-fillable-form/file$t$, $t$https://www.chathamborough.org/departments/fire-prevention$t$, $j$[{"url":"https://www.chathamborough.org/applications/156-continuing-certificate-of-occupancy-permit-residential-property-application-fillable-form/file","label":"Official source (chathamborough.org)"},{"url":"https://www.chathamborough.org/departments/fire-prevention","label":"Official source (chathamborough.org)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$New Jersey Fire Code mandates the following when selling or renting your home:$t$, $t$3e9be6f32b9431cd02e586635a29fed4f304273b67881a3b9a8c0d4dda6f5ee9$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":2,"fee_bad":0,"fee_unchecked":1,"quotes":16,"q_ok":13,"q_bad":0,"q_unchecked":3},"source":"property/data/municipal-requirements/checked/1404.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1404.json$t$, true),
  ($t$1408$t$, $t$Denville Township$t$, $t$MORRIS$t$, $t$resale_cco$t$, $t$official_process_found$t$, $t$Resale / Continued Certificate of Occupancy (CCO)$t$, $j$["Not required for sales, per Denville Township. Confirm with the office if the buyer's lender or title company asks.","Contact: Sal Poli, Construction Official · (973) 625-8300 ext. 251","How to apply: No Township resale Certificate of Occupancy. The Township says the only inspection needed to sell a house is the Fire Prevention smoke detector inspection (smoke alarms, CO alarms and kitchen fire extinguisher). Open permits should be closed before transfer.","Also: Open permits: The Township asks that all open permits be closed out before the property is transferred."]$j$::jsonb, $j$[]$j$::jsonb, null, $t$https://www.denvillenj.gov/departments/selling_your_house.php$t$, $j$[{"url":"https://www.denvillenj.gov/departments/selling_your_house.php","label":"Official source (denvillenj.gov)"},{"url":"https://www.denvillenj.gov/departments/construction.php","label":"Official source (denvillenj.gov)"}]$j$::jsonb, $t$The only inspection required to sell your house is a Smoke Detector Inspection , which also includes carbon monoxide detectors and a fire extinguisher in the kitchen.$t$, $t$82f82e48f5bf8f055326631122679fb1625eb575eb6658e83558438bc7502412$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":6,"fee_bad":0,"fee_unchecked":0,"quotes":12,"q_ok":11,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/1408.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1408.json$t$, true),
  ($t$1408$t$, $t$Denville Township$t$, $t$MORRIS$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Denville Township Fire Prevention Bureau (town fire bureau)","Contact: Carmine Ruta, Fire Official (Fire Inspectors: Don Leyhan and Rich Yobs) · (973) 625-8300 ext. 257 · fireprevention@denvillenj.org","Apply: Fee depends on business days between the request and the change of occupant (more than 10 for the lowest fee). Office hours Wednesday to Friday 8:00 am to 4:00 pm. Inspections are good for 6 months.","How to apply: Fill out the Application For CCO Inspections (Form Center, Fire Prevention) and email it to fireprevention@denvillenj.org or drop it off or mail it to Denville Town Hall, 1 St. Mary's Place. Checks payable to Denville Township Fire Prevention. To schedule call (973) 625-8300 ext. 257.","Fire official in the NJ state directory, updated 3/27/2026: Connor Mc Guinness · (973) 625-8300 · fireprevention@denvillenj.org","Smoke alarm on each level including basements (not attic or crawl space) and outside each separate sleeping area within 10 feet of bedrooms","10-year sealed battery smoke alarms (ANSI/UL 217) where battery alarms are used; AC alarms from construction or rehabilitation cannot be replaced with battery alarms, and AC alarms more than 10 years old must be replaced before the inspection","CO alarm in the immediate vicinity of sleeping areas (UL 2034, NFPA 720) unless the home has no fuel-burning device or attached garage","Low-voltage alarm systems: monitoring contact, account and password, plus certification from an alarm technician","Portable fire extinguisher 2A-10B:C, no more than 10 pounds, serviced and tagged within 12 months or with a recent purchase receipt; owner's manual left for the new occupant (form still lists it)","Secondary power source label (\"Caution: Multiple Sources Of Power\") within 18 inches of the main panel and the meter, if the home has a generator, solar panels or battery storage","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke/CO resale inspection, more than 10 business days before change of occupant","amount":"$35"},{"label":"4 to 10 business days before change of occupant","amount":"$70"},{"label":"Fewer than 4 business days","amount":"$125"},{"label":"Township fee schedule: more than 10 days' notice","amount":"$35.00"},{"label":"Township fee schedule: 4 to 10 days' notice","amount":"$70.00"},{"label":"Township fee schedule: less than 4 days' notice","amount":"$125.00"}]$j$::jsonb, $t$https://www.denvillenj.gov/docs/FirePrevention/Application%20For%20CCO%20Inspections%20%20.pdf$t$, $t$https://www.denvillenj.gov/departments/fire_prevention.php$t$, $j$[{"url":"https://www.denvillenj.gov/departments/fire_prevention.php","label":"Official source (denvillenj.gov)"},{"url":"https://www.denvillenj.gov/docs/FirePrevention/Application%20For%20CCO%20Inspections%20%20.pdf","label":"Official source (denvillenj.gov)"},{"url":"https://www.denvillenj.gov/docs/FirePrevention/Affidavit%20application%20rev2.pdf","label":"Official source (denvillenj.gov)"},{"url":"https://www.denvillenj.gov/departments/selling_your_house.php","label":"Official source (denvillenj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.denvillenj.gov/administration/fee_schedule.php","label":"Official source (denvillenj.gov)"}]$j$::jsonb, $t$Smoke detector inspections are good for 6 months.$t$, $t$35617c3216b911761a404c1a8497d13dccec40f3e96d5aa425f0ba35a96d98f9$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":6,"fee_bad":0,"fee_unchecked":0,"quotes":12,"q_ok":11,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/1408.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1408.json$t$, true),
  ($t$1409$t$, $t$Dover$t$, $t$MORRIS$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Compliance (C of C), residential$t$, $j$["Issued by: Town of Dover Code Enforcement and Inspection Department","Contact: William J. Isselin, Chief Code Enforcement Officer · 973-366-2200 ext. 2114 · wisselin@dover.nj.us","Apply: Apply at least 10 working days before the closing (the Town recommends applying right after attorney review). Inspections are Wednesdays 9 am to 12 pm. A final C of C takes at least three working days to process after a clean inspection and is never issued the same day.","How to apply: Fill out the Certificate of Compliance Application - Residential (check 'Sale') and the Fire Department's smoke and CO alarm application, both in the Town's Residential C of C packet, and submit them with the fee to Code Enforcement, 100 Princeton Ave. (mail: 37 North Sussex Street), Dover, NJ 07801, (973) 366-2200 ext. 2114. Pay by cash or check. The C of C and alarm inspections are scheduled together on a Wednesday morning.","Valid for: A temporary C of C may be issued for 30 days when violations remain (buyer must agree in writing to fix them within 30 days)","Complete the Certificate of Compliance Application (Residential) and pay the fee before an inspection is scheduled","Full interior and exterior property maintenance inspection, including room measurements to set sleeping capacity","All open construction permits must be inspected and approved before the C of C is issued","Checks include sidewalks, drainage, accessory structures, unlicensed vehicles, roofs, gutters, windows, stairs and railings, bathroom and dryer venting, plumbing and sump pump discharge, heating, GFCI and electrical hazards, egress, sanitation and pests","Smoke and carbon monoxide alarm certification from the Fire Inspector is required before the C of C is issued (inspected the same day)","Owners who do not live at the property must file a Non-Owner Occupied Premises form","Also: Open permits: All outstanding construction permits must be inspected and approved before the C of C is issued.","Also: Occupancy calculation: Inspectors measure every room to calculate sleeping capacity and check for overcrowding.","Also: Non-owner occupied form: If the owner's address is not the property, a Non-Owner Occupied Premises form must be filed.","Also: Sidewalks and exterior: The C of C inspection covers exterior property areas, including sidewalks, drainage, accessory structures and unlicensed vehicles."]$j$::jsonb, $j$[{"label":"Certificate of Compliance, detached single family dwelling","amount":"$75.00"},{"label":"Certificate of Compliance, two family dwelling","amount":"$75.00 for the first unit plus $35.00 per additional unit"},{"label":"Re-inspection after the first free re-inspection","amount":"$50.00"}]$j$::jsonb, $t$https://www.dover.nj.us/documents/Residential%20COC-Smoke_Carbon%20Alarm%20Cert-Notice-Guideline%20Packet.pdf$t$, $t$https://www.dover.nj.us/$t$, $j$[{"url":"https://dover.nj.us/FCpdf/Inspection%20Procedure%20Handout%20%28Res%29%202%2E19%2E14%2Epdf","label":"Official source (dover.nj.us)"},{"url":"https://www.dover.nj.us/documents/Residential%20COC-Smoke_Carbon%20Alarm%20Cert-Notice-Guideline%20Packet.pdf","label":"Official source (dover.nj.us)"}]$j$::jsonb, $t$No owner, agent, or any person shall rent or lease or sell or in any way deliver up for use, change of use or occupancy any business, building, dwelling unit, lodging unit, rooming unit, or boarding unit, until a Certificate of Compliance has been issued by the Code Official.$t$, $t$482def709f8849c6d6f8da464872b9e7d7c2031390907575e244ee492daba77f$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":3,"fee_bad":0,"fee_unchecked":0,"quotes":13,"q_ok":12,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/1409.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1409.json$t$, true),
  ($t$1409$t$, $t$Dover$t$, $t$MORRIS$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Town of Dover Fire Department, Fire Prevention Bureau (town fire bureau)","Contact: Jon P. Sperry, Jr., Fire Official · 973-366-3260 · jsperry@dover.nj.us","Apply: Since February 3, 2026 the Fire Inspector does the alarm inspection at the same date and time as the Code Enforcement C of C inspection, Wednesdays 9 am to 12 pm. The alarm certificate is issued at the inspection if the alarms pass. Re-inspections are arranged directly with the Fire Inspector.","How to apply: Fill out the Application for One & Two-Family Dwelling Certificate of Smoke and Carbon Monoxide Alarm Compliance (in the Residential C of C packet) and submit it through Code Enforcement with the C of C application. Fire Prevention Bureau: 37 North Sussex Street, Dover, NJ 07801, 973-366-3260.","Fire official in the NJ state directory, updated 8/5/2026: Jon P Sperry Jr · (973) 366-2200 · jsperry@dover.nj.us","Homes built before 1977: 10-year sealed lithium battery smoke detectors, one on each level including the basement (not unfinished attics) and one within 10 feet of each bedroom","Homes built 1977 to 1990: 120-volt hardwired smoke alarms with battery backup (interconnected in homes built 1984 to 1989), same locations","Homes built 1990 to present: 120-volt hardwired interconnected smoke alarms with battery backup on each level, within 10 feet of each bedroom, and inside each bedroom","One carbon monoxide alarm within 10 feet of each bedroom","All smoke detectors providing coverage must be the same type; smoke detectors over 10 years old must be replaced; fire alarm systems must be tested by a state-certified contractor with an NFPA 72 report","Homes with additions or renovations: call the fire inspector for specific requirements","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[]$j$::jsonb, $t$https://www.dover.nj.us/documents/Residential%20COC-Smoke_Carbon%20Alarm%20Cert-Notice-Guideline%20Packet.pdf$t$, $t$https://www.dover.nj.us/$t$, $j$[{"url":"https://www.dover.nj.us/documents/Residential%20COC-Smoke_Carbon%20Alarm%20Cert-Notice-Guideline%20Packet.pdf","label":"Official source (dover.nj.us)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Application for One & Two-Family Dwelling Certificate of Smoke and Carbon Monoxide Alarm Compliance$t$, $t$3b94a23a8933013080fdf48ffcd495dd18d2e796d329d0e8f6bdf9989ff41274$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":3,"fee_bad":0,"fee_unchecked":0,"quotes":13,"q_ok":12,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/1409.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1409.json$t$, true),
  ($t$1410$t$, $t$East Hanover Township$t$, $t$MORRIS$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Residential Certificate of Compliance$t$, $j$["Issued by: Township of East Hanover Land Use & Construction Departments (Enforcement Officer), after the Fire Prevention Bureau certifies smoke and CO detectors","Contact: Thomas Pershouse, Construction Official / Building Inspector and Zoning Official · 973-888-6025","How to apply: Mail or drop off the Residential Certificate of Compliance packet at the Land Use & Construction Departments, 411 Ridgedale Avenue, East Hanover, NJ 07936: the Certificate of Compliance application with a $100 check or money order payable to the Township of East Hanover, plus the Smoke Detector/CO/Fire Extinguisher application with a separate check (memo: Fire Prevention Bureau). Questions: 973-888-6025.","Valid for: Expires 6 months from the approved date.","Certificate of Compliance application signed by the property owner (resale or rental/lease; single family, two-family, or single family with business use; list any past variances)","Separate Smoke Detector/Carbon Monoxide/Fire Extinguisher application and separate check to the Fire Prevention Bureau","Inspection by the Enforcement Officer for violations of Township codes and ordinances; violations must be corrected and reinspected (extra fee if more than one reinspection)","Fire Prevention Bureau documentation of smoke and carbon monoxide detectors must be presented before the certificate is issued","Also: Uncorrected violations: Selling property with uncorrected violations that the owner was notified of requires the Enforcement Officer's prior approval (Township code 119A-8).","Also: Water and sewer account: A new water/sewer service application must be made and approved by the Township on any change in ownership when the owner is the customer (Township code 159-75)."]$j$::jsonb, $j$[{"label":"Residential Certificate of Compliance (resale or rental/lease)","amount":"$100"},{"label":"Certificate of continued use or occupancy, residential (Township code fee schedule, Chapter 79)","amount":"$75"}]$j$::jsonb, $t$https://www.easthanovertownship.com/_Content/pdf/forms/Certificate-of-Compliance-Residential.pdf$t$, $t$https://www.easthanovertownship.com/Departments/construction-department$t$, $j$[{"url":"https://www.easthanovertownship.com/_Content/pdf/forms/Certificate-of-Compliance-Residential.pdf","label":"Official source (easthanovertownship.com)"},{"url":"https://ecode360.com/13427178","label":"Official source (ecode360.com)"},{"url":"https://www.easthanovertownship.com/Departments/construction-department","label":"Official source (easthanovertownship.com)"},{"url":"https://ecode360.com/13425947","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$In accordance with East Hanover Township Ordinance 119-A-5 and 26-36A(9), any real property containing a building must secure a Certificate of Compliance before sale, lease or rental of said property.$t$, $t$916a0c2d81d2126d9858973768376736f6023b8df31ba806502deb1e84899977$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":7,"fee_ok":6,"fee_bad":0,"fee_unchecked":1,"quotes":12,"q_ok":7,"q_bad":0,"q_unchecked":5},"source":"property/data/municipal-requirements/checked/1410.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1410.json$t$, true),
  ($t$1410$t$, $t$East Hanover Township$t$, $t$MORRIS$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: East Hanover Fire Department, Bureau of Fire Prevention (town fire bureau)","Contact: James C. Cavezza, Bureau Chief/Fire Marshal (Fire Official) · 973-887-6854 · jamesc@easthanovertownship.com","Apply: Fee is based on business days before the change of occupant: more than 10 business days for the lowest fee. If the change of occupancy does not happen within 6 months, a new application is needed.","How to apply: Submit the Application for Certification of Smoke Detector, Carbon Monoxide Alarm & Portable Fire Extinguisher Compliance (part of the Residential Certificate of Compliance packet) with a separate check or money order payable to Township of East Hanover, memo 'Fire Prevention Bureau'. The certificate is non-transferable and the fee is not refundable.","Fire official in the NJ state directory, updated 7/17/2026: James Cavezza · (973) 887-6854 · jamesc@easthanovertownship.com","Smoke detectors on every level (basement, first floor, second floor; not crawl spaces or unfinished attics) and in every separate sleeping area; basement detector near the bottom of the stairs","Battery smoke alarms must be 10-year sealed units (UL 217); hardwired alarms from original construction cannot be replaced with battery units; homes built in or after 1991 need hardwired interconnected alarms with battery backup inside and outside bedrooms and on each level","Carbon monoxide alarm near the sleeping areas in homes with a fuel-burning device or attached garage (battery, hardwired or plug-in, UL 2034)","ABC fire extinguisher, no larger than 10 lbs, mounted within 10 feet of the kitchen in the path of egress, top no more than 5 feet up, new or tagged by a licensed contractor, with owner's manual (Township form and code still list it)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke/CO/extinguisher certificate, application more than 10 business days before change of occupant","amount":"$100.00"},{"label":"Application 4 to 10 business days before change of occupant","amount":"$125.00"},{"label":"Application less than 4 days before change of occupant","amount":"$150.00"},{"label":"Request for certification on the same day as the settlement","amount":"$200.00"},{"label":"Re-inspection (missing/outdated/non-working equipment, no one present, or cancellation under 24 hours)","amount":"$50.00"}]$j$::jsonb, $t$https://www.easthanovertownship.com/_Content/pdf/forms/Certificate-of-Compliance-Residential.pdf$t$, $t$https://www.easthanovertownship.com/departments/fire-department-bureau-of-fire-prevention$t$, $j$[{"url":"https://www.easthanovertownship.com/_Content/pdf/forms/Certificate-of-Compliance-Residential.pdf","label":"Official source (easthanovertownship.com)"},{"url":"https://ecode360.com/13420491","label":"Official source (ecode360.com)"},{"url":"https://www.easthanovertownship.com/departments/fire-department-bureau-of-fire-prevention","label":"Official source (easthanovertownship.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$FEE: CSACMAPFEC (Smoke Alarm Inspection) shall be based upon the amount of time before the change of occupant is expected, as per the following: § 26-36A(9)$t$, $t$3dfce3adbe6e154a6309881e523ff539a817ebac46eba485ba9e8d54fe3eac54$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":7,"fee_ok":6,"fee_bad":0,"fee_unchecked":1,"quotes":12,"q_ok":7,"q_bad":0,"q_unchecked":5},"source":"property/data/municipal-requirements/checked/1410.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1410.json$t$, true),
  ($t$1413$t$, $t$Harding Township$t$, $t$MORRIS$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Construction Records Clearance Certificate (CRC), Residential (in lieu of a Certificate of Occupancy)$t$, $j$["Issued by: Township of Harding Construction Department","Contact: Mark Fornaciari, Construction Official (Technical Assistants: Patricia Walker, pwalker@hardingnj.org; Nicole Ott, nott@hardingnj.org) · 973-267-8000 Ext 716 · mfornaciari@hardingnj.org","Apply: Submit 20 business days before closing","How to apply: Download the Property Re-Sale Application (buyer/seller forms packet) from the Construction page, and submit it with a copy of the real estate listing and a $250.00 check payable to the Township of Harding to 21 Blue Mill Road, P.O. Box 666, New Vernon, NJ 07976, at least 20 business days before closing. Add the signed Well Test Sign Off Sheet if the home has a well.","Application with the real estate listing (or a detailed property description for a private sale)","Answers about address display, swimming pool and pool barrier, finished basement, second kitchen and accessory dwellings","Township checks for open permits, open zoning matters, health approval and zoning approval","Well Test Sign Off Sheet if the property has a private well","Closing date is required on the application","Also: Private well test: Homes with private wells must be tested under the NJ Private Well Testing Act before transfer by a licensed lab; the signed Well Test Sign Off Sheet is added to the CRC application.","Also: Open permits and zoning: The CRC review checks open permits, open zoning matters, health approval and zoning approval."]$j$::jsonb, $j$[{"label":"Construction Records Clearance application, residential","amount":"$250"}]$j$::jsonb, $t$https://hardingnj.org/media/attachments/2026/06/11/buyer---seller-forms.pdf$t$, $t$https://www.hardingnj.org/departments/construction$t$, $j$[{"url":"https://hardingnj.org/media/attachments/2026/06/11/buyer---seller-forms.pdf","label":"Official source (hardingnj.org)"},{"url":"https://www.hardingnj.org/departments/construction","label":"Official source (hardingnj.org)"}]$j$::jsonb, $t$This is required by the Harding Township ordinance 06-2023, in lieu of a Certiﬁcate of Occupancy.$t$, $t$01fdca06e400878e13fd293a5995fdf9cf31b287000e7076eed079491e1e603b$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":4,"fee_bad":0,"fee_unchecked":0,"quotes":11,"q_ok":10,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/1413.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1413.json$t$, true),
  ($t$1413$t$, $t$Harding Township$t$, $t$MORRIS$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: NJ Department of Community Affairs, Division of Fire Safety (state-enforced; Harding Township does not do this inspection) (NJ DCA, state)","Contact: Louis Kilmer, Fire Official of record for Harding (NJ Division of Fire Safety), per the state directory · (609) 633-6132","Apply: State fee tiers count business days between DCA's receipt and the closing date: more than ten business days for the lowest fee. Certificate must be used within 6 months (per the DCA form).","How to apply: Apply to the NJ Division of Fire Safety (the Township's Construction page links to the DCA Fire Safety online portal, firesolutions.dca.nj.gov). Mail address on the DCA form: PO Box 809, Trenton, NJ 08625-0809; checks payable to Treasurer, State of New Jersey. Phone (609) 633-6132.","Fire official in the NJ state directory (NJ DCA, state), updated 2/14/2025: Louis Kilmer · (609)633-6132","Smoke detector on each level including basements (not attic or crawl space), and outside each separate sleeping area within 10 feet of bedrooms","Carbon monoxide alarm outside each separate sleeping area","All alarms in working order; AC powered or interconnected alarms in homes built after January 1977 must be kept working","Fire extinguisher (still on the older DCA form; dropped from the state requirement in February 2025 by P.L.2025, c.19)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"State certificate of smoke detector, CO alarm and extinguisher compliance, closing more than ten business days after receipt (DCA form SD-41, rev. 10/02)","amount":"$35"},{"label":"Received fewer than ten but more than four business days before closing","amount":"$70"},{"label":"Received four business days or fewer before closing","amount":"$125"}]$j$::jsonb, $t$https://firesolutions.dca.nj.gov/$t$, $t$https://www.hardingnj.org/departments/construction$t$, $j$[{"url":"https://hardingnj.org/media/attachments/2026/06/11/buyer---seller-forms.pdf","label":"Official source (hardingnj.org)"},{"url":"https://www.hardingnj.org/departments/construction","label":"Official source (hardingnj.org)"},{"url":"https://www.nj.gov/dca/divisions/dfs/forms/bfce/certificationinlieu.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$All inspections must be made with the State of New Jersey. (Harding Township does not perform this inspection).$t$, $t$0a5926add4c9cf0b84099b5733acc9ec5f22add272fcb1c3df63ea805981bf0e$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":4,"fee_bad":0,"fee_unchecked":0,"quotes":11,"q_ok":10,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/1413.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1413.json$t$, true),
  ($t$1420$t$, $t$Mine Hill Township$t$, $t$MORRIS$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Habitability (CH), combined with the fire safety (smoke/CO) inspection$t$, $j$["Issued by: Mine Hill Township Zoning Department (Construction Code Official, Zoning Officer, Housing Official or Fire Marshal may issue)","Contact: 862-437-1197 · Zoning@MineHill.com","Apply: Submit the application to the Zoning Department at least 30 days before the change in ownership (recommended). The code requires at least seven business days' notice for inspections; less notice costs an extra $50.00.","How to apply: Complete the CH Application for Sale of Residential Property and submit it with the fee to the Zoning Department, Mine Hill Township, 10 Baker Street, Mine Hill, NJ 07803 (862-437-1197, Zoning@MineHill.com). Give a contact name and phone for the Township inspector to set up the appointment. Get the Health Department Certificate of Completion (973-691-0900 ext. 7330) for well or septic items. The approved CH is emailed to the addresses on the application.","Compliance with the Township Property Maintenance code (Chapter 390)","All open construction permits and violations closed out","10-year sealed battery smoke and carbon monoxide detectors properly installed (hardwired systems stay hardwired)","House number clearly visible, at least 2 1/4 inches high and contrasting","Pools and hot tubs: 48-inch barrier, self-closing self-latching gates, and permits on file","Health Department Certificate of Completion: well decommissioning if on town water, septic inspection report if on septic","Secondary power source warning label within 18 inches of the electric panel and meter, where a generator, solar or battery system is present","Copy of a survey, if available","Also: Health Department Certificate of Completion (well and septic): If the home is on town water, any old well must be decommissioned (or certified as irrigation) by a licensed well driller before the transfer; if on septic, a septic inspection report by an engineer or certified septic inspector is required. Health Department: 973-691-0900 ext. 7330.","Also: Pools and hot tubs: Pool barriers and gates must meet the stated height and self-closing rules, and unpermitted pools or hot tubs must be permitted and inspected before the CH is issued.","Also: Secondary power source label: Homes with generators, solar panels or battery storage need a printed 'multiple sources of power' warning label within 18 inches of the electric panel and the meter."]$j$::jsonb, $j$[{"label":"Certificate of habitability combined with fire safety inspection, per residential unit (Code Section 235-19)","amount":"$200.00"},{"label":"Short-notice surcharge, less than seven business days (Code Section 235-19)","amount":"$50.00"},{"label":"Re-inspection after failure (Code Section 235-19)","amount":"$25.00"},{"label":"CH application for sale of residential property (2026 application form)","amount":"$175"}]$j$::jsonb, $t$https://minehill.com/wp-content/uploads/2026/01/Residential-CH-2026-application-rev.pdf$t$, $t$https://minehill.com/construction-and-zoning/$t$, $j$[{"url":"https://ecode360.com/33054127","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/28688398","label":"Official source (ecode360.com)"},{"url":"https://minehill.com/construction-and-zoning/","label":"Official source (minehill.com)"},{"url":"https://minehill.com/wp-content/uploads/2026/01/Residential-CH-2026-application-rev.pdf","label":"Official source (minehill.com)"}]$j$::jsonb, $t$A certificate of habitability shall be required to be obtained by the owner of any residentially occupied real estate prior to the rental or lease or transfer of title of residential property involving a new occupant, a new tenant or a new owner of said property.$t$, $t$73e2109f2118f58c214311c1a0798b8baa942ded1145c32d3fbea015fea684bb$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":1,"fee_bad":0,"fee_unchecked":5,"quotes":11,"q_ok":8,"q_bad":0,"q_unchecked":3},"source":"property/data/municipal-requirements/checked/1420.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1420.json$t$, true),
  ($t$1420$t$, $t$Mine Hill Township$t$, $t$MORRIS$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Mine Hill Township Fire Prevention (Fire Marshal), inspected as part of the Certificate of Habitability (town fire bureau)","Contact: Thomas Trapasso, Fire Official / Fire Marshal (NJ DCA fire directory) · 973-366-9031 · firemarshal@minehill.com","Apply: At least seven business days' notice for the inspection; less notice adds $50.00.","How to apply: No separate application: the smoke/CO inspection is part of the CH Application for Sale of Residential Property filed with the Zoning Department.","Fire official in the NJ state directory, updated 1/8/2026: Thomas Trapasso · (973) 366-9031 · firemarshal@minehill.com","Homes with 110-volt interconnected smoke alarms must keep that system working and may not convert to battery","All smoke alarms less than 10 years old and UL listed; new battery alarms must be sealed 10-year units","Older homes: at least one battery smoke alarm on every level, including the basement and habitable attic, plus attics or crawl spaces with combustion appliances","Smoke alarms in the hallway outside bedrooms within 10 feet of all bedroom doors; basement alarm near the bottom of the stairs","Carbon monoxide alarms on all levels with bedrooms, outside bedrooms within 10 feet of the doors (hardwired, plug-in or battery)","Central station alarm systems must be tested at the inspection with someone present who can reset them","Fire extinguishers are no longer required (per the 2026 application)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Certificate of habitability combined with fire safety inspection, per residential unit (Code Section 235-19)","amount":"$200.00"},{"label":"Short-notice surcharge, less than seven business days","amount":"$50.00"}]$j$::jsonb, $t$https://minehill.com/wp-content/uploads/2026/01/Residential-CH-2026-application-rev.pdf$t$, $t$https://minehill.com/fire-prevention/$t$, $j$[{"url":"https://minehill.com/wp-content/uploads/2026/01/Residential-CH-2026-application-rev.pdf","label":"Official source (minehill.com)"},{"url":"https://minehill.com/construction-and-zoning/","label":"Official source (minehill.com)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://ecode360.com/28688398","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$The proper Smoke/Carbon Monoxide Detectors must be in proper working order. Fire Extinguisher ARE NO$t$, $t$26ed4cf18f1083c4e23e01c3eefde85e4b5fbe3c4d73806cdc1ca295d8e5a2c5$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":1,"fee_bad":0,"fee_unchecked":5,"quotes":11,"q_ok":8,"q_bad":0,"q_unchecked":3},"source":"property/data/municipal-requirements/checked/1420.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1420.json$t$, true),
  ($t$1422$t$, $t$Morris Township$t$, $t$MORRIS$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Habitability (CH)$t$, $j$["Issued by: Township of Morris Building Department (Uniform Construction Code Enforcing Agency)","Contact: Ron Auth, Construction Code Official (rauth@Morristwp.com) · 973-326-7445 · inspections@morristwp.com","Apply: Payment must be made at the office before the CH inspection is done.","How to apply: Fill out the Township's Application Form for CH Inspection (block, lot, owner, responsible person, closing date, 1 family or 2+ family) and pay the $130 inspection fee at the Building Department, 50 Woodland Avenue (check payable to Township of Morris, cash, or credit card in office only). Payment is required before the inspection. Submit a copy of the MLS listing if possible. Phone 973-326-7445 / 973-326-7446.","Valid for: 90 days from issuance; may be extended 30 days by the construction code official for good cause.","No open permits; a CH will not be issued if permitted work has not been inspected and closed (condo association permits need a buyer's attorney letter)","Smoke and carbon monoxide alarm compliance under N.J.A.C. 5:70-2.3 and 5:70-4.19 is checked as part of the CH inspection","Battery smoke alarms must be 10-year sealed; AC-powered alarms must work and be no more than 10 years old; required low-voltage alarm systems need technician certification and monitoring account details","Water heaters, heating and AC equipment must have been permitted and inspected","GFCI outlets working, handrails in place, no extension cords as permanent wiring, stairs in good shape, panel covers secure, no exposed wiring, no broken glass","Holes in attached-garage sheetrock sealed or repaired","No garbage disposal in the kitchen (Township ordinance 37-3)","Pool and fence must meet code with a latching gate","House must match tax records; house numbers visible from the street","Homes with a well or septic system need a report for each at the CH inspection","Also: Well and septic reports: If the house has a well or septic system, a report for each is required at the time of the CH inspection.","Also: Open permits: A CH will not be issued with open permits; unpermitted work (water heater, furnace, AC, finished basement, decks, generators, oil tank removal, etc.) needs permits before the CH.","Also: Garbage disposal: Garbage disposals are not allowed under Morris Township Ordinance 37-3; checked at the CH inspection."]$j$::jsonb, $j$[{"label":"Certificate of Habitability (CH) inspection, 1 family or 2+ family","amount":"$130"},{"label":"Certificate of continued occupancy, municipal ordinance fee (Township code 216-3A(7))","amount":"$130"}]$j$::jsonb, $t$https://www.morristwp.com/DocumentCenter/View/10843/CH-APPLICATION$t$, $t$https://www.morristwp.com/121/Building$t$, $j$[{"url":"https://ecode360.com/28454086","label":"Official source (ecode360.com)"},{"url":"https://www.morristwp.com/DocumentCenter/View/10843/CH-APPLICATION","label":"Official source (morristwp.com)"},{"url":"https://www.morristwp.com/DocumentCenter/View/9647/REQUIREMENTS-FOR-CH-INSPECTION-11822","label":"Official source (morristwp.com)"},{"url":"https://www.morristwp.com/121/Building","label":"Official source (morristwp.com)"},{"url":"https://ecode360.com/28446518","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$It shall hereafter be unlawful for a property owner to transfer title and/or possession to any residential real property in the Township of Morris without having first obtained a certificate of habitability prior to the sale, lease or occupancy of such premises.$t$, $t$6594b1cdc83389d7af8fdf62a452720c087a523fbd455f874dd5dd672a05f93d$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":2,"fee_bad":0,"fee_unchecked":1,"quotes":13,"q_ok":9,"q_bad":0,"q_unchecked":4},"source":"property/data/municipal-requirements/checked/1422.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1422.json$t$, true),
  ($t$1422$t$, $t$Morris Township$t$, $t$MORRIS$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Township of Morris Building Department (smoke/CO compliance checked in the Certificate of Habitability inspection); Morris Township Fire Department is the fire code LEA (town fire bureau)","Contact: Michael B Nunn, Fire Official (NJ DCA fire directory); Fire Subcode Official on the Building page is Ronald Mosca · 973-326-7445 · inspections@morristwp.com","Apply: Done with the CH inspection; pay before the inspection.","How to apply: Apply for the Certificate of Habitability at the Building Department; the CH inspection covers the smoke alarm and CO alarm certificate required by N.J.A.C. 5:70-2.3. The Fire Department's free smoke detector program is not available for sales.","Fire official in the NJ state directory, updated 5/26/2026: Michael B Nunn · (973) 326-7464 · mnunn@morristwp.com","Smoke alarms on each level and outside each separate sleeping area (2 alarms if sleeping areas are on opposite sides of the same level)","Battery smoke alarms must be 10-year sealed (UL 217); AC-powered alarms from construction cannot be replaced with battery units and must be replaced if over 10 years old","Required low-voltage alarm systems: technician certification plus monitoring company contact, account number and password for the inspector","Carbon monoxide alarm in the immediate vicinity of the sleeping areas in homes with a fuel-burning device or attached garage (battery, hardwired or plug-in, UL 2034)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Certificate of Habitability (CH) inspection, 1 family or 2+ family","amount":"$130"}]$j$::jsonb, $t$https://www.morristwp.com/DocumentCenter/View/10843/CH-APPLICATION$t$, $t$https://www.morristwp.com/121/Building$t$, $j$[{"url":"https://www.morristwp.com/DocumentCenter/View/9647/REQUIREMENTS-FOR-CH-INSPECTION-11822","label":"Official source (morristwp.com)"},{"url":"https://www.morristwp.com/145/Smoke-Detectors","label":"Official source (morristwp.com)"},{"url":"https://ecode360.com/28454086","label":"Official source (ecode360.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://www.morristwp.com/DocumentCenter/View/10843/CH-APPLICATION","label":"Official source (morristwp.com)"}]$j$::jsonb, $t$Before any one and two family or attached single family structure is sold, leased or otherwise made subject to a change of occupancy for residential purposed, the owner shall obtain a certificate of smoke alarm, carbon monoxide alarm, evidencing proper compliance with N.J.A.C. 5:704.19$t$, $t$99ed06eaa259e6968f4c84e436b4d1b63e2d9e897377109496c20fe6ae75285e$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":2,"fee_bad":0,"fee_unchecked":1,"quotes":13,"q_ok":9,"q_bad":0,"q_unchecked":4},"source":"property/data/municipal-requirements/checked/1422.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1422.json$t$, true),
  ($t$1424$t$, $t$Morristown$t$, $t$MORRIS$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Habitability (CH) for residential property sale, with Zoning Review and Fire Safety Certification$t$, $j$["Issued by: Town of Morristown Division of Housing & Property Maintenance, with a Zoning Review by the Zoning Officer","Contact: 973-292-6700","How to apply: Complete the Application for Residential Property Sale & Fire Safety Certification Form and submit it with one payment (check, cash or money order payable to the Town of Morristown) covering the Zoning Review and Certificate of Habitability fees to the Division of Housing & Property Maintenance, 200 South Street, 2nd Floor, Morristown, NJ 07960. Zoning reviews the records; Housing then calls to schedule the inspection, which the owner or a designee must attend. Questions: 973-292-6700, weekdays 8:30 a.m. to 4:30 p.m.","Valid for: If the home is not occupied within 60 days of issuance, it must be reinspected and a new CH issued. A Temporary CH can be issued when repairs remain, for up to 30 days.","Habitability inspection of the exterior (fences, garage, sheds, chimneys, foundation, gutters, landscaping, paint, roof, sidewalks, stairs with railings for three or more treads, no pests)","Interior checks: asbestos encapsulated or removed, dry basement, bathroom ventilation, CO detectors, walls and ceilings, two working outlets in each habitable room, fireplace with proof of last flue cleaning, floors, furnace, GFCI outlets in kitchen and baths, water heater, kitchen ventilation to the outside, plumbing, smoke detectors, first-floor window sash locks","Satisfactory Zoning Review by the Zoning Officer for each dwelling unit","No CH while any construction permit is open","Occupancy Standard Form signed by seller, buyer and buyer's agent, returned to Housing & Property Maintenance","Purchaser and real estate licensee certifications about the maximum number of occupants","Pre-1981 dwellings that are not a primary residence must register with the Rent Leveling department","Fire extinguisher in each kitchen for 1-3 family homes (form still lists it)","Also: Zoning Review: A satisfactory Zoning Review by the Zoning Officer is required for each dwelling unit sold: $50 flat fee for a condo, co-op, townhome or single-family, $75 for a 2-4 family home (paid with the CH).","Also: Open construction permits: No Certificate of Habitability is issued while an open construction permit exists; check with the Building Department at 973-292-6712 or on the SDL Portal.","Also: Rent Leveling registration: Dwellings built before 1981 that are not a primary residence must register with the Rent Leveling department."]$j$::jsonb, $j$[{"label":"Certificate of Habitability, sale of condo, co-op, townhome, single-family or 2-family home (per unit)","amount":"$160"},{"label":"Certificate of Habitability, one- and two-family house, each (Town Code 13-81)","amount":"$160"},{"label":"Habitability re-inspection, per instance","amount":"$80"},{"label":"Zoning Review, sale of condo, co-op, townhome or single-family","amount":"$50"},{"label":"Zoning Review, sale of a 2-4 family home","amount":"$75"},{"label":"Temporary certificate (Town Code 13-83)","amount":"$20"}]$j$::jsonb, $t$https://www.townofmorristown.org/vertical/sites/%7B0813EA2E-B627-4F82-BBB0-DDEE646947B5%7D/uploads/Residental_Property_Sale_App__Fire_Safety_Cert_Form_PDF.pdf$t$, $t$https://www.townofmorristown.org/forms$t$, $j$[{"url":"https://www.townofmorristown.org/vertical/sites/%7B0813EA2E-B627-4F82-BBB0-DDEE646947B5%7D/uploads/Residental_Property_Sale_App__Fire_Safety_Cert_Form_PDF.pdf","label":"Official source (townofmorristown.org)"},{"url":"https://ecode360.com/34248422","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/34248427","label":"Official source (ecode360.com)"},{"url":"https://www.townofmorristown.org/forms","label":"Official source (townofmorristown.org)"},{"url":"https://ecode360.com/34248429","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$Before you sell any residential property in Morristown, you must obtain a Certificate of Habitability from the Division of Housing and Property Maintenance and a satisfactory Zoning Review from the Zoning Officer, for each dwelling unit.$t$, $t$62fafad479954424196a6957f7b6b7a09e9e01eceada2a90394c1f5464494685$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":8,"fee_ok":4,"fee_bad":0,"fee_unchecked":4,"quotes":13,"q_ok":8,"q_bad":0,"q_unchecked":5},"source":"property/data/municipal-requirements/checked/1424.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1424.json$t$, true),
  ($t$1424$t$, $t$Morristown$t$, $t$MORRIS$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Town of Morristown Division of Housing & Property Maintenance (Fire Safety Certification combined with the CH); Morristown Fire Bureau is the Uniform Fire Code enforcing agency (town fire bureau)","Contact: Matthew Loughlin, Fire Official (state fire directory) · 973-292-6602 · m-loughlin@townofmorristown.org","Apply: Done with the Certificate of Habitability inspection.","How to apply: For a sale, the smoke/CO/extinguisher certification is applied for on the same Application for Residential Property Sale & Fire Safety Certification Form filed with Housing & Property Maintenance (973-292-6700).","Fire official in the NJ state directory, updated 6/10/2025: Matthew Loughlin · (973) 292-6602 · m-loughlin@townofmorristown.org","Smoke alarms on each level and outside each separate sleeping area (NFPA 72); 10-year sealed battery alarms for homes built before 1977; AC-powered alarms from original construction may not be replaced with battery alarms","Carbon monoxide alarm in the immediate vicinity of the sleeping areas in homes with a fuel-burning device or attached garage (battery, hardwired or plug-in, UL 2034)","Portable fire extinguisher, 2A-10B:C, no more than 10 lbs, within 10 feet of the kitchen, mounted with the maker's bracket, top no more than 5 feet up, serviced and tagged in the past 12 months or with a recent receipt (form still lists it)","Seller signs an attestation that alarms are installed and working and all building permits are closed","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke detector, fire extinguisher and CO detector inspection, if combined with the Certificate of Habitability","amount":"$20"},{"label":"Smoke detector, fire extinguisher and CO detector inspection, stand-alone","amount":"$40"}]$j$::jsonb, $t$https://www.townofmorristown.org/vertical/sites/%7B0813EA2E-B627-4F82-BBB0-DDEE646947B5%7D/uploads/Residental_Property_Sale_App__Fire_Safety_Cert_Form_PDF.pdf$t$, $t$https://www.townofmorristown.org/fire$t$, $j$[{"url":"https://www.townofmorristown.org/vertical/sites/%7B0813EA2E-B627-4F82-BBB0-DDEE646947B5%7D/uploads/Residental_Property_Sale_App__Fire_Safety_Cert_Form_PDF.pdf","label":"Official source (townofmorristown.org)"},{"url":"https://ecode360.com/34248427","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/34248409","label":"Official source (ecode360.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Inspections are required for the sale, rental or change of occupancy of a 1 - or 2- family dwelling.$t$, $t$cf4f00ebd0d06ca31b0b118a3e6036d02b9f3b4be37e6e05b8c88fc6b5492051$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":8,"fee_ok":4,"fee_bad":0,"fee_unchecked":4,"quotes":13,"q_ok":8,"q_bad":0,"q_unchecked":5},"source":"property/data/municipal-requirements/checked/1424.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1424.json$t$, true),
  ($t$1425$t$, $t$Mountain Lakes Borough$t$, $t$MORRIS$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Construction Records Clearance (CRC)$t$, $j$["Issued by: Borough of Mountain Lakes Construction Official (Construction Office)","Contact: Jerelyn Rutzler, Construction Technical Assistant (Construction Code Official/Zoning Officer: Tim Braden, 973-334-3131 x 2012… · 973-334-3131 x 2015 · jrutzler@mtnlakes.org","Apply: Apply at least 10 business days before the change of ownership or occupancy","How to apply: Fill out the Construction Record Clearance Request (fillable PDF on the Borough Forms Center) with owner, address, block and lot, phone and requestor name and email, and submit it with $35.00 cash or check payable to the Borough of Mountain Lakes to the Construction Office, 400 Boulevard, at least 10 business days before closing.","Records inspection only: the Construction Official certifies there are no open permits or pending violations on the property","Any open permits must get all final inspections and approvals, and the matching construction code certificates, before the CRC is issued","Exempt transfers (if no change in physical occupancy): deed corrections, ancient deeds, transfers between spouses or former spouses under a court order, new construction needing a CO, estate distributions, refinancing and home equity loans, and transfers by or to a receiver, bankruptcy trustee or assignee for creditors","Also: Open permits: All open permits must be closed out before a property can be sold; the Construction Records Clearance confirms this."]$j$::jsonb, $j$[{"label":"Construction Record Clearance request (Borough form)","amount":"$35.00"}]$j$::jsonb, $t$https://mountainlakes.gov/wp-content/uploads/2014/11/Construction-Record-Clearance-Requestfillable.pdf$t$, $t$https://mountainlakes.gov/departments/construction-office/$t$, $j$[{"url":"https://ecode360.com/37400917","label":"Official source (ecode360.com)"},{"url":"https://mountainlakes.gov/wp-content/uploads/2014/11/Construction-Record-Clearance-Requestfillable.pdf","label":"Official source (mountainlakes.gov)"},{"url":"https://mountainlakes.gov/departments/construction-office/","label":"Official source (mountainlakes.gov)"}]$j$::jsonb, $t$A CRC shall be required prior to the sale of any residential or commercial structure and prior to the rental of any tenant space in a commercial structure within the Borough.$t$, $t$23b784d5a4d0d948d7052106c2f83b552d4e1671fc192043501474142d88e62e$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":0,"fee_bad":0,"fee_unchecked":3,"quotes":11,"q_ok":4,"q_bad":0,"q_unchecked":7},"source":"property/data/municipal-requirements/checked/1425.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1425.json$t$, true),
  ($t$1425$t$, $t$Mountain Lakes Borough$t$, $t$MORRIS$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Mountain Lakes Fire Prevention (Borough of Mountain Lakes fire official) (town fire bureau)","Contact: Scott Para, Fire Official (per NJ DCA fire directory) · 973-334-3131 ext. 2014","Apply: No appointment is made until the completed application and fee are received; call 973-334-3131 ext. 2014 to schedule.","How to apply: Download the Application for Smoke Detector, Carbon Monoxide Alarm and Fire Extinguisher Compliance from the Borough Forms Center, fill in the property, block and lot, phones and change of occupant date, and submit it with the $100.00 fee payable to the Borough of Mountain Lakes (400 Boulevard). Then call 973-334-3131 ext. 2014 to schedule the inspection.","Fire official in the NJ state directory, updated 6/19/2025: Scott Para · (973) 334-3131 · fireofficial@mtnlakes.org","Smoke detectors on each level of the home","Battery-only smoke detectors must have a 10-year sealed lithium battery; the form asks whether they are hardwired with battery backup","Carbon monoxide alarm on the level(s) with bedrooms, within 10 feet of the bedrooms; combination smoke/CO or plug-in units allowed","Any alarm system must be in working order; if monitored, notify the alarm company so it can be put on test mode on inspection day","Street number clearly displayed for first responders","Form title still lists fire extinguisher compliance (form still lists it), although no extinguisher item appears in its checklist","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke detector, carbon monoxide alarm and fire extinguisher compliance inspection","amount":"$100.00"},{"label":"Re-inspection","amount":"$50.00"}]$j$::jsonb, $t$https://mountainlakes.gov/wp-content/uploads/2014/11/Updated-Application-for-Smoke-Detector-Carbon-Monoxide-Alarm-and-Fire-Extinguisher-Compliance.pdf$t$, $t$https://mountainlakes.gov/forms-center/$t$, $j$[{"url":"https://mountainlakes.gov/wp-content/uploads/2014/11/Updated-Application-for-Smoke-Detector-Carbon-Monoxide-Alarm-and-Fire-Extinguisher-Compliance.pdf","label":"Official source (mountainlakes.gov)"},{"url":"https://mountainlakes.gov/forms-center/","label":"Official source (mountainlakes.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$PLEASE CALL-334-3131(EXTENSION 2014) TO SCHEDULE AN INSPECTION APPOINTMENT$t$, $t$157ded983c52a464d2bfb5c29b8dceebe6483c5b5deb8405d484d7b9e49ad155$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":0,"fee_bad":0,"fee_unchecked":3,"quotes":11,"q_ok":4,"q_bad":0,"q_unchecked":7},"source":"property/data/municipal-requirements/checked/1425.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1425.json$t$, true),
  ($t$1426$t$, $t$Mount Arlington Borough$t$, $t$MORRIS$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Habitability (COH)$t$, $j$["Issued by: Borough of Mount Arlington Zoning Officer","Contact: Kathy Appleby, Zoning Officer, Technical Assistant, LUB Secretary · 973-398-6832 ext. 114 · kappleby@mtarlingtonboro.com","Apply: Apply at least 30 days before the transfer of title. Applications within 7 business days of closing pay an extra $100 expediting fee.","How to apply: Fill out the Certificate of Habitability Application (mark Resale and give the closing date) and submit it with the fee (cash or check) to the Zoning Department, 419 Howard Blvd., at least 30 days before closing. Call 973-398-6832 ext. 114 or email kappleby@mtarlingtonboro.com. The Zoning Officer sets an inspection appointment.","Compliance with Borough zoning, the well certification ordinance and the Property Maintenance chapter","Defects affecting habitability must be corrected before the transfer of title","No open permits; violations need permits before a re-inspection","Application lists bedrooms, bathrooms, kitchens, outbuildings, sewer/water/private well and finished or unfinished basement","Well certification for private wells used for non-potable water or irrigation","Owner certifies no improvements were installed without approved permits","Payment by cash or check only, no credit cards","Also: Private well certification: The Certificate of Habitability checks the Borough's well certification ordinance; the application asks for a well certification for private wells used for non-potable water or irrigation.","Also: Open permits: No Certificate of Habitability is issued while the property has an open permit."]$j$::jsonb, $j$[{"label":"Certificate of Habitability","amount":"$60.00"},{"label":"Expediting fee, application within 7 business days of closing (added to the $60)","amount":"$100"}]$j$::jsonb, $t$https://mountarlingtonnj.org/wp-content/uploads/2022/09/COH.pdf$t$, $t$https://mountarlingtonnj.org/departments/construction/$t$, $j$[{"url":"https://ecode360.com/35500833","label":"Official source (ecode360.com)"},{"url":"https://mountarlingtonnj.org/departments/construction/","label":"Official source (mountarlingtonnj.org)"},{"url":"https://mountarlingtonnj.org/wp-content/uploads/2022/09/COH.pdf","label":"Official source (mountarlingtonnj.org)"}]$j$::jsonb, $t$A certificate of habitability shall be required to be obtained by the owner for any residential use prior to the rental, lease, or transfer of title involving a new occupant, tenant or owner of said property.$t$, $t$6647399135a9c32727e0bf4ff5cec2e447012943073651bc580c478dfec3989e$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":5,"fee_bad":0,"fee_unchecked":0,"quotes":17,"q_ok":11,"q_bad":0,"q_unchecked":6},"source":"property/data/municipal-requirements/checked/1426.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1426.json$t$, true),
  ($t$1426$t$, $t$Mount Arlington Borough$t$, $t$MORRIS$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Entire borough: issued by Borough of Mount Arlington Construction Department (Certification in Lieu of Inspection for smoke/CO) (town fire bureau)","Entire borough contact: Kathy Appleby, Zoning Officer / Technical Assistant, Construction Department · 973-398-6832 ext. 114 · kappleby@mtarlingtonboro.com","Entire borough, apply: Fee depends on business days between receipt and closing: more than 10 business days for the lowest fee. If the change of occupant does not happen within 6 months, a new application is needed.","Entire borough, how to apply: Complete the Application and Certification in Lieu of Inspection (owner or authorized representative checks every box after inspecting the home), have it notarized, and submit it with a check or money order payable to the Borough of Mount Arlington to 419 Howard Blvd (973-398-6832 ext. 114, kappleby@mtarlingtonboro.com). The certificate is not transferable and the fee is not refundable.","Entire borough (State is the fire code enforcing agency): issued by NJ Division of Fire Safety, Bureau of Fire Code Enforcement (State LEA for Mount Arlington) (NJ DCA, state)","Entire borough (State is the fire code enforcing agency) contact: Louis Kilmer, Fire Official, NJ Division of Fire Safety · (609) 633-6132","Entire borough (State is the fire code enforcing agency), how to apply: The state fire directory lists the NJ Division of Fire Safety as the smoke detector compliance office for Mount Arlington. In practice the Borough runs its own notarized self-certification; contact the Borough first.","Fire official in the NJ state directory (NJ DCA, state), updated 6/16/2025: Louis Kilmer · (609)633-6132","Smoke detector on each level, including basements (not attics or crawl spaces)","Smoke detector and carbon monoxide alarm outside each separate sleeping area, within 10 feet of bedrooms","All smoke detectors and CO alarms in working order; battery units allowed and interconnection not required (AC or interconnected alarms in homes built after January 1977 must be kept working)","Fire extinguisher of the correct size, mounted, within 10 feet of the kitchen (form still lists it)","Owner or authorized representative does the inspection and signs a notarized certification in lieu of inspection","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Entire borough: Smoke/CO certification, received more than 10 business days before closing","amount":"$35.00"},{"label":"Entire borough: Received fewer than 10 but more than 4 business days before closing","amount":"$70.00"},{"label":"Entire borough: Received 4 business days or fewer before closing","amount":"$140.00"}]$j$::jsonb, $t$https://mountarlingtonnj.org/wp-content/uploads/2022/09/SMOKE-CERT.pdf$t$, $t$https://mountarlingtonnj.org/departments/construction/$t$, $j$[{"url":"https://mountarlingtonnj.org/wp-content/uploads/2022/09/SMOKE-CERT.pdf","label":"Official source (mountarlingtonnj.org)"},{"url":"https://mountarlingtonnj.org/departments/construction/","label":"Official source (mountarlingtonnj.org)"},{"url":"https://ecode360.com/35500166","label":"Official source (ecode360.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Application and Certification in Lieu of Inspection for$t$, $t$ac90f70bf1a8ca4b77e092d95c4f982ff10af9508eda9b0947942ed18fc1a8de$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":5,"fee_bad":0,"fee_unchecked":0,"quotes":17,"q_ok":11,"q_bad":0,"q_unchecked":6},"source":"property/data/municipal-requirements/checked/1426.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1426.json$t$, true),
  ($t$1428$t$, $t$Netcong Borough$t$, $t$MORRIS$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Habitability (COH)$t$, $j$["Issued by: Borough of Netcong Zoning Officer","Contact: 973-347-0252","How to apply: Download the 'Certificate of Habitability and Residential Fire Inspection Application' from the Borough Forms page (a COH Pre-Checklist is also posted), mark it Resale, give the closing date and inspection contact, and file it with the fee at Borough Hall, 23 Maple Avenue, Netcong, NJ 07857 (973-347-0252). Contact the Zoning Department for the application.","Written application to the Zoning Officer with owner names and addresses, a description of the dwelling and any managing agent","Fee paid in full when the application is filed","Inspection finding the dwelling safe and fit for human habitation and in line with state statutes and Borough housing and health ordinances; violations must be corrected before the certificate is issued","Combined form also covers the residential fire inspection: number of smoke detectors, CO detectors and fire extinguishers (form still lists extinguishers)"]$j$::jsonb, $j$[{"label":"Certificate of Habitability and Residential Fire Inspection, more than 10 days ahead (combined application)","amount":"$100"},{"label":"Combined application within 10 days","amount":"$160"},{"label":"Combined application within 4 days","amount":"$185"},{"label":"Certificate of habitability inspection, each dwelling unit (Code Section 127-4B)","amount":"$35"},{"label":"Certificate of habitability reinspection (Code)","amount":"$20"}]$j$::jsonb, $t$https://netcong.org/?ddownload=26731$t$, $t$https://netcong.org/zoning-habitability/$t$, $j$[{"url":"https://ecode360.com/11254761","label":"Official source (ecode360.com)"},{"url":"https://netcong.org/zoning-habitability/","label":"Official source (netcong.org)"},{"url":"https://netcong.org/borough-forms/","label":"Official source (netcong.org)"},{"url":"https://netcong.org/?ddownload=26731","label":"Official source (netcong.org)"}]$j$::jsonb, $t$No person, firm or corporation shall sell a dwelling or dwelling unit or permit the same to be sold without first obtaining a certificate of habitability, nor shall any person, firm or corporation buying a dwelling or dwelling unit and intending to occupy the same, do so, without securing a certificate of habitability, as hereinafter provided.$t$, $t$6c7d93f2522c474789f8ddf0f3976644bac1fcdc69b48093631c545924a17493$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":11,"fee_ok":6,"fee_bad":0,"fee_unchecked":5,"quotes":12,"q_ok":6,"q_bad":0,"q_unchecked":6},"source":"property/data/municipal-requirements/checked/1428.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1428.json$t$, true),
  ($t$1428$t$, $t$Netcong Borough$t$, $t$MORRIS$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Netcong Borough Bureau of Fire Prevention (town fire bureau)","Contact: Mark Sylvester, Fire Official · (862) 599-0155 · netcongfpb@netcong.org","Apply: Fee depends on how long before the change of ownership the inspection is requested: at least 10 days for the lowest fee.","How to apply: Use the combined Certificate of Habitability and Residential Fire Inspection Application (Borough Forms page). For questions email the Fire Prevention Bureau at netcongfpb@netcong.org or call (862) 599-0155; hours vary, so ask for an appointment.","Fire official in the NJ state directory, updated 4/7/2025: Mark J Sylvester · (973) 347-0252 · netcongfpb@gmail.com","Smoke alarms located and maintained per N.J.A.C. 5:70-4.19 and NFPA 72","Carbon monoxide alarms per N.J.A.C. 5:70-4.19 and NFPA 720","Portable fire extinguisher per N.J.A.C. 5:70-4.19(e) (Borough code and form still list it)","Installed fire alarm systems may need testing and maintenance records before the certificate is issued","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke alarm, CO alarm and extinguisher certificate (CSACMAPFEC), requested at least 10 days before the change of ownership (Code Section 157-8)","amount":"$65"},{"label":"Requested within 10 days (Code)","amount":"$125"},{"label":"Requested within 4 days (Code)","amount":"$150"},{"label":"Certificate of Habitability and Residential Fire Inspection, more than 10 days ahead (combined application)","amount":"$100"},{"label":"Combined application within 10 days","amount":"$160"},{"label":"Combined application within 4 days","amount":"$185"}]$j$::jsonb, $t$https://netcong.org/?ddownload=26731$t$, $t$https://netcong.org/netcong-fire-prevention-bureau/$t$, $j$[{"url":"https://ecode360.com/11255009","label":"Official source (ecode360.com)"},{"url":"https://netcong.org/netcong-fire-prevention-bureau/","label":"Official source (netcong.org)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://netcong.org/?ddownload=26731","label":"Official source (netcong.org)"}]$j$::jsonb, $t$The Fire Official of the Bureau of Fire Prevention and duly appointed inspectors are hereby empowered to conduct the necessary inspections and to issue certificates of compliance as contemplated herein.$t$, $t$dc5ba09fd373eb4c83918a78c33d6fe044f74415037d86a104c7230e48ae8c42$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":11,"fee_ok":6,"fee_bad":0,"fee_unchecked":5,"quotes":12,"q_ok":6,"q_bad":0,"q_unchecked":6},"source":"property/data/municipal-requirements/checked/1428.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1428.json$t$, true),
  ($t$1430$t$, $t$Long Hill Township$t$, $t$MORRIS$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Construction Records Clearance (CRC)$t$, $j$["Issued by: Township of Long Hill Construction Office (Construction Official)","Contact: Jeff Heiss, Construction Code Official / Building Subcode Official (ext. 216) · 908-647-8000 ext. 217 · construction@longhillnj.gov","Apply: Submit the application and fee at least 10 business days before the change of ownership (ordinance); the form charges more when filed under 7 business days.","How to apply: Submit the Construction Records Clearance Application to the Construction Office at Town Hall, 915 Valley Road, with exact cash or a check payable to Long Hill Township. The first point of contact is the Technical Assistant (construction@longhillnj.gov, 908-647-8000 ext. 217).","No open construction permits on the property; if permits are open, all final inspections and approvals must be completed and UCC certificates issued first","Application lists property, closing date (required), seller/agent, block and lot and property type","Exempt (if no change in physical occupancy): deed corrections, ancient deeds, spouse/former spouse transfers, new construction with a CO, estate distributions, refinancing, receivers/trustees","Also: Sump pump discharge check: The Fire Official's sale inspection verifies sump pump discharge lines are not connected to the sanitary waste line.","Also: House numbers: House numbers must be in numerals at least three inches high and match tax records (Chapter 29-2.5).","Also: Resale certificate without occupancy: A separate resale-only fire certificate with no permitted occupancy is available (same $100 / $140 / $211 tiers) when the buyer will not move in right away."]$j$::jsonb, $j$[{"label":"Construction Records Clearance, filed more than 7 business days before closing","amount":"$50"},{"label":"Construction Records Clearance, filed under 7 business days before closing","amount":"$100"}]$j$::jsonb, $t$https://www.longhillnj.gov/_Content/pdf/forms/Construction-Records-Clearance-Application.pdf$t$, $t$https://www.longhillnj.gov/Departments/construction-department$t$, $j$[{"url":"https://ecode360.com/35982748","label":"Official source (ecode360.com)"},{"url":"https://www.longhillnj.gov/_Content/pdf/forms/Construction-Records-Clearance-Application.pdf","label":"Official source (longhillnj.gov)"},{"url":"https://www.longhillnj.gov/forms","label":"Official source (longhillnj.gov)"}]$j$::jsonb, $t$A CRC shall be required prior to the sale of any residential or commercial structure and prior to the rental of any tenant space in a commercial structure within the Township.$t$, $t$37d7561a0d21d38872a7b9d79deac293ba5b47332b66d76619d7b49928c2c750$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":9,"fee_ok":7,"fee_bad":0,"fee_unchecked":2,"quotes":13,"q_ok":7,"q_bad":0,"q_unchecked":6},"source":"property/data/municipal-requirements/checked/1430.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1430.json$t$, true),
  ($t$1430$t$, $t$Long Hill Township$t$, $t$MORRIS$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Long Hill Township Fire Prevention (Office of the Fire Official) (town fire bureau)","Contact: Don Huber, Fire Official · (908) 647-8000, Ext 307 · fireofficial@longhillnj.gov","Apply: Fee depends on business days between the completed application and closing: more than 10 business days for the lowest fee. Appointments are based on availability. Certificates are valid for 6 months from issue.","How to apply: Complete the 'Application for Home Sale/Change in Tenancy Certificate of Inspection' and submit it with payment to \"Township of Long Hill\", ATTN: Fire Official, 915 Valley Road, Gillette (by mail with a check, or in person with cash, check or credit card; card payments carry a convenience fee). Test all alarms before the inspection.","Fire official in the NJ state directory (town), updated 6/3/2026: Donald M Huber · (908) 647-8000 · fireofficial@longhillnj.gov","Smoke alarms: basement at bottom of stairs, each floor at the stairs, and within 10 feet of any bedroom/sleeping area on each level (UL listed); battery alarms must be 10-year sealed units","Carbon monoxide alarms inside and/or outside sleeping areas, in the hallway within 10 feet of bedroom doors, and in any finished basement or recreation area","Existing hardwired or wireless interconnected fire alarm systems maintained to original level","Secondary power source label within 18 inches of the main electrical panel and meter (P.L. 2025, c.19), if applicable","Sump pump discharge not connected to the sanitary waste line","House number in numerals at least 3 inches high, matching tax records","Portable fire extinguisher no longer required for home sales (still required for rentals)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Certificate of Inspection, application received more than 10 business days before closing","amount":"$100"},{"label":"Certificate of Inspection, 4 to 10 business days before closing","amount":"$140"},{"label":"Certificate of Inspection, 4 business days or less before closing","amount":"$211"},{"label":"Reinspection after failed inspection (10+ day tier)","amount":"$25"},{"label":"Reinspection after failed inspection (4-10 day tier)","amount":"$50"},{"label":"Reinspection after failed inspection (4 days or less tier)","amount":"$100"},{"label":"No-show for a scheduled appointment","amount":"$50"}]$j$::jsonb, $t$https://www.longhillnj.gov/_Content/pdf/forms/Smoke-Alarm-Carbon-Monoxide-Portable-Fire-Extinguisher-and-Sump-Pump-Compliance-Application-for-Inspection.pdf$t$, $t$https://www.longhillnj.gov/pages/fire-prevention$t$, $j$[{"url":"https://www.longhillnj.gov/_Content/pdf/forms/Smoke-Alarm-Carbon-Monoxide-Portable-Fire-Extinguisher-and-Sump-Pump-Compliance-Application-for-Inspection.pdf","label":"Official source (longhillnj.gov)"},{"url":"https://www.longhillnj.gov/_Content/pdf/forms/Fire-Prevention-Residential-Alarm-Inspection-Guidelines.pdf","label":"Official source (longhillnj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Change in Tenancy Certificate of Inspection$t$, $t$50a02a8256c70c286ec57a246149a11ee8b182f48c0ef4f581cdaacfa4b8bf55$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":9,"fee_ok":7,"fee_bad":0,"fee_unchecked":2,"quotes":13,"q_ok":7,"q_bad":0,"q_unchecked":6},"source":"property/data/municipal-requirements/checked/1430.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1430.json$t$, true),
  ($t$1431$t$, $t$Pequannock Township$t$, $t$MORRIS$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Construction Records Clearance (CRC)$t$, $j$["Issued by: Pequannock Township Construction Official","Contact: Robert J. Grant, Construction Official (Technical Assistant: Barbara Munnelly, ext. 182) · 973-835-5700, ext. 181","How to apply: Submit the Construction Records Clearance Certificate form to the Construction Department (530 Newark Pompton Turnpike, Pompton Plains) with the $35 fee payable to Pequannock Township. Permit history can be checked on the Township's SDL portal.","No open permits or pending violations on the property","Application lists seller, approximate date of purchase, buyer, property type, whether the house number is displayed and whether it is a rental property","Exempt (if no change in physical occupancy): listed title transfers such as deed corrections and similar transfers in Section 123-6C","Also: House number display: Ordinance 88-23 requires 3 inch house numbers beside the front door, checked at the smoke/CO inspection."]$j$::jsonb, $j$[{"label":"Certificate of construction records clearance (CRC)","amount":"$35"}]$j$::jsonb, $t$https://www.peqtwp.org/DocumentCenter/View/3047/Construction-Records-Clearing-Certificate-PDF$t$, $t$https://www.peqtwp.org/156/Construction-Department$t$, $j$[{"url":"https://ecode360.com/36917919","label":"Official source (ecode360.com)"},{"url":"https://ecode360.com/36919901","label":"Official source (ecode360.com)"},{"url":"https://www.peqtwp.org/DocumentCenter/View/3047/Construction-Records-Clearing-Certificate-PDF","label":"Official source (peqtwp.org)"},{"url":"https://www.peqtwp.org/156/Construction-Department","label":"Official source (peqtwp.org)"}]$j$::jsonb, $t$A certificate issued by the Township Construction Official certifying that there are no open permits or pending violations on the subject property.$t$, $t$e0ab0c838831239d8572c3a8a1a3aa4aa0894bf4f21ea4d1d6d44664b285cbd1$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":4,"fee_bad":0,"fee_unchecked":2,"quotes":13,"q_ok":6,"q_bad":0,"q_unchecked":7},"source":"property/data/municipal-requirements/checked/1431.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1431.json$t$, true),
  ($t$1431$t$, $t$Pequannock Township$t$, $t$MORRIS$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Pequannock Township Fire Safety Bureau (town fire bureau)","Contact: Mark Lime, Fire Official · 973-835-5700, ext. 194 · mlime@peqtwp.org","Apply: Fee depends on business days between the request and the change of occupant: more than 10 business days for the lowest fee.","How to apply: Call the Fire Safety Inspector at 973-835-5700, ext. 194 to request an inspection.","Fire official in the NJ state directory (town), updated 6/3/2026: Mark W Lime · (973) 835-5700 · mlime@peqtwp.org","House number at least three inch numerals next to the front door, five feet above the door saddle, contrasting and visible (Ordinance 88-23)","At least one smoke detector on each level including basements (unless the original CO required more); replacement battery units must be 10 year sealed UL approved","Smoke detector in the bedroom area within 10 feet of the bedrooms; hardwired/interconnected units must work and be under 10 years old","Active monitored fire alarm systems need paperwork from the alarm company before the inspection","Carbon monoxide alarm on each level with bedrooms, within 10 feet of the bedrooms, in homes with fuel-burning appliances or attached garages","Chimneys and smoke pipes properly sealed","No open permits with the Construction Department","Fire extinguisher (Township page and code still list it)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"CSDCMAC, request received more than 10 business days before the change of occupant","amount":"$45"},{"label":"CSDCMAC, 4 to 10 business days before the change of occupant","amount":"$90"},{"label":"CSDCMAC, fewer than 4 business days (Township web page)","amount":"$165"},{"label":"CSDCMAC, fewer than 4 business days (Township code)","amount":"$161"},{"label":"Each reinspection","amount":"$40"}]$j$::jsonb, null, $t$https://www.peqtwp.org/169/Fire-Safety-Bureau$t$, $j$[{"url":"https://www.peqtwp.org/169/Fire-Safety-Bureau","label":"Official source (peqtwp.org)"},{"url":"https://ecode360.com/36919901","label":"Official source (ecode360.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$If you are selling your house, you will need a smoke detector and carbon monoxide alarm compliance certificate. Please contact the Fire Safety Inspector at 973-835-5700, ext. 194 in order to request an inspection.$t$, $t$aacc7edd6b829581f3ae43def1e6930a253d4097417525ed75ddc0efbc5f6d88$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":4,"fee_bad":0,"fee_unchecked":2,"quotes":13,"q_ok":6,"q_bad":0,"q_unchecked":7},"source":"property/data/municipal-requirements/checked/1431.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1431.json$t$, true),
  ($t$1433$t$, $t$Riverdale Borough$t$, $t$MORRIS$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Municipal Certificate of Continuing Occupancy (Municipal CCO), Residential Sale of House$t$, $j$["Issued by: Borough of Riverdale Zoning Officer (enforcement officer under Borough Code Chapter 82)","Contact: Stephanie Colella, Zoning Department · 973-835-4060 ext. 6 · scolella@riverdalenj.gov","Apply: A minimum of 72 hours notice (not counting weekends and holidays) is required for the inspection.","How to apply: Complete the Application for Residential Municipal CCO and return it to the Zoning Official's office, 91 Newark Pompton Turnpike, with two checks payable to the Borough of Riverdale: $100 per residential unit for the exterior inspection and $45 for the Fire Marshal's smoke and carbon monoxide inspection. The Fire Marshal then calls to set up the interior inspection.","Exterior zoning / property maintenance inspection: siding, trim and railings, gutters, glass and roof in good repair; sheds, pools, decks and fences meet zoning; driveway paved with asphalt; yard free of debris and overgrowth","Smoke and carbon monoxide detector certificate from the Fire Marshal (required for the Municipal CCO)","All open building, electrical, plumbing and fire permits closed before the CCO is issued","Seller provides a copy of the original survey and the buyer provides a copy of the new survey (not for condos or townhouses)","Seller's attorney name and phone required on the application","Any outstanding sewer connection fee balance paid in full; a sewer application is required if a sewer line is available to a home on private septic","Disclose abandoned wells, septic systems or fuel tanks, and any pools or hot tubs (pool barrier must meet state rules)","Also: Surveys: The seller must give a copy of the original survey and the buyer a copy of the new survey with the Municipal CCO application (not for condos or townhouses).","Also: Sewer connection fee / sewer application: Any outstanding balance on the Sewer Connection Fee must be paid in full; homes on private septic with a sewer line available on the street need a sewer application.","Also: Abandoned wells, septic or fuel tanks: The CCO application asks whether there are abandoned wells, septic systems or fuel tanks on the property.","Also: Open permits: All open building, electrical, plumbing and fire permits must be closed before the Municipal CCO is issued (construction permits through the Pompton Lakes shared building department, 973-835-0143)."]$j$::jsonb, $j$[{"label":"Municipal CCO, per residential unit (Borough of Riverdale)","amount":"$100"}]$j$::jsonb, $t$https://www.riverdalenj.gov/_Content/pdf/forms/Municipal-CCO-Residential.pdf$t$, $t$https://www.riverdalenj.gov/Departments/construction-department$t$, $j$[{"url":"https://ecode360.com/11330806","label":"Official source (ecode360.com)"},{"url":"https://www.riverdalenj.gov/_Content/pdf/forms/Municipal-CCO-Residential.pdf","label":"Official source (riverdalenj.gov)"},{"url":"https://www.riverdalenj.gov/Departments/construction-department","label":"Official source (riverdalenj.gov)"}]$j$::jsonb, $t$No person shall convey title to any building unless, prior to the conveyance, the owner shall have obtained a continued certificate of occupancy.$t$, $t$050537903dea53e943a1ce6de9bdff3c7fa4bb39cf7e3a419bdc35d9340d61d4$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":2,"fee_ok":0,"fee_bad":0,"fee_unchecked":2,"quotes":16,"q_ok":5,"q_bad":0,"q_unchecked":11},"source":"property/data/municipal-requirements/checked/1433.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1433.json$t$, true),
  ($t$1433$t$, $t$Riverdale Borough$t$, $t$MORRIS$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Riverdale Bureau of Fire Prevention (Fire Marshal), Borough of Riverdale (town fire bureau)","Contact: Mark Lime, Fire Official (from the NJ DCA fire directory) · (973) 835-4060 · fireprevention@riverdalenj.gov","Apply: After the CCO application is returned, the Fire Marshal calls to set up the interior inspection. The Fire Marshal is in the office Monday, Wednesday and Friday, 11:00 AM to 1:00 PM.","How to apply: Submit the $45 check (payable to Borough of Riverdale) with the Municipal CCO application to the Zoning Official's office; the Fire Marshal schedules the interior inspection. Code 100-14 says applications go to the Fire Official with the fee prepaid.","Fire official in the NJ state directory (town), updated 7/14/2026: Mark Lime · (973) 835-4060 · fireprevention@riverdalenj.gov","Smoke detectors installed in one- and two-family homes upon sale or change of occupancy, per N.J.A.C. 5:70","Carbon monoxide detectors in working order","All detectors working when the Fire Marshal arrives; a return inspection may need another inspection fee","Portable fire extinguisher (Borough Code 100-14 still names it in the certificate title; state law dropped it from the sale certificate in February 2025)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Fire Marshal smoke and carbon monoxide detector inspection (with the Municipal CCO)","amount":"$45"}]$j$::jsonb, $t$https://www.riverdalenj.gov/_Content/pdf/forms/Municipal-CCO-Residential.pdf$t$, $t$https://www.riverdalenj.gov/forms$t$, $j$[{"url":"https://www.riverdalenj.gov/_Content/pdf/ordinances/ORD-6-2022-ORDINANCE-AMENDING-MULTIPLE-SECTIONS-OF-CHAPTER-100-FIRE-PREVENTION.pdf","label":"Official source (riverdalenj.gov)"},{"url":"https://www.riverdalenj.gov/_Content/pdf/forms/Municipal-CCO-Residential.pdf","label":"Official source (riverdalenj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Prior to the sale, rental, transfer, lease or change of occupancy of any structure or part thereof, the owner shall first obtain from the Bureau of Fire Prevention a Certificate of smoke alarm, carbon monoxide alarm, and portable fire extinguisher compliance$t$, $t$7d5bafb9ce85e0b6b7f04e1ffeb4f2a4783539cc99aaba7d87f0d593cb8a2d21$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":2,"fee_ok":0,"fee_bad":0,"fee_unchecked":2,"quotes":16,"q_ok":5,"q_bad":0,"q_unchecked":11},"source":"property/data/municipal-requirements/checked/1433.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1433.json$t$, true),
  ($t$1437$t$, $t$Victory Gardens Borough$t$, $t$MORRIS$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Transfer Certificate of Occupancy (Housing Certificate of Occupancy / Certificate of Continued Occupancy on resale)$t$, $j$["Issued by: Borough of Victory Gardens Code Enforcement Department (signed off by the Code Enforcement Officer, Fire Official, Electrical and Plumbing Subcode officials)","Contact: 973-366-5312 · clerk@victorygardensnj.gov","How to apply: Download the Transfer Certificate of Occupancy application from the Borough's Forms, Permits, Licenses page, fill it in and hand deliver it with a check or money order payable to Borough of Victory Gardens to the Code Enforcement Department, 337 South Salem Street, Victory Gardens (Dover), NJ 07801. Schedule the inspection when you submit it. Phone (973) 366-5312, Monday to Friday 8 to 4.","Submit a completed Application for Inspection for Housing Certificate (Resale) with the fee before closing and title change","Book the inspection when you apply; a checklist is available from the Code Enforcement office","Someone over 18 must be present for the inspection","All permits and inspections must be completed before a Housing Certificate of Occupancy is issued","Inspection is signed by the Code Enforcement Officer, Fire Official, Electrical Subcode and Plumbing Subcode officials","A temporary certificate is possible only for renovation (property sold as-is, not occupied until permits are taken out and paid for)","The application must be hand delivered to the Borough at 337 South Salem Street","Also: Open permits: All permits and inspections must be completed before a Housing Certificate of Occupancy is issued."]$j$::jsonb, $j$[{"label":"Housing certificate inspection (resale), per unit (application form)","amount":"$160.00 per unit"},{"label":"Resale inspection, one family dwelling (code)","amount":"$150"},{"label":"Resale inspection, two family dwelling (code)","amount":"$250"}]$j$::jsonb, $t$https://storage.googleapis.com/juniper-media-library/517/2025/12/Transfer-of-Ownership-CO-application.pdf$t$, $t$https://victorygardensnj.gov/code-enforcement$t$, $j$[{"url":"https://victorygardensnj.gov/code-enforcement","label":"Official source (victorygardensnj.gov)"},{"url":"https://storage.googleapis.com/juniper-media-library/517/2025/12/Transfer-of-Ownership-CO-application.pdf","label":"Official source (storage.googleapis.com)"},{"url":"https://ecode360.com/36355908","label":"Official source (ecode360.com)"}]$j$::jsonb, $t$A Transfer Certificate of Occupancy must be obtained prior to the closing and title change of real estate property in the Borough of Victory Gardens.$t$, $t$0ac12f3f71537463d8d42a3fc91862505930e3e0eda960713624e919b9cc4e42$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":0,"fee_bad":0,"fee_unchecked":3,"quotes":11,"q_ok":4,"q_bad":0,"q_unchecked":7},"source":"property/data/municipal-requirements/checked/1437.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1437.json$t$, true),
  ($t$1437$t$, $t$Victory Gardens Borough$t$, $t$MORRIS$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Victory Gardens Borough Fire Official (Fire Prevention), part of the Borough resale housing certificate inspection (town fire bureau)","Contact: Bernie Grilletti, Fire Official · 973-366-5312 · bgrilletti78@gmail.com","How to apply: The resale housing certificate application includes a Fire Official sign-off; ask the Code Enforcement Department at (973) 366-5312 whether the smoke and CO certificate is done in the same inspection or needs a separate application.","Fire official in the NJ state directory, updated 8/5/2026: Bernie Grilletti · (973) 366-5312 · bgrilletti78@gmail.com","Smoke alarm and carbon monoxide alarm compliance under N.J.A.C. 5:70-2.3 (the Borough does not post its own checklist online)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[]$j$::jsonb, $t$https://storage.googleapis.com/juniper-media-library/517/2025/12/Transfer-of-Ownership-CO-application.pdf$t$, $t$https://victorygardensnj.gov/code-enforcement$t$, $j$[{"url":"https://storage.googleapis.com/juniper-media-library/517/2025/12/Transfer-of-Ownership-CO-application.pdf","label":"Official source (storage.googleapis.com)"},{"url":"https://ecode360.com/36356247","label":"Official source (ecode360.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Fire Official:$t$, $t$378285d8ae53afcd9e062b16213daa8b5e1fc372ee92a071c98ba4f51aaea259$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":0,"fee_bad":0,"fee_unchecked":3,"quotes":11,"q_ok":4,"q_bad":0,"q_unchecked":7},"source":"property/data/municipal-requirements/checked/1437.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1437.json$t$, true),
  ($t$1439$t$, $t$Wharton Borough$t$, $t$MORRIS$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Habitation (property sale)$t$, $j$["Issued by: Borough of Wharton Housing and Zoning Officer (Property Maintenance Enforcement)","Contact: Leon Stickle, Housing and Zoning Officer / Road Opening Coordinator (Deputy: Patrick Laverty) · 973-361-8444 ext. 2721 · lstickle@whartonnj.com","Apply: Granted or denied within 10 days of the application. Contact the Zoning and Housing Official about two weeks before closing to set up the smoke and CO alarm test.","How to apply: Fill out the Certificate of Habitation / Property Sale form and submit it with the fee to the Housing & Zoning Official, Borough of Wharton, 10 Robert Street, Wharton, NJ 07885 (973-361-8444 ext. 2721, lstickle@whartonnj.com). Call about two weeks before closing to book the inspection, which includes the smoke and CO alarm test.","Inspection by the Zoning and Housing Officer for compliance with all Borough ordinances","One GFI-protected receptacle in each bathroom; GFI on receptacles within 5 feet of the kitchen sink and any other water basin","Water heater pressure valve extension directed down, at least 12 inches off the floor","All empty spaces in the main electric panel covered","Handrails on stairways with three steps or more","One smoke detector on each level, lithium batteries required","Carbon monoxide detector within 10 feet of sleeping areas, 5 feet or lower on the wall","Fire extinguisher in the kitchen, ABC type, 10 lbs or less, hung no more than 5 feet off the floor and in view (page still lists it)","Two receptacles in each room other than bathrooms; windows stay up when open; glass and screens intact; heat in all habitable rooms; doors on all bedrooms","Application lists any previously granted variances, buyer details, residents, bedrooms, bathrooms, units and off-street parking","Also: Prior variances: The Certificate of Habitation form asks the seller to list any previously granted variances with dates and details."]$j$::jsonb, $j$[{"label":"Certificate of Habitation inspection, per dwelling unit sold (includes one reinspection)","amount":"$50"},{"label":"Additional fee each time a unit needs more than two inspections","amount":"$20"},{"label":"Certificate of Habitation / Property Sale inspection fee (application form)","amount":"$50.00"}]$j$::jsonb, $t$https://www.whartonnj.com/media/attachments/2025/01/09/certification-of-habitation-property-sale.pdf$t$, $t$https://www.whartonnj.com/index.php/departments/zoning-and-housing$t$, $j$[{"url":"https://www.whartonnj.com/index.php/departments/zoning-and-housing","label":"Official source (whartonnj.com)"},{"url":"https://ecode360.com/11909740","label":"Official source (ecode360.com)"},{"url":"https://www.whartonnj.com/media/attachments/2025/01/09/certification-of-habitation-property-sale.pdf","label":"Official source (whartonnj.com)"}]$j$::jsonb, $t$A Certificate of Habitation is required for every resale of residential property. It requires an inspection by the Zoning and Housing Officer.$t$, $t$955dd8fde0a9c2263496b8485ef295e6ef54116a74ddeaa6921d35840212b686$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":0,"fee_bad":0,"fee_unchecked":3,"quotes":10,"q_ok":5,"q_bad":0,"q_unchecked":5},"source":"property/data/municipal-requirements/checked/1439.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1439.json$t$, true),
  ($t$1439$t$, $t$Wharton Borough$t$, $t$MORRIS$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Borough of Wharton Zoning and Housing Official (smoke and CO alarm test for resale); Wharton Fire Department Bureau of Fire Prevention is the Uniform Fire Code enforcing agency (town fire bureau)","Contact: Leon Stickle, Housing and Zoning Officer · 973-361-8444 ext. 2721 · lstickle@whartonnj.com","Apply: Contact the Zoning and Housing Official approximately two weeks before closing.","How to apply: Contact the Zoning and Housing Official (973-361-8444 ext. 2721) about two weeks before closing to set up the smoke detector and carbon monoxide alarm test; it is done with the Certificate of Habitation inspection. No separate fee was found.","Fire official in the NJ state directory, updated 1/9/2026: Richard W Cloughley · (973) 361-8444 · rcloughley@whartonnj.com","One smoke detector on each level of the home, lithium batteries required","Carbon monoxide detector within 10 feet of sleeping areas, 5 feet or lower on the wall","Fire extinguisher in the kitchen, ABC type, 10 lbs or less (Borough page still lists it)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[]$j$::jsonb, null, $t$https://www.whartonnj.com/index.php/departments/zoning-and-housing$t$, $j$[{"url":"https://www.whartonnj.com/index.php/departments/zoning-and-housing","label":"Official source (whartonnj.com)"},{"url":"https://ecode360.com/11907299","label":"Official source (ecode360.com)"},{"url":"https://www.whartonnj.com/index.php/departments/fire-official","label":"Official source (whartonnj.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$This is required for the resale of residential property. You should contact the Zoning and Housing Official approximately two weeks prior to closing to set up an appointment for this.$t$, $t$ecb1bed679942459acfd9ff8e3fbd96a2d1912f9af93ff2a5644b205dc16c508$t$, $t$2026-10-04T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-10-04","approved_on":"2026-10-04","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":0,"fee_bad":0,"fee_unchecked":3,"quotes":10,"q_ok":5,"q_bad":0,"q_unchecked":5},"source":"property/data/municipal-requirements/checked/1439.json"}}$j$::jsonb, $t$Checked from official sources on 2026-10-04 and approved in the NJ Resale Certificate Tracker on 2026-10-04. Source: property/data/municipal-requirements/checked/1439.json$t$, true)
