-- Person-approved CO and fire certificate data: 170 rows for 85 towns that are new or
-- changed since the previous checked_municipal_requirements migration.
-- Generated by property/scripts/build_checked_municipal_requirements.py from
-- property/data/municipal-requirements/ (checked research, approvals, NJ DCA fire officials).
-- Do not edit by hand: change the data and generate a new migration.

on conflict (municipality_code, requirement_key) do update set
  municipality_name = excluded.municipality_name,
  county = excluded.county,
  requirement_state = excluded.requirement_state,
  title = excluded.title,
  requirements = excluded.requirements,
  fees = excluded.fees,
  application_url = excluded.application_url,
  department_url = coalesce(excluded.department_url, transaction_municipal_requirements.department_url),
  source_urls = excluded.source_urls,
  source_excerpt = excluded.source_excerpt,
  source_hash = excluded.source_hash,
  last_verified_at = excluded.last_verified_at,
  metadata = transaction_municipal_requirements.metadata || excluded.metadata,
  curated_override = true,
  curated_note = excluded.curated_note,
  updated_at = now();
